"use client";

import { useCallback, useEffect, useState } from "react";
import { Film, Loader2, Upload } from "lucide-react";
import { toast } from "sonner";
import { inspectLocalVideoFile } from "@/domains/materials/media/video-file-metadata.client";
import { validateAssemblyVideoFile } from "@/domains/production/assembly-branding/assembly-branding-upload";
import { uploadWithSignedUrl } from "@/lib/storage-upload";

type Kind = "OUTRO";
type Asset = { created_at: string; duration_milliseconds: number; file_size_bytes: number; id: string; kind: Kind; mime_type: string; name: string; status: string };

export function AssemblyBrandingCard() {
  const [assets, setAssets] = useState<Asset[]>([]);
  const [busy, setBusy] = useState<Kind | "LOAD" | null>("LOAD");
  const load = useCallback(async () => {
    try {
      const response = await fetch("/api/production/assembly-branding", { cache: "no-store" });
      const body = await response.json(); if (!response.ok) throw new Error(body.error);
      setAssets((body.data.assets as Asset[]).filter((asset) => asset.kind === "OUTRO"));
    } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudo cargar la identidad de ensamble."); }
    finally { setBusy(null); }
  }, []);
  useEffect(() => { void load(); }, [load]);

  async function upload(kind: Kind, file: File) {
    setBusy(kind);
    try {
      const validation = validateAssemblyVideoFile(file);
      if (!validation.success) {
        const messages = {
          empty: "El video está vacío.",
          too_large: "El video supera el límite de 100 MB.",
          unsupported_type: "Solo se permiten videos MP4 o WebM.",
        } as const;
        throw new Error(messages[validation.reason]);
      }
      const metadata = await inspectLocalVideoFile(file);
      if (metadata.duration <= 0) throw new Error("No se pudo medir la duración del video.");
      const uploaded = await uploadWithSignedUrl("production-assets", "", file, {
        assetKind: kind,
        contentType: file.type,
        deliveryMode: "server-only",
        fileSizeBytes: file.size,
        purpose: "assembly-branding",
        upsert: false,
      });
      const response = await fetch("/api/production/assembly-branding", {
        body: JSON.stringify({
          fileSizeBytes: file.size,
          kind,
          mimeType: file.type,
          name: file.name,
          path: uploaded.path,
        }),
        headers: { "Content-Type": "application/json" },
        method: "PATCH",
      });
      const body = await response.json(); if (!response.ok) throw new Error(body.error);
      await load();
      toast.success("Outro subido a la biblioteca corporativa.");
    } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudo subir el video."); }
    finally { setBusy(null); }
  }

  return <section className="engine-integration-row">
    <div className="engine-integration-row__main"><div className="flex items-start gap-4"><div className="flex h-12 w-12 items-center justify-center rounded-xl bg-cyan-500/10 text-cyan-600"><Film size={24} /></div><div><h2 className="text-lg font-bold text-gray-900 dark:text-white">Outros corporativos</h2><p className="mt-1 max-w-xl text-sm text-gray-600 dark:text-slate-400">Biblioteca reutilizable. Cada video elige su outro desde el editor; las intros pertenecen a los assets de Producción de cada video.</p></div></div></div>
    <div className="engine-integration-row__details"><div className="rounded-xl border border-gray-200 p-4 dark:border-white/10"><div className="mb-3 flex items-center justify-between"><strong>Biblioteca de outros</strong>{busy === "OUTRO" ? <Loader2 className="animate-spin" size={16} /> : null}</div><div className="max-h-32 space-y-1 overflow-auto text-sm text-gray-600 dark:text-slate-300">{assets.filter((asset) => asset.status === "APPROVED").length === 0 ? <p>Sin outros disponibles.</p> : assets.filter((asset) => asset.status === "APPROVED").map((asset) => <p key={asset.id}>{asset.name} · {(asset.duration_milliseconds / 1000).toFixed(1)} s</p>)}</div><p className="mt-2 text-xs text-gray-500 dark:text-slate-400">La elección operativa se realiza por video en el editor.</p><label className="engine-button engine-button--secondary mt-3 inline-flex cursor-pointer"><Upload size={16} /> Subir outro<input className="sr-only" type="file" accept="video/mp4,video/webm" disabled={Boolean(busy)} onChange={(event) => { const file = event.target.files?.[0]; if (file) void upload("OUTRO", file); event.currentTarget.value = ""; }} /></label></div></div>
  </section>;
}

"use client";

import { useEffect, useState } from "react";
import {
  CheckCircle2,
  KeyRound,
  Loader2,
  RefreshCw,
  Unplug,
} from "lucide-react";
import { toast } from "sonner";

type ConnectionStatus = {
  connected: boolean;
  last4: string | null;
  lastValidationError: string | null;
};

type BusyAction = "save" | "validate" | "disconnect" | null;

export type ProviderIntegrationCardProps = {
  connectionPath: string;
  description: string;
  keyLabel: string;
  name: string;
  validatePath: string;
};

/** Reusable UI contract for organization-scoped provider API keys. */
export function ProviderIntegrationCard({
  connectionPath,
  description,
  keyLabel,
  name,
  validatePath,
}: ProviderIntegrationCardProps) {
  const [connection, setConnection] = useState<ConnectionStatus | null>(null);
  const [apiKey, setApiKey] = useState("");
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState<BusyAction>(null);

  const loadConnection = async () => {
    try {
      const response = await fetch(connectionPath, { cache: "no-store" });
      const body = await response.json();
      if (!response.ok)
        throw new Error(
          body.error || `No se pudo cargar la conexión de ${name}.`,
        );
      setConnection(body.data);
    } catch (error) {
      toast.error(
        error instanceof Error
          ? error.message
          : `No se pudo cargar la conexión de ${name}.`,
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadConnection();
    // The endpoint is a stable card configuration, not mutable UI state.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [connectionPath]);

  const request = async (
    action: Exclude<BusyAction, null>,
    path: string,
    init: RequestInit,
  ) => {
    setBusy(action);
    try {
      const response = await fetch(path, init);
      const body = await response.json();
      if (!response.ok)
        throw new Error(body.error || `No se pudo actualizar ${name}.`);
      setConnection(body.data);
      setApiKey("");
      toast.success(
        action === "disconnect"
          ? `${name} desconectado para esta empresa.`
          : action === "validate"
            ? `Conexión de ${name} validada.`
            : `API de ${name} guardada y validada.`,
      );
    } catch (error) {
      toast.error(
        error instanceof Error
          ? error.message
          : `No se pudo actualizar ${name}.`,
      );
    } finally {
      setBusy(null);
    }
  };

  const connected = connection?.connected === true;
  const disabled = loading || busy !== null;

  return (
    <section className="engine-integration-row engine-integration-row--credential">
      <div className="engine-integration-row__main">
        <div className="flex items-start gap-4">
          <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-[var(--engine-accent)]/10 text-[var(--engine-accent-strong)] dark:text-[var(--engine-accent)]">
            <KeyRound size={24} />
          </div>
          <div>
            <h2 className="text-lg font-bold text-gray-900 dark:text-white">
              {name}
            </h2>
            <p className="mt-1 max-w-md text-sm text-gray-600 dark:text-slate-400">
              {description}
            </p>
          </div>
        </div>
        <ConnectionBadge connected={connected} loading={loading} />
      </div>

      <div className="engine-integration-row__details">
        {connected ? (
          <p className="engine-integration-note engine-integration-note--success">
            API configurada ••••{connection?.last4 || ""}
          </p>
        ) : null}
        {connection?.lastValidationError ? (
          <p className="engine-integration-note engine-integration-note--danger">
            {connection.lastValidationError}
          </p>
        ) : null}
        <label className="engine-field">
          <span>{keyLabel}</span>
          <input
            type="password"
            value={apiKey}
            onChange={(event) => setApiKey(event.target.value)}
            autoComplete="off"
            disabled={disabled}
            placeholder={
              connected
                ? "Pega una nueva API key para reemplazarla"
                : `Pega la API key de ${name}`
            }
          />
        </label>
        <p className="mt-2 text-xs text-gray-500 dark:text-slate-400">
          La clave se valida y almacena cifrada por empresa. No volverá a
          mostrarse.
        </p>
      </div>

      <div className="engine-integration-row__actions">
        <button
          type="button"
          disabled={disabled || !apiKey.trim()}
          onClick={() =>
            void request("save", connectionPath, {
              body: JSON.stringify({ apiKey }),
              headers: { "Content-Type": "application/json" },
              method: "POST",
            })
          }
          className="engine-button engine-button--primary"
        >
          {busy === "save" ? (
            <Loader2 className="animate-spin" size={16} />
          ) : (
            <RefreshCw size={16} />
          )}
          {connected ? "Cambiar API key" : "Guardar y conectar"}
        </button>
        {connected ? (
          <>
            <button
              type="button"
              disabled={disabled}
              onClick={() =>
                void request("validate", validatePath, { method: "POST" })
              }
              className="engine-button"
            >
              {busy === "validate" ? (
                <Loader2 className="animate-spin" size={16} />
              ) : (
                <CheckCircle2 size={16} />
              )}
              Validar conexión
            </button>
            <button
              type="button"
              disabled={disabled}
              onClick={() =>
                void request("disconnect", connectionPath, { method: "DELETE" })
              }
              className="engine-button engine-button--danger"
            >
              {busy === "disconnect" ? (
                <Loader2 className="animate-spin" size={16} />
              ) : (
                <Unplug size={16} />
              )}
              Desconectar
            </button>
          </>
        ) : null}
      </div>
    </section>
  );
}

function ConnectionBadge({
  connected,
  loading,
}: {
  connected: boolean;
  loading: boolean;
}) {
  if (loading)
    return (
      <span className="inline-flex items-center gap-1.5 rounded-full bg-gray-100 px-2.5 py-1 text-xs font-semibold text-gray-500 dark:bg-white/5 dark:text-slate-400">
        <Loader2 className="animate-spin" size={14} />
        Consultando
      </span>
    );
  if (connected)
    return (
      <span className="inline-flex items-center gap-1.5 rounded-full bg-emerald-500/10 px-2.5 py-1 text-xs font-semibold text-emerald-600 dark:text-emerald-400">
        <CheckCircle2 size={14} />
        Conectado
      </span>
    );
  return (
    <span className="inline-flex items-center gap-1.5 rounded-full bg-gray-100 px-2.5 py-1 text-xs font-semibold text-gray-500 dark:bg-white/5 dark:text-slate-400">
      Desconectado
    </span>
  );
}

import { redirect } from 'next/navigation';
import { createClient } from '@/utils/supabase/server';
import { getAuthBridgeUser } from '@/utils/auth/session';
import { logoutAction } from '../login/actions';
import AdminLayoutClient from './AdminLayoutClient';
import { getSupabaseServiceRoleKey, getSupabaseUrl } from '@/lib/server/env';
import { resolveSidebarProfile } from '@/components/layout/layout.types';
import { normalizePlatformRole } from '@/utils/auth/platform-role';
import { userHasPlatformPermission } from '@/lib/server/platform-authorization';
import { PLATFORM_PERMISSIONS } from '@/utils/auth/platform-permissions';

export default async function AdminLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const supabase = await createClient();

  // 1. Verificar Sesión - intentar GoTrue primero, luego Auth Bridge
  let { data: { user } } = await supabase.auth.getUser();

  let bridgeUser = null;
  if (!user) {
    bridgeUser = await getAuthBridgeUser();
    if (!bridgeUser) {
      redirect('/login');
    }
  }

  const userId = user?.id || bridgeUser?.id;
  const userEmail = user?.email || bridgeUser?.email;

  // 2. Verificar Rol de Admin local de SofLIA - Engine
  let { data: profile } = await supabase
    .from('profiles')
    .select('avatar_url, first_name, last_name_father, platform_role')
    .eq('id', userId)
    .single();

  // --- FALLBACK ROLE DETECTION ---
  // Si no pudimos leer el perfil con el cliente normal (puede pasar por RLS 
  // si el JWT aún no se propaga completamente), intentamos con el cliente admin.
  if (!profile) {
    const { createClient: createAdminClient } = await import('@supabase/supabase-js');
    const cfAdmin = createAdminClient(
      getSupabaseUrl(),
      getSupabaseServiceRoleKey(),
    );
    const { data: adminProfile } = await cfAdmin
      .from('profiles')
      .select('avatar_url, first_name, last_name_father, platform_role')
      .eq('id', userId)
      .single();
    
    if (adminProfile) {
      profile = adminProfile;
    }
  }

  const effectiveRole =
    normalizePlatformRole(bridgeUser?.platform_role) ||
    normalizePlatformRole(profile?.platform_role);
  const hasValidRole = ['ADMIN', 'ARQUITECTO', 'CONSTRUCTOR', 'SUPERADMIN'].includes(effectiveRole as string);

  if (!hasValidRole) {
    redirect('/login?error=unauthorized');
  }

  // Usar datos disponibles
  const displayProfile = {
    ...(resolveSidebarProfile(profile, bridgeUser) || {}),
    platform_role: effectiveRole,
  };
  const showPlatformMonitoring = await userHasPlatformPermission(
    PLATFORM_PERMISSIONS.AI_USAGE_READ,
  );

  return (
    <AdminLayoutClient userEmail={userEmail} logoutAction={logoutAction} profile={displayProfile} showPlatformMonitoring={showPlatformMonitoring}>
      {children}
    </AdminLayoutClient>
  );
}

