  const [activeSection, setActiveSection] = useState<'general' | 'security' | 'integrations'>('general');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [avatarUrl, setAvatarUrl] = useState(profile?.avatar_url);
  const [isGoogleConnected, setIsGoogleConnected] = useState(googleConnected);
  const [googleEmailAddress, setGoogleEmailAddress] = useState(googleEmail);
  const [isOneDriveConnected, setIsOneDriveConnected] = useState(oneDriveConnected);
  const [oneDriveEmailAddress, setOneDriveEmailAddress] = useState(oneDriveEmail);
  const memberSinceLabel = formatMemberSinceDate(user.created_at);

  // Profile State
  const [formData, setFormData] = useState({
    firstName: profile?.first_name || '',
    lastNameFather: profile?.last_name_father || '',
    lastNameMother: profile?.last_name_mother || '',
    username: profile?.username || '',
  });

  // Password State
  const [passwordData, setPasswordData] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });
  const [showPassword, setShowPassword] = useState(false);

  const handleProfileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handlePasswordChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setPasswordData({ ...passwordData, [e.target.name]: e.target.value });
  };

  const handleSubmitProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    const result = await updateProfile(formData);

    setIsLoading(false);
    if (result.error) {
        toast.error(result.error);
    } else {
        toast.success("Perfil actualizado correctamente");
    }
  };

  const handleSubmitPassword = async (e: React.FormEvent) => {
    e.preventDefault();

    if (passwordData.newPassword !== passwordData.confirmPassword) {
        toast.error("Las contraseñas no coinciden");
        return;
    }

    setIsLoading(true);
    const result = await updatePassword(passwordData);
    setIsLoading(false);

    if (result.error) {
        toast.error(result.error);
    } else {
        setPasswordData({ currentPassword: '', newPassword: '', confirmPassword: '' });
        toast.success("Contraseña actualizada correctamente");
    }
  };

  const handleDisconnectGoogle = async () => {
    setIsLoading(true);
    try {
      const res = await disconnectCloudStorageAction("google_drive");
      if (res.success) {
        setIsGoogleConnected(false);
        setGoogleEmailAddress(null);
        toast.success("Cuenta de Google Drive desvinculada correctamente");
      } else {
        toast.error(res.error || "Error al desvincular Google Drive");
      }
    } catch (err: any) {
      toast.error(err.message || "Error al desvincular Google Drive");
    } finally {
      setIsLoading(false);
    }
  };

  const handleDisconnectOneDrive = async () => {
    setIsLoading(true);
    try {
      const res = await disconnectCloudStorageAction("onedrive");
      if (res.success) {
        setIsOneDriveConnected(false);
        setOneDriveEmailAddress(null);
        toast.success("Cuenta de OneDrive desvinculada correctamente");
      } else {
        toast.error(res.error || "Error al desvincular OneDrive");
      }
    } catch (err: any) {
      toast.error(err.message || "Error al desvincular OneDrive");
    } finally {
      setIsLoading(false);
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 5 * 1024 * 1024) {
        toast.error("La imagen no debe superar los 5MB");
        return;
    }

    setIsLoading(true);
    const supabase = createClient();

    // Upload with standard name (overwrite usually handled by uuid specific names or upsert)
    // We append timestamp to avoid cache issues
    const fileExt = file.name.split('.').pop();
    const fileName = `${user.id}-${Date.now()}.${fileExt}`;
    const filePath = `${fileName}`;

    const { error: uploadError } = await supabase.storage
        .from('avatars')
        .upload(filePath, file);

    if (uploadError) {
        console.error(uploadError);
        toast.error("Error al subir la imagen");
        setIsLoading(false);
        return;
    }

    const { data: { publicUrl } } = supabase.storage
        .from('avatars')
        .getPublicUrl(filePath);

    const result = await updateAvatar(publicUrl);

    setIsLoading(false);

    if (result.error) {
        toast.error(result.error);
    } else {
        setAvatarUrl(publicUrl);
        toast.success("Foto de perfil actualizada");
    }
  };

  return (
      <div className="space-y-8 pb-20 animate-in fade-in zoom-in duration-500">

        {/* HERO HEADER SECTION */}
        <div className="relative w-full bg-white dark:bg-gradient-to-r dark:from-[#12161C] dark:to-[#0A0D11] border border-gray-200 dark:border-white/5 rounded-3xl p-8 overflow-hidden shadow-xl shadow-black/5 dark:shadow-2xl">
             {/* Background glow effects */}
             <div className="absolute top-0 right-0 w-2/3 h-full bg-[var(--engine-accent)]/5 blur-3xl pointer-events-none" />
             <div className="absolute bottom-0 left-0 w-1/3 h-2/3 bg-blue-500/5 blur-3xl pointer-events-none" />

             <div className="relative z-10 flex flex-col lg:flex-row items-start lg:items-center gap-8">
                 {/* Avatar */}
                 <div className="relative group shrink-0">
                     <div className="w-32 h-32 rounded-3xl bg-gray-100 dark:bg-[#1A2029] border border-gray-200 dark:border-white/5 flex items-center justify-center text-4xl font-bold text-gray-400 dark:text-slate-300 shadow-xl group-hover:border-[var(--engine-accent)]/30 transition-colors overflow-hidden relative">
                        {avatarUrl ? (
                            <img src={avatarUrl} alt="Profile" className="w-full h-full object-cover" />
                        ) : (
                            profile?.first_name?.[0] || user?.email?.[0]?.toUpperCase()
                        )}
                     </div>
                     <input
                        type="file"
                        ref={fileInputRef}
                        onChange={handleImageUpload}
                        hidden
                        accept="image/*"
                     />
                     <button
                        onClick={() => fileInputRef.current?.click()}
                        type="button"
                        className="absolute -bottom-3 -right-3 bg-[var(--engine-accent)] text-white dark:text-black p-2.5 rounded-xl hover:scale-110 transition-transform shadow-lg shadow-[var(--engine-accent)]/20 cursor-pointer border border-white dark:border-transparent z-10"
                     >
                        <Camera size={18} />
                     </button>
                 </div>

                 {/* User Info */}
                 <div className="flex-1 space-y-3">
                     <div>
                        <h1 className="text-3xl font-bold text-gray-900 dark:text-white tracking-tight">
                            {formData.firstName} {formData.lastNameFather}
                        </h1>
                        <p className="text-gray-500 dark:text-slate-400 font-medium flex items-center gap-2 mt-1">
                            <Shield size={14} className="text-[var(--engine-accent)]" />
                            {profile?.platform_role === 'ADMIN' ? 'CTO / Director(a) de Tecnología' : 'Miembro de Plataforma'}
                        </p>
                     </div>

                     <div className="flex flex-wrap items-center gap-x-6 gap-y-2 text-xs text-gray-500 dark:text-slate-500 font-medium pt-2">
                        <span className="flex items-center gap-2">
                             <Calendar size={14} />
                             {memberSinceLabel
                               ? `Miembro desde ${memberSinceLabel}`
                               : 'Fecha de registro no disponible'}
                        </span>
                        <span className="flex items-center gap-2 text-emerald-500 dark:text-green-400">
                             <CheckCircle2 size={14} />
                             Email verificado
                        </span>
                     </div>
                 </div>

                 {/* Stats Cards (Right side) */}
                     <div className="bg-gray-50 dark:bg-[var(--engine-surface-solid)] border border-gray-100 dark:border-white/5 rounded-2xl p-4 text-center min-w-[110px] hover:bg-gray-100 dark:hover:bg-[#1A2029] transition-colors cursor-default">
                        <FileCode size={20} className="mx-auto text-[var(--engine-accent)] mb-2" />
                        <div className="text-2xl font-bold text-gray-900 dark:text-white">{artifactCount}</div>
                        <div className="text-[10px] text-gray-500 dark:text-slate-500 uppercase tracking-wider font-semibold">Artefactos</div>
                     </div>
             </div>
        </div>

        {/* NAVIGATION TABS */}
        <div className="flex items-center gap-2 mt-8">
             <button
                onClick={() => setActiveSection('general')}
                className={`px-6 py-2.5 rounded-full text-sm font-medium transition-all flex items-center gap-2 border ${activeSection === 'general' ? 'bg-[var(--engine-accent)]/10 text-[var(--engine-accent)] border-[var(--engine-accent)]/20' : 'bg-transparent border-transparent text-gray-500 hover:text-gray-900 hover:bg-gray-100 dark:text-slate-500 dark:hover:text-white dark:hover:bg-white/5'}`}
             >
                <User size={16} /> Información Personal
             </button>
             <button
                onClick={() => setActiveSection('security')}
                className={`px-6 py-2.5 rounded-full text-sm font-medium transition-all flex items-center gap-2 border ${activeSection === 'security' ? 'bg-[var(--engine-accent)]/10 text-[var(--engine-accent)] border-[var(--engine-accent)]/20' : 'bg-transparent border-transparent text-gray-500 hover:text-gray-900 hover:bg-gray-100 dark:text-slate-500 dark:hover:text-white dark:hover:bg-white/5'}`}
             >
                <Shield size={16} /> Seguridad
             </button>
        </div>

        {/* CONTENT AREA */}
        <AnimatePresence mode='wait'>
            {activeSection === 'general' && (
                 <motion.form
                    key="general"
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                    transition={{ duration: 0.2 }}
                    onSubmit={handleSubmitProfile}
                    className="space-y-6"
                 >
                    {/* Grid Layout Inputs */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
                        <BoxInput label="Nombre" name="firstName" value={formData.firstName} onChange={handleProfileChange} icon={User} />
                        <BoxInput label="Apellido" name="lastNameFather" value={formData.lastNameFather} onChange={handleProfileChange} icon={User} />
                        <BoxInput label="Nombre de Usuario" name="username" value={formData.username} onChange={handleProfileChange} icon={User} />
                    </div>

                    {/* Floating Save Button */}
                     <div className="fixed bottom-6 right-8 z-50">
                        <button
                            type="submit"
                            disabled={isLoading}
                            className="flex items-center gap-3 bg-white dark:bg-[var(--engine-canvas)] hover:bg-gray-50 dark:hover:bg-[var(--engine-surface-solid)] text-gray-900 dark:text-white border border-gray-200 dark:border-[var(--engine-accent)]/30 px-6 py-3 rounded-xl font-medium shadow-2xl shadow-black/10 dark:shadow-black/50 transition-all hover:-translate-y-1 hover:border-[var(--engine-accent)]"
                        >
                             {isLoading ? <Loader2 size={18} className="animate-spin text-[var(--engine-accent)]" /> : <Save size={18} className="text-[var(--engine-accent)]" />}
                             <span className="text-sm">Guardar cambios</span>
                        </button>
                    </div>

                 </motion.form>
            )}

            {activeSection === 'security' && (
                 <motion.div
                    key="security"
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                    className="w-full"
                 >
                     <div className="bg-white dark:bg-[var(--engine-surface-solid)] border border-gray-200 dark:border-white/5 rounded-3xl p-8 backdrop-blur-sm relative overflow-hidden shadow-sm">

                        <div className="flex items-start justify-between mb-8 relative z-10">
                            <div>
                                <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-2">Cambiar Contraseña</h3>
                                <p className="text-sm text-gray-500 dark:text-slate-400">Asegúrate de usar una contraseña segura.</p>
                            </div>
                            <div className="p-3 bg-gray-100 dark:bg-white/5 rounded-xl text-[var(--engine-accent)]">
                                <Key size={24} />
                            </div>
                        </div>

                         <form onSubmit={handleSubmitPassword} className="space-y-6 relative z-10 w-full">
                            <BoxInput
                                label="Contraseña Actual"
                                type={showPassword ? "text" : "password"}
                                name="currentPassword"
                                value={passwordData.currentPassword}
                                onChange={handlePasswordChange}
                                icon={Lock}
                            />

                            <div className="grid grid-cols-2 gap-4">
                                <BoxInput
                                    label="Nueva Contraseña"
                                    type={showPassword ? "text" : "password"}
                                    name="newPassword"
                                    value={passwordData.newPassword}
                                    onChange={handlePasswordChange}
                                    icon={Lock}
                                />
                                <BoxInput
                                    label="Confirmar"
                                    type={showPassword ? "text" : "password"}
                                    name="confirmPassword"
                                    value={passwordData.confirmPassword}
                                    onChange={handlePasswordChange}
                                    icon={Lock}
                                />
                            </div>

                            <div className="flex items-center justify-between pt-4">
                                <button type="button" onClick={() => setShowPassword(!showPassword)} className="text-xs text-gray-500 hover:text-gray-900 dark:text-slate-400 dark:hover:text-white flex items-center gap-2 transition-colors">
                                    {showPassword ? <EyeOff size={14} /> : <Eye size={14} />}
                                    {showPassword ? 'Ocultar caracteres' : 'Mostrar caracteres'}
                                </button>

                                <button
                                    type="submit"
                                    disabled={isLoading}
                                    className="bg-[var(--engine-accent)] hover:bg-[#00bda0] text-white dark:text-black px-6 py-2.5 rounded-xl font-bold text-sm transition-colors shadow-lg shadow-[var(--engine-accent)]/20"
                                >
                                    {isLoading ? 'Actualizando...' : 'Actualizar Clave'}
                                </button>
                            </div>
                         </form>
                     </div>
                 </motion.div>
            )}

            {activeSection === 'integrations' && (
                 <motion.div
                    key="integrations"
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                    className="w-full"
                 >
                      <div className="bg-white dark:bg-[var(--engine-surface-solid)] border border-gray-200 dark:border-white/5 rounded-3xl p-8 backdrop-blur-sm relative overflow-hidden shadow-sm">

                         <div className="flex items-start justify-between mb-8 relative z-10">
                             <div>
                                 <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-2">Integraciones de Terceros</h3>
                                 <p className="text-sm text-gray-500 dark:text-slate-400">Conecta herramientas externas para potenciar tu flujo de creación.</p>
                             </div>
                             <div className="p-3 bg-gray-100 dark:bg-white/5 text-[var(--engine-accent)] rounded-xl">
                                 <HardDrive size={24} />
                             </div>
                         </div>

                         <div className="border border-gray-150 dark:border-white/5 rounded-2xl p-6 bg-gray-50/50 dark:bg-[#1A2029]/40 relative z-10 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-6 transition-all hover:border-[var(--engine-accent)]/20">
                             <div className="flex items-start gap-4">
                                 <div className="w-12 h-12 rounded-xl bg-[var(--engine-accent)]/10 flex items-center justify-center text-[var(--engine-accent)] shrink-0">
                                     <HardDrive size={24} />
                                 </div>
                                 <div>
                                     <h4 className="text-gray-900 dark:text-white font-bold text-base">Google Drive</h4>
                                     <p className="text-xs text-gray-500 dark:text-slate-400 mt-1 max-w-md">
                                         Permite a {APP_CONFIG.name} crear carpetas organizadas y estructuradas para tus talleres y leer tus recursos de forma directa.
                                     </p>
                                     {isGoogleConnected && (
                                         <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-[10px] font-medium bg-emerald-500/10 text-emerald-500 mt-2 border border-emerald-500/25">
                                             <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                                             Conectado como {googleEmailAddress}
                                         </span>
                                     )}
                                 </div>
                             </div>

                             <div className="shrink-0">
                                 {isGoogleConnected ? (
                                     <button
                                         type="button"
                                         onClick={handleDisconnectGoogle}
                                         disabled={isLoading}
                                         className="w-full sm:w-auto px-5 py-2.5 rounded-xl border border-red-500/30 text-red-500 hover:bg-red-500/5 dark:hover:bg-red-500/10 transition-colors font-medium text-sm cursor-pointer"
                                     >
                                         Desvincular
                                     </button>
                                 ) : (
                                     <CloudStorageConnectButton
                                         provider="google_drive"
                                         className="inline-flex justify-center items-center w-full sm:w-auto px-5 py-2.5 rounded-xl bg-[var(--engine-accent)] hover:bg-[#00bda0] text-white dark:text-black font-bold text-sm transition-colors shadow-lg shadow-[var(--engine-accent)]/15 text-center cursor-pointer"
                                     >
                                         Vincular Cuenta
                                     </CloudStorageConnectButton>
                                 )}
                             </div>
                         </div>

                         <div className="mt-4 border border-gray-150 dark:border-white/5 rounded-2xl p-6 bg-gray-50/50 dark:bg-[#1A2029]/40 relative z-10 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-6 transition-all hover:border-[var(--engine-accent)]/20">
                             <div className="flex items-start gap-4">
                                 <div className="w-12 h-12 rounded-xl bg-[var(--engine-accent)]/10 flex items-center justify-center text-[var(--engine-accent)] shrink-0">
                                     <HardDrive size={24} />
                                 </div>
                                 <div>
                                     <h4 className="text-gray-900 dark:text-white font-bold text-base">OneDrive</h4>
                                     <p className="text-xs text-gray-500 dark:text-slate-400 mt-1 max-w-md">
                                         Permite crear carpetas de trabajo en OneDrive e importar assets hacia el almacenamiento principal de {APP_CONFIG.name}.
                                     </p>
                                     {isOneDriveConnected && (
                                         <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-[10px] font-medium bg-emerald-500/10 text-emerald-500 mt-2 border border-emerald-500/25">
                                             <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                                             Conectado como {oneDriveEmailAddress}
                                         </span>
                                     )}
                                 </div>
                             </div>

                             <div className="shrink-0">
                                 {isOneDriveConnected ? (
                                     <button
                                         type="button"
                                         onClick={handleDisconnectOneDrive}
                                         disabled={isLoading}
                                         className="w-full sm:w-auto px-5 py-2.5 rounded-xl border border-red-500/30 text-red-500 hover:bg-red-500/5 dark:hover:bg-red-500/10 transition-colors font-medium text-sm cursor-pointer"
                                     >
                                         Desvincular
                                     </button>
                                 ) : (
                                     <CloudStorageConnectButton
                                         provider="onedrive"
                                         className="inline-flex justify-center items-center w-full sm:w-auto px-5 py-2.5 rounded-xl bg-[var(--engine-accent)] hover:bg-[#00bda0] text-white dark:text-black font-bold text-sm transition-colors shadow-lg shadow-[var(--engine-accent)]/15 text-center cursor-pointer"
                                     >
                                         Vincular Cuenta
                                     </CloudStorageConnectButton>
                                 )}
                             </div>
                         </div>
                      </div>
                 </motion.div>
            )}
        </AnimatePresence>
      </div>
  );
}

