interface TemplateModifiers {
  cornerRadius: number;
  density: "compact" | "comfortable" | "spacious";
  fontPairing: "system_sans" | "editorial_serif" | "technical_mono";
  font?: { family: string; source: "google" | "uploaded"; cssUrl?: string; fontAssetId?: string; googleNativePin?: GoogleFontNativePin };
  showBrandMark: boolean;
}

interface OrganizationSlideFont {
  id: string;
  family: string;
  source: "google" | "uploaded";
  cssUrl?: string;
  renderEligible?: boolean;
}

function organizationFontIdentity(font: Pick<OrganizationSlideFont, "family" | "source">) {
  return `${font.source}:${font.family.trim().toLowerCase()}`;
}

function mergeOrganizationFonts(fonts: OrganizationSlideFont[]) {
  const fontsByIdentity = new Map<string, OrganizationSlideFont>();
  for (const font of fonts) {
    const identity = organizationFontIdentity(font);
    if (!fontsByIdentity.has(identity)) {
      fontsByIdentity.set(identity, font);
    }
  }
  return [...fontsByIdentity.values()];
}

interface TemplateLayout {
  id: SlideLayoutId;
  label: string;
  purpose: string;
  regions: string[];
}

interface TemplateSlideType {
  defaultLayout: SlideLayoutId;
  id: SlideTypeId;
  label: string;
  purpose: string;
  requiredContent: string[];
}

interface SlideTemplateSpec {
  artifactKind: "slide_template";
  changeSummary: string;
  description: string;
  packageId: string;
  templateBlueprint?: {
    designTokens: DesignTokens;
    layouts: TemplateLayout[];
    modifiers: TemplateModifiers;
    slideTypes: TemplateSlideType[];
  };
  title: string;
}

