      importedAsset: result,
      importType: type,
      organizationId: tenant.organizationId,
      provider: "google_drive",
      supabase: admin,
    });

    const currentAssets = authorizedComponent.component.assets || {};
    const assetsPatch: Record<string, unknown> = {};

