function buildDodChecklist(
  assets: Partial<MaterialAssets>,
): ProductionDodChecklist {
  const hasAnimatedDeck = assets.slides?.animated_deck?.status === "READY_FOR_RENDER";
  return {
    has_slides_url: Boolean(assets.slides_url || hasAnimatedDeck),
    has_video_url: Boolean(assets.video_url),
    has_screencast_url: Boolean(assets.screencast_url),
    has_b_roll_prompts: Boolean(assets.b_roll_prompts),
    has_final_video_url: Boolean(assets.final_video_url),
  };
}

function hasRenderableSlides(assets: Partial<MaterialAssets>) {
  return Boolean(
    assets.slides?.animated_deck?.status === "READY_FOR_RENDER" ||
      assets.slides?.animated_deck?.status === "READY_FOR_PREVIEW" ||
      assets.slides?.images?.length ||
      assets.slides_url,
  );
}

function resolveProductionStatus(
  componentType: string,
  assets: Partial<MaterialAssets> = {},
): ProductionStatus {
  // Si ya existe el video final (subido o enlazado), el asset de producción
  // se considera COMPLETADO directamente en tiempo real.
  if (assets.final_video_url) {
    return "COMPLETED";
  }

  const needsSlides =
    componentType === "VIDEO_THEORETICAL" || componentType === "VIDEO_GUIDE";
  const needsScreencast =
    componentType === "DEMO_GUIDE" || componentType === "VIDEO_GUIDE";
  const needsVoice = componentType.includes("VIDEO");
  
  // A talking head avatar is generally required for theoretical explanation videos
  const needsAvatar = componentType === "VIDEO_THEORETICAL";
  const hasCompletedAvatarClips = Boolean(
    assets.avatar_clips?.some((clip) => clip.status === "COMPLETED" && clip.public_url),
  );
  const hasAvatarAsset = Boolean(assets.avatar_video?.public_url || hasCompletedAvatarClips);
  const hasCompletedVoiceClips = Boolean(
    assets.voice_clips?.some((clip) => clip.status === "COMPLETED" && clip.public_url),
  );

  const hasRequiredSlides = !needsSlides || hasRenderableSlides(assets);
  const hasRequiredScreencast = !needsScreencast || Boolean(assets.screencast_url);
  const hasRequiredVoice = !needsVoice || Boolean(
    assets.voice_audio?.public_url ||
    assets.manual_voice_clips?.some((clip) => clip.public_url) ||
    hasCompletedVoiceClips ||
    assets.avatar_video?.public_url || 
    hasCompletedAvatarClips ||
    assets.video_url
  );
  const hasRequiredAvatar = !needsAvatar || hasAvatarAsset;
  
  // Clips are ready if we have video clips uploaded or generated prompts for them
  const hasRequiredClips = !needsVoice || Boolean(assets.b_roll_clips?.length || assets.b_roll_prompts);

  if (
    hasRequiredSlides &&
    hasRequiredScreencast &&
    hasRequiredVoice &&
    hasRequiredAvatar &&
    hasRequiredClips
  ) {
    return "IN_PROGRESS";
  }

  if (
    hasRenderableSlides(assets) ||
    Boolean(assets.screencast_url) ||
    Boolean(assets.voice_audio?.public_url || assets.manual_voice_clips?.some((clip) => clip.public_url) || hasCompletedVoiceClips || assets.video_url) ||
    hasAvatarAsset ||
    Boolean(assets.b_roll_clips?.length || assets.b_roll_prompts)
  ) {
    return "IN_PROGRESS";
  }

  return "PENDING";
}

function buildGammaDeckId(params: {
  componentType: string;
  currentAssets: Partial<MaterialAssets>;
  lesson?: ProductionLessonRelation;
}) {
  const { componentType, currentAssets, lesson } = params;
  if (currentAssets.gamma_deck_id || !lesson) {
    return currentAssets.gamma_deck_id;
  }

  const materials = firstRelation(lesson.materials);
  const artifact = firstRelation(materials?.artifacts);
  const courseId = artifact?.course_id || "CRS";
  const lessonNumMatch = lesson.lesson_title.match(/^(\d+(\.\d+)*)/);
  const lessonNum = lessonNumMatch
    ? lessonNumMatch[0]
    : `L${lesson.lesson_id.substring(0, 4)}`;

  const typeMap: Record<string, string> = {
    VIDEO_THEORETICAL: "VTH",
    VIDEO_GUIDE: "VGD",
    VIDEO_DEMO: "VDM",
    DEMO_GUIDE: "DG",
    QUIZ: "QZ",
  };
  const typeCode = typeMap[componentType] || "UNK";
  const suffix = Math.random().toString(36).substring(2, 5).toUpperCase();

  return `${courseId}-${lessonNum}-${typeCode}-${suffix}`;
}

function isProductionComplete(_componentType: string, assets?: MaterialAssets | null) {
  return assets?.production_status === "COMPLETED";
}

function isPositiveNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value) && value > 0;
}

function resolveTimelineOverrideCanonicalDurationSeconds(
  assets: MaterialAssets,
  manifests: TimelineOverrideManifest[],
) {
  const normalized = normalizeAssemblyAssets(assets, ASSEMBLY_FPS);
  if (isPositiveNumber(assets.assembly_target_duration_seconds)) {
    return assets.assembly_target_duration_seconds;
  }
  if (normalized.totalDurationSeconds > 0) {
    return normalized.totalDurationSeconds;
  }

  const manifestDuration = manifests.find((manifest) =>
    isPositiveNumber(manifest.timeline.fps) &&
    isPositiveNumber(manifest.timeline.durationInFrames)
  );
  if (manifestDuration) {
    return manifestDuration.timeline.durationInFrames / manifestDuration.timeline.fps;
  }

  return ASSEMBLY_FALLBACK_DURATION_SECONDS;
}

type TimedAssetRecord = {
  duration?: unknown;
  public_url?: unknown;
  storage_path?: unknown;
  [key: string]: unknown;
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function hasOwnProperty<T extends object, K extends PropertyKey>(
  value: T,
  key: K,
): value is T & Record<K, unknown> {
  return Object.prototype.hasOwnProperty.call(value, key);
}

function assetReferenceKey(asset: unknown) {
  if (!isRecord(asset)) {
    return "";
  }

  const publicUrl = typeof asset.public_url === "string" ? asset.public_url.trim() : "";
  const storagePath = typeof asset.storage_path === "string" ? asset.storage_path.trim() : "";
  return `${publicUrl}|${storagePath}`;
}

function incomingHasOwnDuration(asset: unknown) {
  return isRecord(asset) && hasOwnProperty(asset, "duration");
}

function sanitizeTimedAssetDuration(
  currentAsset: unknown,
  incomingAsset: unknown,
  mergedAsset: unknown,
) {
  if (!isRecord(mergedAsset)) {
    return mergedAsset;
  }

  const referenceChanged = assetReferenceKey(currentAsset) !== assetReferenceKey(mergedAsset);
  if (!referenceChanged || incomingHasOwnDuration(incomingAsset)) {
    return mergedAsset;
  }

  const cleaned: TimedAssetRecord = { ...mergedAsset };
  delete cleaned.duration;
  return cleaned;
}

function sanitizeBrollClipDurations(
  currentClips: MaterialAssets["b_roll_clips"],
  incomingClips: MaterialAssets["b_roll_clips"] | null | undefined,
  mergedClips: MaterialAssets["b_roll_clips"] | null | undefined,
) {
  if (!Array.isArray(mergedClips)) {
    return mergedClips;
  }

  const currentById = new Map(
    (currentClips || []).map((clip) => [clip.id, clip] as const),
  );
  const incomingById = new Map(
    (incomingClips || []).map((clip) => [clip.id, clip] as const),
  );

  return mergedClips.map((clip) => {
    const currentClip = currentById.get(clip.id);
    const incomingClip = incomingById.get(clip.id);
    return sanitizeTimedAssetDuration(currentClip, incomingClip, clip) as NonNullable<
      MaterialAssets["b_roll_clips"]
    >[number];
  });
}

function sanitizeAvatarClipDurations(
  currentClips: MaterialAssets["avatar_clips"],
  incomingClips: MaterialAssets["avatar_clips"] | null | undefined,
  mergedClips: MaterialAssets["avatar_clips"] | null | undefined,
) {
  if (!Array.isArray(mergedClips)) {
