    >[number];
  });
}

function sanitizeVoiceClipDurations(
  currentClips: MaterialAssets["voice_clips"],
  incomingClips: MaterialAssets["voice_clips"] | null | undefined,
  mergedClips: MaterialAssets["voice_clips"] | null | undefined,
) {
  if (!Array.isArray(mergedClips)) return mergedClips;
  const currentById = new Map(
    (currentClips || []).map((clip) => [clip.id, clip] as const),
  );
  const incomingById = new Map(
    (incomingClips || []).map((clip) => [clip.id, clip] as const),
  );
  return mergedClips.map((clip) => sanitizeTimedAssetDuration(
    currentById.get(clip.id),
    incomingById.get(clip.id),
    clip,
  ) as NonNullable<MaterialAssets["voice_clips"]>[number]);
}

function buildMaterialAssetsPatch(
  currentAssetsValue: object,
  nextAssetsValue: object,
) {
  const currentAssets = currentAssetsValue as Record<string, unknown>;
  const nextAssets = nextAssetsValue as Record<string, unknown>;
  const patch: Record<string, unknown> = {};
  const keys = new Set([...Object.keys(currentAssets), ...Object.keys(nextAssets)]);
  for (const key of keys) {
    if (!(key in nextAssets)) {
      patch[key] = null;
      continue;
    }
    if (JSON.stringify(currentAssets[key]) !== JSON.stringify(nextAssets[key])) {
      patch[key] = nextAssets[key] ?? null;
    }
  }
  return patch;
}

function sanitizeManualVoiceClipDurations(
  currentClips: MaterialAssets["manual_voice_clips"],
  incomingClips: MaterialAssets["manual_voice_clips"] | null | undefined,
  mergedClips: MaterialAssets["manual_voice_clips"] | null | undefined,
) {
  if (!Array.isArray(mergedClips)) return mergedClips;
  const currentById = new Map((currentClips || []).map((clip) => [clip.id, clip] as const));
  const incomingById = new Map((incomingClips || []).map((clip) => [clip.id, clip] as const));
  return mergedClips.map((clip) => sanitizeTimedAssetDuration(
    currentById.get(clip.id),
    incomingById.get(clip.id),
    clip,
  ) as NonNullable<MaterialAssets["manual_voice_clips"]>[number]);
}

function sourceSignature(assets: Partial<MaterialAssets>) {
  const broll = (assets.b_roll_clips || []).map((clip) => ({
    id: clip.id,
    order: clip.order,
    ref: assetReferenceKey(clip),
  }));
  const avatarClips = (assets.avatar_clips || []).map((clip) => ({
    id: clip.id,
    order: clip.order,
    ref: assetReferenceKey(clip),
    status: clip.status,
  }));
  const voiceClips = (assets.voice_clips || []).map((clip) => ({
    clipId: clip.clip_id,
    id: clip.id,
    order: clip.order,
    ref: assetReferenceKey(clip),
    scriptHash: clip.script_hash,
    status: clip.status,
  }));
  const manualVoiceClips = (assets.manual_voice_clips || []).map((clip) => ({
    id: clip.id,
    order: clip.order,
    ref: assetReferenceKey(clip),
  }));
  const slideImages = (assets.slides?.images || []).map((slide) => ({
    index: slide.slide_index,
    ref: assetReferenceKey(slide),
  }));

  return JSON.stringify({
    voice: assetReferenceKey(assets.voice_audio),
    manualVoiceClips,
    voiceClips,
    avatar: assetReferenceKey(assets.avatar_video),
    avatarGenerationMode: assets.avatar_generation_mode || "",
    avatarClips,
    backgroundMusic: assetReferenceKey(assets.background_music),
    broll,
    slidesUrl: assets.slides_url || "",
    slidesHtmlUrl: assets.slides?.html_public_url || "",
    slidesHtmlPath: assets.slides?.html_content_path || "",
    slideImages,
    videoUrl: assets.video_url || "",
    screencastUrl: assets.screencast_url || "",
    assemblyTargetDurationSeconds:
      typeof assets.assembly_target_duration_seconds === "number"
        ? assets.assembly_target_duration_seconds
        : null,
  });
}

function clearFinalVideoMetadata(assets: MaterialAssets) {
  const cleaned = { ...assets };
  delete (cleaned as any).final_video_url;
  delete (cleaned as any).final_video_source;
  delete (cleaned as any).final_video_file_name;
  delete (cleaned as any).final_video_storage_provider;
  delete (cleaned as any).final_video_storage_path;
  delete (cleaned as any).final_video_source_storage_path;
  delete (cleaned as any).final_video_url_expires_at;
  delete (cleaned as any).final_video_layout_stale;
  delete (cleaned as any).final_video_assembly_stale;
  delete (cleaned as any).video_duration;
  delete (cleaned as any).assembly_target_duration_seconds;
  delete (cleaned as any).layout_overrides;
  delete (cleaned as any).layout_overrides_updated_at;
  delete (cleaned as any).timeline_overrides;
  delete (cleaned as any).timeline_overrides_updated_at;
  return cleaned;
}

function slideSourceSignature(assets: Partial<MaterialAssets>) {
  return JSON.stringify({
    slidesUrl: assets.slides_url || "",
    htmlUrl: assets.slides?.html_public_url || "",
    htmlPath: assets.slides?.html_content_path || "",
    images: (assets.slides?.images || []).map((slide) => ({
      index: slide.slide_index,
      ref: assetReferenceKey(slide),
    })),
  });
}

function normalizeProductionStoragePath(value: unknown) {
  if (typeof value !== "string") return null;
  const normalized = value.trim().replace(/^\/+/, "");
  if (!normalized || /^https?:\/\//i.test(normalized)) return null;
  return normalized.startsWith("production-assets/")
    ? normalized.slice("production-assets/".length)
    : normalized;
}

function collectProductionStoragePaths(assets: Partial<MaterialAssets>) {
  const paths = new Set<string>();
  const add = (value: unknown) => {
    const path = normalizeProductionStoragePath(value);
    if (path) paths.add(path);
  };

  add(assets.voice_audio?.storage_path);
  for (const clip of assets.manual_voice_clips || []) add(clip.storage_path);
  for (const clip of assets.voice_clips || []) add(clip.storage_path);
  add(assets.background_music?.storage_path);
  for (const clip of assets.b_roll_clips || []) add(clip.storage_path);
  add(assets.avatar_video?.storage_path);
  for (const clip of assets.avatar_clips || []) add(clip.storage_path);
  add(assets.slides?.html_content_path);
  add(assets.slides?.qa_content_path);
  add(assets.slides?.spec_content_path);
  for (const image of assets.slides?.images || []) add(image.storage_path);
  add(assets.slides?.animated_deck?.source_html_path);
  add(assets.slides?.animated_deck?.deck_json_path);
  add(assets.slides?.animated_deck?.deck_css_path);
  for (const remote of assets.slides?.animated_deck?.remote_assets || []) add(remote.storage_path);
  add((assets as any).final_video_storage_path);
  add((assets as any).final_video_source_storage_path);
  add(assets.png_export_path);

  return paths;
}

async function cleanupOrphanedProductionStorage(
  supabase: Awaited<ReturnType<typeof getServiceRoleClient>>,
  previousAssets: Partial<MaterialAssets>,
  nextAssets: Partial<MaterialAssets>,
) {
  const nextPaths = collectProductionStoragePaths(nextAssets);
  const orphanedPaths = [...collectProductionStoragePaths(previousAssets)]
    .filter((path) => !nextPaths.has(path));
  if (orphanedPaths.length === 0) return;

  let lastError: unknown = null;
  for (let attempt = 0; attempt < 2; attempt += 1) {
    const { error } = await supabase.storage
      .from("production-assets")
      .remove(orphanedPaths);
    if (!error) {
      const persistedPaths = orphanedPaths.flatMap((path) => [
        path,
        `production-assets/${path}`,
      ]);
      const { error: archiveError } = await supabase
        .from("production_assets")
        .update({
          public_url: null,
          qa_status: PRODUCTION_QA_STATUSES.ARCHIVED,
        })
        .eq("storage_bucket", "production-assets")
        .in("storage_path", persistedPaths)
        .neq("qa_status", PRODUCTION_QA_STATUSES.ARCHIVED);
      if (archiveError) {
        console.error(
          "[ProductionActions] Storage objects removed but asset rows could not be archived:",
          archiveError,
        );
      }
      return;
    }
    lastError = error;
  }

  console.error("[ProductionActions] Error cleaning orphaned production assets:", lastError);
}

function sanitizeMaterialAssetMetadata(params: {
  currentAssets: MaterialAssets;
  incomingAssets: Partial<MaterialAssets>;
  mergedAssets: MaterialAssets;
}) {
  const { currentAssets, incomingAssets } = params;
  let sanitizedAssets: MaterialAssets = { ...params.mergedAssets };

  if (hasOwnProperty(incomingAssets, "voice_audio")) {
    sanitizedAssets.voice_audio = sanitizeTimedAssetDuration(
      currentAssets.voice_audio,
      incomingAssets.voice_audio,
      sanitizedAssets.voice_audio,
    ) as MaterialAssets["voice_audio"];
  }

  if (hasOwnProperty(incomingAssets, "manual_voice_clips")) {
    sanitizedAssets.manual_voice_clips = sanitizeManualVoiceClipDurations(
      currentAssets.manual_voice_clips,
      incomingAssets.manual_voice_clips,
      sanitizedAssets.manual_voice_clips,
    ) as MaterialAssets["manual_voice_clips"];
  }

  if (hasOwnProperty(incomingAssets, "voice_clips")) {
    sanitizedAssets.voice_clips = sanitizeVoiceClipDurations(
      currentAssets.voice_clips,
      incomingAssets.voice_clips,
      sanitizedAssets.voice_clips,
    ) as MaterialAssets["voice_clips"];
  }

  if (hasOwnProperty(incomingAssets, "avatar_video")) {
    sanitizedAssets.avatar_video = sanitizeTimedAssetDuration(
      currentAssets.avatar_video,
      incomingAssets.avatar_video,
      sanitizedAssets.avatar_video,
    ) as MaterialAssets["avatar_video"];
  }

  if (hasOwnProperty(incomingAssets, "background_music")) {
    sanitizedAssets.background_music = sanitizeTimedAssetDuration(
      currentAssets.background_music,
      incomingAssets.background_music,
      sanitizedAssets.background_music,
    ) as MaterialAssets["background_music"];
  }

  if (hasOwnProperty(incomingAssets, "b_roll_clips")) {
    sanitizedAssets.b_roll_clips = sanitizeBrollClipDurations(
      currentAssets.b_roll_clips,
      incomingAssets.b_roll_clips,
      sanitizedAssets.b_roll_clips,
    ) as MaterialAssets["b_roll_clips"];
  }

  if (hasOwnProperty(incomingAssets, "avatar_clips")) {
    sanitizedAssets.avatar_clips = sanitizeAvatarClipDurations(
      currentAssets.avatar_clips,
      incomingAssets.avatar_clips,
      sanitizedAssets.avatar_clips,
    ) as MaterialAssets["avatar_clips"];
  }

  if (slideSourceSignature(currentAssets) !== slideSourceSignature(sanitizedAssets)) {
    delete (sanitizedAssets as any).gamma_deck_id;
    delete (sanitizedAssets as any).png_export_path;
  }

  if (sourceSignature(currentAssets) !== sourceSignature(sanitizedAssets)) {
    sanitizedAssets = clearFinalVideoMetadata(sanitizedAssets);
  }

  return sanitizedAssets;
}


async function getAuthorizedSupabase() {
  const supabase = await createClient();
  const authenticatedUser = await getAuthenticatedUser(supabase);

  if (!authenticatedUser) {
    return { error: "Unauthorized" as const, supabase, user: null };
  }

  // Use service role for admin DB operations — consistent with admin pattern
  // in artifact-action-auth.ts and required when Auth Bridge users have no GoTrue session
  return { error: null, supabase: getServiceRoleClient(), user: authenticatedUser };
}

export async function generateVideoPromptsAction(
  componentId: string,
  storyboard: StoryboardItem[],
) {
  const supabase = await createClient();
  const userToken = await getAccessToken(supabase);
  if (!userToken) return { success: false, error: "Unauthorized" };

  try {
    const authenticatedUser = await getAuthenticatedUser(supabase);
    if (!authenticatedUser) {
      return { success: false, error: "Unauthorized" };
    }

    const admin = getServiceRoleClient();
    const context = await resolveProductionComponentContext({
      componentId,
      supabase: admin,
    });
    const inputSnapshot = buildBrollPromptJobInputSnapshot({
      componentId,
      storyboard,
      videoDurationContract: context.videoDurationContract,
    });
    const productionJob = await createOrReuseProductionJob(admin, {
      context,
      createdBy: authenticatedUser.userId,
      idempotencyKey: buildProductionIdempotencyKey({
        componentId,
        input: inputSnapshot,
        jobType: PRODUCTION_JOB_TYPES.BROLL_PROMPT_GENERATION,
        provider: PRODUCTION_PROVIDERS.GEMINI,
      }),
      inputSnapshot,
      jobType: PRODUCTION_JOB_TYPES.BROLL_PROMPT_GENERATION,
      provider: PRODUCTION_PROVIDERS.GEMINI,
      providerModel: "gemini-3.5-flash",
    });

    if (
      productionJob.status === PRODUCTION_JOB_STATUSES.SUCCEEDED &&
      typeof productionJob.output_snapshot?.prompts_text === "string"
    ) {
      return {
        success: true,
        prompts: productionJob.output_snapshot.prompts_text,
      };
    }

    const data = await callBackgroundFunctionJson<{ prompts?: string }>(
      "video-prompts-generation",
      {
        componentId,
        productionJobId: productionJob.id,
        storyboard,
        userToken,
      },
      {
        fallbackError: "No se pudieron generar los prompts de video",
        localHandlerLoader: () =>
          import("../../../../netlify/functions/video-prompts-generation"),
      },
    );

    return { success: true, prompts: data.prompts || "" };
  } catch (error: unknown) {
    console.error("[ProductionActions] Error generating prompts:", error);
    return { success: false, error: getErrorMessage(error) };
  }
}

/**
 * When a video is saved in the Production step, mirror it into publication_requests.lesson_videos
 * so the Send step always has up-to-date video data without requiring manual sync.
 * Fails silently to avoid blocking the production save.
 */
async function syncVideoToPublicationRequests(
  supabase: ReturnType<typeof getServiceRoleClient>,
  artifactId: string,
  lesson: ProductionLessonRelation,
  assets: MaterialAssets,
) {
  if (!assets.final_video_url) return;

  try {
    const { provider, id: videoId } = getVideoProviderAndId(assets.final_video_url);

    const videoData: LessonVideoData = {
      lesson_id: lesson.lesson_id,
      lesson_title: lesson.lesson_title,
      module_title: lesson.module_title || "",
      video_provider: provider,
      video_id: videoId,
      duration: assets.video_duration || 0,
    };

    const { data: existingRequest } = await supabase
      .from("publication_requests")
      .select("id, lesson_videos")
      .eq("artifact_id", artifactId)
      .maybeSingle();

    const currentLessonVideos =
      (existingRequest?.lesson_videos as Record<string, LessonVideoData> | null) || {};

    const updatedLessonVideos = {
      ...currentLessonVideos,
      [lesson.lesson_id]: videoData,
    };

    if (existingRequest?.id) {
      await supabase
        .from("publication_requests")
        .update({
          lesson_videos: updatedLessonVideos,
          updated_at: new Date().toISOString(),
        })
        .eq("id", existingRequest.id);
    } else {
      await supabase.from("publication_requests").insert({
        artifact_id: artifactId,
        lesson_videos: updatedLessonVideos,
        status: "DRAFT",
        updated_at: new Date().toISOString(),
      });
    }
  } catch (error) {
    console.error("[ProductionActions] Error syncing video to publication_requests:", error);
  }
}

async function removeVideoFromPublicationRequests(
  supabase: Awaited<ReturnType<typeof getServiceRoleClient>>,
  artifactId: string,
  lessonId: string,
) {
  const { data: existingRequest } = await supabase
    .from("publication_requests")
    .select("id, lesson_videos")
    .eq("artifact_id", artifactId)
    .maybeSingle();

  if (!existingRequest?.id) return;

  const currentLessonVideos =
    (existingRequest.lesson_videos as Record<string, LessonVideoData> | null) || {};
  if (!hasOwnProperty(currentLessonVideos, lessonId)) return;

  const nextLessonVideos = { ...currentLessonVideos };
  delete nextLessonVideos[lessonId];
  await supabase
    .from("publication_requests")
    .update({
      lesson_videos: nextLessonVideos,
      updated_at: new Date().toISOString(),
    })
    .eq("id", existingRequest.id);
}

export async function saveMaterialAssetsAction(
  componentId: string,
  assets: Partial<MaterialAssets>,
) {
  const { error: authError, supabase } = await getAuthorizedSupabase();
  if (authError) return { success: false, error: authError };

  const { data: rawComponent } = await supabase
    .from("material_components")
    .select(
      `
        assets, type, material_lesson_id,
        material_lessons (
          lesson_id, lesson_title, module_title, module_id,
          materials (
            artifact_id,
            artifacts ( course_id )
          )
        )
      `,
    )
    .eq("id", componentId)
    .single();

  const component = (rawComponent || null) as ProductionComponentRecord | null;
  const currentAssets = (component?.assets || {}) as MaterialAssets;
  const { data: patchedAssets, error: patchError } = await supabase.rpc(
    "patch_material_component_assets",
    {
      p_assets_patch: assets,
      p_component_id: componentId,
    },
  );

  if (patchError) {
    console.error("[ProductionActions] Error patching material assets:", patchError);
    return { success: false, error: patchError.message };
  }

  const mergedAssets = (patchedAssets || {}) as MaterialAssets;
  const sanitizedAssets = sanitizeMaterialAssetMetadata({
    currentAssets,
    incomingAssets: assets,
    mergedAssets,
  });
  const componentType = component?.type || "";
  const lesson = firstRelation(component?.material_lessons);
  const materials = firstRelation(lesson?.materials);
  const artifactId = materials?.artifact_id || undefined;
  const dodChecklist = buildDodChecklist(sanitizedAssets);
  const productionStatus = resolveProductionStatus(componentType, sanitizedAssets);

  const finalAssets: MaterialAssets = {
    ...sanitizedAssets,
    gamma_deck_id: buildGammaDeckId({
      componentType,
      currentAssets: sanitizedAssets,
      lesson,
    }),
    production_status: productionStatus,
    dod_checklist: dodChecklist,
    updated_at: new Date().toISOString(),
  };

  // Only write the derived/sanitized top-level fields.  Replacing the full JSON
  // here would reintroduce the lost-update race fixed by the RPC above.
  const derivedPatch: Record<string, unknown> = Object.fromEntries(
    Object.entries(finalAssets).filter(([key, value]) => {
      return value !== mergedAssets[key as keyof MaterialAssets];
    }),
  );
  for (const key of Object.keys(mergedAssets)) {
    if (!hasOwnProperty(finalAssets, key)) {
      derivedPatch[key] = null;
    }
  }
  const { error: updateError } = await supabase.rpc(
    "patch_material_component_assets",
    {
      p_assets_patch: derivedPatch,
      p_component_id: componentId,
    },
  );

  if (updateError) {
    console.error("[ProductionActions] Error saving material assets:", updateError);
    return { success: false, error: updateError.message };
  }

  await cleanupOrphanedProductionStorage(supabase, currentAssets, finalAssets);

  if (artifactId && lesson?.lesson_id && currentAssets.final_video_url && !finalAssets.final_video_url) {
    await removeVideoFromPublicationRequests(supabase, artifactId, lesson.lesson_id);
  }

  if (artifactId && lesson) {
    await markDownstreamDirtyAction(
      artifactId,
      5,
      "Materiales (assets actualizados)",
    );
    await syncProductionStatusAction(artifactId);
    await logPipelineEventAction(
      artifactId,
      productionStatus === "COMPLETED"
        ? "GO-OP-06_ASSET_COMPLETED"
        : "GO-OP-06_ASSET_UPDATED",
      {
        component_id: componentId,
        component_type: componentType,
        production_status: productionStatus,
        dod_checklist: dodChecklist,
      },
      "GO-OP-06",
      componentId,
      "material_component",
    );
  }

  return { success: true, productionStatus, dodChecklist };
}

export async function saveRemotionLayoutOverridesAction(
  componentId: string,
  rawLayoutOverrides: unknown,
  context: { templateId?: string | null; templateVersionId?: string | null } = {},
) {
  const authorized = await getAuthorizedMaterialComponentAdmin(componentId);
  if (!authorized) {
    return { success: false, error: "No autorizado para editar este componente" };
  }

  const parsedResult = safeParseLayoutOverrideManifests(rawLayoutOverrides);
  if (!parsedResult.success) {
    return { success: false, error: "Ajustes de layout invalidos" };
  }
  const parsed = parsedResult.data;
  const currentAssets = (authorized.component.assets || {}) as MaterialAssets;
  const existingParsedResult = safeParseLayoutOverrideManifests(currentAssets.layout_overrides);
  const existingLayoutOverrides = existingParsedResult.success ? existingParsedResult.data : [];
  const scopedTemplateId = context.templateId || parsed[0]?.templateId || null;
  const scopedTemplateVersionId = context.templateVersionId || parsed[0]?.templateVersionId || null;
  const isClearingLayoutScope = parsed.length === 0;
  const isSameLayoutScope = (manifest: { templateId?: string | null; templateVersionId?: string | null }) => {
    if (!scopedTemplateId) return false;
    return (
      manifest.templateId === scopedTemplateId &&
      (isClearingLayoutScope || (scopedTemplateVersionId ? manifest.templateVersionId === scopedTemplateVersionId : true))
    );
  };
  const nextLayoutOverrides = scopedTemplateId
    ? [
        ...existingLayoutOverrides.filter((manifest) => !isSameLayoutScope(manifest)),
        ...parsed,
      ]
    : parsed;
  const now = new Date().toISOString();
  const nextAssets: MaterialAssets = {
    ...currentAssets,
    updated_at: now,
  };

  if (nextLayoutOverrides.length > 0) {
    nextAssets.layout_overrides = nextLayoutOverrides;
    nextAssets.layout_overrides_updated_at = now;
    if (currentAssets.final_video_url) {
      nextAssets.final_video_layout_stale = true;
    }
  } else {
    delete (nextAssets as any).layout_overrides;
    delete (nextAssets as any).layout_overrides_updated_at;
    delete (nextAssets as any).final_video_layout_stale;
  }

  const { error } = await authorized.admin.rpc(
    "patch_material_component_assets",
    {
      p_component_id: componentId,
      p_assets_patch: buildMaterialAssetsPatch(currentAssets, nextAssets),
    },
  );

  if (error) {
    console.error("[ProductionActions] Error saving layout overrides:", error);
    return { success: false, error: error.message };
  }

  await markDownstreamDirtyAction(
    authorized.artifactId,
    7,
    parsed.length > 0
      ? "Postproduccion (layout ajustado)"
      : "Postproduccion (layout restablecido)",
  );
  await logPipelineEventAction(
    authorized.artifactId,
    parsed.length > 0
      ? "REMOTION_LAYOUT_OVERRIDES_SAVED"
      : "REMOTION_LAYOUT_OVERRIDES_CLEARED",
    {
      component_id: componentId,
      overrides_count: nextLayoutOverrides.length,
      final_video_layout_stale: Boolean(nextAssets.final_video_layout_stale),
    },
    "GO-OP-07",
    componentId,
    "material_component",
  );

  return {
    success: true,
    layoutOverrides: nextLayoutOverrides,
    finalVideoLayoutStale: Boolean(nextAssets.final_video_layout_stale),
  };
}

