    if (selectedClip.kind !== "VIDEO" && selectedClip.kind !== "AUDIO" && selectedClip.kind !== "TEXT" && selectedClip.kind !== "CAPTION") {
      setSaveError("La eliminación de intervalos está disponible para clips de video, audio, texto o captions.");
