"use client";

import { useEffect, useState } from "react";
import { ChevronDown, ChevronRight, Eye, EyeOff, Lock, Unlock, Volume2, VolumeX } from "lucide-react";
import type { CompositionTrack } from "@/domains/production/composition-editor/composition-document.types";
import type { CompositionTrackUpdateHandler } from "./composition-studio.types";

interface TrackControlsProps {
  disabled: boolean;
  displayLabel?: string;
  expanded?: boolean;
  onUpdate: CompositionTrackUpdateHandler;
  onToggleExpanded?: () => void;
  track: CompositionTrack;
}

export function TrackControls({ disabled, displayLabel, expanded, onToggleExpanded, onUpdate, track }: TrackControlsProps) {
  const [volume, setVolume] = useState(track.volume ?? 1);
  const [editingName, setEditingName] = useState(false);
  const [name, setName] = useState(track.label);
  useEffect(() => setName(track.label), [track.label]);
  const commitName = () => {
    const label = name.trim();
    if (label && label !== track.label) onUpdate(track, { label }, `Renombró la pista a ${label}.`);
    else setName(track.label);
    setEditingName(false);
  };

  useEffect(() => setVolume(track.volume ?? 1), [track.volume]);

  const isAudio = track.kind === "AUDIO" || track.semanticRole === "AVATAR" || ["media-mp4", "media-webm"].includes(track.id);
  const formatLabel = track.kind === "DECK" ? "HTML" : track.id.startsWith("media-")
    ? track.id.slice("media-".length).toUpperCase().replace("JPEG", "JPG").replace("MPEG", "MP3") : null;
  const commitVolume = () => {
    const storedVolume = track.volume ?? 1;
    if (Math.abs(storedVolume - volume) < 0.005) return;

    onUpdate(
      track,
      { volume },
      `Ajustó el volumen de ${track.label} a ${Math.round(volume * 100)}%.`,
    );
  };

  return (
    <div className="min-w-0 pt-1">
      {editingName ? <input
        autoFocus aria-label="Nombre de la pista" maxLength={120} value={name}
        disabled={disabled} className="w-full rounded border px-1 text-xs text-slate-900"
        onChange={(event) => setName(event.target.value)} onBlur={commitName}
        onKeyDown={(event) => {
          if (event.key === "Enter") event.currentTarget.blur();
          if (event.key === "Escape") { setName(track.label); setEditingName(false); }
        }}
      /> : <button type="button" disabled={disabled} onClick={() => setEditingName(true)}
        className="text-[10px] text-cyan-700 dark:text-cyan-300" aria-label={`Renombrar ${track.label}`}>Renombrar</button>}
      {onToggleExpanded ? <button
        type="button"
        aria-expanded={expanded}
        aria-label={`${expanded ? "Contraer" : "Expandir"} ${displayLabel || track.label}`}
        onClick={onToggleExpanded}
        className="flex max-w-full items-center gap-1 rounded pr-1 text-left text-xs font-semibold text-slate-700 hover:bg-slate-100 dark:text-gray-200 dark:hover:bg-white/10"
        title={`${displayLabel || track.label} · ${track.semanticRole || track.kind}`}
      >
        {expanded ? <ChevronDown className="shrink-0" size={13} /> : <ChevronRight className="shrink-0" size={13} />}
        <span className="truncate">{displayLabel || track.label}</span>
      </button> : <span
        className="block truncate text-xs font-semibold text-slate-700 dark:text-gray-200"
        title={`${displayLabel || track.label} · ${track.semanticRole || track.kind}`}
      >
        {displayLabel || track.label}
      </span>}
      {formatLabel && <span className="ml-1 text-[10px] text-slate-500">{formatLabel}</span>}
      <div className="mt-1 flex items-center gap-1 text-slate-500 dark:text-gray-400">
        <button
          type="button"
          disabled={disabled}
          aria-label={track.hidden ? `Mostrar ${track.label}` : `Ocultar ${track.label}`}
          aria-pressed={Boolean(track.hidden)}
          onClick={() =>
            onUpdate(
              track,
              { hidden: !track.hidden },
              `${track.hidden ? "Mostró" : "Ocultó"} la capa ${track.label}.`,
            )
          }
          title={track.hidden ? `Mostrar ${track.label}` : `Ocultar ${track.label}`}
          className="rounded p-1 hover:bg-slate-200 disabled:opacity-50 dark:hover:bg-white/10"
        >
          {track.hidden ? <EyeOff size={13} /> : <Eye size={13} />}
        </button>
        <button
          type="button"
          disabled={disabled}
          aria-label={track.locked ? `Desbloquear ${track.label}` : `Bloquear ${track.label}`}
          aria-pressed={Boolean(track.locked)}
          onClick={() =>
            onUpdate(
              track,
              { locked: !track.locked },
              `${track.locked ? "Desbloqueó" : "Bloqueó"} la capa ${track.label}.`,
            )
          }
          title={track.locked ? `Desbloquear ${track.label}` : `Bloquear ${track.label}`}
          className="rounded p-1 hover:bg-slate-200 disabled:opacity-50 dark:hover:bg-white/10"
        >
          {track.locked ? <Lock size={13} /> : <Unlock size={13} />}
        </button>
        {isAudio && (
          <>
            <button
              type="button"
              disabled={disabled}
              aria-label={track.muted ? `Activar audio de ${track.label}` : `Silenciar ${track.label}`}
              aria-pressed={Boolean(track.muted)}
              onClick={() =>
                onUpdate(
                  track,
                  { muted: !track.muted },
                  `${track.muted ? "Activó" : "Silenció"} el audio de ${track.label}.`,
                )
              }
              title={track.muted ? `Activar audio de ${track.label}` : `Silenciar ${track.label}`}
              className="rounded p-1 hover:bg-slate-200 disabled:opacity-50 dark:hover:bg-white/10"
            >
              {track.muted ? <VolumeX size={13} /> : <Volume2 size={13} />}
            </button>
            <input
              aria-label={`Volumen base de ${track.label}`}
              aria-valuetext={`${Math.round(volume * 100)}%`}
              title={`Volumen base de ${track.label}: ${Math.round(volume * 100)}%`}
              disabled={disabled || track.muted}
              type="range"
              min="0"
              max="1"
              step="0.05"
              value={volume}
              onChange={(event) => setVolume(Number(event.target.value))}
              onPointerUp={commitVolume}
              onKeyUp={commitVolume}
              onBlur={commitVolume}
              className="w-14 accent-[var(--engine-accent)] disabled:opacity-40"
            />
          </>
        )}
      </div>
    </div>
  );
}

