"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { updateArtifactStatusAction } from "@/domains/artifacts/actions/artifact.actions";
import {
  generateInstructionalPlanAction,
  getInstructionalPlanSnapshotAction,
  updateInstructionalPlanVideoDurationPolicyAction,
  updateInstructionalPlanStatusAction,
  validateInstructionalPlanAction,
} from "../actions/plan.actions";
import { dismissUpstreamDirtyAction } from "@/lib/server/pipeline-dirty-actions";
import {
  PLAN_STATES,
  PLAN_TERMINAL_STATES,
  REVIEWER_ROLE_SET,
} from "@/lib/pipeline-constants";
import { usePolling } from "@/shared/hooks/usePolling";
import { useInstructionalPlanEditor } from "../hooks/useInstructionalPlanEditor";
import { InstructionalPlanResultsView } from "./InstructionalPlanResultsView";
import { InstructionalPlanSetupView } from "./InstructionalPlanSetupView";
import type { InstructionalPlanRecord } from "./plan-view.types";
import {
  DEFAULT_VIDEO_DURATION_POLICY,
  type VideoDurationPolicy,
} from "@/domains/video-duration/video-duration-policy";
import {
  canIteratePlan,
  PLAN_MAX_ITERATIONS,
} from "@/domains/plan/lib/plan-iteration";

interface InstructionalPlanGenerationContainerProps {
  coordinatedReview?: boolean;
  artifactId: string;
  onNext?: () => void;
  profile?: {
    platform_role?: string | null;
  } | null;
}

const PLAN_POLL_INTERVAL_MS = 3000;
const PLAN_REFRESH_DELAY_MS = 2000;

export function InstructionalPlanGenerationContainer({
  coordinatedReview = false,
  artifactId,
  onNext,
  profile,
}: InstructionalPlanGenerationContainerProps) {
  const router = useRouter();
  const [customPrompt, setCustomPrompt] = useState("");
  const [configuredPrompt, setConfiguredPrompt] = useState("");
  const [promptSource, setPromptSource] = useState<
    "organization" | "global" | "default" | null
  >(null);
  const [promptVersion, setPromptVersion] = useState<string | null>(null);
  const [existingPlan, setExistingPlan] =
    useState<InstructionalPlanRecord | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isValidating, setIsValidating] = useState(false);
  const [loadingPlan, setLoadingPlan] = useState(true);
  const [reviewNotes, setReviewNotes] = useState("");
  const [useCustomPrompt, setUseCustomPrompt] = useState(false);
  const [videoDurationPolicy, setVideoDurationPolicy] =
    useState<VideoDurationPolicy>({
      ...DEFAULT_VIDEO_DURATION_POLICY,
    });
  const canReview = !coordinatedReview && REVIEWER_ROLE_SET.has(profile?.platform_role || "");
  const lastKnownPlanStateRef = useRef<string | null>(null);
  const lastKnownValidationRef = useRef(false);
  const promptInitializedRef = useRef(false);
  const {
    editedLesson,
    editingLessonId,
    expandedLessonId,
    handleCancelEdit,
    handleComponentFieldChange,
    handleComponentTypeChange,
    handleLessonFieldChange,
    handleSaveLesson,
    handleStartEdit,
    handleToggleExpandedLesson,
  } = useInstructionalPlanEditor({
    artifactId,
    existingPlan,
    setExistingPlan,
  });

  const fetchPlan = useCallback(
    async (silent = false) => {
      if (!silent) {
        setLoadingPlan(true);
      }

      try {
        const result = await getInstructionalPlanSnapshotAction(artifactId);

        if (!result.success) {
          console.error(
            "[InstructionalPlan] Error fetching plan:",
            result.error,
          );

          if (
            result.error === "Artifact not found or inaccessible" ||
            result.error === "Unauthorized"
          ) {
            setIsGenerating(false);
            setIsValidating(false);

            if (silent) {
              toast.error(
                result.error === "Unauthorized"
                  ? "Tu sesion expiro. Recarga la pagina e inicia sesion de nuevo."
                  : "No se pudo volver a leer el plan. Verifica la organizacion activa y vuelve a intentar.",
              );
            }
          }

          return;
        }

        const plan = (result.plan as InstructionalPlanRecord | null) || null;
        if (result.generationPrompt && !promptInitializedRef.current) {
          setConfiguredPrompt(result.generationPrompt.content);
          setCustomPrompt(result.generationPrompt.content);
          setPromptSource(result.generationPrompt.source);
          setPromptVersion(result.generationPrompt.version);
          promptInitializedRef.current = true;
        }
        if (result.videoDurationPolicy) {
          setVideoDurationPolicy(result.videoDurationPolicy);
        }

        if (!plan) {
          setExistingPlan(null);
          lastKnownPlanStateRef.current = null;
          lastKnownValidationRef.current = false;
          return;
        }

        const hasLessons =
          Array.isArray(plan.lesson_plans) && plan.lesson_plans.length > 0;
        const hasValidation = Boolean(plan.validation);
        const planReachedTerminalState = PLAN_TERMINAL_STATES.has(plan.state);
        const shouldRefreshParent =
          silent &&
          ((lastKnownPlanStateRef.current !== plan.state &&
            planReachedTerminalState) ||
            (!lastKnownValidationRef.current && hasValidation));

        setExistingPlan(plan);
        setReviewNotes(plan.qa_decision?.notes || "");
        lastKnownPlanStateRef.current = plan.state;
        lastKnownValidationRef.current = hasValidation;

        if (plan.state === PLAN_STATES.PROCESSING && !isGenerating) {
          setIsGenerating(true);
        }

        if (planReachedTerminalState || (hasLessons && !isGenerating)) {
          setIsGenerating(false);
        }

        if (plan.state === PLAN_STATES.FAILED) {
          setIsGenerating(false);
          toast.error(
            plan.last_error?.message ||
              "La generacion fallo. Por favor, intenta de nuevo o revisa los logs.",
          );
        }

        if (hasValidation) {
          setIsValidating(false);
        }

        if (shouldRefreshParent) {
          router.refresh();
        }
      } catch (error) {
        console.error(
          "[InstructionalPlan] Unexpected error fetching plan:",
          error,
        );
      } finally {
        if (!silent) {
          setLoadingPlan(false);
        }
      }
    },
    [artifactId, isGenerating, router],
  );

  useEffect(() => {
    void fetchPlan();
  }, [fetchPlan]);

  usePolling(() => fetchPlan(true), isGenerating || isValidating, {
    intervalMs: PLAN_POLL_INTERVAL_MS,
  });

  const handleGenerate = useCallback(async () => {
    if (existingPlan && !canIteratePlan(existingPlan.iteration_count)) {
      toast.error(
        `El plan instruccional alcanzo el limite de ${PLAN_MAX_ITERATIONS} iteraciones.`,
      );
      return false;
    }

    setIsGenerating(true);
    lastKnownValidationRef.current = false;
    lastKnownPlanStateRef.current = PLAN_STATES.PROCESSING;
    setExistingPlan((currentPlan) =>
      currentPlan
        ? {
            ...currentPlan,
            state: PLAN_STATES.PROCESSING,
            validation: null,
          }
        : currentPlan,
    );

    try {
      const result = await generateInstructionalPlanAction(
        artifactId,
        customPrompt,
        useCustomPrompt,
        existingPlan ? reviewNotes.trim() || undefined : undefined,
      );

      if (!result.success) {
        toast.error(
          result.error === "Unauthorized"
            ? "Sesion expirada. Recarga la pagina e inicia sesion nuevamente."
            : `Error al generar: ${result.error}`,
        );
        setIsGenerating(false);
        await fetchPlan();
        return false;
      }

      toast.info(
        "Generacion iniciada. Esto puede tomar entre 30 a 60 segundos.",
      );

      window.setTimeout(() => {
        void fetchPlan();
        router.refresh();
      }, PLAN_REFRESH_DELAY_MS);
      return true;
    } catch (error) {
      console.error("Error calling plan generation action:", error);
      toast.error("Error de conexion. Intenta de nuevo.");
      setIsGenerating(false);
      await fetchPlan();
      return false;
    }
  }, [
    artifactId,
    customPrompt,
    existingPlan,
    fetchPlan,
    reviewNotes,
    router,
    useCustomPrompt,
  ]);

  const handleValidate = useCallback(async () => {
    setIsValidating(true);
    lastKnownValidationRef.current = false;
    setExistingPlan((currentPlan) =>
      currentPlan ? { ...currentPlan, validation: null } : currentPlan,
    );

    try {
      const result = await validateInstructionalPlanAction(artifactId);

      if (!result.success) {
        toast.error(
          result.error === "Unauthorized"
            ? "Sesion expirada. Recarga la pagina e inicia sesion nuevamente."
            : `Error al validar: ${result.error}`,
        );
        setIsValidating(false);
        return;
      }

      toast.info("Validacion iniciada...");
    } catch (error) {
      console.error("Error calling validate action:", error);
      toast.error("Error de conexion. Intenta de nuevo.");
      setIsValidating(false);
    }
  }, [artifactId]);

  const handleApprove = useCallback(async () => {
    const approval = await updateInstructionalPlanStatusAction(
      artifactId,
      PLAN_STATES.APPROVED,
      reviewNotes,
    );
    if (!approval.success) {
      toast.error(approval.error || "No se puede aprobar un plan incompleto.");
      await fetchPlan();
      return;
    }
    const artifactUpdate = await updateArtifactStatusAction(
      artifactId,
      "READY_FOR_QA",
    );
    if (!artifactUpdate.success) {
      toast.error(artifactUpdate.error || "No se pudo avanzar el artefacto.");
      await fetchPlan();
      return;
    }
    setExistingPlan((currentPlan) =>
      currentPlan
        ? {
            ...currentPlan,
            state: PLAN_STATES.APPROVED,
          }
        : currentPlan,
    );
    router.refresh();
    onNext?.();
  }, [artifactId, fetchPlan, onNext, reviewNotes, router]);

  const handleReject = useCallback(async () => {
    const rejection = await updateInstructionalPlanStatusAction(
      artifactId,
      PLAN_STATES.REJECTED,
      reviewNotes,
    );
    if (!rejection.success) {
      toast.error(rejection.error || "No se pudo rechazar el plan.");
      return;
    }
    setExistingPlan((currentPlan) =>
      currentPlan
        ? {
            ...currentPlan,
            state: PLAN_STATES.REJECTED,
          }
        : currentPlan,
    );
    router.refresh();
  }, [artifactId, reviewNotes, router]);

  const handleRegenerateRejected = useCallback(async () => {
    if (
      !confirm(
        "Estas seguro de que quieres regenerar? Esto eliminara el plan actual.",
      )
    ) {
      return;
    }

    try {
      handleCancelEdit();
      await handleGenerate();
    } catch (error) {
      console.error(error);
    }
  }, [handleCancelEdit, handleGenerate]);

  const handleDismissUpstreamDirty = useCallback(async () => {
    await dismissUpstreamDirtyAction("instructional_plans", artifactId);
    setExistingPlan((currentPlan) =>
      currentPlan ? { ...currentPlan, upstream_dirty: false } : currentPlan,
    );
    router.refresh();
  }, [artifactId, router]);

  const handleIterateUpstreamDirty = useCallback(async () => {
    const generationStarted = await handleGenerate();
    if (!generationStarted) return;

    await dismissUpstreamDirtyAction("instructional_plans", artifactId);
    setExistingPlan((currentPlan) =>
      currentPlan ? { ...currentPlan, upstream_dirty: false } : currentPlan,
    );
    router.refresh();
  }, [artifactId, handleGenerate, router]);

  const handleVideoDurationPolicySave = useCallback(
    async (policy: VideoDurationPolicy) => {
      const result = await updateInstructionalPlanVideoDurationPolicyAction(
        artifactId,
        policy,
      );
      if (!result.success) {
        toast.error(result.error || "No se pudo actualizar la duración");
        return false;
      }

      if (!result.videoDurationPolicy || !result.lessonPlans) {
        toast.error("La actualización no devolvió el plan recalculado");
        return false;
      }
      setVideoDurationPolicy(result.videoDurationPolicy);
      setExistingPlan((currentPlan) =>
        currentPlan
          ? { ...currentPlan, lesson_plans: result.lessonPlans }
          : currentPlan,
      );
      toast.success("Duración actualizada para todos los videos del plan");
      router.refresh();
      return true;
    },
    [artifactId, router],
  );

  const handleGenerateFromUi = useCallback(async () => {
    await handleGenerate();
  }, [handleGenerate]);

  if (loadingPlan) {
    return (
      <div className="py-10 text-center text-gray-500">
        Cargando plan instruccional...
      </div>
    );
  }

  if (existingPlan) {
    return (
      <InstructionalPlanResultsView
        canReview={canReview}
        editedLesson={editedLesson}
        editingLessonId={editingLessonId}
        expandedLessonId={expandedLessonId}
        isGenerating={isGenerating}
        isValidating={isValidating}
        onApprove={handleApprove}
        onCancelEdit={handleCancelEdit}
        onComponentFieldChange={handleComponentFieldChange}
        onComponentTypeChange={handleComponentTypeChange}
        onDismissUpstreamDirty={handleDismissUpstreamDirty}
        onIterateUpstreamDirty={handleIterateUpstreamDirty}
        onLessonFieldChange={handleLessonFieldChange}
        onNext={onNext}
        onRegenerate={handleGenerateFromUi}
        onRegenerateRejected={handleRegenerateRejected}
        onReject={handleReject}
        onReviewNotesChange={setReviewNotes}
        onSaveLesson={handleSaveLesson}
        onStartEdit={handleStartEdit}
        onToggleExpandedLesson={handleToggleExpandedLesson}
        onValidate={handleValidate}
        plan={existingPlan}
        reviewNotes={reviewNotes}
        videoDurationPolicy={videoDurationPolicy}
        onVideoDurationPolicySave={handleVideoDurationPolicySave}
      />
    );
  }

  return (
    <InstructionalPlanSetupView
      configuredPrompt={configuredPrompt}
      customPrompt={customPrompt}
      isGenerating={isGenerating}
      lessonCount={0}
      onGenerate={handleGenerateFromUi}
      promptSource={promptSource}
      promptVersion={promptVersion}
      setCustomPrompt={setCustomPrompt}
      setUseCustomPrompt={setUseCustomPrompt}
      useCustomPrompt={useCustomPrompt}
    />
  );
}

"use client";

import { useEffect, useState } from "react";
import { Save } from "lucide-react";
import {
  VideoDurationPolicyFields,
} from "@/domains/artifacts/components/VideoDurationPolicyFields";
import type { VideoDurationPolicy } from "@/domains/video-duration/video-duration-policy";

interface VideoDurationCoursePolicyEditorProps {
  disabled?: boolean;
  onSave: (policy: VideoDurationPolicy) => Promise<boolean>;
  value: VideoDurationPolicy;
}

export function VideoDurationCoursePolicyEditor({
  disabled = false,
  onSave,
  value,
}: VideoDurationCoursePolicyEditorProps) {
  const [draft, setDraft] = useState(value);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => setDraft(value), [value]);

  const hasChanges = JSON.stringify(draft) !== JSON.stringify(value);

  return (
    <section className="rounded-2xl border border-gray-200 bg-white p-5 dark:border-white/10 dark:bg-[var(--engine-surface-hover)]">
      <div className="mb-4">
        <h3 className="font-semibold text-gray-900 dark:text-white">
          Estándar de duración del curso
        </h3>
        <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
          Recalcula los contratos de todos los videos y marca los pasos posteriores para revisión.
        </p>
      </div>
      <VideoDurationPolicyFields onChange={setDraft} value={draft} />
      <div className="mt-4 flex justify-end">
        <button
          type="button"
          disabled={disabled || isSaving || !hasChanges}
          onClick={async () => {
            setIsSaving(true);
            await onSave(draft);
            setIsSaving(false);
          }}
          className="inline-flex items-center gap-2 rounded-lg bg-[var(--engine-accent)] px-4 py-2 text-sm font-semibold text-white transition-opacity disabled:cursor-not-allowed disabled:opacity-50 dark:text-[var(--engine-primary)]"
        >
          <Save size={15} />
          {isSaving ? "Guardando..." : "Aplicar a todos los videos"}
        </button>
      </div>
    </section>
  );
}

"use server";

import { createClient } from "@/utils/supabase/server";
import { getAuthenticatedUser, getServiceRoleClient } from "@/lib/server/artifact-action-auth";
import { resolveActiveTenantContext } from "@/lib/server/tenant-context";
import {
  deleteCloudStorageCredentials,
  decryptCredentialToken,
  getCloudStorageCredentials,
} from "@/domains/production/cloud-storage/credentials.repository";
import type {
  CloudStorageConnection,
  CloudStorageProvider,
} from "@/domains/production/cloud-storage/types";
import { fetchWithDeadline } from "@/lib/server/outbound-http";
import { createOperationalLogger, resolveCorrelationId } from "@/lib/server/operational-logger";

export async function getCloudStorageConnectionsForTenant(params: {
  organizationId: string;
  userId: string;
}): Promise<CloudStorageConnection[]> {
  const admin = getServiceRoleClient();
  const { data, error } = await admin
    .from("user_cloud_storage_credentials")
    .select("provider, account_email, organization_id")
    .eq("user_id", params.userId)
    .or(`organization_id.eq.${params.organizationId},organization_id.is.null`);

  if (error) {
    console.error("[CloudStorageConnections] Error:", error);
    return [];
  }

  const scopedConnections = (data || []).filter(
    (row: any) => row.organization_id === params.organizationId,
  );
  const legacyConnections = new Set(
    (data || [])
      .filter((row: any) => !row.organization_id)
      .map((row: any) => row.provider as CloudStorageProvider),
  );
  const connectedByProvider = new Map(
    scopedConnections.map((row: any) => [
      row.provider as CloudStorageProvider,
      row.account_email as string,
    ]),
  );

  return (["google_drive", "onedrive"] as CloudStorageProvider[]).map((provider) => ({
    connected: connectedByProvider.has(provider),
    email: connectedByProvider.get(provider) || null,
    needsReconnect: !connectedByProvider.has(provider) && legacyConnections.has(provider),
    provider,
  }));
}

export async function getCloudStorageConnectionsAction(): Promise<{
  connections: CloudStorageConnection[];
}> {
  try {
    const supabase = await createClient();
    const user = await getAuthenticatedUser(supabase);
    if (!user) {
      return { connections: [] };
    }

    const tenant = await resolveActiveTenantContext();
    if (!tenant) {
      return { connections: [] };
    }

    return {
      connections: await getCloudStorageConnectionsForTenant({
        organizationId: tenant.organizationId,
        userId: user.userId,
      }),
    };
  } catch (error) {
    console.error("[CloudStorageConnections] Unexpected error:", error);
    return { connections: [] };
  }
}

export async function disconnectCloudStorageAction(provider: CloudStorageProvider) {
  const logger = createOperationalLogger("cloud_storage.disconnect", {
    correlationId: resolveCorrelationId(),
    provider,
  });
  try {
    const supabase = await createClient();
    const user = await getAuthenticatedUser(supabase);
    if (!user) return { success: false, error: "No autorizado" };

    const tenant = await resolveActiveTenantContext();
    if (!tenant) return { success: false, error: "Empresa no valida o no autorizada" };

    const creds = await getCloudStorageCredentials(user.userId, tenant.organizationId, provider);
    if (creds) {
      const tokenToRevoke = decryptCredentialToken(creds.refresh_token || creds.access_token);
      try {
        if (provider === "google_drive") {
          await fetchWithDeadline(`https://oauth2.googleapis.com/revoke?token=${encodeURIComponent(tokenToRevoke)}`, {
            method: "POST",
            headers: { "Content-Type": "application/x-www-form-urlencoded" },
          });
        }
      } catch (revokeErr) {
        logger.warn("cloud_storage.disconnect.revocation_failed", { error: revokeErr });
      }

      await deleteCloudStorageCredentials(user.userId, tenant.organizationId, provider);

    }

    return { success: true };
  } catch (error: unknown) {
    logger.error("cloud_storage.disconnect.failed", error);
    return {
      success: false,
      error: error instanceof Error ? error.message : "Error al desvincular la integracion",
    };
  }
}

import { getErrorMessage } from "@/lib/errors";
import { signBackgroundPayload } from "@/lib/server/background-payload-signature";
import { readJsonResponseWithLimit } from "@/lib/server/outbound-http";
import type { AvatarClip, MaterialAssets } from "@/domains/materials/types/materials.types";
import { getHeygenClientForOrganization } from "../providers/heygen/heygen-credential-resolver.service";
import { HeygenScenesService } from "../providers/heygen/heygen-scenes.service";
import { HeygenVideoService } from "../providers/heygen/heygen-video.service";
import type { ProductionAssetRequirement } from "./production-automation.types";
import type {
  ProductionAvatarConfiguration,
  ProductionRunConfiguration,
  ProductionRunItemConfiguration,
} from "./production-automation.types";
import type { SupabaseClient } from "@supabase/supabase-js";

type DispatchableItem = {
  configuration: ProductionRunItemConfiguration | null;
  dispatch_attempts: number;
  id: string;
  material_component_id: string;
  requirements: ProductionAssetRequirement[] | null;
};

type ComponentRow = {
  assets: MaterialAssets | null;
  content: unknown;
  id: string;
  type: string;
};

const MAX_INTERNAL_DISPATCH_ERROR_BYTES = 32 * 1024;

/**
 * Dispatches source-asset jobs only. It deliberately never creates a
 * composition, initialises the editor, or submits a HyperFrames render.
 */
export class ProductionAutomationDispatcher {
  constructor(private readonly supabase: SupabaseClient<any, "public", any>) {}

  async dispatchRun(params: { organizationId: string; runId: string }) {
    const { data: run, error: runError } = await this.supabase
      .from("production_runs")
      .select("id, created_by, status, configuration")
      .eq("id", params.runId)
      .eq("organization_id", params.organizationId)
      .maybeSingle();
    if (runError) throw runError;
    if (!run) throw new Error("Ejecucion de produccion no encontrada.");
    if (run.status === "CANCELLED") return { dispatched: 0, skipped: 0 };
    if ((run.configuration as { approval_state?: unknown } | null)?.approval_state !== "APPROVED") {
      throw new Error("La configuracion de produccion debe aprobarse antes de enviar assets.");
    }

    const { data: items, error: itemsError } = await this.supabase
      .from("production_run_items")
      .select("id, material_component_id, requirements, configuration, dispatch_attempts")
      .eq("production_run_id", params.runId)
      .eq("organization_id", params.organizationId)
      .in("status", ["PLANNED", "FAILED_RETRYABLE"])
      .order("module_order", { ascending: true })
      .order("lesson_order", { ascending: true });
    if (itemsError) throw itemsError;

    let dispatched = 0;
    let skipped = 0;
    for (const item of (items || []) as DispatchableItem[]) {
      const requirements = Array.isArray(item.requirements) ? item.requirements : [];
      // Drafts created before the requirement-inference repair are still video
      // production items, so treat an empty list as an avatar/voice job.
      const requiresAvatar = requirements.length === 0 || requirements.some((requirement) => requirement.kind === "AVATAR_AND_VOICE");
      const requiresSlides = requirements.some((requirement) => requirement.kind === "SLIDES");
      const defaults = resolveItemConfiguration(run.configuration);
      const itemConfiguration: ProductionRunItemConfiguration = {
        ...defaults,
        ...item.configuration,
      };
      if (!requiresAvatar && !requiresSlides) {
        await this.markUnsupported(item.id, "Este componente requiere una automatizacion de slides, B-roll o screencast que aun no ha sido conectada al despachador.");
        skipped += 1;
        continue;
      }

      const configuredAvatar = itemConfiguration.avatar;
      const configuredSlides = itemConfiguration.slides;
      if (!requiresAvatar) {
        if (!configuredSlides) {
          await this.markUnsupported(item.id, "Selecciona y aprueba una plantilla de diapositivas antes de despachar este componente.");
          skipped += 1;
          continue;
        }
        try {
          await this.dispatchSlides({ componentId: item.material_component_id, configuration: configuredSlides, createdBy: run.created_by || "", organizationId: params.organizationId });
          await this.markWaitingProvider(item);
          dispatched += 1;
        } catch (error) { await this.markDispatchFailed(item, error); }
        continue;
      }
      if (configuredAvatar?.generationMode === "single_video" && isConfiguredAvatar(configuredAvatar)) {
        try {
          await this.dispatchAvatarVideo({
            avatar: configuredAvatar,
            componentId: item.material_component_id,
            createdBy: run.created_by || "",
            organizationId: params.organizationId,
          });
          if (requiresSlides && configuredSlides) {
            await this.dispatchSlides({ componentId: item.material_component_id, configuration: configuredSlides, createdBy: run.created_by || "", organizationId: params.organizationId });
          }
          await this.markWaitingProvider(item);
          dispatched += 1;
        } catch (error) {
          await this.markDispatchFailed(item, error);
        }
        continue;
      }

      if (!isConfiguredSceneAvatar(configuredAvatar)) {
        await this.markUnsupported(
          item.id,
          "Selecciona y aprueba avatar, voz y modo de generacion antes de despachar este componente.",
        );
        skipped += 1;
        continue;
      }

      try {
        await this.dispatchAvatarScenes({
          avatar: configuredAvatar,
          componentId: item.material_component_id,
          createdBy: run.created_by || "",
          organizationId: params.organizationId,
        });
        if (requiresSlides && configuredSlides) {
          await this.dispatchSlides({ componentId: item.material_component_id, configuration: configuredSlides, createdBy: run.created_by || "", organizationId: params.organizationId });
        }
        await this.markWaitingProvider(item);
        dispatched += 1;
      } catch (error) {
        await this.markDispatchFailed(item, error);
      }
    }

    await this.supabase
      .from("production_runs")
      .update({ status: dispatched > 0 ? "GENERATING" : "NEEDS_ATTENTION", updated_at: new Date().toISOString() })
      .eq("id", params.runId)
      .eq("organization_id", params.organizationId);
    return { dispatched, skipped };
  }

  private async dispatchAvatarScenes(params: {
    avatar: ProductionAvatarConfiguration;
    componentId: string;
    createdBy: string;
    organizationId: string;
  }) {
    if (!params.createdBy) throw new Error("La ejecucion no tiene un usuario creador para registrar los jobs.");
    const { data, error } = await this.supabase
      .from("material_components")
      .select("id, assets, content")
      .eq("id", params.componentId)
      .maybeSingle();
    if (error) throw error;
    if (!data) throw new Error("Componente de video no encontrado.");
    const component = data as ComponentRow;
    const auth = await getHeygenClientForOrganization({
      allowGlobalFallback: false,
      organizationId: params.organizationId,
      supabase: this.supabase,
    });
    const service = new HeygenScenesService(this.supabase, auth.client);
    const clips = service.buildSceneClips({
      componentContent: component.content,
      existingClips: component.assets?.avatar_clips,
    });
    const configuredClips = clips.map((clip) => ({
      ...clip,
      // A reviewed clip-level correction wins over the course/lesson profile.
      // Both values are explicit; no provider default is allowed here.
      avatar_preset_id: clip.expected_media_mode === "avatar"
        ? clip.avatar_preset_id || params.avatar.avatarPresetId
        : clip.avatar_preset_id,
      voice_preset_id: clip.voice_preset_id || params.avatar.voicePresetId,
    }));
    const activeClips = configuredClips.filter((clip) => !clip.deleted);
    const unconfiguredClips = activeClips.filter((clip) => !clip.expected_media_mode);
    if (unconfiguredClips.length > 0) {
      throw new Error(
        `Define el medio esperado de las escenas ${unconfiguredClips.map((clip) => clip.order).join(", ")} antes de ejecutar la automatización.`,
      );
    }

    const voiceByClipId = new Map(
      (component.assets?.voice_clips || []).map((voiceClip) => [voiceClip.clip_id, voiceClip]),
    );
    const hasCurrentVoice = (clip: (typeof activeClips)[number]) => {
      const voiceClip = voiceByClipId.get(clip.id);
      return voiceClip?.status === "COMPLETED"
        && Boolean(voiceClip.public_url)
        && (!clip.script_hash || voiceClip.script_hash === clip.script_hash);
    };
    const voiceOnlyClips = activeClips.filter(
      (clip) => (
        clip.expected_media_mode === "voice_only"
        || (clip.expected_media_mode === "avatar" && clip.status === "COMPLETED")
      ) && !hasCurrentVoice(clip),
    );
    const avatarClips = activeClips.filter(
      (clip) => clip.expected_media_mode === "avatar" && clip.status !== "COMPLETED",
    );

    let workingClips: AvatarClip[] = configuredClips;
    for (const batch of [
      { clips: voiceOnlyClips, generationTarget: "voice_only" as const },
      { clips: avatarClips, generationTarget: "avatar" as const },
    ]) {
      if (batch.clips.length === 0) continue;
      const clipIds = batch.clips.map((clip) => clip.id);
      const queued = await service.queueSceneClips({
        clipIds,
        clips: workingClips,
        componentId: component.id,
        generationTarget: batch.generationTarget,
        organizationId: params.organizationId,
      });
      const generated = await service.generateSceneClips({
        createdBy: params.createdBy,
        options: {
          aspectRatio: params.avatar.aspectRatio,
          caption: params.avatar.caption,
          clipIds,
          clips: queued.clips,
          componentId: component.id,
          engine: params.avatar.engine,
          generationTarget: batch.generationTarget,
          outputFormat: params.avatar.outputFormat,
          requestOrigin: "production_automation",
          resolution: params.avatar.resolution,
          speed: 1,
        },
        organizationId: params.organizationId,
      });
      workingClips = generated.clips;
    }
  }

  private async dispatchAvatarVideo(params: {
    avatar: ProductionAvatarConfiguration;
    componentId: string;
    createdBy: string;
    organizationId: string;
  }) {
    if (!params.createdBy) throw new Error("La ejecucion no tiene un usuario creador para registrar los jobs.");
    const { data, error } = await this.supabase
      .from("material_components")
      .select("id, assets, content, type")
      .eq("id", params.componentId)
      .maybeSingle();
    if (error) throw error;
    if (!data) throw new Error("Componente de video no encontrado.");
    const component = data as ComponentRow;
    const auth = await getHeygenClientForOrganization({
      allowGlobalFallback: false,
      organizationId: params.organizationId,
      supabase: this.supabase,
    });
    await new HeygenVideoService(this.supabase, auth.client).createAvatarVideoForComponent({
      componentContent: component.content,
      componentType: component.type,
      createdBy: params.createdBy,
      options: {
        aspectRatio: params.avatar.aspectRatio,
        autoPromote: true,
        avatarPresetId: params.avatar.avatarPresetId,
        caption: params.avatar.caption,
        componentId: component.id,
        engine: params.avatar.engine,
        outputFormat: params.avatar.outputFormat,
        resolution: params.avatar.resolution,
        voicePresetId: params.avatar.voicePresetId,
      },
      organizationId: params.organizationId,
    });
  }

  private async dispatchSlides(params: {
    componentId: string;
    configuration: NonNullable<ProductionRunItemConfiguration["slides"]>;
    createdBy: string;
    organizationId: string;
  }) {
    if (!params.createdBy) throw new Error("La ejecucion no tiene un usuario creador para registrar los jobs.");
    const { POST } = await import("@/app/api/production/slides/generate/route");
    const response = await POST(new Request("http://production-automation.local/api/production/slides/generate", {
      body: JSON.stringify({
        appearance: params.configuration.appearance,
        componentId: params.componentId,
        generateVisuals: params.configuration.generateVisuals,
        locale: params.configuration.locale,
        slideTemplateRunId: params.configuration.slideTemplateRunId,
        template: params.configuration.template,
      }),
      headers: {
        "Content-Type": "application/json",
        "x-production-automation": JSON.stringify(signBackgroundPayload({
          componentId: params.componentId,
          createdBy: params.createdBy,
          organizationId: params.organizationId,
        })),
      },
      method: "POST",
    }));
    if (!response.ok) {
      const payload = await readJsonResponseWithLimit<{ error?: unknown }>(
        response,
        MAX_INTERNAL_DISPATCH_ERROR_BYTES,
      ).catch((): { error?: unknown } => ({}));
      throw new Error(typeof payload.error === "string" ? payload.error : "No se pudieron generar las diapositivas.");
    }
  }

  private async markWaitingProvider(item: DispatchableItem) {
    const { error } = await this.supabase
      .from("production_run_items")
      .update({
        dispatch_attempts: item.dispatch_attempts + 1,
        dispatched_at: new Date().toISOString(),
        last_error: null,
        status: "WAITING_PROVIDER",
        updated_at: new Date().toISOString(),
      })
      .eq("id", item.id);
    if (error) throw error;
  }

  private async markDispatchFailed(item: DispatchableItem, error: unknown) {
    const message = getErrorMessage(error, "No se pudieron enviar los assets de avatar.");
    const { error: updateError } = await this.supabase
      .from("production_run_items")
      .update({
        dispatch_attempts: item.dispatch_attempts + 1,
        last_error: { message, source: "production_automation_dispatch" },
        status: "FAILED_RETRYABLE",
        updated_at: new Date().toISOString(),
      })
      .eq("id", item.id);
    if (updateError) throw updateError;
  }

  private async markUnsupported(itemId: string, message: string) {
    const now = new Date().toISOString();
    const { error } = await this.supabase
      .from("production_run_items")
      .update({
        last_error: { code: "AUTOMATION_NOT_IMPLEMENTED", message },
        status: "FAILED_RETRYABLE",
        updated_at: now,
      })
      .eq("id", itemId);
    if (error) throw error;
  }
}

type SceneAvatarConfiguration = ProductionAvatarConfiguration & { generationMode: "scene_clips" };

function isConfiguredSceneAvatar(value: ProductionAvatarConfiguration | undefined): value is SceneAvatarConfiguration {
  return Boolean(
    value
    && value.generationMode === "scene_clips"
    && value.avatarPresetId
    && value.aspectRatio
    && value.engine
    && value.outputFormat
    && value.resolution,
  );
}

function isConfiguredAvatar(value: ProductionAvatarConfiguration | undefined): value is ProductionAvatarConfiguration {
  return Boolean(value && value.avatarPresetId && value.voicePresetId && value.aspectRatio && value.engine && value.outputFormat && value.resolution);
}

function resolveItemConfiguration(configuration: unknown): ProductionRunItemConfiguration {
  const run = configuration as ProductionRunConfiguration | null;
  return run?.defaults || {};
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { createOperationalLogger } from "@/lib/server/operational-logger";
import { ensureProductionNativeCaptions } from "./production-native-captions.service";
import { productionNativeCaptionPorts } from "./production-native-captions.server";
import { nativeCaptionsEnabledForItem } from "./production-automation-configuration";
import { getHeygenClientForOrganization } from "../providers/heygen/heygen-credential-resolver.service";
import { HeygenScenesService } from "../providers/heygen/heygen-scenes.service";
import { HeygenVideoService } from "../providers/heygen/heygen-video.service";
import {
  deriveProductionAssetRequirements,
  evaluateProductionItemReadiness,
} from "./production-automation-readiness.service";
import type {
  ProductionAutomationComponent,
  ProductionRunItemConfiguration,
  ProductionRunConfiguration,
  ProductionRunItemStatus,
  ProductionRunStatus,
  ProductionItemReadiness,
  ProductionCaptionOverwriteRequest,
} from "./production-automation.types";

type ComponentRow = {
  assets: ProductionAutomationComponent["assets"];
  content: ProductionAutomationComponent["content"];
  id: string;
  material_lesson_id: string;
  type: ProductionAutomationComponent["componentType"];
  material_lessons: {
    lesson_id: string;
    module_id: string | null;
    materials: { artifact_id: string } | { artifact_id: string }[] | null;
  } | { lesson_id: string; module_id: string | null; materials: { artifact_id: string } | { artifact_id: string }[] | null }[] | null;
};

function first<T>(value: T | T[] | null | undefined) {
  return Array.isArray(value) ? value[0] : value || null;
}

export class ProductionAutomationRunError extends Error {
  constructor(message: string, readonly status = 400) {
    super(message);
  }
}

/** Evalúa assets y prepara subtítulos optativos; el render sigue siendo explícito. */
export class ProductionAutomationRunService {
  constructor(private readonly supabase: SupabaseClient<any, "public", any>) {}

  async createRun(params: { artifactId: string; createdBy: string; organizationId: string }) {
    const components = await this.loadVideoComponents(params);
    if (components.length === 0) {
      throw new ProductionAutomationRunError("El curso no tiene componentes de video para automatizar.", 409);
    }

    const { data: run, error: runError } = await this.supabase
      .from("production_runs")
      .insert({
        artifact_id: params.artifactId,
        configuration: { approval_state: "DRAFT", render_mode: "MANUAL_ONLY", version: 1 },
        created_by: params.createdBy,
        organization_id: params.organizationId,
        status: "PLANNING",
      })
      .select("id")
      .single();
    if (runError || !run) {
      if (runError?.code === "23505") {
        throw new ProductionAutomationRunError("Ya existe una automatizacion de produccion activa para este curso.", 409);
      }
      throw runError || new Error("No se pudo crear la ejecucion de produccion.");
    }

    const itemRows = components.map((component) => {
      const requirements = deriveProductionAssetRequirements(component.content?.storyboard);
      // Every video component belongs in the pre-production review, even when
      // its storyboard has not yet been enriched with narration text.
      if (!requirements.some((requirement) => requirement.kind === "AVATAR_AND_VOICE")) {
        requirements.unshift({
          kind: "AVATAR_AND_VOICE",
          reason: "Componente de video incluido en la configuracion de produccion.",
        });
      }
      const readiness = evaluateProductionItemReadiness({ assets: component.assets, requirements });
      return {
        artifact_id: params.artifactId,
        component_type: component.componentType,
        configuration: {},
        material_component_id: component.id,
        material_lesson_id: component.materialLessonId,
        module_id: component.moduleId,
        module_order: component.moduleOrder,
        lesson_order: component.lessonOrder,
        organization_id: params.organizationId,
        production_run_id: run.id,
        readiness,
        ready_for_assembly_at: readiness.complete ? readiness.evaluatedAt : null,
        requirements,
        status: readiness.complete ? "READY_FOR_ASSEMBLY" : "PLANNED",
      };
    });
    const { error: itemError } = await this.supabase.from("production_run_items").insert(itemRows);
    if (itemError) throw itemError;

    return { runId: run.id as string, status: "PLANNING" as const, totalItems: itemRows.length };
  }

  async refreshRun(runId: string, organizationId: string, command?: { userId: string; overwriteCaptions?: ProductionCaptionOverwriteRequest }) {
    const { data: run, error: runLookupError } = await this.supabase
      .from("production_runs")
      .select("configuration, created_by, status")
      .eq("id", runId)
      .eq("organization_id", organizationId)
      .maybeSingle();
    if (runLookupError) throw runLookupError;
    if (!run) throw new ProductionAutomationRunError("Ejecucion de produccion no encontrada.", 404);
    if (run.status === "CANCELLED") return { runId, status: "CANCELLED" as const, totalItems: 0 };
    const defaults = (run.configuration as ProductionRunConfiguration | null)?.defaults;
    const { data: items, error } = await this.supabase
      .from("production_run_items")
      .select("id, material_component_id, requirements, configuration, status, readiness")
      .eq("production_run_id", runId)
      .eq("organization_id", organizationId);
    if (error) throw error;

    if (command?.overwriteCaptions && !(items || []).some(item => item.id === command.overwriteCaptions?.itemId)) {
      throw new ProductionAutomationRunError("La capa solicitada no pertenece a esta ejecución.", 404);
    }

    for (const item of items || []) {
      if (["SKIPPED", "FAILED", "IN_ASSEMBLY"].includes(item.status)) continue;
      const requirements = Array.isArray(item.requirements) ? item.requirements : [];
      if (item.status === "WAITING_PROVIDER" && requirements.some((requirement: { kind?: string }) => requirement.kind === "AVATAR_AND_VOICE")) {
        const configuration = item.configuration as ProductionRunItemConfiguration | null;
        const avatar = configuration?.avatar || defaults?.avatar;
        if (avatar?.generationMode === "single_video") {
          await this.refreshAvatarVideoStatus({ componentId: item.material_component_id, organizationId });
        } else {
          await this.refreshAvatarSceneStatuses({
            componentId: item.material_component_id,
            organizationId,
          });
        }
      }
      const component = await this.loadComponentAssets(item.material_component_id, organizationId);
      const readiness = evaluateProductionItemReadiness({ assets: component.assets, requirements });
      const configuration = item.configuration as ProductionRunItemConfiguration | null;
      const overwrite = command?.overwriteCaptions;
      const nativeCaptionsEnabled = nativeCaptionsEnabledForItem(run.configuration as ProductionRunConfiguration | null, configuration);
      const previous = (item.readiness as ProductionItemReadiness | null)?.nativeCaptions;
      if (nativeCaptionsEnabled) {
        readiness.nativeCaptions = readiness.complete
          ? await ensureProductionNativeCaptions({
            componentId: item.material_component_id, organizationId, userId: command?.userId || run.created_by || "",
            itemId: item.id, assets: component.assets, previous,
            ...(overwrite && overwrite.itemId === item.id ? { overwrite } : {}),
          }, productionNativeCaptionPorts(this.supabase))
          : { status: "WAITING_TIMESTAMPS", detail: "Los assets requeridos todavía no están listos.",
            ...(previous?.hfId ? { hfId: previous.hfId } : {}) };
        readiness.complete = readiness.complete && readiness.nativeCaptions.status === "READY";
        if (JSON.stringify(previous) !== JSON.stringify(readiness.nativeCaptions)) {
          createOperationalLogger("produccion.subtitulos", { runId, organizationId, itemId: item.id })
            .info("Estado de subtítulos automáticos actualizado", { status: readiness.nativeCaptions.status });
        }
      } else if (previous?.hfId) {
        readiness.nativeCaptions = { status: "DISABLED", detail: "La generación automática está desactivada. Se conservó la capa registrada.", hfId: previous.hfId };
      }
      const nextStatus: ProductionRunItemStatus = readiness.complete
        ? "READY_FOR_ASSEMBLY"
        : nativeCaptionsEnabled && readiness.nativeCaptions?.status !== "READY"
          && readiness.requirements.every(requirement => requirement.complete)
          ? "STALE"
        : item.status === "WAITING_PROVIDER" && hasFailedAvatarGeneration(component.assets)
          ? "FAILED_RETRYABLE"
        : item.status === "READY_FOR_ASSEMBLY" || item.status === "IN_ASSEMBLY"
          ? "STALE"
          : item.status;
      const { error: updateError } = await this.supabase
        .from("production_run_items")
        .update({
          readiness,
          ready_for_assembly_at: readiness.complete ? readiness.evaluatedAt : null,
          status: nextStatus,
          updated_at: readiness.evaluatedAt,
        })
        .eq("id", item.id)
        .eq("organization_id", organizationId)
        .eq("production_run_id", runId);
      if (updateError) throw updateError;
    }

    const { data: refreshed, error: refreshedError } = await this.supabase
      .from("production_run_items")
      .select("status")
      .eq("production_run_id", runId)
      .eq("organization_id", organizationId);
    if (refreshedError) throw refreshedError;
    const statuses = (refreshed || []).map((item) => item.status as ProductionRunItemStatus);
    const status: ProductionRunStatus = statuses.every((value) => value === "READY_FOR_ASSEMBLY" || value === "IN_ASSEMBLY")
      ? "READY_FOR_ASSEMBLY"
      : statuses.some((value) => value === "READY_FOR_ASSEMBLY" || value === "IN_ASSEMBLY")
        ? "PARTIALLY_READY"
        : statuses.some((value) => value === "FAILED" || value === "STALE")
          ? "NEEDS_ATTENTION"
          : "GENERATING";
    const now = new Date().toISOString();
    const { error: runError } = await this.supabase
      .from("production_runs")
      .update({
        completed_at: status === "READY_FOR_ASSEMBLY" ? now : null,
        progress: {
          ready_items: statuses.filter((value) => value === "READY_FOR_ASSEMBLY" || value === "IN_ASSEMBLY").length,
          total_items: statuses.length,
        },
        started_at: now,
        status,
        updated_at: now,
      })
      .eq("id", runId)
      .eq("organization_id", organizationId);
    if (runError) throw runError;
    return { runId, status, totalItems: statuses.length };
  }

  async reconcileActiveRuns() {
    const { data, error } = await this.supabase
      .from("production_runs")
      .select("id, organization_id")
      .in("status", ["GENERATING", "PARTIALLY_READY"])
      .order("updated_at", { ascending: true })
      .limit(20);
    if (error) throw error;

    const results = await Promise.allSettled(
      (data || []).map((run) => this.refreshRun(run.id, run.organization_id)),
    );
    return {
      failed: results.filter((result) => result.status === "rejected").length,
      reconciled: results.filter((result) => result.status === "fulfilled").length,
    };
  }

  async getRun(runId: string, organizationId: string) {
    const { data: run, error: runError } = await this.supabase
      .from("production_runs")
      .select("id, artifact_id, status, configuration, progress, created_at, started_at, completed_at")
      .eq("id", runId)
      .eq("organization_id", organizationId)
      .maybeSingle();
    if (runError) throw runError;
    if (!run) throw new ProductionAutomationRunError("Ejecucion de produccion no encontrada.", 404);

    const { data: items, error: itemsError } = await this.supabase
      .from("production_run_items")
      .select("id, module_id, module_order, lesson_order, material_component_id, component_type, status, requirements, configuration, readiness, last_error, ready_for_assembly_at")
      .eq("production_run_id", runId)
      .eq("organization_id", organizationId)
      .order("module_order", { ascending: true })
      .order("lesson_order", { ascending: true });
    if (itemsError) throw itemsError;
    return { ...run, items: items || [] };
  }

  private async loadVideoComponents(params: { artifactId: string; organizationId: string }) {
    const { data, error } = await this.supabase
      .from("material_components")
      .select("id, assets, content, material_lesson_id, type, material_lessons!inner(lesson_id, module_id, materials!inner(artifact_id))")
      .in("type", ["VIDEO_THEORETICAL", "VIDEO_DEMO", "VIDEO_GUIDE"]);
    if (error) throw error;
    return (data || [])
      .flatMap((row) => {
        const component = this.toAutomationComponent(row as ComponentRow);
        return component ? [component] : [];
      })
      .filter((component) => component.artifactId === params.artifactId)
      .sort((left, right) => left.moduleOrder - right.moduleOrder || left.lessonOrder - right.lessonOrder);
  }

  private async refreshAvatarSceneStatuses(params: { componentId: string; organizationId: string }) {
    const auth = await getHeygenClientForOrganization({
      allowGlobalFallback: false,
      organizationId: params.organizationId,
      supabase: this.supabase,
    });
    await new HeygenScenesService(this.supabase, auth.client).refreshSceneClipStatuses({
      componentId: params.componentId,
      organizationId: params.organizationId,
    });
  }

  private async refreshAvatarVideoStatus(params: { componentId: string; organizationId: string }) {
    const { data: job, error } = await this.supabase
      .from("production_jobs")
      .select("id")
      .eq("material_component_id", params.componentId)
      .eq("organization_id", params.organizationId)
      .eq("job_type", "HEYGEN_AVATAR_VIDEO")
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();
    if (error) throw error;
    if (!job) return;
    const auth = await getHeygenClientForOrganization({
      allowGlobalFallback: false,
      organizationId: params.organizationId,
      supabase: this.supabase,
    });
    await new HeygenVideoService(this.supabase, auth.client).getAvatarVideoJobStatus({
      autoPromote: true,
      jobId: job.id,
      organizationId: params.organizationId,
    });
  }

  private toAutomationComponent(row: ComponentRow): (ProductionAutomationComponent & { artifactId: string }) | null {
    const lesson = first(row.material_lessons);
    const materials = first(lesson?.materials);
    if (!lesson || !materials?.artifact_id) return null;
    return {
      artifactId: materials.artifact_id,
      assets: row.assets,
      componentType: row.type,
      content: row.content,
      id: row.id,
      lessonId: lesson.lesson_id,
      lessonOrder: sequenceOrder(lesson.lesson_id),
      materialLessonId: row.material_lesson_id,
      moduleId: lesson.module_id,
      moduleOrder: moduleOrder(lesson.module_id),
    };
  }

  private async loadComponentAssets(componentId: string, organizationId: string) {
    const { data, error } = await this.supabase
      .from("material_components")
      .select("assets, material_lessons!inner(materials!inner(artifacts!inner(organization_id)))")
      .eq("id", componentId)
      .maybeSingle();
    if (error) throw error;
    const lesson = first(data?.material_lessons as unknown as ComponentRow["material_lessons"]);
    const materials = first(lesson?.materials);
    const artifact = first((materials as { artifacts?: { organization_id?: string } | { organization_id?: string }[] } | null)?.artifacts);
    if (!data || artifact?.organization_id !== organizationId) {
      throw new ProductionAutomationRunError("Componente de produccion no encontrado para esta empresa.", 404);
    }
    return { assets: data.assets };
  }
}

function moduleOrder(moduleId: string | null) {
  const match = moduleId?.match(/(\d+)$/);
  return match ? Number(match[1]) : 0;
}

function sequenceOrder(value: string | null) {
  const match = value?.match(/(\d+)$/);
  return match ? Number(match[1]) : 0;
}

function hasFailedAvatarGeneration(assets: unknown) {
  const value = assets as { avatar_clips?: Array<{ status?: string }>; avatar_video?: { sync_status?: string } } | null;
  return Boolean(
    value?.avatar_clips?.some((clip) => clip.status === "FAILED")
    || value?.avatar_video?.sync_status === "FAILED",
  );
}

import { APP_CONFIG } from "../../../config/app";
import { GoogleGenAI } from "@google/genai";
import { getOptionalGeminiApiKey, getOptionalOpenAIApiKey } from "@/lib/server/env";
import {
  fetchWithDeadline,
  readJsonResponseWithLimit,
  readResponseTextWithLimit,
} from "@/lib/server/outbound-http";
import { getPipelineModelSettings, type PipelineModelSettings } from "@/lib/server/model-settings";
import {
  bundleAgentMessageMetadataSchema,
  bundleAgentSpecSchema,
  type BundleAgentSpec,
  type BundleAgentVisualReference,
} from "./types";
import { buildSpecFromConversation, normalizeBundleAgentSpecForRendering } from "./spec.service";
import { sanitizeErrorMessage } from "./redaction.service";
import { normalizeGeneratedBundleSpec } from "./ai-spec-normalizer.service";
import { getBundleModelProvider, resolveGeminiBundleModel, resolveOpenAIBundleModel } from "./provider-model.service";

const AI_SPEC_TIMEOUT_MS = 60_000;
const AI_SPEC_RESPONSE_MAX_BYTES = 4 * 1024 * 1024;
const AI_ERROR_RESPONSE_MAX_BYTES = 32 * 1024;

interface MessageForSpec {
  role: string;
  content_redacted: string;
  metadata?: unknown;
}

export interface AiSpecGenerationResult {
  spec: BundleAgentSpec;
  model: string;
  source: "openai" | "gemini" | "deterministic_fallback";
  warning: string | null;
}

interface OpenAIResponsesPayload {
  output?: Array<{
    content?: Array<{
      text?: string;
      type?: string;
    }>;
  }>;
  output_text?: string;
}

interface OpenAIInputMessage {
  role: "user";
  content: Array<
    | { type: "input_text"; text: string }
    | { type: "input_image"; image_url: string; detail?: "low" | "high" | "auto" }
  >;
}

function getVisualReferencesFromMessage(message: MessageForSpec): BundleAgentVisualReference[] {
  const parsed = bundleAgentMessageMetadataSchema.safeParse(message.metadata || {});
  return parsed.success ? parsed.data.visualReferences || [] : [];
}

function getImageReferences(messages: MessageForSpec[]) {
  return messages
    .flatMap((message) => getVisualReferencesFromMessage(message))
    .filter((reference) => reference.type === "image" && reference.publicUrl);
}

function formatBytes(sizeBytes: number) {
  if (sizeBytes >= 1024 * 1024) return `${Math.round(sizeBytes / (1024 * 1024))} MB`;
  return `${Math.max(1, Math.round(sizeBytes / 1024))} KB`;
}

function buildVisualReferenceContext(messages: MessageForSpec[]) {
  const references = messages.flatMap((message) => getVisualReferencesFromMessage(message));

  if (references.length === 0) {
    return "Sin referencias visuales adjuntas.";
  }

  return references
    .map((reference, index) => {
      const note = reference.note ? ` Nota del usuario: ${reference.note}` : "";
      const visualSummary = reference.visualSummary ? ` Analisis automatico: ${reference.visualSummary}` : "";
      return `${index + 1}. ${reference.type.toUpperCase()} "${reference.fileName}" (${reference.mimeType}, ${formatBytes(reference.sizeBytes)}).${note}${visualSummary}`;
    })
    .join("\n");
}

function buildConstraintText(messages: MessageForSpec[]) {
  return [
    messages.map((message) => message.content_redacted).join("\n"),
    buildVisualReferenceContext(messages),
  ].join("\n").toLowerCase();
}

function extractReferenceFrameColor(messages: MessageForSpec[]) {
  const text = [
    messages.map((message) => message.content_redacted).join("\n"),
    buildVisualReferenceContext(messages),
  ].join("\n");
  const explicitFrameColor = text.match(/(?:frame\/border color|marco|border color)\s+(#[0-9a-fA-F]{6})/i);
  if (explicitFrameColor?.[1]) return explicitFrameColor[1].toUpperCase();

  const explicitHex = text.match(/#[0-9a-fA-F]{6}\b/);
  return explicitHex ? explicitHex[0].toUpperCase() : null;
}

function hasReferenceWireframeConstraint(messages: MessageForSpec[]) {
  const text = buildConstraintText(messages);

  return (
    text.includes("wireframe structure") ||
    text.includes("large left region plus right column split") ||
    text.includes("distribución de la imagen") ||
    text.includes("distribucion de la imagen") ||
    text.includes("estructura de la imagen") ||
    text.includes("color del marco") ||
    text.includes("conservando el color del marco")
  );
}

function hasSceneSwapConstraint(messages: MessageForSpec[]) {
  const text = buildConstraintText(messages);

  return (
    text.includes("todos los elementos de la izquierda se van a la derecha") ||
    text.includes("los de la derecha a la izquierda") ||
    text.includes("left") && text.includes("right") && text.includes("swap")
  );
}

function hasSupportExpansionConstraint(messages: MessageForSpec[]) {
  const text = buildConstraintText(messages);

  return (
    text.includes("si no hay b-roll") ||
    text.includes("si no hay broll") ||
    text.includes("si no hay diapositiva") ||
    text.includes("tomará el espacio del otro") ||
    text.includes("tomara el espacio del otro")
  );
}

function mergePropsSchemaProperties(spec: BundleAgentSpec, properties: Record<string, { type: "string" | "number" | "integer" | "boolean" | "array" | "object" | "null"; description?: string }>) {
  return {
    ...spec.propsSchema,
    type: "object" as const,
    properties: {
      ...(spec.propsSchema.properties || {}),
      ...properties,
    },
  };
}

function applyVisualReferenceConstraints(spec: BundleAgentSpec, messages: MessageForSpec[]) {
  const shouldLockReference = hasReferenceWireframeConstraint(messages);
  const shouldSwapScenes = shouldLockReference || hasSceneSwapConstraint(messages);
  const shouldExpandSupport = shouldLockReference || hasSupportExpansionConstraint(messages);

  if (!shouldLockReference && !shouldSwapScenes && !shouldExpandSupport) {
    return spec;
  }

  const accentColor = extractReferenceFrameColor(messages) || (
    typeof spec.defaultProps.accentColor === "string" ? spec.defaultProps.accentColor : spec.creativeBrief.colorTokens.accent
  );
  const requiredAssets = Array.from(new Set([
    ...spec.requiredAssets,
    ...(shouldLockReference ? ["avatar", "slides", "broll"] as const : []),
  ]));
  const motionDirectives = [
    shouldSwapScenes ? "Scene changes happen on slide changes; left and right regions trade sides with smooth positional interpolation." : null,
    shouldExpandSupport ? "If either slide or B-roll is missing, the available support media expands to occupy both right-side regions." : null,
  ].filter(Boolean).join(" ");
  const visualStyle = [
    spec.visualStyle,
    shouldLockReference ? "reference wireframe lock: orange frame, avatar left, slide top-right, B-roll bottom-right" : null,
    motionDirectives,
  ].filter(Boolean).join("; ").slice(0, 240);
  const creativeBrief = {
    ...spec.creativeBrief,
    directionName: shouldLockReference ? "Reference Wireframe Lock" : spec.creativeBrief.directionName,
    layoutSystem: shouldLockReference
      ? "Reference wireframe lock: thick colored outer frame, left half reserved for avatar, right half split equally with slide region above and B-roll region below."
      : spec.creativeBrief.layoutSystem,
    motionLanguage: [
      spec.creativeBrief.motionLanguage,
      motionDirectives,
    ].filter(Boolean).join(" ").slice(0, 500),
    colorTokens: {
      ...spec.creativeBrief.colorTokens,
      paletteName: shouldLockReference ? "Reference frame color" : spec.creativeBrief.colorTokens.paletteName,
      background: shouldLockReference ? accentColor : spec.creativeBrief.colorTokens.background,
      surface: shouldLockReference ? "#FFFFFF" : spec.creativeBrief.colorTokens.surface,
      accent: accentColor,
      text: shouldLockReference ? "#0F172A" : spec.creativeBrief.colorTokens.text,
      muted: shouldLockReference ? "#475569" : spec.creativeBrief.colorTokens.muted,
    },
    similarityCheck: {
      ...spec.creativeBrief.similarityCheck,
      differentiators: Array.from(new Set([
        "Reference image geometry is treated as a hard layout contract.",
        shouldSwapScenes ? "Left and right regions swap at every slide change." : null,
        shouldExpandSupport ? "Support media expands when slide or B-roll is missing." : null,
        ...spec.creativeBrief.similarityCheck.differentiators,
      ].filter((item): item is string => typeof item === "string"))).slice(0, 10),
    },
    visualVariants: [
      {
        id: "variant-reference-wireframe",
        name: "Reference wireframe",
        composition: "Avatar occupies the left half; slide and B-roll split the right half into upper and lower regions.",
        palette: `Reference frame color ${accentColor} with white content regions.`,
        motion: shouldSwapScenes ? "Scene-indexed left/right position swap with smooth interpolation." : "Measured opacity transitions aligned to slide changes.",
        emphasis: "Faithful structure and frame color from the uploaded reference.",
      },
      ...spec.creativeBrief.visualVariants.filter((variant) => variant.id !== "variant-reference-wireframe"),
    ].slice(0, 6),
  };

  return bundleAgentSpecSchema.parse({
    ...spec,
    templateFamily: shouldLockReference ? "reference-frame" : spec.templateFamily,
    visualStyle,
    creativeBrief,
    requiredAssets,
    propsSchema: mergePropsSchemaProperties(spec, {
      visualVariantId: { type: "string", description: "ID de variante visual declarada en creativeBrief.visualVariants." },
      animationVariant: { type: "string", description: "Ritmo de animacion elegido desde la direccion creativa." },
      designTokens: { type: "object", description: "Tokens visuales seguros expuestos por la direccion creativa." },
      sceneSwapOnSlideChange: { type: "boolean", description: "Intercambia izquierda/derecha al cambiar de diapositiva." },
      expandMissingSupportMedia: { type: "boolean", description: "Expande slide o B-roll cuando falta el otro soporte visual." },
    }),
    defaultProps: {
      ...spec.defaultProps,
      accentColor,
      animationVariant: shouldSwapScenes ? "scene-swap" : spec.defaultProps.animationVariant,
      designTokens: {
        ...(typeof spec.defaultProps.designTokens === "object" && spec.defaultProps.designTokens ? spec.defaultProps.designTokens : {}),
        backgroundColor: creativeBrief.colorTokens.background,
        surfaceColor: creativeBrief.colorTokens.surface,
        accentColor,
        textColor: creativeBrief.colorTokens.text,
        mutedTextColor: creativeBrief.colorTokens.muted,
        typographyDisplay: creativeBrief.typographyTokens.display,
        typographyBody: creativeBrief.typographyTokens.body,
      },
      expandMissingSupportMedia: shouldExpandSupport,
      sceneSwapOnSlideChange: shouldSwapScenes,
      visualVariantId: creativeBrief.visualVariants[0].id,
    },
    changeSummary: [
      spec.changeSummary,
      shouldLockReference ? "Applied uploaded reference as hard wireframe layout and frame-color contract." : null,
      shouldSwapScenes ? "Enabled scene swaps on slide changes." : null,
      shouldExpandSupport ? "Enabled support-media expansion when slide or B-roll is missing." : null,
    ].filter(Boolean).join(" "),
  });
}

function buildFallbackMessagesWithVisualContext(messages: MessageForSpec[]): MessageForSpec[] {
  const visualContext = buildVisualReferenceContext(messages);

  if (visualContext === "Sin referencias visuales adjuntas.") {
    return messages;
  }

  return [
    ...messages,
    {
      role: "USER",
      content_redacted: `Referencias visuales adjuntas para orientar estilo, layout, ritmo o atmosfera:\n${visualContext}`,
    },
  ];
}

function buildOpenAIInput(input: { title?: string | null; messages: MessageForSpec[] }): string | OpenAIInputMessage[] {
  const prompt = buildPrompt(input);
  const imageReferences = getImageReferences(input.messages).slice(0, 4);

  if (imageReferences.length === 0) {
    return prompt;
  }

  return [
    {
      role: "user",
      content: [
        { type: "input_text", text: prompt },
        ...imageReferences.map((reference) => ({
          type: "input_image" as const,
          image_url: reference.publicUrl!,
          detail: "high" as const,
        })),
      ],
    },
  ];
}

function buildGeminiContents(input: { title?: string | null; messages: MessageForSpec[] }) {
  const prompt = buildPrompt(input);
  const imageReferences = getImageReferences(input.messages).slice(0, 4);

  if (imageReferences.length === 0) {
    return prompt;
  }

  return [
    {
      role: "user",
      parts: [
        { text: prompt },
        ...imageReferences.map((reference) => ({
          fileData: {
            mimeType: reference.mimeType,
            fileUri: reference.publicUrl!,
          },
        })),
      ],
    },
  ];
}

function buildPrompt(input: {
  title?: string | null;
  messages: MessageForSpec[];
}) {
  const latestUserMessage = [...input.messages]
    .reverse()
    .find((message) => message.role === "USER")
    ?.content_redacted
    .trim() || "Sin mensaje de usuario.";
  const conversation = input.messages
    .map((message) => `${message.role}: ${message.content_redacted}`)
    .join("\n")
    .slice(0, 16_000);
  const visualReferences = buildVisualReferenceContext(input.messages).slice(0, 4_000);

  return `Eres ${APP_CONFIG.assistant.displayName} Bundle Agent dentro de ${APP_CONFIG.name}. Convierte esta conversacion en una especificacion JSON segura para un bundle de video.

Reglas estrictas:
- Responde solo JSON, sin markdown.
- No incluyas codigo fuente.
- No incluyas secretos, tokens, credenciales, URLs remotas ni datos sensibles.
- No pidas dependencias ni runtime arbitrario.
- Si el titulo sugerido es generico ("Nuevo bundle de video"), crea un titulo descriptivo basado en el diseño solicitado.
- description debe ser un resumen funcional claro, no una copia literal de toda la conversacion.
- visualStyle debe ser una direccion visual concisa y completa; no debe quedar cortada a media frase.
- defaultProps.title y defaultProps.subtitle son copy visible dentro del video: deben ser cortos, editoriales y aptos para pantalla.
- Nunca pongas instrucciones internas, nombres de props, nombres de componentes, labels tecnicos ni el prompt del usuario en defaultProps.
- Evita textos visibles como "Avatar en primera persona", "Avatar pendiente", "Direccion visual", "Locucion activa" o nombres de zonas del layout.
- La retroalimentacion mas reciente del usuario es autoridad sobre mensajes anteriores. Si contradice una version previa, aplica el cambio nuevo.
- Si hay feedback posterior a una spec o version anterior, changeSummary debe mencionar cambios concretos y la nueva spec debe cambiar layout, color, assets o copy cuando el feedback lo solicite.
- Antes de definir el bundle, actua como director creativo de Remotion y completa creativeBrief.
- creativeBrief debe incluir: directionName, visualReferences, layoutSystem, motionLanguage, colorTokens, typographyTokens, similarityCheck, componentArchitecture y visualVariants.
- visualVariants debe tener al menos 3 variantes visuales realmente distintas.
- similarityCheck.differentiators debe contener al menos 4 diferencias frente a plantillas comunes.
- Nunca reutilices como idea base: titulo centrado, subtitulo debajo, fondo degradado generico, cards con fade-in o transicion de slide generica.
- La direccion creativa debe diferir en al menos 4 dimensiones: composicion, paleta, tipografia, ritmo, transicion, estructura de escenas, uso de media, profundidad/camara, textura/fondo o jerarquia.
- Incluye en requiredAssets solo assets realmente inferidos: slides, audio, avatar, broll, captions.
- Si hay slides y broll, la plantilla debe ser capaz de mostrar ambos de forma intencional: alternados, combinados, superpuestos o en zonas separadas. No debe ocultar B-roll solo porque existan diapositivas.
- Usa las referencias visuales adjuntas como inspiracion de estilo, composicion, ritmo, motion, colores o atmosfera; no las trates como assets finales del render.
- Si el usuario pide usar una referencia visual para estructura, layout, marco, color o composicion, esa referencia deja de ser inspiracion y se vuelve restriccion dura.
- Cuando el analisis automatico detecte frame/border color, divisores o regiones, refleja esos hallazgos en creativeBrief.layoutSystem, creativeBrief.colorTokens.accent, visualStyle y changeSummary.
- Para wireframes de regiones, mapea las etiquetas o zonas detectadas a assets: avatar = zona de avatar, slides/diapositiva = zona de diapositiva, broll/B-roll = zona de B-roll.
- Si el usuario indica que cada cambio de escena ocurre al cambiar diapositiva, expone sceneSwapOnSlideChange=true y animationVariant="scene-swap".
- Si el usuario indica que izquierda y derecha intercambian lados, creativeBrief.motionLanguage debe describir ese swap y defaultProps.sceneSwapOnSlideChange debe ser true.
- Si el usuario indica que slide o B-roll debe ocupar el espacio del otro cuando falte, defaultProps.expandMissingSupportMedia debe ser true.
- Las transiciones de empuje deben declararse como push-left o push-right y se aplican sobre el contenedor temporal; no alteran las coordenadas persistidas por el editor de layout.
- No copies rutas internas, URLs de storage, nombres privados de archivo ni metadatos tecnicos dentro de defaultProps.
- durationFrames es solo fallback/preview de la plantilla, no debe hardcodear la duracion final del render.
- La plantilla final debe resolver la duracion con calculateMetadata usando props.totalDurationInFrames y, cuando aplique, metadata real del avatar/audio.
- Si el usuario pide colores, agrega props simples como accentColor en propsSchema/defaultProps.
- propsSchema/defaultProps debe exponer visualVariantId, animationVariant y designTokens cuando creativeBrief exista.
- templateFamily debe ser exactamente una de: asymmetric-studio, cinematic-field, editorial-rail, floating-collage, minimal-focus, reference-frame, split-contrast, stacked-evidence. Elige una sola familia que cambie de verdad composición, fondo y transición; si hay una referencia estructural, usa reference-frame.
- Usa compositionId estable con letras, numeros, punto, guion, dos puntos o guion bajo.
- durationFrames entre 30 y 900; fps entre 12 y 60; width max 3840; height max 2160.
- propsSchema debe ser JSON Schema simple type=object con properties de tipos basicos.
- defaultProps debe ser pequeno y compatible con propsSchema.

Contrato exacto:
{
  "title": "string",
  "description": "string",
  "visualStyle": "string",
  "templateFamily": "asymmetric-studio",
  "creativeBrief": {
    "directionName": "string",
    "visualReferences": ["string", "string"],
    "layoutSystem": "string",
    "motionLanguage": "string",
    "colorTokens": {
      "paletteName": "string",
      "background": "#05070B",
      "surface": "#111827",
      "accent": "#00D4B3",
      "secondary": "#8B5CF6",
      "text": "#F8FAFC",
      "muted": "#CBD5E1"
    },
    "typographyTokens": {
      "display": "string",
      "body": "string",
      "label": "string"
    },
    "similarityCheck": {
      "avoidedPatterns": ["Centered title with subtitle below", "Single gradient background", "Generic fade-in cards"],
