import { conformanceFontPath, conformanceFontManifestHash } from "../composition-conformance-font-bindings";
import { assertRequiredFontUsageEvidence } from "../qa/composition-font-usage-evidence";
import { createFontUsageEvidenceFixture } from "./fixtures/composition-font-usage.fixture";
import { evaluateCompositionConformance } from "../composition-preview-render-conformance";
import { COMPOSITION_TEXT_PARITY_POLICY } from "../composition-text-parity-policy";
import { assertConformanceReportMatchesContract } from "../qa/composition-conformance-contract-report-gate";

function fixture() {
  const {fontUsage} = createFontUsageEvidenceFixture([{frameIndex: 0, timeSeconds: 0}]);
  const font = fontUsage.manifest[0]!;
  const document = createInitialCompositionDocument({animatedDeck: null, assets: [], sourceInsertionMode: "MANUAL",
    plan: {accentColor: "#38BDF8", durationSeconds: 2, title: "Fonts", subtitle: "Frozen obligation"}});
  const {clip, track} = createCompositionNativeOverlay({document, id: "native", kind: "TEXT", playheadSeconds: 0});
  if (clip.source.type !== "NATIVE_TEXT") throw new Error("Expected text");
  clip.source.style.fontAssetId = font.fontAssetId; clip.source.style.fontFamily = font.family;
  if (track) document.tracks.push(track); document.clips.push(clip);
  document.format = NATIVE_TEXT_COMPOSITION_DOCUMENT_FORMAT;
  const input = {document, documentHash: hashCompositionDocument(document), assets: [],
    renderProfile: {format: "mp4" as const, fps: 25 as const, quality: "high" as const, resolution: "1080p" as const}};
  const contract = buildSnapshotConformanceContract({...input, contractVersion: 4, fontUsage: true, fontManifest: [font]});
  const fontAssets = new Map([[font.fontAssetId, {assetId: font.fontAssetId, family: font.family, format: "woff2" as const, sourceUrl: conformanceFontPath(font)}]]);
  return {font, input, contract, fontAssets, fontUsage};
}

test("font obligation is explicit v4 opt-in and freezes manifest identity and document-owned bindings", () => {
  const {input, contract, font} = fixture();
  assert.equal(contract.schemaVersion, 4);
  if (contract.schemaVersion !== 4) throw new Error("Expected v4");
  assert.equal(contract.fontUsageContract?.manifestSha256, conformanceFontManifestHash([font]));
  assert.deepEqual(contract.fontUsageContract?.bindings, [{elementId: "native-motion", fontAssetId: font.fontAssetId}]);
  for (const version of [1, 2, 3] as const) assert.equal("fontUsageContract" in buildSnapshotConformanceContract({...input, contractVersion: version, fontUsage: true}), false);
  assert.equal("fontUsageContract" in buildSnapshotConformanceContract({...input, contractVersion: 4}), false);
  assert.throws(() => buildSnapshotConformanceContract({...input, contractVersion: 4, fontUsage: true}), /MANIFEST_MISSING/);
});

test("producer and source reader recompute font obligation, even after authorized source hashes are updated", async () => {
  const {input, contract, font, fontAssets} = fixture();
  const source = await buildConformanceReferenceSource({document: input.document, contract, assets: [], fontAssets, fontManifest: [font]});
  assert.doesNotThrow(() => verifyConformanceReferenceSource({...source, fontManifest: [font]}));
  const changed = structuredClone(contract);
  if (changed.schemaVersion !== 4 || !changed.fontUsageContract) throw new Error("Expected font obligation");
  changed.fontUsageContract.bindings = [];
  await assert.rejects(buildConformanceReferenceSource({document: input.document, contract: changed, assets: [], fontAssets, fontManifest: [font]}), /FONT_CONTRACT_MISMATCH/);
  const contractJson = JSON.stringify(changed);
  assert.throws(() => verifyConformanceReferenceSource({...source, contractJson, fontManifest: [font],
    metadata: {...source.metadata, contractSha256: createHash("sha256").update(contractJson).digest("hex")}}), /FONT_CONTRACT_MISMATCH/);
});

test("deleting both witness copies or reducing its bindings cannot satisfy the independent contract", () => {
  const {contract, fontUsage} = fixture();
  assert.doesNotThrow(() => assertRequiredFontUsageEvidence(fontUsage, contract));
  assert.throws(() => assertRequiredFontUsageEvidence(undefined, contract), /REQUIRED_EVIDENCE_MISSING/);
  assert.throws(() => assertRequiredFontUsageEvidence({...fontUsage, bindings: []}, contract), /FROZEN_BINDING_MISMATCH/);
  assert.throws(() => assertRequiredFontUsageEvidence({...fontUsage, manifestSha256: "c".repeat(64)}, contract), /FROZEN_BINDING_MISMATCH/);
});

test("perfect image/text samples cannot grant full PASS while required renderer font evidence is unimplemented", () => {
  const {contract} = fixture();
  if (contract.schemaVersion !== 4) throw new Error("Expected v4");
  const samples = contract.textParity.checkpoints.map((checkpoint) => ({frameIndex: checkpoint.frameIndex,
    meanAbsoluteError: 0, mismatchedPixelRatio: 0, psnrDb: 99, temporalDriftMs: 0, ssim: 1,
    width: contract.canvas.width, height: contract.canvas.height,
    textParity: {policy: COMPOSITION_TEXT_PARITY_POLICY.id, status: "PASS" as const,
      expectedRegionCount: checkpoint.expectedTexts.length, checkedRegionCount: checkpoint.expectedTexts.length,
      maximumAcceptedDisplacementPixels: 0, regions: checkpoint.expectedTexts.map((text) => ({elementId: text.elementId,
        status: "PASS" as const, reason: null, displacementX: 0, displacementY: 0, meanAbsoluteError: 0, mismatchedPixelRatio: 0}))}}));
  const params = {contract, samples, previewDocumentHash: contract.documentHash, renderDocumentHash: contract.documentHash};
  const pending = evaluateCompositionConformance(params);
  assert.equal(pending.status, "INCOMPLETE");
  assertConformanceReportMatchesContract(contract, pending);
  assert.throws(() => assertConformanceReportMatchesContract(contract, {...pending, status: "PASS"}), /FONT_ATTESTATION_PENDING/);
  assert.throws(() => assertConformanceReportMatchesContract(contract, {...pending, fontUsage: {
    ...pending.fontUsage!, manifestSha256: "f".repeat(64)}}), /FONT_USAGE_CONTRACT/);
  assert.throws(() => assertConformanceReportMatchesContract(contract, {...pending, incompletenessReasons: []}), /FONT_ATTESTATION_PENDING/);
  assert.deepEqual(pending.fontUsage, {policy: contract.fontUsageContract!.policy, scope: "RENDERER_GLYPH_PROVENANCE",
    status: "INCOMPLETE", reason: "RENDERER_FONT_USAGE_EVIDENCE_UNAVAILABLE",
    manifestSha256: contract.fontUsageContract!.manifestSha256, requiredBindingCount: contract.fontUsageContract!.bindings.length});
  const {fontUsageContract: _fontUsageContract, ...legacy} = contract;
  assert.equal(evaluateCompositionConformance({...params, contract: legacy}).status, "PASS");
});

import assert from "node:assert/strict";
import test from "node:test";
import sharp from "sharp";
import { mkdtemp, mkdir, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { measureFrameSsim } from "../qa/composition-frame-ssim";
import { COMPOSITION_SSIM_POLICY as policy } from "../composition-visual-metrics-policy";
import { buildCompositionConformanceContract, evaluateCompositionConformance, resolveSnapshotConformanceContractVersion } from "../composition-preview-render-conformance";
import { compareCompositionConformanceDirectories } from "../qa/composition-conformance-files";
import { createTransitionDocument } from "./composition-transition-test-fixtures";

const rgb = (width: number, height: number, value: number) => Buffer.alloc(width * height * 3, value);
function contract(version: 2 | 3 = 3) {
  const document = createTransitionDocument(); document.canvas.width = 32; document.canvas.height = 24;
  return buildCompositionConformanceContract({document, contractVersion: version, assets: [], documentHash: "a".repeat(64),
    renderProfile: {format: "mp4", fps: 25, quality: "high", resolution: "1080p"}});
}

test("identical black/white/gradient images and narrow edge windows score one", () => {
  for (const [width, height] of [[1, 1], [2, 19], [32, 24]]) {
    for (const value of [0, 255]) assert.ok(Math.abs(measureFrameSsim(rgb(width!, height!, value), rgb(width!, height!, value), width!, height!, 3) - 1) < 1e-12);
    const gradient = rgb(width!, height!, 0); gradient.forEach((_, index) => {gradient[index] = index % 256;});
    assert.ok(Math.abs(measureFrameSsim(gradient, gradient, width!, height!, 3) - 1) < 1e-12);
  }
});

test("constant fields agree with closed-form SSIM and symmetry", () => {
  const left = rgb(15, 23, 64), right = rgb(15, 23, 80);
  const c1 = (policy.k1 * policy.dynamicRange) ** 2;
  const expected = (2 * 64 * 80 + c1) / (64 ** 2 + 80 ** 2 + c1);
  const actual = measureFrameSsim(left, right, 15, 23, 3);
  assert.ok(Math.abs(actual - expected) < 1e-12);
  assert.equal(actual, measureFrameSsim(right, left, 15, 23, 3));
});

test("separable ring buffer matches independent direct 2D Gaussian oracle across evictions", () => {
  const width = 7, height = 19, left = rgb(width, height, 0), right = rgb(width, height, 0);
  for (let index = 0; index < left.length; index++) {left[index] = (index * 31) % 256; right[index] = (index * 29) % 256;}
  const weights = Array.from({length: 11}, (_, index) => Math.exp(-((index - 5) ** 2) / (2 * 1.5 ** 2)));
  const sum = weights.reduce((total, value) => total + value, 0); let totalScore = 0;
  const luma = (image: Buffer, x: number, y: number) => {
    const offset = (Math.max(0, Math.min(height - 1, y)) * width + Math.max(0, Math.min(width - 1, x))) * 3;
    return image[offset]! * 0.2126 + image[offset + 1]! * 0.7152 + image[offset + 2]! * 0.0722;
  };
  for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
    let meanLeft = 0, meanRight = 0, squareLeft = 0, squareRight = 0, product = 0;
    for (let dy = 0; dy < 11; dy++) for (let dx = 0; dx < 11; dx++) {
      const weight = weights[dy]! * weights[dx]! / (sum ** 2);
      const a = luma(left, x + dx - 5, y + dy - 5), b = luma(right, x + dx - 5, y + dy - 5);
      meanLeft += weight * a; meanRight += weight * b; squareLeft += weight * a * a;
      squareRight += weight * b * b; product += weight * a * b;
    }
    totalScore += ((2 * meanLeft * meanRight + 6.5025) * (2 * (product - meanLeft * meanRight) + 58.5225))
      / ((meanLeft ** 2 + meanRight ** 2 + 6.5025) * (squareLeft - meanLeft ** 2 + squareRight - meanRight ** 2 + 58.5225));
  }
  assert.ok(Math.abs(measureFrameSsim(left, right, width, height, 3) - totalScore / (width * height)) < 1e-12);
});

test("local structural distortion fails threshold without alignment or gain correction", () => {
  const left = rgb(32, 24, 120), right = Buffer.from(left);
  for (let y = 8; y < 16; y++) for (let x = 12; x < 20; x++) right.fill(240, (y * 32 + x) * 3, (y * 32 + x + 1) * 3);
  assert.ok(measureFrameSsim(left, right, 32, 24, 3) < policy.minimum);
});

test("frame quota, shape and channel mismatches fail explicitly", () => {
  for (const [width, height, channels] of [[0, 1, 3], [1, 1, 2], [3841, 2160, 3], [NaN, 1, 3], [1.5, 1, 3]]) {
    assert.throws(() => measureFrameSsim(Buffer.alloc(3), Buffer.alloc(3), width!, height!, channels!), /FRAME_INVALID/);
  }
  assert.throws(() => measureFrameSsim(Buffer.alloc(3), Buffer.alloc(6), 1, 1, 3), /FRAME_INVALID/);
});

test("opaque RGBA is equivalent to RGB, transparency is not silently ignored", () => {
  const rgba = Buffer.from([64, 64, 64, 255]);
  assert.equal(measureFrameSsim(rgba, rgba, 1, 1, 4), measureFrameSsim(rgb(1, 1, 64), rgb(1, 1, 64), 1, 1, 3));
  const transparent = Buffer.from(rgba); transparent[3] = 0;
  assert.throws(() => measureFrameSsim(rgba, transparent, 1, 1, 4), /NON_OPAQUE_FRAME/);
});

test("v3 freezes SSIM, preserves v1/v2 rules and requires metric plus real resolution", () => {
  const frozen = contract(); const samples = frozen.checkpoints.map(({frameIndex}) => ({frameIndex, meanAbsoluteError: 0,
    mismatchedPixelRatio: 0, psnrDb: 99, temporalDriftMs: 0, width: 32, height: 24, ssim: 1}));
  const evaluate = (input: typeof samples) => evaluateCompositionConformance({contract: frozen,
    previewDocumentHash: frozen.documentHash, renderDocumentHash: frozen.documentHash, samples: input});
  assert.equal(evaluate(samples).status, "PASS"); assert.equal(evaluate(samples).ssim?.minimumObserved, 1);
  assert.equal(evaluate(samples.map((sample) => ({...sample, ssim: 0.994}))).status, "FAIL");
  assert.equal(evaluate([{...samples[0]!, ssim: 0.994}]).status, "FAIL");
  assert.equal(evaluate(samples.map((sample) => ({...sample, width: 33}))).status, "FAIL");
  const missing = samples.map(({ssim: _ssim, ...sample}) => sample);
  assert.equal(evaluateCompositionConformance({contract: frozen, previewDocumentHash: frozen.documentHash,
    renderDocumentHash: frozen.documentHash, samples: missing}).status, "INCOMPLETE");
  assert.equal(evaluateCompositionConformance({contract: contract(2), previewDocumentHash: frozen.documentHash,
    renderDocumentHash: frozen.documentHash, samples: missing}).status, "PASS");
  assert.equal(resolveSnapshotConformanceContractVersion(undefined, "true"), 3);
  assert.equal(resolveSnapshotConformanceContractVersion("true", "TRUE"), 2);
});

test("PNG directory comparator measures SSIM through the production path and keeps observed minima", async () => {
  const root = await mkdtemp(join(tmpdir(), "composition-ssim-"));
  try {
    const frozen = contract(); const previewDirectory = join(root, "preview"), renderDirectory = join(root, "render");
    await Promise.all([mkdir(previewDirectory), mkdir(renderDirectory)]);
    const image = await sharp(rgb(32, 24, 100), {raw: {width: 32, height: 24, channels: 3}}).png().toBuffer();
    const metadata = {documentHash: frozen.documentHash, frames: frozen.checkpoints.map(({frameIndex, timeSeconds}) => ({frameIndex, timeSeconds}))};
    const contractPath = join(root, "contract.json"), metadataPath = join(root, "metadata.json");
    await writeFile(contractPath, JSON.stringify(frozen)); await writeFile(metadataPath, JSON.stringify(metadata));
    for (const checkpoint of frozen.checkpoints) {
      await writeFile(join(previewDirectory, `frame-${checkpoint.frameIndex}.png`), image);
      await writeFile(join(renderDirectory, `frame-${checkpoint.frameIndex}.png`), image);
    }
    const result = await compareCompositionConformanceDirectories({contractPath, previewDirectory, renderDirectory,
      previewMetadataPath: metadataPath, renderMetadataPath: metadataPath});
    assert.equal(result.status, "PASS"); assert.equal(result.ssim?.checkedCheckpointCount, frozen.checkpoints.length);
    assert.ok(result.ssim!.minimumObserved! >= policy.minimum);
  } finally {await rm(root, {recursive: true, force: true});}
});

import test from "node:test";
import assert from "node:assert/strict";
import type { SupabaseClient } from "@supabase/supabase-js";
import { CompositionHtmlEditingBootstrapHost } from "../composition-html-editing-bootstrap-host.server";
import { bindHtmlEditingRevisionToComposition } from "../composition-html-editing-document.server";
import { computeHtmlEditingInitializationRequestSha256 } from "../composition-html-editing-initialization-operation-digest.server";
import { HtmlEditingTemplateCatalog } from "../html-editing/html-editing-template-catalog.server";
import { createHtmlEditingRevisionFixture as fixture, htmlEditingFixtureId as uuid,
  htmlEditingFixtureOtherId as other } from "./composition-html-editing-test-fixtures";

function host() {
  const input = fixture();
  const binding = input.current.revision.manifest.binding;
  const template = { format: "courseforge-html-editable-template-v1", templateId: binding.templateId,
    templateVersion: binding.templateVersion, sourceSha256: binding.sourceSha256, elements: input.current.revision.manifest.elements };
  const catalog = new HtmlEditingTemplateCatalog(JSON.stringify({ format: "courseforge-html-editable-catalog-v1",
    organizationId: uuid, templates: [template] }));
  const state = { bootstrap: { organizationId: uuid, documentId: uuid, clipId: binding.clipId, revisionId: other,
    documentHash: input.row.compositionDocumentHash, document: input.document, grantedAssetIds: [uuid, other] },
    revision: input.row, error: false, acknowledgement: true as unknown,
    receiptRead: { status: "NOT_FOUND" } as unknown, operationCommitError: false };
  const calls: Array<{ name: string; args: Record<string, any>; signal: AbortSignal }> = [];
  const supabase = { rpc: (name: string, args: Record<string, any>) => ({ abortSignal: async (signal: AbortSignal) => {
    calls.push({ name, args, signal });
    return { data: name === "read_html_editing_bootstrap_context" ? structuredClone(state.bootstrap)
      : name === "read_html_editing_revision" ? structuredClone(state.revision)
        : name === "read_html_editing_initialization_operation" ? state.receiptRead : state.acknowledgement,
    error: state.error || (state.operationCommitError && name === "commit_html_editing_initialization_operation") ? { message: "PRIVATE_TOKEN" } : null };
  } }) } as unknown as SupabaseClient;
  const service = new CompositionHtmlEditingBootstrapHost(supabase, catalog);
  const request = { actorId: uuid, organizationId: uuid, documentId: uuid, clipId: binding.clipId,
    templateId: binding.templateId, templateVersion: binding.templateVersion, expectedDocumentHash: input.row.compositionDocumentHash };
  return { input, state, calls, service, request };
}

function operation(scenario: ReturnType<typeof host>) {
  const request = { templateId: scenario.request.templateId, templateVersion: scenario.request.templateVersion,
    expectedDocumentHash: scenario.request.expectedDocumentHash };
  return { scope: "HTML_INITIALIZATION_RECEIPT_NOT_CURRENT_STATE_OR_RENDERED", owner: { actorId: uuid, organizationId: uuid, draftId: uuid },
    operationId: other, requestSha256: computeHtmlEditingInitializationRequestSha256(request), clipId: scenario.request.clipId, request,
    acknowledgment: { status: "CONFIRMED", created: true, version: 1, sha256: scenario.input.current.sha256,
      compositionDocumentHash: scenario.request.expectedDocumentHash } };
}

test("durable bootstrap first reads scoped receipt then prepares current authority and commits once without legacy readback", async () => {
  const scenario = host(), receipt = operation(scenario); scenario.state.acknowledgement = receipt;
  assert.deepEqual(await scenario.service.registerOperation({ ...scenario.request, operationId: other }), receipt);
  assert.deepEqual(scenario.calls.map(call => call.name), ["read_html_editing_initialization_operation", "read_html_editing_bootstrap_context",
    "commit_html_editing_initialization_operation"]);
  assert.equal(scenario.calls[2]!.args.p_request_sha256, receipt.requestSha256);
  assert.deepEqual(scenario.calls[2]!.args.p_used_asset_ids, [uuid]);
});

