    await assert.rejects(scenario.service.registerOperation({ ...scenario.request, operationId: other,
      ...(mismatch === "hash" ? { expectedDocumentHash: "f".repeat(64) } : mismatch === "template" ? { templateVersion: 2 } : {}) }));
