      storagePath: "broll/snapshot.mp4",
      timelineRole: "BROLL",
    }],
    plan: { accentColor: "#38BDF8", durationSeconds: 10, subtitle: "Prueba", title: "Snapshot" },
  });
}

function chain(data: unknown, single = true) {
  const query: Record<string, any> = {};
  for (const method of ["contains", "eq", "limit", "order", "select"]) {
    query[method] = () => query;
  }
  query.maybeSingle = async () => ({ data: single ? data : null, error: null });
  query.then = (resolve: (value: unknown) => unknown) => resolve({ data, error: null });
  return query;
}

function rpcChain(data: unknown) {
  const query: Record<string, any> = {};
  query.retry = () => query;
  query.abortSignal = () => query;
  query.then = (resolve: (value: unknown) => unknown) => resolve({ data, error: null });
  return query;
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { buildCompositionAgentProposal } from "./composition-agent-proposal.service";
import {
  compositionAgentProposalEnvelopeSchema,
  type CompositionAgentProposalEnvelope,
} from "./composition-agent-proposal.types";
import { simulateCompositionAgentOperations } from "./composition-agent-simulation.service";
import {
  getCurrentCompositionDocument,
  hashCompositionDocument,
} from "./composition-document.service";
import { applyCompositionEditorPatches } from "./editor-patch.service";
import type { CompositionEditorDocument } from "./composition-document.types";
import type { CompositionAgentRecoveryMetadata } from "./composition-agent-recovery.service";

export const COMPOSITION_AGENT_PROPOSAL_TTL_MS = 15 * 60 * 1_000;

const PROPOSAL_STATUSES = ["APPLIED", "DISMISSED", "EXPIRED", "PENDING", "UNDONE"] as const;
type ProposalStatus = typeof PROPOSAL_STATUSES[number];

interface StoredCompositionAgentProposal {
  appliedDocumentHash: string | null;
  appliedVersion: number | null;
  baseDocumentHash: string;
  envelope: CompositionAgentProposalEnvelope;
  expiresAt: string;
  model: string;
  status: ProposalStatus;
  undoneDocumentHash: string | null;
  undoneVersion: number | null;
}

export class CompositionAgentProposalStoreError extends Error {
  constructor(
    message: string,
    readonly code:
      | "PROPOSAL_CONFIRMATION_REQUIRED"
      | "PROPOSAL_CONFLICT"
      | "PROPOSAL_EXPIRED"
      | "PROPOSAL_STORAGE_NOT_READY"
      | "PROPOSAL_UNAVAILABLE"
      | "PROPOSAL_UNDO_CONFLICT",
    readonly status: number,
    readonly retryable = false,
  ) {
    super(message);
  }
}

export async function persistCompositionAgentProposal(params: {
  draftId: string;
  envelope: CompositionAgentProposalEnvelope;
  model: string;
  organizationId: string;
  recovery: CompositionAgentRecoveryMetadata;
  supabase: SupabaseClient<any, "public", any>;
  userId: string;
}) {
  const envelope = compositionAgentProposalEnvelopeSchema.parse(params.envelope);
  const expiresAt = new Date(Date.now() + COMPOSITION_AGENT_PROPOSAL_TTL_MS).toISOString();
  const { error } = await params.supabase.from("video_composition_agent_proposals").insert({
    base_document_hash: envelope.baseDocumentHash,
    created_by: params.userId,
    draft_id: params.draftId,
    envelope,
    expires_at: expiresAt,
    id: envelope.proposalId,
    model: params.model,
    organization_id: params.organizationId,
    recovery_attempt_count: params.recovery.attemptCount,
    recovery_repaired: params.recovery.repaired,
    recovery_used_fallback: params.recovery.usedFallback,
    schema_version: envelope.schemaVersion,
    status: "PENDING",
  });
  if (error) throw normalizeProposalStorageError(error);
  return { expiresAt };
}

export async function getCompositionAgentPreviewDocument(params: ProposalLookupParams) {
  const stored = await getStoredProposal(params);
  assertPendingProposalAvailable(stored);
  const current = await getCurrentCompositionDocument(params);
  if (current.documentHash !== stored.baseDocumentHash) throw proposalConflict();
  return rebuildAndSimulate(stored, current.document).document;
}

export async function applyStoredCompositionAgentProposal(params: ProposalLookupParams & {
  expectedDocumentHash: string;
  reinforcedConfirmation: boolean;
  signal?: AbortSignal;
  userId: string;
}) {
  const stored = await getStoredProposal(params);
  const current = await getCurrentCompositionDocument(params);

  if (stored.status === "APPLIED" || stored.status === "UNDONE") {
    return { ...(await getCurrentCompositionDocument(params)), idempotentReplay: true, proposalStatus: stored.status };
  }
  assertPendingProposalAvailable(stored);
  if (params.expectedDocumentHash !== stored.baseDocumentHash || current.documentHash !== stored.baseDocumentHash) {
    throw proposalConflict();
  }

  const rebuilt = rebuildAndSimulate(stored, current.document);
  if (rebuilt.envelope.risk.requiresReinforcedConfirmation && !params.reinforcedConfirmation) {
    throw new CompositionAgentProposalStoreError(
      "Esta propuesta requiere una confirmación reforzada antes de aplicarse.",
      "PROPOSAL_CONFIRMATION_REQUIRED",
      409,
    );
  }
  const nextHash = hashCompositionDocument(rebuilt.document);
  let request = params.supabase.rpc("apply_video_composition_agent_proposal", {
    p_actor_id: params.userId,
    p_document: rebuilt.document,
    p_document_hash: nextHash,
    p_draft_id: params.draftId,
    p_expected_document_hash: params.expectedDocumentHash,
    p_format: rebuilt.document.format,
    p_metadata: proposalAuditMetadata(stored, rebuilt.envelope),
    p_organization_id: params.organizationId,
    p_proposal_id: params.proposalId,
    p_reinforced_confirmation: params.reinforcedConfirmation,
    p_summary: rebuilt.envelope.summary,
  }).retry(false);
  if (params.signal) request = request.abortSignal(params.signal);
  const { data, error } = await request;
  if (error) throw normalizeProposalStorageError(error);
  const outcome = parseRpcOutcome(data);
  assertApplyOutcome(outcome.outcome);
  return {
    ...(await getCurrentCompositionDocument(params)),
    idempotentReplay: outcome.outcome === "ALREADY_APPLIED" || outcome.outcome === "ALREADY_UNDONE",
    proposalStatus: outcome.outcome === "ALREADY_UNDONE" ? "UNDONE" as const : "APPLIED" as const,
  };
}

export async function undoStoredCompositionAgentProposal(params: ProposalLookupParams & {
  expectedDocumentHash: string;
  signal?: AbortSignal;
  userId: string;
}) {
  const stored = await getStoredProposal(params);
  if (stored.status === "UNDONE") {
    return { ...(await getCurrentCompositionDocument(params)), idempotentReplay: true, proposalStatus: "UNDONE" as const };
  }
  if (stored.status !== "APPLIED" || !stored.appliedDocumentHash) {
    throw new CompositionAgentProposalStoreError(
      "La propuesta no está aplicada y no se puede deshacer.",
      "PROPOSAL_UNDO_CONFLICT",
      409,
    );
  }
  const current = await getCurrentCompositionDocument(params);
  if (
    params.expectedDocumentHash !== stored.appliedDocumentHash
    || current.documentHash !== stored.appliedDocumentHash
  ) {
    throw new CompositionAgentProposalStoreError(
      "La composición cambió después de aplicar la propuesta. Restaura una versión desde el historial para evitar perder cambios posteriores.",
      "PROPOSAL_UNDO_CONFLICT",
      409,
    );
  }

  const { document: nextDocument, documentHash: nextHash } = prepareCompositionAgentProposalUndo({
    appliedDocument: current.document,
    envelope: stored.envelope,
  });

  let request = params.supabase.rpc("undo_video_composition_agent_proposal", {
    p_actor_id: params.userId,
    p_document: nextDocument,
    p_document_hash: nextHash,
    p_draft_id: params.draftId,
    p_expected_document_hash: params.expectedDocumentHash,
    p_format: nextDocument.format,
    p_metadata: { inverseOperationTypes: stored.envelope.inverseOperations.map((operation) => operation.type) },
    p_organization_id: params.organizationId,
    p_proposal_id: params.proposalId,
    p_summary: `Deshizo la propuesta: ${stored.envelope.summary}`.slice(0, 300),
  }).retry(false);
  if (params.signal) request = request.abortSignal(params.signal);
  const { data, error } = await request;
  if (error) throw normalizeProposalStorageError(error);
  const outcome = parseRpcOutcome(data);
  if (outcome.outcome === "UNDO_CONFLICT") {
    throw new CompositionAgentProposalStoreError(
      "La composición cambió después de aplicar la propuesta y no puede deshacerse automáticamente.",
      "PROPOSAL_UNDO_CONFLICT",
      409,
    );
  }
  if (outcome.outcome !== "UNDONE" && outcome.outcome !== "ALREADY_UNDONE") {
    assertCommonMutationOutcome(outcome.outcome);
  }
  return {
    ...(await getCurrentCompositionDocument(params)),
    idempotentReplay: outcome.outcome === "ALREADY_UNDONE",
    proposalStatus: "UNDONE" as const,
  };
}

export async function dismissStoredCompositionAgentProposal(params: ProposalLookupParams) {
  const { error } = await params.supabase
    .from("video_composition_agent_proposals")
    .update({ status: "DISMISSED", updated_at: new Date().toISOString() })
    .eq("id", params.proposalId)
    .eq("draft_id", params.draftId)
    .eq("organization_id", params.organizationId)
    .eq("status", "PENDING");
  if (error) throw normalizeProposalStorageError(error);
}

interface ProposalLookupParams {
  draftId: string;
  organizationId: string;
  proposalId: string;
  supabase: SupabaseClient<any, "public", any>;
}

async function getStoredProposal(params: ProposalLookupParams): Promise<StoredCompositionAgentProposal> {
  const { data, error } = await params.supabase
    .from("video_composition_agent_proposals")
    .select("applied_document_hash, applied_version, base_document_hash, envelope, expires_at, model, status, undone_document_hash, undone_version")
    .eq("id", params.proposalId)
    .eq("draft_id", params.draftId)
    .eq("organization_id", params.organizationId)
    .maybeSingle();
  if (error) throw normalizeProposalStorageError(error);
  if (!data || !PROPOSAL_STATUSES.includes(data.status as ProposalStatus)) {
    throw new CompositionAgentProposalStoreError("La propuesta ya no está disponible.", "PROPOSAL_UNAVAILABLE", 404);
  }
  return {
    appliedDocumentHash: data.applied_document_hash as string | null,
    appliedVersion: data.applied_version as number | null,
    baseDocumentHash: data.base_document_hash as string,
    envelope: compositionAgentProposalEnvelopeSchema.parse(data.envelope),
    expiresAt: data.expires_at as string,
    model: data.model as string,
    status: data.status as ProposalStatus,
    undoneDocumentHash: data.undone_document_hash as string | null,
    undoneVersion: data.undone_version as number | null,
  };
}

function assertPendingProposalAvailable(stored: StoredCompositionAgentProposal) {
  if (stored.status !== "PENDING") {
    throw new CompositionAgentProposalStoreError("La propuesta ya no está pendiente.", "PROPOSAL_UNAVAILABLE", 409);
  }
  if (Date.parse(stored.expiresAt) <= Date.now()) {
    throw new CompositionAgentProposalStoreError("La propuesta expiró. Solicita una nueva para trabajar sobre la versión actual.", "PROPOSAL_EXPIRED", 410);
  }
}

export function prepareCompositionAgentProposalApplication(params: {
  baseDocumentHash: string;
  document: CompositionEditorDocument;
  envelope: CompositionAgentProposalEnvelope;
}) {
  const envelope = buildCompositionAgentProposal({
    baseDocumentHash: params.baseDocumentHash,
    document: params.document,
    patch: { operations: params.envelope.operations, source: "AGENT", summary: params.envelope.summary },
    proposalId: params.envelope.proposalId,
  });
  const simulation = simulateCompositionAgentOperations(params.document, envelope.operations);
  return { document: simulation.document, envelope };
}

export function prepareCompositionAgentProposalUndo(params: {
  appliedDocument: CompositionEditorDocument;
  envelope: CompositionAgentProposalEnvelope;
}) {
  const document = applyCompositionEditorPatches(
    params.appliedDocument,
    params.envelope.inverseOperations,
    "USER",
  );
  const documentHash = hashCompositionDocument(document);
  if (documentHash !== params.envelope.baseDocumentHash) {
    throw new CompositionAgentProposalStoreError(
      "La reversión ya no reproduce exactamente la versión original.",
      "PROPOSAL_UNDO_CONFLICT",
      409,
    );
  }
  return { document, documentHash };
}

function rebuildAndSimulate(stored: StoredCompositionAgentProposal, document: CompositionEditorDocument) {
  return prepareCompositionAgentProposalApplication({
    baseDocumentHash: stored.baseDocumentHash,
    document,
    envelope: stored.envelope,
  });
}

function proposalAuditMetadata(stored: StoredCompositionAgentProposal, envelope: CompositionAgentProposalEnvelope) {
  return {
    model: stored.model,
    operationTypes: envelope.operations.map((operation) => operation.type),
    riskLevel: envelope.risk.level,
    schemaVersion: envelope.schemaVersion,
    validationCodes: envelope.validation.issues.map((issue) => issue.code),
  };
}

function parseRpcOutcome(data: unknown) {
  const row = Array.isArray(data) ? data[0] : data;
  if (!row || typeof row !== "object" || typeof (row as { outcome?: unknown }).outcome !== "string") {
    throw new CompositionAgentProposalStoreError("El almacenamiento devolvió un resultado inválido.", "PROPOSAL_STORAGE_NOT_READY", 503, true);
  }
  return row as { document_hash: string | null; outcome: string; version: number | null };
}

function assertApplyOutcome(outcome: string) {
  if (outcome === "APPLIED" || outcome === "ALREADY_APPLIED" || outcome === "ALREADY_UNDONE") return;
  if (outcome === "CONFIRMATION_REQUIRED") {
    throw new CompositionAgentProposalStoreError("La propuesta requiere confirmación reforzada.", "PROPOSAL_CONFIRMATION_REQUIRED", 409);
  }
  if (outcome === "PROPOSAL_EXPIRED") {
    throw new CompositionAgentProposalStoreError("La propuesta expiró.", "PROPOSAL_EXPIRED", 410);
  }
  assertCommonMutationOutcome(outcome);
}

function assertCommonMutationOutcome(outcome: string) {
  if (outcome === "CONFLICT" || outcome === "UNDO_CONFLICT") throw proposalConflict();
  if (outcome === "PROPOSAL_UNAVAILABLE" || outcome === "NOT_EDITABLE") {
    throw new CompositionAgentProposalStoreError("La propuesta o el borrador ya no están disponibles.", "PROPOSAL_UNAVAILABLE", 409);
  }
  if (outcome === "BUSY") {
    throw new CompositionAgentProposalStoreError("Ya hay otro cambio guardándose. Vuelve a intentar.", "PROPOSAL_CONFLICT", 409, true);
  }
  throw new CompositionAgentProposalStoreError("No se pudo guardar la propuesta.", "PROPOSAL_STORAGE_NOT_READY", 503, true);
}

function proposalConflict() {
  return new CompositionAgentProposalStoreError(
    "La composición cambió desde que se creó la propuesta. Solicita una nueva propuesta.",
    "PROPOSAL_CONFLICT",
    409,
  );
}

function normalizeProposalStorageError(error: unknown) {
  const candidate = error && typeof error === "object" ? error as { code?: unknown; message?: unknown } : {};
  if (candidate.code === "PGRST202" || /Could not find the function|relation .* does not exist/i.test(String(candidate.message || ""))) {
    return new CompositionAgentProposalStoreError(
      "El almacenamiento de propuestas aún no está disponible. Aplica la migración correspondiente.",
      "PROPOSAL_STORAGE_NOT_READY",
      503,
      true,
    );
  }
  return error;
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { compositionEditorDocumentSchema, type CompositionClip, type CompositionEditorDocument, type CompositionTrack } from "./composition-document.types";

export type AssemblyBrandingAsset = {
  checksum: string;
  durationMilliseconds: number;
  id: string;
  hasAudio: boolean;
  kind: "INTRO" | "OUTRO";
  mimeType: string;
  name: string;
  storageBucket: string;
  storagePath: string;
  sourceHeight: number | null;
  sourceWidth: number | null;
};

export type ResolvedAssemblyBranding = {
  intro: AssemblyBrandingAsset | null;
  introSource: "ASSEMBLY_OVERRIDE" | "GENERATED" | "ORG_DEFAULT";
  outro: AssemblyBrandingAsset | null;
};

/** Resolves only approved, tenant-owned branding. No client-provided asset id is trusted. */
export async function resolveAssemblyBranding(params: {
  draftId: string;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}): Promise<ResolvedAssemblyBranding> {
  const { data: draftBranding, error: draftError } = await params.supabase
    .from("video_composition_draft_branding")
    .select("intro_asset_id, intro_source, outro_asset_id")
    .eq("draft_id", params.draftId)
    .eq("organization_id", params.organizationId)
    .maybeSingle();
  if (draftError) throw draftError;
  // Intros now belong to each video's Production assets. Preserve an explicit
  // historical draft intro, but never inject a global organization default.
  const usesDraftOverride = draftBranding?.intro_source === "ASSEMBLY_OVERRIDE" || draftBranding?.intro_source === "GENERATED";
  const introId = usesDraftOverride ? draftBranding?.intro_asset_id : null;
  // Outros are reusable corporate assets, selected explicitly per video.
  const outroId = draftBranding?.outro_asset_id || null;
  const ids = [introId, outroId].filter((id): id is string => typeof id === "string");
  if (ids.length === 0) return { intro: null, introSource: "ORG_DEFAULT", outro: null };
  const { data, error } = await params.supabase
    .from("organization_assembly_assets")
    .select("id, kind, name, storage_bucket, storage_path, mime_type, duration_milliseconds, checksum, metadata")
    .eq("organization_id", params.organizationId)
    .eq("status", "APPROVED")
    .in("id", ids);
  if (error) throw error;
  const byId = new Map((data || []).map((row) => [row.id as string, mapAsset(row)]));
  const intro = introId ? byId.get(introId) || null : null;
  const outro = outroId ? byId.get(outroId) || null : null;
  if (intro && intro.kind !== "INTRO") throw new Error("El asset configurado como intro tiene un tipo inválido.");
  if (outro && outro.kind !== "OUTRO") throw new Error("El asset configurado como outro tiene un tipo inválido.");
  return {
    intro,
    introSource: draftBranding?.intro_source === "ASSEMBLY_OVERRIDE" || draftBranding?.intro_source === "GENERATED"
      ? draftBranding.intro_source
      : "ORG_DEFAULT",
    outro,
  };
}

export function buildAssemblyBrandingSnapshot(asset: AssemblyBrandingAsset) {
  return {
    checksum: asset.checksum,
    duration_milliseconds: asset.durationMilliseconds,
    mime_type: asset.mimeType,
    name: asset.name,
    has_audio: asset.hasAudio,
    source_height: asset.sourceHeight,
    source_width: asset.sourceWidth,
    storage_bucket: asset.storageBucket,
    storage_path: asset.storagePath,
  };
}

/** Materializes the resolved branding as timeline clips without embedding media bytes. */
export function reconcileAssemblyBrandingDocument(
  document: CompositionEditorDocument,
  branding: ResolvedAssemblyBranding,
) {
  const previousBrandingIds = new Set(document.clips.flatMap((clip) => (
    clip.source.type === "ASSEMBLY_BRAND_ASSET" ? [clip.id] : []
  )));
  const content = document.clips.filter((clip) => !previousBrandingIds.has(clip.id));
  if (content.length === 0) throw new Error("La composición debe conservar contenido además del intro y outro.");
  const retainedIntro = findRetainedBrandingClip(document, branding.intro, "INTRO");
  const retainedOutro = findRetainedBrandingClip(document, branding.outro, "OUTRO");
  const introDuration = retainedIntro?.durationSeconds ?? (branding.intro ? branding.intro.durationMilliseconds / 1_000 : 0);
  const outroDuration = retainedOutro?.durationSeconds ?? (branding.outro ? branding.outro.durationMilliseconds / 1_000 : 0);
  const currentContentStart = Math.min(...content.map((clip) => clip.startSeconds));
  const shift = roundSeconds(introDuration - currentContentStart);
  const shiftedContent = content.map((clip) => ({ ...clip, startSeconds: roundSeconds(clip.startSeconds + shift) }));
  const contentEnd = Math.max(...shiftedContent.map((clip) => clip.startSeconds + clip.durationSeconds));
  const track = resolveBrandingTrack(document);
  const occupiedIds = new Set(shiftedContent.flatMap((clip) => [clip.id, clip.hfId]));
  for (const retained of [retainedIntro, retainedOutro]) {
    if (retained) { occupiedIds.add(retained.id); occupiedIds.add(retained.hfId); }
  }
  const clips: CompositionClip[] = [...shiftedContent];
  if (branding.intro) clips.push(retainedIntro ? { ...retainedIntro, startSeconds: 0 } : buildBrandingClip({ asset: branding.intro, document, id: uniqueEditorId("assembly-intro", occupiedIds), placement: "INTRO", startSeconds: 0, trackId: track.id }));
  if (branding.outro) clips.push(retainedOutro ? { ...retainedOutro, startSeconds: roundSeconds(contentEnd) } : buildBrandingClip({ asset: branding.outro, document, id: uniqueEditorId("assembly-outro", occupiedIds), placement: "OUTRO", startSeconds: roundSeconds(contentEnd), trackId: track.id }));
  const retainedIds = new Set([retainedIntro?.id, retainedOutro?.id]);
  const tracks = document.tracks.some((candidate) => candidate.id === track.id)
    ? document.tracks
    : [...document.tracks, track];
  return compositionEditorDocumentSchema.parse({
    ...document,
    canvas: { ...document.canvas, durationMode: "AUTO", durationSeconds: roundSeconds(contentEnd + outroDuration) },
    clips,
    motion: {
      ...document.motion,
      animations: document.motion.animations.filter((animation) => !previousBrandingIds.has(animation.target.clipId) || retainedIds.has(animation.target.clipId)),
    },
    tracks,
  });
}

function findRetainedBrandingClip(document: CompositionEditorDocument, asset: AssemblyBrandingAsset | null, placement: "INTRO" | "OUTRO"): CompositionClip | undefined {
  return asset ? document.clips.find((clip) => clip.source.type === "ASSEMBLY_BRAND_ASSET"
    && clip.source.assemblyBrandAssetId === asset.id && clip.source.placement === placement) : undefined;
}

function buildBrandingClip(params: { asset: AssemblyBrandingAsset; document: CompositionEditorDocument; id: string; placement: "INTRO" | "OUTRO"; startSeconds: number; trackId: string }): CompositionClip {
  const durationSeconds = roundSeconds(params.asset.durationMilliseconds / 1_000);
  return {
    durationSeconds,
    hidden: false,
    hfId: `${params.id}-media`,
    id: params.id,
    kind: "VIDEO",
    label: params.placement === "INTRO" ? `Intro · ${params.asset.name}` : `Outro · ${params.asset.name}`,
    layout: { height: params.document.canvas.height, opacity: 1, rotation: 0, width: params.document.canvas.width, x: 0, y: 0, zIndex: 10 },
    mediaFit: "COVER",
    source: {
      assemblyBrandAssetId: params.asset.id,
      hasAudio: params.asset.hasAudio,
      placement: params.placement,
      ...(params.asset.sourceHeight ? { sourceHeight: params.asset.sourceHeight } : {}),
      ...(params.asset.sourceWidth ? { sourceWidth: params.asset.sourceWidth } : {}),
      type: "ASSEMBLY_BRAND_ASSET",
    },
    sourceDurationSeconds: durationSeconds,
    sourceOffsetSeconds: 0,
    startSeconds: params.startSeconds,
    timingSource: "ESTIMATED",
    trackId: params.trackId,
    volume: params.asset.hasAudio ? 1 : 0,
  };
}

function resolveBrandingTrack(document: CompositionEditorDocument): CompositionTrack {
  const existing = document.tracks.find((track) => track.id === "assembly-branding");
  if (existing) return existing;
  if (document.tracks.length >= 32) {
    const visual = document.tracks.find((track) => track.kind === "VISUAL");
    if (!visual) throw new Error("La composición no tiene espacio para el track de intro y outro.");
    return visual;
  }
  return { id: "assembly-branding", kind: "VISUAL", label: "Intro / Outro", locked: false, order: Math.min(99, Math.max(...document.tracks.map((track) => track.order)) + 1), semanticRole: "VISUAL", volume: 1 };
}

function uniqueEditorId(base: string, occupied: Set<string>) {
  let candidate = base;
  let suffix = 2;
  while (occupied.has(candidate) || occupied.has(`${candidate}-media`)) candidate = `${base}-${suffix++}`;
  occupied.add(candidate);
  occupied.add(`${candidate}-media`);
  return candidate;
}

function roundSeconds(value: number) {
  return Math.round(value * 1_000) / 1_000;
}

function mapAsset(row: Record<string, unknown>): AssemblyBrandingAsset {
  const metadata = row.metadata && typeof row.metadata === "object" && !Array.isArray(row.metadata)
    ? row.metadata as Record<string, unknown>
    : {};
  return {
    checksum: String(row.checksum),
    durationMilliseconds: Number(row.duration_milliseconds),
    id: String(row.id),
    hasAudio: metadata.has_audio === true,
    kind: row.kind === "OUTRO" ? "OUTRO" : "INTRO",
    mimeType: String(row.mime_type),
    name: String(row.name),
    storageBucket: String(row.storage_bucket),
    storagePath: String(row.storage_path),
    sourceHeight: readPositiveInteger(metadata.source_height),
    sourceWidth: readPositiveInteger(metadata.source_width),
  };
}

function readPositiveInteger(value: unknown) {
  return typeof value === "number" && Number.isInteger(value) && value > 0 ? value : null;
}

import { getCompositionGroupingCapabilities } from "./composition-group-capabilities.server";
import { buildCompositionGroupIndex } from "./composition-group-hierarchy";
import { assertCompositionGroupingWrite } from "./composition-group-policy";
import { readStandaloneHtmlLibrary, hasCanonicalHtmlSource } from "../standalone/standalone-timeline-library.service";
import { isRelatedAudioProcessingReplacement, type AudioReplacementRecord } from "../audio-processing/audio-replacement-policy";
import { preservesCompositionHtmlRevisionReferences } from "./composition-html-editing-reference-policy";
import { randomUUID } from "node:crypto";
import { hashCompositionDocument } from "./composition-document-hash";
export { hashCompositionDocument } from "./composition-document-hash";
import type { SupabaseClient } from "@supabase/supabase-js";
import { compositionEditorDocumentSchema, type CompositionEditorDocument } from "./composition-document.types";
import { applyCompositionEditorPatches, CompositionEditorPatchError } from "./editor-patch.service";
import type { CompositionEditorPatchRequest } from "./editor-patch.types";
import { normalizeCompositionTrackTopology } from "./composition-track-registry";
import { COMPOSITION_MOTION_ENABLED, isCompositionMotionOperation } from "./composition-motion.config";
import { buildCompositionAgentDiff } from "./composition-agent-diff.service";
import { assertCompositionAgentOperationsAllowed, CompositionAgentPolicyError } from "./composition-agent-policy.service";
import { validateCompositionAgentSimulation, CompositionAgentValidationError } from "./composition-agent-validation.service";
import { normalizeCompositionDocumentLayerDepths } from "./composition-layer-depth";
import { readReadyLinkedSoundEffectAssetIds } from "./composition-sound-effect-assets.service";
import { isCompositionDocumentHash } from "./composition-preview-comparison";
import { isUsableCompositionReplacementAsset, replacementAssetStoragePath, type CompositionReplacementAssetRecord } from "./composition-replacement-asset";

export class CompositionDocumentError extends Error {
  constructor(message: string, readonly status = 400) {
    super(message);
  }
}

export class CompositionDocumentConflictError extends CompositionDocumentError {
  constructor(readonly current: Awaited<ReturnType<typeof getCurrentCompositionDocument>>) {
    super("La composición cambió en otra sesión. Recarga el preview antes de volver a editar.", 409);
  }
}

/**
 * Normalizes PostgREST/Postgres failures before they cross the API boundary.
 * Supabase errors are plain objects (not Error instances), which used to turn
 * every database failure into an unhelpful "Unknown error" in route logs.
 */
export class CompositionDocumentPersistenceError extends CompositionDocumentError {
  constructor(
    message: string,
    readonly code: string,
    status = 500,
    readonly retryable = false,
    readonly diagnosticId?: string,
  ) {
    super(message, status);
  }
}

/** Stores only the first version. Future edits append a new version atomically. */
export async function ensureInitialCompositionDocument(params: {
  document: CompositionEditorDocument;
  draftId: string;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
  userId: string;
}) {
  const parsed = compositionEditorDocumentSchema.parse(params.document);
  const existing = await getLatestCompositionDocument(params);
  if (existing) return { created: false, document: existing.document, version: existing.version };

  const documentHash = hashCompositionDocument(parsed);
  const { data: inserted, error } = await params.supabase
    .from("video_composition_draft_documents")
    .insert({
      created_by: params.userId,
      document: parsed,
      document_hash: documentHash,
      draft_id: params.draftId,
      format: parsed.format,
      organization_id: params.organizationId,
      version: 1,
    })
    .select("document, version")
    .single();
  if (!error) return { created: true, document: inserted.document as CompositionEditorDocument, version: inserted.version as number };
  if (error.code === "23505") {
    const concurrent = await getLatestCompositionDocument(params);
    if (concurrent) return { created: false, document: concurrent.document, version: concurrent.version };
  }
  throw error;
}

export async function getCurrentCompositionDocument(params: {
  draftId: string;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const current = await getLatestCompositionDocument(params);
  if (!current) throw new CompositionDocumentError("El documento de composición aún no está disponible.", 404);
  return current;
}

/** Returns one immutable saved document version for side-by-side preview. */
export async function getCompositionDocumentByHash(params: {
  documentHash: string;
  draftId: string;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  if (!isCompositionDocumentHash(params.documentHash)) {
    throw new CompositionDocumentError("La versión de comparación no es válida.", 400);
  }

  const { data, error } = await params.supabase
    .from("video_composition_draft_documents")
    .select("document, document_hash, version")
    .eq("draft_id", params.draftId)
    .eq("organization_id", params.organizationId)
    .eq("document_hash", params.documentHash.toLowerCase())
    .order("version", { ascending: false })
    .limit(1)
    .maybeSingle();
  if (error) throw error;
  if (!data) throw new CompositionDocumentError("La versión de comparación ya no está disponible.", 404);

  return resolveCompositionDocumentRow({
    assetLinks: await getDraftAssetLinks(params),
    document: data.document,
    documentHash: data.document_hash,
    version: data.version,
  });
}

/** Returns immutable prior states for explicit user-directed restoration. */
export async function listCompositionDocumentHistory(params: {
  draftId: string;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const { data, error } = await params.supabase
    .from("video_composition_draft_documents")
    .select("created_at, document, document_hash, version")
    .eq("draft_id", params.draftId)
    .eq("organization_id", params.organizationId)
    .order("version", { ascending: false })
    .limit(20);
  if (error) throw error;
  return (data || []).map((row: {
    created_at: string;
    document: unknown;
    document_hash: string;
    version: number;
  }) => ({
    createdAt: row.created_at,
    document: parsePersistedCompositionDocument(row.document),
    documentHash: row.document_hash,
    version: row.version,
  }));
}

export async function applyAndAppendCompositionDocumentPatches(params: {
  auditSource?: "SYSTEM";
  draftId: string;
  expectedDocumentHash: string;
  groupingClientVersion?: string | null;
  organizationId: string;
  patch: CompositionEditorPatchRequest;
  signal?: AbortSignal;
  supabase: SupabaseClient<any, "public", any>;
  userId: string;
}) {
  if (!COMPOSITION_MOTION_ENABLED && params.patch.operations.some((operation) => isCompositionMotionOperation(operation.type))) {
    throw new CompositionDocumentError("La edición de animaciones está deshabilitada temporalmente para este despliegue.", 409);
  }
  const current = await getCurrentCompositionDocument(params);
  if (current.documentHash !== params.expectedDocumentHash) throw new CompositionDocumentConflictError(current);
  await assertReferencedAssetsBelongToDraft({ ...params, currentDocument: current.document });
  if (current.document.sourceInsertionMode === "MANUAL") {
    const addedHtml = params.patch.operations.flatMap((operation) => operation.type === "clip.add" && operation.clip.source.type === "DECK_SLIDE" ? [operation.clip] : []);
    if (addedHtml.length) {
      const { data: draft, error: draftError } = await params.supabase.from("video_composition_drafts")
        .select("composition_id").eq("id", params.draftId).eq("organization_id", params.organizationId).single();
      if (draftError) throw draftError;
      const { data: composition, error: compositionError } = await params.supabase.from("video_compositions")
        .select("material_component_id").eq("id", draft.composition_id).eq("organization_id", params.organizationId).single();
      if (compositionError) throw compositionError;
      const library = await readStandaloneHtmlLibrary({ componentId: composition.material_component_id, organizationId: params.organizationId, supabase: params.supabase });
      if (addedHtml.some((clip) => !hasCanonicalHtmlSource(clip, library))) {
        throw new CompositionDocumentError("La diapositiva no corresponde a un HTML preparado de este proyecto.", 422);
      }
    }
  }

  let nextDocument: CompositionEditorDocument;
  try {
    const enforceAgentPolicy = params.patch.source === "AGENT" && params.auditSource !== "SYSTEM";
    if (enforceAgentPolicy) {
      assertCompositionAgentOperationsAllowed(params.patch.operations);
    }
    nextDocument = applyCompositionEditorPatches(current.document, params.patch.operations, params.auditSource || params.patch.source);
    if (enforceAgentPolicy) {
      validateCompositionAgentSimulation({
        after: nextDocument,
        before: current.document,
        diff: buildCompositionAgentDiff(current.document, nextDocument),
      });
    }
  } catch (error) {
    if (
      error instanceof CompositionEditorPatchError
      || error instanceof CompositionAgentPolicyError
      || error instanceof CompositionAgentValidationError
    ) throw new CompositionDocumentError(error.message);
    throw error;
  }
  assertCompositionGroupingWrite({ before: current.document, after: nextDocument,
    // SYSTEM procede del llamador interno; nunca se acepta desde el payload HTTP.
    clientVersion: params.auditSource === "SYSTEM" ? "2" : params.groupingClientVersion,
    ...await getCompositionGroupingCapabilities(params.supabase) });
  const nextHash = hashCompositionDocument(nextDocument);
  // Generic timeline/history commands cannot publish or retarget HTML revision
  // references. Only the dedicated atomic HTML repository may do that.
  if (!preservesCompositionHtmlRevisionReferences(current.document, nextDocument)) {
    throw new CompositionDocumentError("Las revisiones HTML deben cambiarse mediante su guardado versionado específico.", 422);
  }
  const documentBytes = Buffer.byteLength(JSON.stringify(nextDocument), "utf8");
  const groupIndex = buildCompositionGroupIndex(nextDocument.groups);
  const rpcStartedAt = Date.now();
  let appendRequest = params.supabase.rpc("append_video_composition_draft_document_v2", {
    p_actor_id: params.userId,
    p_document: nextDocument,
    p_document_hash: nextHash,
    p_draft_id: params.draftId,
    p_expected_document_hash: params.expectedDocumentHash,
    p_format: nextDocument.format,
    p_metadata: {
      groupCount: nextDocument.groups?.length || 0,
      groupingVersion: nextDocument.groupingVersion ?? 1,
      groupedClipCount: groupIndex.parentByClipId.size,
      maxGroupDepth: Math.max(0, ...groupIndex.depthByGroupId.values()),
      motionAnimationCount: nextDocument.motion.animations.length,
      motionKeyframeCount: nextDocument.motion.animations.reduce((total, animation) => total + animation.keyframes.length, 0),
      operations: params.patch.operations.map((operation) => operation.type),
      transitionCount: nextDocument.transitions?.items.length || 0,
    },
    p_organization_id: params.organizationId,
    p_source: params.auditSource || params.patch.source,
    p_summary: params.patch.summary,
  }).retry(false);
  if (params.signal) appendRequest = appendRequest.abortSignal(params.signal);
  const { data, error } = await appendRequest;

  if (error) {
    const diagnosticId = randomUUID();
    logCompositionPersistenceFailure({
      diagnosticId,
      documentBytes,
      elapsedMs: Date.now() - rpcStartedAt,
      error,
      clipCount: nextDocument.clips.length,
      operationTypes: [...new Set(params.patch.operations.map((operation) => operation.type))],
    });
    throw normalizeCompositionPersistenceError(error, diagnosticId);
  }
  const result = Array.isArray(data) ? data[0] : data;
  if (!result) throw new CompositionDocumentError("No se pudo guardar la nueva versión de la composición.", 500);
  const outcome = result.outcome as string;
  if (outcome === "CONFLICT") {
    throw new CompositionDocumentConflictError(await getCurrentCompositionDocument(params));
  }
  if (outcome === "BUSY") {
    throw new CompositionDocumentPersistenceError(
      "Ya hay otro cambio guardándose en esta composición. Espera un momento y vuelve a intentarlo.",
      "COMPOSITION_SAVE_BUSY",
      409,
      true,
    );
  }
  if (outcome === "NOT_EDITABLE") {
    throw new CompositionDocumentPersistenceError(
      "El borrador ya no está disponible para edición.",
      "COMPOSITION_DRAFT_NOT_EDITABLE",
      409,
      false,
    );
  }
  if (outcome !== "APPENDED" && outcome !== "UNCHANGED") {
    throw new CompositionDocumentPersistenceError(
      "El almacenamiento devolvió un resultado de guardado desconocido.",
      "COMPOSITION_APPEND_OUTCOME_INVALID",
      500,
      false,
    );
  }
  return {
    document: nextDocument,
    documentHash: result.document_hash as string,
    version: result.version as number,
  };
}

/** Prevents add, replace and restore from referencing assets outside this draft. */
async function assertReferencedAssetsBelongToDraft(params: {
  currentDocument: CompositionEditorDocument;
  draftId: string;
  organizationId: string;
  patch: CompositionEditorPatchRequest;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const assetIds = [...new Set(params.patch.operations.flatMap((operation) => {
    if (operation.type === "clip.add" && operation.clip.source.type === "PRODUCTION_ASSET") {
      return [operation.clip.source.productionAssetId];
    }
    if (operation.type === "clip.replace-source") return [operation.productionAssetId];
    if (operation.type === "document.restore" || operation.type === "document.reconcile") {
      return operation.document.clips.flatMap((clip) => (
        clip.source.type === "PRODUCTION_ASSET" ? [clip.source.productionAssetId] : []
      ));
    }
    return [];
  }))];
  const soundEffectAssetIds = [...new Set(params.patch.operations.flatMap((operation) => {
    if (operation.type === "clip.add" && operation.clip.source.type === "SOUND_EFFECT_ASSET") {
      return [operation.clip.source.soundEffectAssetId];
    }
    if (operation.type === "document.restore" || operation.type === "document.reconcile") {
      return operation.document.clips.flatMap((clip) => (
        clip.source.type === "SOUND_EFFECT_ASSET" ? [clip.source.soundEffectAssetId] : []
      ));
    }
    return [];
  }))];
  const brandingAssetIds = [...new Set(params.patch.operations.flatMap((operation) => {
    if (operation.type === "clip.add" && operation.clip.source.type === "ASSEMBLY_BRAND_ASSET") {
      return [operation.clip.source.assemblyBrandAssetId];
    }
    if (operation.type === "document.restore" || operation.type === "document.reconcile") {
      return operation.document.clips.flatMap((clip) => (
        clip.source.type === "ASSEMBLY_BRAND_ASSET" ? [clip.source.assemblyBrandAssetId] : []
      ));
    }
    return [];
  }))];
  if (assetIds.length === 0 && brandingAssetIds.length === 0 && soundEffectAssetIds.length === 0) return;
  const sourceIds = params.patch.operations.flatMap((operation) => {
    if (operation.type !== "clip.replace-source") return [];
    const source = params.currentDocument.clips.find((clip) => clip.id === operation.clipId)?.source;
    return source?.type === "PRODUCTION_ASSET" ? [source.productionAssetId] : [];
  });
  const linkLookupIds = [...new Set([...assetIds, ...sourceIds])];

  const [{ data, error }, { data: branding, error: brandingError }, linkedSoundEffectIds] = await Promise.all([
    assetIds.length > 0
      ? params.supabase.from("video_composition_draft_assets").select("production_asset_id").eq("draft_id", params.draftId).eq("organization_id", params.organizationId).in("production_asset_id", linkLookupIds)
      : Promise.resolve({ data: [], error: null }),
    brandingAssetIds.length > 0
      ? params.supabase.from("video_composition_draft_branding").select("intro_asset_id, outro_asset_id").eq("draft_id", params.draftId).eq("organization_id", params.organizationId).maybeSingle()
      : Promise.resolve({ data: null, error: null }),
    readReadyLinkedSoundEffectAssetIds({
      draftId: params.draftId,
      organizationId: params.organizationId,
      soundEffectAssetIds,
      supabase: params.supabase,
    }),
  ]);
  if (error) throw error;
  if (brandingError) throw brandingError;
  const linkedIds = new Set((data || []).map((row: { production_asset_id: string }) => row.production_asset_id));
  const replacements = params.patch.operations.filter((operation) => operation.type === "clip.replace-source");
  if (replacements.length > 0) {
    const replacementIds = [...new Set(replacements.flatMap((operation) => {
      const source = params.currentDocument.clips.find((clip) => clip.id === operation.clipId)?.source;
      return [operation.productionAssetId, ...(source?.type === "PRODUCTION_ASSET" ? [source.productionAssetId] : [])];
    }))];
    const { data: registry, error: registryError } = await params.supabase.from("production_assets")
      .select("id, asset_type, provider, material_component_id, checksum, file_size_bytes, mime_type, duration_milliseconds, duration_seconds, metadata, qa_status, storage_bucket, storage_path")
      .eq("organization_id", params.organizationId)
      .in("id", replacementIds);
    if (registryError) throw registryError;
    const byId = new Map((registry || []).map((row: { id: string }) => [row.id, row]));
    const validatedAssets = new Map<string, CompositionReplacementAssetRecord>();
    for (const operation of replacements) {
      delete operation.audioProcessingPreviousAssetId;
      const asset = byId.get(operation.productionAssetId) as (CompositionReplacementAssetRecord & {
        duration_milliseconds: number | null;
        duration_seconds: number | null;
      }) | undefined;
      if (!asset || !isUsableCompositionReplacementAsset(asset)) {
        throw new CompositionDocumentError("El medio de reemplazo no está disponible.", 422);
      }
      const currentSource = params.currentDocument.clips.find((clip) => clip.id === operation.clipId)?.source;
      const currentAsset = currentSource?.type === "PRODUCTION_ASSET" ? byId.get(currentSource.productionAssetId) : null;
      if (currentSource?.type === "PRODUCTION_ASSET" && linkedIds.has(currentSource.productionAssetId) && currentAsset
        && isRelatedAudioProcessingReplacement(currentAsset as AudioReplacementRecord, asset as unknown as AudioReplacementRecord)) {
        operation.audioProcessingPreviousAssetId = currentSource.productionAssetId;
      }
      validatedAssets.set(operation.productionAssetId, asset);
      // Never trust media metadata submitted by the browser: normalize from
      // the tenant-scoped registry before applying and persisting the patch.
      operation.mimeType = asset.mime_type!;
      const duration = typeof asset.duration_milliseconds === "number" && asset.duration_milliseconds > 0
        ? asset.duration_milliseconds / 1000 : asset.duration_seconds;
      if (typeof duration === "number" && duration > 0) operation.sourceDurationSeconds = duration;
      else delete operation.sourceDurationSeconds;
      const metadata = asset.metadata || {};
      operation.hasAudio = typeof metadata.has_audio === "boolean" ? metadata.has_audio : undefined;
      operation.sourceWidth = typeof metadata.source_width === "number" ? metadata.source_width : undefined;
      operation.sourceHeight = typeof metadata.source_height === "number" ? metadata.source_height : undefined;
      if (!linkedIds.has(operation.productionAssetId) && operation.audioProcessingPreviousAssetId) {
        const { error: linkError } = await params.supabase.from("video_composition_draft_assets").upsert({
          draft_id: params.draftId, organization_id: params.organizationId, production_asset_id: operation.productionAssetId,
          role: "VOICE", source_reference: "PRODUCTION_MEDIA",
        }, { onConflict: "draft_id,production_asset_id" });
        if (linkError) throw linkError;
        linkedIds.add(operation.productionAssetId);
      }
    }
    if (assetIds.some((assetId) => !linkedIds.has(assetId))) {
      throw new CompositionDocumentError("El asset seleccionado no está vinculado a este borrador.");
    }
    // Check only replacement candidates, not every existing clip. This also
    // permits relinking a clip whose previous object has disappeared.
    for (const asset of validatedAssets.values()) {
      const storageResult = await params.supabase.storage.from(asset.storage_bucket!).info(replacementAssetStoragePath(asset))
        .catch(() => {
          throw new CompositionDocumentPersistenceError("No se pudo verificar el archivo de reemplazo. Inténtalo de nuevo.", "COMPOSITION_REPLACEMENT_STORAGE_UNAVAILABLE", 503, true);
        });
      const { data: storedObject, error: storageError } = storageResult;
      if (storageError) {
        if (storageError.status === 404) throw new CompositionDocumentError("El archivo de reemplazo ya no existe en Storage.", 422);
        throw new CompositionDocumentPersistenceError("No se pudo verificar el archivo de reemplazo. Inténtalo de nuevo.", "COMPOSITION_REPLACEMENT_STORAGE_UNAVAILABLE", 503, true);
      }
      if (!storedObject || (typeof storedObject.size === "number" && storedObject.size !== asset.file_size_bytes)) {
        throw new CompositionDocumentError("El archivo de reemplazo no coincide con el registro de medios.", 422);
      }
    }
  }
  if (assetIds.some((assetId) => !linkedIds.has(assetId))) {
    throw new CompositionDocumentError("El asset seleccionado no está vinculado a este borrador.");
  }
  const linkedBrandingIds = new Set([branding?.intro_asset_id, branding?.outro_asset_id].filter((id): id is string => typeof id === "string"));
  if (brandingAssetIds.some((assetId) => !linkedBrandingIds.has(assetId))) {
    throw new CompositionDocumentError("El intro u outro seleccionado no está vinculado a este borrador.");
  }
  if (soundEffectAssetIds.some((assetId) => !linkedSoundEffectIds.has(assetId))) {
    throw new CompositionDocumentError("El efecto de sonido seleccionado no está listo o no está vinculado a este borrador.", 409);
  }
}

export function normalizeCompositionPersistenceError(error: unknown, diagnosticId?: string) {
  const candidate = error && typeof error === "object" ? error as {
    code?: unknown;
    message?: unknown;
  } : {};
  const code = typeof candidate.code === "string" ? candidate.code : "COMPOSITION_PERSISTENCE_FAILED";
  const message = typeof candidate.message === "string" ? candidate.message : "";

  if (code === "PGRST202" || /Could not find the function/i.test(message)) {
    return new CompositionDocumentPersistenceError(
      "El almacenamiento versionado del editor no est\u00e1 disponible. Aplica la migraci\u00f3n de composiciones y vuelve a intentar.",
      "COMPOSITION_STORAGE_NOT_READY",
      503,
      true,
      diagnosticId,
    );
  }
  if (
    code === "PGRST003"
    || /timed out acquiring connection|connection pool|pool timeout|fetch failed|upstream request timeout|gateway timeout/i.test(message)
  ) {
    return new CompositionDocumentPersistenceError(
      "El almacenamiento está ocupado y no pudo guardar a tiempo. Tus cambios siguen en el editor; reintenta en unos segundos.",
      "COMPOSITION_STORAGE_UNAVAILABLE",
      503,
      true,
      diagnosticId,
    );
  }
  if (code === "57014") {
    return new CompositionDocumentPersistenceError(
      "El guardado excedió el tiempo permitido. Tus cambios siguen en el editor; vuelve a intentar una vez.",
      "COMPOSITION_SAVE_TIMEOUT",
      503,
      true,
      diagnosticId,
    );
  }
  if (code === "42501") {
    return new CompositionDocumentPersistenceError(
      "No tienes permisos para guardar cambios en esta composici\u00f3n.",
      "COMPOSITION_SAVE_FORBIDDEN",
      403,
      false,
      diagnosticId,
    );
  }
  if (code === "P0002") {
    return new CompositionDocumentPersistenceError(
      "El borrador ya no est\u00e1 disponible para edici\u00f3n.",
      "COMPOSITION_DRAFT_NOT_EDITABLE",
      409,
      false,
      diagnosticId,
    );
  }
  if (code === "55P03") {
    return new CompositionDocumentPersistenceError(
      "Ya hay otro cambio guardándose en esta composición. Espera un momento y vuelve a intentarlo.",
      "COMPOSITION_SAVE_BUSY",
      409,
      true,
      diagnosticId,
    );
  }
  if (code === "22023") {
    return new CompositionDocumentPersistenceError(
      "La versi\u00f3n o los datos de auditor\u00eda de la edici\u00f3n no son v\u00e1lidos.",
      "COMPOSITION_AUDIT_INVALID",
      400,
      false,
      diagnosticId,
    );
  }
  if (code === "42702") {
    return new CompositionDocumentPersistenceError(
      "El almacenamiento versionado requiere una actualizaci\u00f3n de base de datos antes de poder guardar.",
      "COMPOSITION_STORAGE_MIGRATION_REQUIRED",
      503,
      true,
      diagnosticId,
    );
  }
  return new CompositionDocumentPersistenceError(
    "No se pudo guardar la nueva versi\u00f3n de la composici\u00f3n.",
    "COMPOSITION_PERSISTENCE_FAILED",
    500,
    true,
    diagnosticId,
  );
}

function logCompositionPersistenceFailure(params: {
  clipCount: number;
  diagnosticId: string;
  documentBytes: number;
  elapsedMs: number;
  error: unknown;
  operationTypes: string[];
}) {
  const candidate = params.error && typeof params.error === "object"
    ? params.error as Record<string, unknown>
    : {};
  console.error("[CompositionDocumentPersistence] RPC failed", {
    clipCount: params.clipCount,
    diagnosticId: params.diagnosticId,
    documentBytes: params.documentBytes,
    elapsedMs: params.elapsedMs,
    event: "composition_document_append_failed",
    operationTypes: params.operationTypes,
    postgres: {
      code: safeDiagnosticText(candidate.code, 32),
      details: safeDiagnosticText(candidate.details, 500),
      hint: safeDiagnosticText(candidate.hint, 300),
      message: safeDiagnosticText(candidate.message, 500),
    },
  });
}

function safeDiagnosticText(value: unknown, maxLength: number) {
  if (typeof value !== "string" || !value.trim()) return null;
  return value
    .replace(/\b[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\b/gi, "[redacted-uuid]")
    .replace(/(bearer\s+)[^\s]+/gi, "$1[redacted]")
    .slice(0, maxLength);
}

async function getLatestCompositionDocument(params: {
  draftId: string;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const { data, error } = await params.supabase
    .from("video_composition_draft_documents")
    .select("document, document_hash, version")
    .eq("draft_id", params.draftId)
    .eq("organization_id", params.organizationId)
    .order("version", { ascending: false })
    .limit(1)
    .maybeSingle();
  if (error) throw error;
  if (!data) return null;
  return resolveCompositionDocumentRow({
    assetLinks: await getDraftAssetLinks(params),
    document: data.document,
    documentHash: data.document_hash,
    version: data.version,
  });
}

async function getDraftAssetLinks(params: {
  draftId: string;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const { data, error } = await params.supabase
    .from("video_composition_draft_assets")
    .select("production_asset_id, role")
    .eq("draft_id", params.draftId)
    .eq("organization_id", params.organizationId);
  if (error) throw error;
  return (data || []) as Array<{ production_asset_id: string; role: string }>;
}

function resolveCompositionDocumentRow(params: {
  assetLinks: Array<{ production_asset_id: string; role: string }>;
  document: unknown;
  documentHash: unknown;
  version: unknown;
}) {
  const documentHash = String(params.documentHash || "");
  if (!isCompositionDocumentHash(documentHash)) {
    throw new CompositionDocumentPersistenceError(
      "La versión almacenada de la composición no tiene un identificador válido.",
      "COMPOSITION_DOCUMENT_HASH_INVALID",
      500,
      false,
    );
  }
  const parsedDocument = parsePersistedCompositionDocument(params.document);
  const assetRoles = new Map(params.assetLinks.map((link) => [link.production_asset_id, link.role]));
  return {
    document: compositionEditorDocumentSchema.parse(normalizeCompositionTrackTopology(parsedDocument, assetRoles)),
    documentHash: documentHash.toLowerCase(),
    version: Number(params.version),
  };
}

function parsePersistedCompositionDocument(input: unknown): CompositionEditorDocument {
  return compositionEditorDocumentSchema.parse(
    normalizeCompositionDocumentLayerDepths(input),
  );
}

import { createHash } from "node:crypto";
import type { SupabaseClient } from "@supabase/supabase-js";
import type { CompositionEditorDocument } from "./composition-document.types";
import type { CompositionCompiledFont, OrganizationFontRecord } from "../fonts/organization-font.types";
import { ORGANIZATION_FONT_TABLE } from "../fonts/organization-font.types";
import { compositionFontReferenceDetails } from "./composition-font-references";
import { readReadyGoogleFontFaces } from "../fonts/google-font-native-face-reader.server";
import { googleFontFaceBinding, googleFontNativeFile } from "../fonts/google-font-native-face.contract";
import { googleFontBundleStoragePath } from "../fonts/google-font-bundle.contract";
import { ORGANIZATION_FONT_STORAGE_BUCKET } from "../fonts/organization-font.types";
import { HTML_EDITING_REPOSITORY_POLICY } from "./composition-html-editing-repository-policy";
import type { ConformanceFontManifest } from "./composition-conformance-font-bindings";

export class CompositionFontAssetError extends Error {
  constructor(message: string, readonly status = 409) {
    super(message);
    this.name = "CompositionFontAssetError";
  }
}

export async function readReferencedCompositionFonts(params: {
  document: CompositionEditorDocument;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
  signal?: AbortSignal;
}) {
  let references: ReturnType<typeof compositionFontReferenceDetails>;
  try { references = compositionFontReferenceDetails(params.document); }
  catch { throw new CompositionFontAssetError("Las referencias tipográficas de la composición no son válidas."); }
  const ids = [...references.keys()];
  if (ids.length === 0) return [];
  const googleIds = ids.filter(id => references.get(id)?.googleFace);
  const uploadedIds = ids.filter(id => !references.get(id)?.googleFace);
  const signal = params.signal ? AbortSignal.any([params.signal, AbortSignal.timeout(HTML_EDITING_REPOSITORY_POLICY.rpcTimeoutMs)])
    : AbortSignal.timeout(HTML_EDITING_REPOSITORY_POLICY.rpcTimeoutMs);
  signal.throwIfAborted();
  const { data, error } = uploadedIds.length ? await params.supabase.from(ORGANIZATION_FONT_TABLE)
    .select("id, family, source, status, checksum_sha256, mime_type, file_size_bytes, storage_bucket, storage_path")
    .eq("organization_id", params.organizationId)
    .in("id", uploadedIds) : { data: [], error: null };
  if (error) throw new CompositionFontAssetError("No se pudieron verificar las fuentes de la composición.", 500);

  const records = new Map<string, OrganizationFontRecord>();
  if (googleIds.length) {
    const faces = await readReadyGoogleFontFaces({ organizationId: params.organizationId, selection: { faceIds: googleIds },
      supabase: params.supabase, signal });
    for (const face of faces) records.set(face.id, { id: face.id, family: face.family, status: "READY",
      checksumSha256: face.face.checksumSha256, fileSizeBytes: face.face.fileSizeBytes, mimeType: face.face.mimeType,
      storageBucket: ORGANIZATION_FONT_STORAGE_BUCKET,
      storagePath: googleFontBundleStoragePath(params.organizationId, face.pin.candidateSha256, googleFontNativeFile(face)), googleFace: googleFontFaceBinding(face) });
  }
  for (const row of data || []) {
    if (row.source !== "uploaded" || row.status !== "READY" || !row.checksum_sha256 || !row.mime_type
      || !row.file_size_bytes || !row.storage_bucket || !row.storage_path) continue;
    records.set(String(row.id), {
      checksumSha256: String(row.checksum_sha256),
      family: String(row.family),
      fileSizeBytes: Number(row.file_size_bytes),
      id: String(row.id),
      mimeType: String(row.mime_type),
      status: "READY",
      storageBucket: String(row.storage_bucket),
      storagePath: String(row.storage_path),
    });
  }
  return ids.map((id) => {
    const record = records.get(id);
    if (!record) throw new CompositionFontAssetError("Una fuente usada por la composición no está lista para render.");
    if (record.family !== references.get(id)?.fontFamily
      || JSON.stringify(record.googleFace) !== JSON.stringify(references.get(id)?.googleFace)) {
      throw new CompositionFontAssetError(`La familia declarada no coincide con la fuente ${record.family}.`);
    }
    return record;
  });
}

export async function resolveCompositionPreviewFonts(params: {
  document: CompositionEditorDocument;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const fonts = await readReferencedCompositionFonts(params);
  const compiled = await Promise.all(fonts.map(async (font): Promise<[string, CompositionCompiledFont]> => {
    const { data, error } = await params.supabase.storage.from(font.storageBucket).createSignedUrl(font.storagePath, 15 * 60);
    if (error || !data?.signedUrl) throw new CompositionFontAssetError(`No se pudo firmar la fuente ${font.family}.`, 500);
    return [font.id, compiledCompositionFont(font, data.signedUrl)];
  }));
  return new Map(compiled);
}

export async function downloadCompositionFont(params: {
  font: OrganizationFontRecord;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const { data, error } = await params.supabase.storage.from(params.font.storageBucket).download(params.font.storagePath);
  if (error || !data) throw new CompositionFontAssetError(`No se pudo descargar la fuente ${params.font.family}.`, 500);
  const bytes = new Uint8Array(await data.arrayBuffer());
  if (bytes.byteLength !== params.font.fileSizeBytes) {
    throw new CompositionFontAssetError(`La fuente ${params.font.family} cambió de tamaño después de validarse.`, 409);
  }
  const checksum = createHash("sha256").update(bytes).digest("hex");
  if (checksum !== params.font.checksumSha256) {
    throw new CompositionFontAssetError(`La integridad de la fuente ${params.font.family} no coincide con su registro.`, 409);
  }
  return bytes;
}

export function compositionFontArchivePath(font: OrganizationFontRecord) {
  return `assets/fonts/${font.checksumSha256}.${fontExtension(font.mimeType)}`;
}

export function compiledCompositionFont(font: OrganizationFontRecord, sourceUrl: string): CompositionCompiledFont {
  return { assetId: font.id, family: font.family, format: fontFormat(font.mimeType), sourceUrl,
    ...(font.googleFace ? { googleFace: font.googleFace } : {}) };
}
export function compositionFontManifestBinding(font: OrganizationFontRecord): ConformanceFontManifest[number] {
  return { fontAssetId: font.id, family: font.family, checksumSha256: font.checksumSha256,
    fileSizeBytes: font.fileSizeBytes, mimeType: font.mimeType as ConformanceFontManifest[number]["mimeType"],
    ...(font.googleFace ? { googleFace: font.googleFace } : {}) };
}
export function compiledManifestFont(font: ConformanceFontManifest[number], sourceUrl: string): CompositionCompiledFont {
  return { assetId: font.fontAssetId, family: font.family, format: fontFormat(font.mimeType), sourceUrl,
    ...(font.googleFace ? { googleFace: font.googleFace } : {}) };
}

function fontExtension(mimeType: string) {
  if (mimeType === "font/woff2") return "woff2";
  if (mimeType === "font/woff") return "woff";
  if (mimeType === "font/otf") return "otf";
  if (mimeType === "font/ttf") return "ttf";
  throw new CompositionFontAssetError("La fuente tiene un tipo MIME no soportado.");
}

function fontFormat(mimeType: string): CompositionCompiledFont["format"] {
  const extension = fontExtension(mimeType);
  if (extension === "otf") return "opentype";
  if (extension === "ttf") return "truetype";
  return extension;
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";
import sharp from "sharp";
import { htmlEditingImageIdentitySchema, assertHtmlEditingImageIdentities, type HtmlEditingImageIdentity } from "./composition-html-editing-image-identity";
import { prepareCompositionHtmlEditingSnapshotImages } from "./composition-html-editing-snapshot-images.service";
import { HTML_EDITING_PREVIEW_STORAGE_POLICY, readHtmlEditingPreviewStorageBytes } from "./composition-html-editing-preview-storage.server";

export const HTML_EDITING_PREVIEW_IMAGE_POLICY = Object.freeze({ totalBytes: 128 * 1024 * 1024,
  readTimeoutMs: HTML_EDITING_PREVIEW_STORAGE_POLICY.readTimeoutMs,
  maximumPixels: 16_777_216, maximumEdge: 8192, maximumChunks: 16_384 });
export class HtmlEditingPreviewImageError extends Error {
  constructor() { super("HTML_EDITING_PREVIEW_IMAGES_UNAVAILABLE"); this.name = "HtmlEditingPreviewImageError"; }
}
function assertStaticRasterContainer(bytes: Buffer, mimeType: HtmlEditingImageIdentity["mimeType"]) {
  if (mimeType === "image/jpeg") return; // JPEG's format is checked by Sharp below.
  const png = mimeType === "image/png";
  if (png ? bytes.length < 20 || !bytes.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]))
    : bytes.length < 20 || bytes.toString("ascii", 0, 4) !== "RIFF" || bytes.toString("ascii", 8, 12) !== "WEBP"
      || bytes.readUInt32LE(4) + 8 !== bytes.length) throw new Error();
  let offset = png ? 8 : 12, chunks = 0, ended = false;
  while (offset < bytes.length) {
    if (++chunks > HTML_EDITING_PREVIEW_IMAGE_POLICY.maximumChunks || offset + (png ? 12 : 8) > bytes.length) throw new Error();
    const length = png ? bytes.readUInt32BE(offset) : bytes.readUInt32LE(offset + 4);
    const kind = png ? bytes.toString("ascii", offset + 4, offset + 8) : bytes.toString("ascii", offset, offset + 4);
    const end = offset + length + (png ? 12 : 8 + (length % 2));
    if (end > bytes.length || (png ? ["acTL", "fcTL", "fdAT"].includes(kind) : ["ANIM", "ANMF"].includes(kind))) throw new Error();
    if (!png && kind === "VP8X" && (length < 10 || (bytes[offset + 8] & 2) !== 0)) throw new Error();
    offset = end;
    if (png && kind === "IEND") { if (length !== 0 || offset !== bytes.length) throw new Error(); ended = true; }
  }
  if (png && !ended) throw new Error();
}

/** Reusable raster admission after a verified private spool or bounded download.
 * Metadata/container checks are not a complete decode or sandbox attestation. */
export async function validateCompositionHtmlEditingPreviewImageBytes(input: {
  bytes: Uint8Array; identity: HtmlEditingImageIdentity; signal?: AbortSignal;
}) {
  const identity = htmlEditingImageIdentitySchema.parse(input.identity);
  if (input.bytes.byteLength !== identity.fileSizeBytes) throw new HtmlEditingPreviewImageError();
  input.signal?.throwIfAborted();
  const bytes = Buffer.from(input.bytes);
  assertStaticRasterContainer(bytes, identity.mimeType);
  const metadata = await sharp(bytes, { failOn: "error", limitInputPixels: HTML_EDITING_PREVIEW_IMAGE_POLICY.maximumPixels }).metadata();
  const formats = { "image/png": "png", "image/jpeg": "jpeg", "image/webp": "webp" } as const;
  if (metadata.format !== formats[identity.mimeType] || !metadata.width || !metadata.height || (metadata.pages ?? 1) !== 1
    || metadata.width > HTML_EDITING_PREVIEW_IMAGE_POLICY.maximumEdge || metadata.height > HTML_EDITING_PREVIEW_IMAGE_POLICY.maximumEdge
    || metadata.width * metadata.height > HTML_EDITING_PREVIEW_IMAGE_POLICY.maximumPixels) throw new HtmlEditingPreviewImageError();
  input.signal?.throwIfAborted();
}

/** Download only a host-authorized identity from the operator's Storage origin.
 * Signed URLs remain private; redirects, partial content and unbounded responses
 * are never accepted. Fetch is an infrastructure port, not request input. */
export async function readCompositionHtmlEditingPreviewImage(input: {
  identity: HtmlEditingImageIdentity; supabase: SupabaseClient; storageOrigin: string; signal?: AbortSignal;
  fetchResource?: typeof fetch;
}): Promise<Uint8Array> {
  try {
    const identity = htmlEditingImageIdentitySchema.parse(input.identity);
    const signal = input.signal ? AbortSignal.any([input.signal, AbortSignal.timeout(HTML_EDITING_PREVIEW_IMAGE_POLICY.readTimeoutMs)])
      : AbortSignal.timeout(HTML_EDITING_PREVIEW_IMAGE_POLICY.readTimeoutMs);
    signal.throwIfAborted();
    const { productionAssetId: _assetId, ...storageIdentity } = identity;
    const bytes = Buffer.from(await readHtmlEditingPreviewStorageBytes({ ...input, identity: storageIdentity, signal }));
    await validateCompositionHtmlEditingPreviewImageBytes({ bytes, identity, signal });
    return new Uint8Array(bytes);
  } catch { throw new HtmlEditingPreviewImageError(); }
}

type Preparation = Parameters<typeof prepareCompositionHtmlEditingSnapshotImages>[0];
/** Read-only assembler. The existing producer supplies exact historical authority,
 * current draft links and image records. A second authorized read detects drift
 * after byte acquisition; it is not a permanent permission lease or upload. */
export async function prepareCompositionHtmlEditingPreviewImages(input: Preparation & {
  storageOrigin: string; fetchResource?: typeof fetch;
}) {
  try {
    z.string().url().parse(input.storageOrigin);
    input.signal?.throwIfAborted();
    const prepared = await prepareCompositionHtmlEditingSnapshotImages(input);
    const identities = prepared.imageAssets.map(identity => htmlEditingImageIdentitySchema.parse(identity));
    if (identities.reduce((total, identity) => total + identity.fileSizeBytes, 0) > HTML_EDITING_PREVIEW_IMAGE_POLICY.totalBytes) throw new Error();
    const images = new Map<string, Uint8Array>();
    // Sequential reads bound per-request working memory and Storage concurrency.
    for (const identity of identities) images.set(identity.productionAssetId,
      await readCompositionHtmlEditingPreviewImage({ ...input, identity }));
    const refreshed = await prepareCompositionHtmlEditingSnapshotImages(input);
    if (refreshed.bundle.encodedBundle !== prepared.bundle.encodedBundle || refreshed.bundle.sha256 !== prepared.bundle.sha256) throw new Error();
    assertHtmlEditingImageIdentities({ usedAssetIds: identities.map(identity => identity.productionAssetId),
      currentImages: refreshed.imageAssets, frozenBindings: identities.map(identity => ({ assetId: identity.productionAssetId,
        checksum: identity.checksum, fileSizeBytes: identity.fileSizeBytes, mimeType: identity.mimeType,
        storageBucket: identity.storageBucket!, storagePath: identity.storagePath, localPath: `conformance-media/${identity.productionAssetId}` })) });
    input.signal?.throwIfAborted();
    return { ...refreshed, images, scope: "AUTHORIZED_BYTE_VERIFIED_PREVIEW_IMAGES_NOT_RENDER_EVIDENCE" as const };
  } catch { throw new HtmlEditingPreviewImageError(); }
}

import { createHash } from "node:crypto";
import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";
import { getCurrentCompositionDocument } from "./composition-document.service";
import { compositionEditorDocumentSchema } from "./composition-document.types";
import { hashCompositionDocument } from "./composition-document.service";
import { applyCompositionPresetDefinition } from "./composition-preset-application.service";
import { BUILT_IN_COMPOSITION_PRESETS, findBuiltInCompositionPreset } from "./composition-preset-builtins";
import {
  COMPOSITION_PRESET_SCHEMA_VERSION,
  compositionDynamicPresetDefinitionSchema,
  type CompositionDynamicPresetDefinition,
  type CompositionPresetCatalogEntry,
  type CompositionPresetSourceKind,
} from "./composition-preset.types";
import type { CompositionPresetExtractionDiagnostic } from "./composition-preset-extraction.service";

const PRESET_APPLICATION_STATUSES = ["APPLIED", "DISMISSED", "EXPIRED", "PENDING", "UNDONE"] as const;
type PresetApplicationStatus = typeof PRESET_APPLICATION_STATUSES[number];

export class CompositionPresetStoreError extends Error {
  constructor(
    message: string,
    readonly code: string,
    readonly status: number,
    readonly retryable = false,
  ) { super(message); }
}

type StoreParams = {
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
};

export type RecoverableCompositionPresetApplication = {
  applicationId: string;
  name: string;
};

const recoverableCompositionPresetApplicationRowSchema = z.object({
  id: z.string().uuid(),
  proposed_document_hash: z.string().regex(/^[a-f0-9]{64}$/i),
  status: z.literal("APPLIED"),
  summary: z.object({ presetName: z.string().trim().min(1).max(120) }).passthrough(),
});

export async function listCompositionPresetCatalog(params: StoreParams): Promise<CompositionPresetCatalogEntry[]> {
  const { data, error } = await params.supabase
    .from("video_composition_presets")
    .select("id, name, description, source_kind, current_version, created_at")
    .eq("organization_id", params.organizationId)
    .eq("status", "ACTIVE")
    .order("updated_at", { ascending: false })
    .limit(100);
  if (error) throw normalizePresetStorageError(error);
  const custom = (data || []).map((row: Record<string, unknown>): CompositionPresetCatalogEntry => ({
    createdAt: String(row.created_at),
    description: String(row.description || ""),
    id: String(row.id),
    name: String(row.name),
    sourceKind: parseSourceKind(row.source_kind),
    version: Number(row.current_version),
  }));
  return [
    ...BUILT_IN_COMPOSITION_PRESETS.map(({ definition: _definition, ...entry }) => entry),
    ...custom,
  ];
}

export async function createStoredCompositionPreset(params: StoreParams & {
  definition: CompositionDynamicPresetDefinition;
  description: string;
  diagnostics: CompositionPresetExtractionDiagnostic[];
  instruction?: string;
  name: string;
  sourceDocumentHash: string;
  sourceKind: Exclude<CompositionPresetSourceKind, "SYSTEM">;
  userId: string;
}) {
  const definition = compositionDynamicPresetDefinitionSchema.parse(params.definition);
  const definitionHash = hashPresetDefinition(definition);
  const { data, error } = await params.supabase.rpc("create_video_composition_preset", {
    p_actor_id: params.userId,
    p_definition: definition,
    p_definition_hash: definitionHash,
    p_description: params.description,
    p_extraction_diagnostics: params.diagnostics,
    p_instruction: params.instruction || null,
    p_name: params.name,
    p_organization_id: params.organizationId,
    p_schema_version: COMPOSITION_PRESET_SCHEMA_VERSION,
    p_source_document_hash: params.sourceDocumentHash,
    p_source_kind: params.sourceKind,
  });
  if (error) throw normalizePresetStorageError(error);
  const row = Array.isArray(data) ? data[0] : data;
  if (!row?.preset_id || !row?.preset_version_id) throw storageUnavailable();
  return {
    createdAt: new Date().toISOString(),
    description: params.description,
    diagnostics: params.diagnostics,
    id: String(row.preset_id),
    name: params.name,
    sourceKind: params.sourceKind,
    version: Number(row.version),
    versionId: String(row.preset_version_id),
  };
}

export async function createCompositionPresetPreview(params: StoreParams & {
  draftId: string;
  presetId: string;
  userId: string;
}) {
  await expirePendingCompositionPresetApplications(params);
  const [current, preset] = await Promise.all([
    getCurrentCompositionDocument(params),
    resolveCompositionPreset(params),
  ]);
  const application = applyCompositionPresetDefinition({ definition: preset.definition, document: current.document });
  const proposedDocumentHash = hashCompositionDocument(application.document);
  if (proposedDocumentHash === current.documentHash) {
    throw new CompositionPresetStoreError("El preset no produciría cambios en esta edición.", "COMPOSITION_PRESET_NO_EFFECT", 409);
  }
  const expiresAt = new Date(Date.now() + 30 * 60 * 1_000).toISOString();
  const summary = {
    affectedClipCount: application.affectedClipCount,
    affectedTrackCount: application.affectedTrackCount,
    generatedAnimationCount: application.generatedAnimationCount,
    presetName: preset.name,
    warnings: application.warnings,
  };
  const { data, error } = await params.supabase
    .from("video_composition_preset_applications")
    .insert({
      base_document: current.document,
      base_document_hash: current.documentHash,
      created_by: params.userId,
      draft_id: params.draftId,
      expires_at: expiresAt,
      organization_id: params.organizationId,
      preset_ref: preset.id,
      preset_version_id: preset.versionId,
      proposed_document: application.document,
      proposed_document_hash: proposedDocumentHash,
      summary,
    })
    .select("id, expires_at")
    .single();
  if (error) throw normalizePresetStorageError(error);
  return {
    applicationId: String(data.id),
    baseDocumentHash: current.documentHash,
    expiresAt: String(data.expires_at),
    preset: { id: preset.id, name: preset.name, version: preset.version },
    proposedDocumentHash,
    summary,
  };
}

export async function getCompositionPresetPreviewDocument(params: StoreParams & {
  applicationId: string;
  draftId: string;
}) {
  const stored = await getStoredApplication(params);
  if (stored.status !== "PENDING" || Date.parse(stored.expiresAt) <= Date.now()) {
    if (stored.status === "PENDING") await expireCompositionPresetApplication(params);
    throw new CompositionPresetStoreError("El preview del preset ya no está disponible.", "COMPOSITION_PRESET_PREVIEW_EXPIRED", 410);
  }
  return compositionEditorDocumentSchema.parse(stored.proposedDocument);
}

/**
 * Returns the only preset application that can still be undone safely. Matching
 * the current document hash prevents an old application from overwriting edits
 * made after the preset was applied.
 */
export async function getRecoverableCompositionPresetApplication(params: StoreParams & {
  draftId: string;
}): Promise<RecoverableCompositionPresetApplication | null> {
  const current = await getCurrentCompositionDocument(params);
  const { data, error } = await params.supabase
    .from("video_composition_preset_applications")
    .select("id, proposed_document_hash, status, summary")
    .eq("draft_id", params.draftId)
    .eq("organization_id", params.organizationId)
    .eq("status", "APPLIED")
    .eq("proposed_document_hash", current.documentHash)
    .order("applied_at", { ascending: false })
    .limit(1)
    .maybeSingle();
  if (error) throw normalizePresetStorageError(error);
  return parseRecoverableCompositionPresetApplication(data, current.documentHash);
}

export function parseRecoverableCompositionPresetApplication(
  row: unknown,
  currentDocumentHash: string,
): RecoverableCompositionPresetApplication | null {
  const parsed = recoverableCompositionPresetApplicationRowSchema.safeParse(row);
  if (!parsed.success || parsed.data.proposed_document_hash !== currentDocumentHash) return null;
  return {
    applicationId: parsed.data.id,
    name: parsed.data.summary.presetName,
  };
}

export async function applyStoredCompositionPreset(params: StoreParams & {
  applicationId: string;
  draftId: string;
  expectedDocumentHash: string;
  signal?: AbortSignal;
  userId: string;
}) {
  let request = params.supabase.rpc("apply_video_composition_preset_application", {
    p_actor_id: params.userId,
    p_application_id: params.applicationId,
    p_draft_id: params.draftId,
    p_expected_document_hash: params.expectedDocumentHash,
    p_organization_id: params.organizationId,
  }).retry(false);
  if (params.signal) request = request.abortSignal(params.signal);
  const { data, error } = await request;
  if (error) throw normalizePresetStorageError(error);
  assertMutationOutcome(parseOutcome(data), "APPLY");
  return getCurrentCompositionDocument(params);
}

export async function undoStoredCompositionPreset(params: StoreParams & {
  applicationId: string;
  draftId: string;
  expectedDocumentHash: string;
  signal?: AbortSignal;
  userId: string;
}) {
  let request = params.supabase.rpc("undo_video_composition_preset_application", {
    p_actor_id: params.userId,
    p_application_id: params.applicationId,
    p_draft_id: params.draftId,
    p_expected_document_hash: params.expectedDocumentHash,
    p_organization_id: params.organizationId,
  }).retry(false);
  if (params.signal) request = request.abortSignal(params.signal);
  const { data, error } = await request;
  if (error) throw normalizePresetStorageError(error);
  assertMutationOutcome(parseOutcome(data), "UNDO");
  return getCurrentCompositionDocument(params);
}

export async function dismissStoredCompositionPresetPreview(params: StoreParams & {
  applicationId: string;
  draftId: string;
}) {
  const { error } = await params.supabase
    .from("video_composition_preset_applications")
    .update({ status: "DISMISSED", updated_at: new Date().toISOString() })
    .eq("id", params.applicationId)
    .eq("draft_id", params.draftId)
    .eq("organization_id", params.organizationId)
    .eq("status", "PENDING");
  if (error) throw normalizePresetStorageError(error);
}

async function resolveCompositionPreset(params: StoreParams & { presetId: string }) {
  const builtIn = findBuiltInCompositionPreset(params.presetId);
  if (builtIn) return { ...builtIn, versionId: null };
  if (!z.string().uuid().safeParse(params.presetId).success) throw presetNotFound();
  const { data: preset, error: presetError } = await params.supabase
    .from("video_composition_presets")
    .select("id, name, description, current_version, source_kind")
    .eq("id", params.presetId)
    .eq("organization_id", params.organizationId)
    .eq("status", "ACTIVE")
    .maybeSingle();
  if (presetError) throw normalizePresetStorageError(presetError);
  if (!preset) throw presetNotFound();
  const { data: version, error: versionError } = await params.supabase
    .from("video_composition_preset_versions")
    .select("id, version, definition")
    .eq("preset_id", preset.id)
    .eq("organization_id", params.organizationId)
    .eq("version", preset.current_version)
    .maybeSingle();
  if (versionError) throw normalizePresetStorageError(versionError);
  if (!version) throw presetNotFound();
  return {
    definition: compositionDynamicPresetDefinitionSchema.parse(version.definition),
    description: String(preset.description || ""),
    id: String(preset.id),
    name: String(preset.name),
    sourceKind: parseSourceKind(preset.source_kind),
    version: Number(version.version),
    versionId: String(version.id),
  };
}

async function getStoredApplication(params: StoreParams & { applicationId: string; draftId: string }) {
  const { data, error } = await params.supabase
    .from("video_composition_preset_applications")
    .select("expires_at, proposed_document, status")
    .eq("id", params.applicationId)
    .eq("draft_id", params.draftId)
    .eq("organization_id", params.organizationId)
    .maybeSingle();
  if (error) throw normalizePresetStorageError(error);
  if (!data || !PRESET_APPLICATION_STATUSES.includes(data.status as PresetApplicationStatus)) {
    throw new CompositionPresetStoreError("La aplicación del preset no existe.", "COMPOSITION_PRESET_APPLICATION_NOT_FOUND", 404);
  }
  return {
    expiresAt: String(data.expires_at),
    proposedDocument: data.proposed_document,
    status: data.status as PresetApplicationStatus,
  };
}

async function expirePendingCompositionPresetApplications(params: StoreParams & { draftId: string }) {
  const now = new Date().toISOString();
  const { error } = await params.supabase
    .from("video_composition_preset_applications")
    .update({ status: "EXPIRED", updated_at: now })
    .eq("draft_id", params.draftId)
    .eq("organization_id", params.organizationId)
    .eq("status", "PENDING")
    .lt("expires_at", now);
  if (error) throw normalizePresetStorageError(error);
}

async function expireCompositionPresetApplication(params: StoreParams & { applicationId: string; draftId: string }) {
  const { error } = await params.supabase
    .from("video_composition_preset_applications")
    .update({ status: "EXPIRED", updated_at: new Date().toISOString() })
    .eq("id", params.applicationId)
    .eq("draft_id", params.draftId)
    .eq("organization_id", params.organizationId)
    .eq("status", "PENDING");
  if (error) throw normalizePresetStorageError(error);
}

function parseOutcome(data: unknown) {
  const row = Array.isArray(data) ? data[0] : data;
  if (!row || typeof row !== "object" || typeof (row as { outcome?: unknown }).outcome !== "string") throw storageUnavailable();
  return (row as { outcome: string }).outcome;
}

function assertMutationOutcome(outcome: string, operation: "APPLY" | "UNDO") {
  if (operation === "APPLY" && (outcome === "APPLIED" || outcome === "ALREADY_APPLIED")) return;
  if (operation === "UNDO" && (outcome === "UNDONE" || outcome === "ALREADY_UNDONE")) return;
  if (outcome === "CONFLICT" || outcome === "UNDO_CONFLICT") {
    throw new CompositionPresetStoreError(
      operation === "UNDO"
        ? "La edición cambió después de aplicar el preset. Restaura la versión anterior desde el historial para no perder cambios nuevos."
        : "La edición cambió desde que se abrió el preview. Genera un preview nuevo.",
      "COMPOSITION_PRESET_VERSION_CONFLICT",
      409,
    );
  }
  if (outcome === "EXPIRED") throw new CompositionPresetStoreError("El preview expiró. Genera uno nuevo.", "COMPOSITION_PRESET_PREVIEW_EXPIRED", 410);
  if (outcome === "BUSY") throw new CompositionPresetStoreError("Ya hay otro cambio guardándose. Vuelve a intentar.", "COMPOSITION_PRESET_BUSY", 409, true);
  if (outcome === "NOT_EDITABLE") throw new CompositionPresetStoreError("El borrador ya no está disponible para edición.", "COMPOSITION_PRESET_NOT_EDITABLE", 409);
  throw new CompositionPresetStoreError("La aplicación del preset ya no está disponible.", "COMPOSITION_PRESET_APPLICATION_UNAVAILABLE", 409);
}

function hashPresetDefinition(definition: CompositionDynamicPresetDefinition) {
  return createHash("sha256").update(JSON.stringify(definition)).digest("hex");
}

function parseSourceKind(value: unknown): Exclude<CompositionPresetSourceKind, "SYSTEM"> {
  if (value === "INSTRUCTIONS" || value === "MANUAL") return value;
  throw new CompositionPresetStoreError("El preset almacenado tiene un origen inválido.", "COMPOSITION_PRESET_CORRUPT", 500);
}

function presetNotFound() {
  return new CompositionPresetStoreError("El preset no existe o no pertenece a esta empresa.", "COMPOSITION_PRESET_NOT_FOUND", 404);
}

function storageUnavailable() {
  return new CompositionPresetStoreError("El almacenamiento de presets aún no está disponible.", "COMPOSITION_PRESET_STORAGE_NOT_READY", 503, true);
}

function normalizePresetStorageError(error: unknown) {
  const candidate = error && typeof error === "object" ? error as { code?: unknown; message?: unknown } : {};
  const code = String(candidate.code || "");
  const message = String(candidate.message || "");
  if (code === "PGRST202" || /Could not find the function|relation .* does not exist/i.test(message)) return storageUnavailable();
  if (code === "42501") return new CompositionPresetStoreError("No tienes permisos para administrar presets.", "COMPOSITION_PRESET_FORBIDDEN", 403);
  if (code === "22023") return new CompositionPresetStoreError("Los datos del preset no son válidos.", "COMPOSITION_PRESET_INVALID", 400);
  return error;
}

import type { SupabaseClient } from "@supabase/supabase-js";
import type { CompositionEditorDocument } from "./composition-document.types";
import { CompositionPreviewCompilerError } from "./composition-preview-compiler.service";
import { PUBLIC_PRODUCTION_MEDIA_BUCKETS } from "../media-storage.config";
import {
  elapsedMilliseconds,
  type CompositionPreviewAssetDiagnostics,
} from "./composition-preview-performance";
import { readReadyLinkedSoundEffectAssetIds } from "./composition-sound-effect-assets.service";
import { compositionDeckImageAssetIds, isCompositionDeckImageAvailable } from "./composition-deck-image-aliases.server";

export const COMPOSITION_PREVIEW_ASSET_URL_TTL_SECONDS = 60 * 60;
export const COMPOSITION_PREVIEW_SIGNING_CONCURRENCY = 6;
export const COMPOSITION_PREVIEW_PUBLIC_BUCKETS = PUBLIC_PRODUCTION_MEDIA_BUCKETS;

/** Resolves only linked assets into scoped Storage URLs renewed on every preview load. */
export async function resolveCompositionPreviewAssetUrls(params: {
  document: CompositionEditorDocument;
  draftId: string;
  onDiagnostics?: (diagnostics: CompositionPreviewAssetDiagnostics) => void;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const deckImageIds = compositionDeckImageAssetIds(params.document);
  const productionAssetIds = [...new Set([...deckImageIds, ...params.document.clips.flatMap((clip) => (
    clip.source.type === "PRODUCTION_ASSET" ? [clip.source.productionAssetId] : []
  ))])];
  const brandingAssetIds = [...new Set(params.document.clips.flatMap((clip) => (
    clip.source.type === "ASSEMBLY_BRAND_ASSET" ? [clip.source.assemblyBrandAssetId] : []
  )))];
  const soundEffectAssetIds = [...new Set(params.document.clips.flatMap((clip) => (
    clip.source.type === "SOUND_EFFECT_ASSET" ? [clip.source.soundEffectAssetId] : []
  )))];
  const assetIds = [...productionAssetIds, ...brandingAssetIds, ...soundEffectAssetIds];
  if (assetIds.length === 0) {
    params.onDiagnostics?.({
      assetCount: 0,
      assetQueryMs: 0,
      draftLinkQueryMs: 0,
      privateAssetCount: 0,
      publicAssetCount: 0,
      signingMs: 0,
    });
    return new Map<string, string>();
  }

  const draftLinkQueryStartedAt = performance.now();
  const [{ data: draftLinks, error: draftLinksError }, { data: draftBranding, error: draftBrandingError }, linkedSoundEffectIds] = await Promise.all([
    productionAssetIds.length > 0
      ? params.supabase.from("video_composition_draft_assets").select("production_asset_id").eq("draft_id", params.draftId).eq("organization_id", params.organizationId).in("production_asset_id", productionAssetIds)
      : Promise.resolve({ data: [], error: null }),
    brandingAssetIds.length > 0
      ? params.supabase.from("video_composition_draft_branding").select("intro_asset_id, outro_asset_id").eq("draft_id", params.draftId).eq("organization_id", params.organizationId).maybeSingle()
      : Promise.resolve({ data: null, error: null }),
    readReadyLinkedSoundEffectAssetIds({
      draftId: params.draftId,
      organizationId: params.organizationId,
      soundEffectAssetIds,
      supabase: params.supabase,
    }),
  ]);
  if (draftLinksError) throw draftLinksError;
  if (draftBrandingError) throw draftBrandingError;
  const draftLinkQueryMs = elapsedMilliseconds(draftLinkQueryStartedAt);
  const linkedIds = new Set((draftLinks || []).map((link) => link.production_asset_id as string));
  const brandingLinks = new Set([draftBranding?.intro_asset_id, draftBranding?.outro_asset_id].filter((id): id is string => typeof id === "string"));
  const missingLinks = productionAssetIds.filter((assetId) => !linkedIds.has(assetId));
  const missingBrandingLinks = brandingAssetIds.filter((assetId) => !brandingLinks.has(assetId));
  const missingSoundEffectLinks = soundEffectAssetIds.filter((assetId) => !linkedSoundEffectIds.has(assetId));
  if (missingLinks.length > 0 || missingBrandingLinks.length > 0 || missingSoundEffectLinks.length > 0) {
    throw new CompositionPreviewCompilerError("La composición referencia assets que no pertenecen al borrador.");
  }

  const assetQueryStartedAt = performance.now();
  const [{ data: productionAssets, error: assetsError }, { data: brandingAssets, error: brandingAssetsError }, { data: soundEffectAssets, error: soundEffectAssetsError }] = await Promise.all([
    productionAssetIds.length > 0
      ? params.supabase.from("production_assets").select("id, checksum, storage_bucket, storage_path, mime_type, qa_status").eq("organization_id", params.organizationId).in("id", productionAssetIds)
      : Promise.resolve({ data: [], error: null }),
    brandingAssetIds.length > 0
      ? params.supabase.from("organization_assembly_assets").select("id, checksum, storage_bucket, storage_path").eq("organization_id", params.organizationId).in("status", ["APPROVED", "ARCHIVED"]).in("id", brandingAssetIds)
      : Promise.resolve({ data: [], error: null }),
    soundEffectAssetIds.length > 0
      ? params.supabase.from("sound_effect_assets").select("id, checksum_sha256, storage_bucket, storage_path").eq("organization_id", params.organizationId).eq("status", "READY").in("id", soundEffectAssetIds)
      : Promise.resolve({ data: [], error: null }),
  ]);
  if (assetsError) throw assetsError;
  if (brandingAssetsError) throw brandingAssetsError;
  if (soundEffectAssetsError) throw soundEffectAssetsError;
  if (deckImageIds.some(id => !productionAssets?.some(asset => asset.id === id
    && isCompositionDeckImageAvailable(asset.mime_type, asset.qa_status)))) {
    throw new CompositionPreviewCompilerError("Una imagen de las diapositivas ya no está disponible para este borrador.", 409);
  }
  const assetQueryMs = elapsedMilliseconds(assetQueryStartedAt);
  const urls = new Map<string, string>();
  const storedAssets = [
    ...(productionAssets || []).map((asset) => ({ ...asset, checksum: asset.checksum })),
    ...(brandingAssets || []).map((asset) => ({ ...asset, checksum: asset.checksum })),
    ...(soundEffectAssets || []).map((asset) => ({ ...asset, checksum: asset.checksum_sha256 })),
  ];
  const privateAssets = [];
  for (const asset of storedAssets) {
    if (!asset.storage_bucket || !asset.storage_path) {
      throw new CompositionPreviewCompilerError("Un asset de la composición no tiene storage disponible.");
    }
    const storagePath = toBucketRelativePath(asset.storage_bucket, asset.storage_path);
    if (COMPOSITION_PREVIEW_PUBLIC_BUCKETS.has(asset.storage_bucket)) {
      const rawPublicUrl = params.supabase.storage.from(asset.storage_bucket).getPublicUrl(storagePath).data.publicUrl;
      assertSafeStorageUrl(rawPublicUrl);
      const publicUrl = withContentVersion(
        rawPublicUrl,
        asset.checksum,
      );
      urls.set(asset.id, publicUrl);
      continue;
    }
    privateAssets.push({ ...asset, storagePath });
  }
  const signingStartedAt = performance.now();
  for (let offset = 0; offset < privateAssets.length; offset += COMPOSITION_PREVIEW_SIGNING_CONCURRENCY) {
    const batch = privateAssets.slice(offset, offset + COMPOSITION_PREVIEW_SIGNING_CONCURRENCY);
    const signedAssets = await Promise.all(batch.map(async (asset) => {
      const { data: signed, error: signedError } = await params.supabase.storage
        .from(asset.storage_bucket)
        .createSignedUrl(
          asset.storagePath,
          COMPOSITION_PREVIEW_ASSET_URL_TTL_SECONDS,
        );
      if (signedError) throw signedError;
      assertSafeStorageUrl(signed.signedUrl);
      return [asset.id, signed.signedUrl] as const;
    }));
    signedAssets.forEach(([assetId, signedUrl]) => urls.set(assetId, signedUrl));
  }
  if (urls.size !== assetIds.length) {
    throw new CompositionPreviewCompilerError("No se pudo resolver uno o más assets de preview.");
  }
  params.onDiagnostics?.({
    assetCount: assetIds.length,
    assetQueryMs,
    draftLinkQueryMs,
    privateAssetCount: privateAssets.length,
    publicAssetCount: storedAssets.length - privateAssets.length,
    signingMs: elapsedMilliseconds(signingStartedAt),
  });
  return urls;
}

function assertSafeStorageUrl(rawUrl: string) {
  let url: URL;
  try {
    url = new URL(rawUrl);
  } catch {
    throw new CompositionPreviewCompilerError("Storage devolvió una URL de preview inválida.");
  }
  const isLocalDevelopmentUrl = url.protocol === "http:"
    && (url.hostname === "localhost" || url.hostname === "127.0.0.1");
  if (url.protocol !== "https:" && !isLocalDevelopmentUrl) {
    throw new CompositionPreviewCompilerError("La URL de un asset de preview debe usar HTTPS.");
  }
}

function withContentVersion(rawUrl: string, checksum: unknown) {
  if (typeof checksum !== "string" || !/^[a-f0-9]{64}$/i.test(checksum)) return rawUrl;
  const url = new URL(rawUrl);
  url.searchParams.set("v", checksum.toLowerCase());
  return url.toString();
}

function toBucketRelativePath(bucket: string, storedPath: string) {
  const prefix = `${bucket}/`;
  const path = storedPath.startsWith(prefix) ? storedPath.slice(prefix.length) : storedPath;
  if (!path || path.startsWith("/") || path.includes("..") || path.includes("\\")) {
    throw new CompositionPreviewCompilerError("La ruta de un asset de preview es insegura.");
  }
  return path;
}

import { resolveCompositionCanvasFormat } from "./composition-canvas-format";
import { createHash } from "node:crypto";
import JSZip from "jszip";
import type { SupabaseClient } from "@supabase/supabase-js";
import { getCurrentCompositionDocument, hashCompositionDocument } from "./composition-document.service";
import { compositionEditorDocumentSchema } from "./composition-document.types";
import {
  COMPOSITION_COMPILATION_TARGETS,
  compileCompositionPreview,
  readCompositionAnimationRuntime,
} from "./composition-preview-compiler.service";
import { validateHyperframesPreflight } from "../hyperframes/hyperframes-preflight.service";
import { HYPERFRAMES_MEDIA_BINDING_VERSION } from "../hyperframes/hyperframes-render-media.service";
import {
  buildHyperframesAssetVariableNames,
  buildHyperframesAssetVariableSchema,
  resolveHyperframesAssetDeliveryUrl,
} from "../hyperframes/hyperframes-asset-delivery.service";
import {
  HYPERFRAMES_ASSET_DELIVERY_MODES,
  HYPERFRAMES_CLOUD_ARCHIVE_LIMIT_BYTES,
  HYPERFRAMES_COMPOSITION_FORMAT,
  hyperframesAssetManifestSchema,
  hyperframesRenderProfileSchema,
} from "../hyperframes/hyperframes.types";
import {
  HYPERFRAMES_DURABLE_RENDER_PROFILE,
  validateHyperframesMediaAsset,
} from "../hyperframes/hyperframes-media-constraints";
import {
  findHyperframesRenderProfile,
  toHyperframesRenderSettings,
  type HyperframesRenderProfile,
  type HyperframesRenderSettings,
} from "../hyperframes/hyperframes-render-profiles";
import {
  compiledCompositionFont,
  compositionFontManifestBinding,
  compositionFontArchivePath,
  CompositionFontAssetError,
  downloadCompositionFont,
  readReferencedCompositionFonts,
} from "./composition-font-assets.service";
import {
  resolveSnapshotConformanceContractVersion,
  summarizeCompositionConformanceContract,
} from "./composition-preview-render-conformance";
import { buildSnapshotConformanceContract } from "./composition-snapshot-conformance-contract";
import { writeConformanceReferenceArchive } from "./composition-conformance-reference-archive.server";
import { restrictSnapshotDeckTextReuse } from "./composition-snapshot-conformance-policy";
import { buildCompositionEventBatchAuthorization, assertSnapshotEventBatchAuthorization } from "./composition-conformance-event-batch-contract";
import { assertSnapshotFontManifestReuse, assertDocumentConformanceFontBindings } from "./composition-conformance-font-bindings";
import type { ConformanceFontManifest } from "./composition-conformance-font-bindings";
import { assertSnapshotVisibilityReuse, restrictSnapshotVisibilityReuse, restrictSnapshotFontUsageReuse, restrictSnapshotColorTagReuse, restrictSnapshotEventCheckpointReuse, restrictSnapshotPaintMaskReuse, resolveSnapshotTextVisibilityPolicy } from "./composition-snapshot-conformance-policy";
import {restrictSnapshotRenderExecutionReuse} from "./composition-snapshot-conformance-policy";
import { buildConformanceReferenceSource, conformanceReferenceVersion } from "./composition-conformance-reference.service";
import { compositionDeckImageAssetIds, isCompositionDeckImageAvailable } from "./composition-deck-image-aliases.server";

const PROJECT_BUCKET = "production-assets";

export class CompositionSnapshotError extends Error {
  constructor(message: string, readonly status = 400) { super(message); }
}

type AssetRow = { checksum: string; file_size_bytes: number; id: string; metadata: Record<string, unknown> | null; mime_type: string; public_url: string | null; storage_bucket: string; storage_path: string };
type SnapshotAssetRow = AssetRow & { origin: "BRANDING" | "PRODUCTION" | "SOUND_EFFECT" };

export type CompositionSnapshotSummary = {
  createdAt: string;
  documentHash: string;
  documentVersion: number;
  id: string;
  isActive: boolean;
  isCurrentDocument: boolean;
  projectArchiveSizeBytes: number;
  renderProfile: HyperframesRenderSettings | null;
  renderProfileId: string | null;
  revisionNumber: number;
};

/** Freezes exactly one saved native document into the immutable render revision contract. */
export async function snapshotCompositionDocument(params: {
  compositionId: string;
  draftId: string;
  organizationId: string;
  renderProfile: HyperframesRenderProfile;
  supabase: SupabaseClient<any, "public", any>;
  userId: string;
  /** Initial editorial onboarding freezes first; a separate draft-locked RPC
   * may activate it only while no active revision exists. Never reuse partially
   * linked legacy rows in this path. */
  initialEditorialAnchor?: { expectedDocumentHash: string };
}) {
  const [{ data: draft, error: draftError }, { data: composition, error: compositionError }, current] = await Promise.all([
    params.supabase.from("video_composition_drafts").select("id, composition_id, state").eq("id", params.draftId).eq("organization_id", params.organizationId).maybeSingle(),
    params.supabase.from("video_compositions").select("id, status").eq("id", params.compositionId).eq("organization_id", params.organizationId).maybeSingle(),
    getCurrentCompositionDocument({ draftId: params.draftId, organizationId: params.organizationId, supabase: params.supabase }),
  ]);
  if (draftError) throw draftError;
  if (compositionError) throw compositionError;
  if (!draft || draft.composition_id !== params.compositionId || draft.state !== "ACTIVE") throw new CompositionSnapshotError("El borrador no pertenece a una composici\u00f3n editable.", 409);
  if (!composition) throw new CompositionSnapshotError("La composici\u00f3n no existe.", 404);
  if (params.initialEditorialAnchor && (current.documentHash !== params.initialEditorialAnchor.expectedDocumentHash
    || hashCompositionDocument(current.document) !== current.documentHash))
    throw new CompositionSnapshotError("El borrador cambió. Recarga la composición antes de preparar la edición.", 409);
  assertCompositionSnapshotRenderContract(current.document);
  if (!current.document.canvas.durationSource && current.document.canvas.durationMode !== "USER_EDITED") {
    throw new CompositionSnapshotError(
      "La duración todavía no tiene un origen verificable. Usa ‘Calcular y organizar’ en el timeline antes de preparar el ensamble.",
      409,
    );
  }

  const renderSettings = toHyperframesRenderSettings(params.renderProfile);
  const conformanceContractVersion = resolveSnapshotConformanceContractVersion(process.env.COMPOSITION_CONFORMANCE_AUDIO_V2,
    process.env.COMPOSITION_CONFORMANCE_VISUAL_V3, process.env.COMPOSITION_CONFORMANCE_TEXT_V4);
  const visibilityPolicy = resolveSnapshotTextVisibilityPolicy(conformanceContractVersion,
    process.env.COMPOSITION_CONFORMANCE_MOTION_VISIBILITY_V1, process.env.COMPOSITION_CONFORMANCE_TRANSITION_VISIBILITY_V2,
    process.env.COMPOSITION_CONFORMANCE_TEXT_APPEARANCE_V3,
    process.env.COMPOSITION_CONFORMANCE_TEXT_GEOMETRY_V4);
  const persistedRenderProfile = { id: params.renderProfile.id, ...renderSettings };
  let referencedFonts;
  try {
    referencedFonts = await readReferencedCompositionFonts({
      document: current.document,
      organizationId: params.organizationId,
      supabase: params.supabase,
    });
  } catch (error) {
    if (error instanceof CompositionFontAssetError) throw new CompositionSnapshotError(error.message, error.status);
    throw error;
  }
  let fontManifest: ConformanceFontManifest;
  try {
    fontManifest = assertDocumentConformanceFontBindings(current.document, referencedFonts.map(compositionFontManifestBinding));
  } catch {
    throw new CompositionSnapshotError("Las fuentes de la composición no tienen una identidad única y verificable para render. Revisa sus familias y registros.", 409);
  }
  const referenceVersion = conformanceReferenceVersion(process.env.COMPOSITION_CONFORMANCE_REFERENCE_V1);
  const fontUsage = conformanceContractVersion === 4 && process.env.COMPOSITION_CONFORMANCE_FONT_USAGE_V1 === "true";
  const colorTags = conformanceContractVersion === 4 && process.env.COMPOSITION_CONFORMANCE_COLOR_TAGS_V1 === "true";
  const eventCheckpoints = conformanceContractVersion === 4 && process.env.COMPOSITION_CONFORMANCE_EVENT_CHECKPOINTS_V1 === "true";
  const paintMasks = conformanceContractVersion === 4 && process.env.COMPOSITION_CONFORMANCE_TEXT_PAINT_MASKS_V1 === "true";
  const deckText = conformanceContractVersion === 4 && process.env.COMPOSITION_CONFORMANCE_DECK_TEXT_V1 === "true";
  const deckTextPaintMasks = deckText && process.env.COMPOSITION_CONFORMANCE_DECK_TEXT_PAINT_MASKS_V1 === "true";
  const checkpointContract = buildSnapshotConformanceContract({assets: [], visibilityPolicy,
    contractVersion: conformanceContractVersion, document: current.document, documentHash: current.documentHash,
    renderProfile: renderSettings, fontUsage, fontManifest, colorTags, eventCheckpoints, paintMasks, deckText, deckTextPaintMasks});
  const reuseQuery = params.supabase
    .from("video_composition_revisions")
    .select("id, revision_number, project_hash, project_archive_size_bytes, manifest")
    .eq("composition_id", params.compositionId)
    .contains("manifest", {
      asset_delivery_mode: HYPERFRAMES_ASSET_DELIVERY_MODES.REMOTE_VARIABLES,
      media_binding_version: HYPERFRAMES_MEDIA_BINDING_VERSION,
      conformance_contract_version: checkpointContract.schemaVersion,
      draft_document_hash: current.documentHash,
      font_manifest: fontManifest,
      render_profile: persistedRenderProfile,
      ...(referenceVersion ? { conformance_reference_version: referenceVersion } : {}),
    });
  const deckReuseQuery = restrictSnapshotRenderExecutionReuse(restrictSnapshotDeckTextReuse(reuseQuery, checkpointContract), checkpointContract);
  const { data: existing, error: existingError } = params.initialEditorialAnchor ? { data: null, error: null } : await restrictSnapshotPaintMaskReuse(restrictSnapshotEventCheckpointReuse(restrictSnapshotColorTagReuse(restrictSnapshotFontUsageReuse(
    restrictSnapshotVisibilityReuse(deckReuseQuery, checkpointContract), checkpointContract), checkpointContract), checkpointContract), checkpointContract).maybeSingle();
  if (existingError) throw existingError;
  if (existing) {
    const {manifest: storedManifest, ...existingSummary} = existing;
    assertSnapshotVisibilityReuse(storedManifest, checkpointContract);
    assertSnapshotFontManifestReuse(storedManifest, fontManifest);
    assertSnapshotEventBatchAuthorization(storedManifest, current.document);
    await setActiveCompositionSnapshot({
      compositionId: params.compositionId,
      organizationId: params.organizationId,
      revisionId: existing.id,
      supabase: params.supabase,
    });
    return {
      ...existingSummary,
      conformance: summarizeCompositionConformanceContract(checkpointContract),
      documentHash: current.documentHash,
      reused: true,
      version: current.version,
    };
  }

  const referencedAssetIds = [...new Set(current.document.clips.flatMap((clip) => clip.source.type === "PRODUCTION_ASSET" ? [clip.source.productionAssetId] : []))];
  const referencedBrandingAssetIds = [...new Set(current.document.clips.flatMap((clip) => clip.source.type === "ASSEMBLY_BRAND_ASSET" ? [clip.source.assemblyBrandAssetId] : []))];
  const referencedSoundEffectAssetIds = [...new Set(current.document.clips.flatMap((clip) => clip.source.type === "SOUND_EFFECT_ASSET" ? [clip.source.soundEffectAssetId] : []))];
  const [clipAssets, brandingAssets, soundEffectAssets, deckDependencies] = await Promise.all([
    readSnapshotAssets(params, referencedAssetIds),
    readSnapshotBrandingAssets(params, referencedBrandingAssetIds),
    readSnapshotSoundEffectAssets(params, referencedSoundEffectAssetIds),
    readReferencedDeckDependencies(params, current.document),
  ]);
  const assetRows: Array<[string, SnapshotAssetRow]> = [
    ...clipAssets.map((asset): [string, SnapshotAssetRow] => [asset.id, { ...asset, origin: "PRODUCTION" }]),
    ...brandingAssets.map((asset): [string, SnapshotAssetRow] => [asset.id, { ...asset, origin: "BRANDING" }]),
    ...soundEffectAssets.map((asset): [string, SnapshotAssetRow] => [asset.id, { ...asset, origin: "SOUND_EFFECT" }]),
    ...deckDependencies.map((asset): [string, SnapshotAssetRow] => [asset.id, { ...asset, origin: "PRODUCTION" }]),
  ];
  const assets = [...new Map<string, SnapshotAssetRow>(assetRows).values()];
  const mediaErrors = assets.flatMap((asset) => validateHyperframesMediaAsset({
    deliveryMode: HYPERFRAMES_ASSET_DELIVERY_MODES.REMOTE_VARIABLES,
    fileName: typeof asset.metadata?.file_name === "string" ? asset.metadata.file_name : asset.storage_path,
    fileSizeBytes: asset.file_size_bytes,
    height: readPositiveInteger(asset.metadata?.source_height),
    mimeType: asset.mime_type,
    width: readPositiveInteger(asset.metadata?.source_width),
  }).errors);
  if (mediaErrors.length > 0) throw new CompositionSnapshotError(mediaErrors.join(" "));
  const manifest = hyperframesAssetManifestSchema.parse(assets.map((asset) => ({
    checksum: asset.checksum,
    fileSizeBytes: asset.file_size_bytes,
    mimeType: asset.mime_type,
    productionAssetId: asset.id,
    storageBucket: asset.storage_bucket,
    storagePath: asset.storage_path,
  })));
  const conformanceContract = buildSnapshotConformanceContract({
    assets: manifest.map((asset) => ({ checksum: asset.checksum, id: asset.productionAssetId })),
    fontUsage, fontManifest, colorTags, eventCheckpoints, paintMasks, deckText, deckTextPaintMasks,
    visibilityPolicy,
    contractVersion: conformanceContractVersion,
    document: current.document,
    documentHash: current.documentHash,
    renderProfile: renderSettings,
  });
  const preflight = validateHyperframesPreflight({
    assets: manifest,
    deliveryMode: HYPERFRAMES_ASSET_DELIVERY_MODES.REMOTE_VARIABLES,
    durationSeconds: current.document.canvas.durationSeconds,
    renderProfile: renderSettings,
  });
  if (!preflight.valid) throw new CompositionSnapshotError(preflight.errors.join(" "));

  const zip = new JSZip();
  let packagedFonts;
  try {
    packagedFonts = await Promise.all(referencedFonts.map(async (font) => ({
      bytes: await downloadCompositionFont({ font, supabase: params.supabase }),
      font,
      path: compositionFontArchivePath(font),
    })));
  } catch (error) {
    if (error instanceof CompositionFontAssetError) throw new CompositionSnapshotError(error.message, error.status);
    throw error;
  }
  const compiledFonts = new Map(packagedFonts.map(({ font, path }) => [
    font.id,
    compiledCompositionFont(font, path),
  ]));
  const assetVariableNames = buildHyperframesAssetVariableNames(manifest);
  // Direct media is represented by provider variables and receives its URL at
  // submission time. Only deck-owned public dependencies must be rewritten in
  // the immutable HTML snapshot.
  const manifestById = new Map(manifest.map((asset) => [asset.productionAssetId, asset]));
  const assetDeliveryUrls = new Map(await Promise.all(deckDependencies.map(async (asset) => {
    const manifestAsset = manifestById.get(asset.id);
    if (!manifestAsset) throw new CompositionSnapshotError("Falta una dependencia del deck en el manifiesto.");
    return [
      asset.id,
      await resolveHyperframesAssetDeliveryUrl({ asset: manifestAsset, supabase: params.supabase }),
    ] as const;
  })));
  const deckAssetUrls = new Map(deckDependencies.flatMap((asset) => (
    asset.public_url ? [[asset.public_url, assetDeliveryUrls.get(asset.id)!] as const] : []
  )));
  const [snapshotHtml, animationRuntime] = await Promise.all([
    compileCompositionPreview({
      assetUrls: assetDeliveryUrls,
      assetVariableNames,
      deckAssetUrls,
      document: current.document,
      fontAssets: compiledFonts,
      target: COMPOSITION_COMPILATION_TARGETS.HYPERFRAMES_RENDER,
    }),
    readCompositionAnimationRuntime(),
  ]);
  zip.file("index.html", snapshotHtml);
  zip.file("assets/gsap.min.js", animationRuntime);
  for (const packagedFont of packagedFonts) zip.file(packagedFont.path, packagedFont.bytes);
  zip.file("composition-document.json", JSON.stringify(current.document, null, 2));
  zip.file("asset-manifest.json", JSON.stringify(manifest, null, 2));
  zip.file("font-manifest.json", JSON.stringify(fontManifest, null, 2));
  zip.file("conformance-contract.json", JSON.stringify(conformanceContract, null, 2));
  const referenceSource = referenceVersion ? await buildConformanceReferenceSource({
    document: current.document, contract: conformanceContract, assets: manifest, fontAssets: compiledFonts, fontManifest,
    deckPublicUrls: new Map(deckDependencies.flatMap((asset) => asset.public_url ? [[asset.id, asset.public_url] as const] : [])),
  }) : null;
  if (referenceSource) {
    writeConformanceReferenceArchive(zip, referenceSource);
  }
  const archive = await zip.generateAsync({ compression: "DEFLATE", type: "uint8array", compressionOptions: { level: 6 } });
  const archivePreflight = validateHyperframesPreflight({
    archiveSizeBytes: archive.byteLength,
    assets: manifest,
    deliveryMode: HYPERFRAMES_ASSET_DELIVERY_MODES.REMOTE_VARIABLES,
    durationSeconds: current.document.canvas.durationSeconds,
    renderProfile: renderSettings,
  });
  if (!archivePreflight.valid || archive.byteLength > HYPERFRAMES_CLOUD_ARCHIVE_LIMIT_BYTES) {
    throw new CompositionSnapshotError(archivePreflight.errors.join(" ") || "El snapshot excede el l\u00edmite de 200 MB.");
  }
  const projectHash = createHash("sha256").update(archive).digest("hex");
  // The document hash identifies the semantic edit; the archive hash identifies
  // the exact bytes that a renderer will download. A repeated path can only be
  // produced by the same bytes, so retrying an interrupted upload is safe.
  const projectPath = `composition-snapshots/${params.organizationId}/${params.compositionId}/${projectHash}.zip`;
  // The path is content-addressed by projectHash. Replacing an orphan left by
  // an interrupted request is therefore idempotent: the bytes are identical.
  const { error: uploadError } = await params.supabase.storage.from(PROJECT_BUCKET).upload(projectPath, archive, { contentType: "application/zip", upsert: true });
  if (uploadError) {
    throw new CompositionSnapshotError(
      `No se pudo cargar el archivo del snapshot${readExternalErrorCode(uploadError) ? ` (${readExternalErrorCode(uploadError)})` : ""}.`,
      502,
    );
  }
  const { data: latest, error: latestError } = await params.supabase.from("video_composition_revisions").select("revision_number").eq("composition_id", params.compositionId).order("revision_number", { ascending: false }).limit(1).maybeSingle();
  if (latestError) {
    throw new CompositionSnapshotError(
      `No se pudo calcular la siguiente revisión${readExternalErrorCode(latestError) ? ` (${readExternalErrorCode(latestError)})` : ""}.`,
      500,
    );
  }
  const creatorId = await resolveSnapshotCreatorId(params.supabase, params.userId);
  const { data: revision, error: revisionError } = await params.supabase.from("video_composition_revisions").insert({
    composition_id: params.compositionId,
    created_by: creatorId,
    entry_point: "index.html",
    format: HYPERFRAMES_COMPOSITION_FORMAT,
    generation_mode: "AUTOMATIC",
    manifest: {
      asset_delivery_mode: HYPERFRAMES_ASSET_DELIVERY_MODES.REMOTE_VARIABLES,
      media_binding_version: HYPERFRAMES_MEDIA_BINDING_VERSION,
      asset_manifest: manifest,
      conformance_contract: conformanceContract,
      ...(eventCheckpoints ? {conformance_event_batch_authorization: buildCompositionEventBatchAuthorization({
        document: current.document, parentContract: conformanceContract})} : {}),
      conformance_contract_version: conformanceContract.schemaVersion,
      canvas_duration_seconds: current.document.canvas.durationSeconds,
      canvas_aspect_ratio: resolveCompositionCanvasFormat(current.document.canvas),
      draft_document_hash: current.documentHash,
      draft_document_id: params.draftId,
      draft_document_version: current.version,
      font_manifest: fontManifest,
      render_profile: {
        ...persistedRenderProfile,
      },
      snapshot: true,
      ...(referenceSource ? {
        conformance_reference_version: referenceVersion,
        conformance_reference: referenceSource.metadata,
      } : {}),
    },
    organization_id: params.organizationId,
    project_archive_size_bytes: archive.byteLength,
    project_hash: projectHash,
    project_storage_bucket: PROJECT_BUCKET,
    project_storage_path: projectPath,
    revision_number: (latest?.revision_number || 0) + 1,
    variables_schema: buildHyperframesAssetVariableSchema(manifest),
    variables_values: current.document.variables,
  }).select("id, revision_number, project_hash, project_archive_size_bytes").single();
  if (revisionError) {
    throw new CompositionSnapshotError(
      `El archivo se cargó, pero no se pudo registrar la revisión${readExternalErrorCode(revisionError) ? ` (${readExternalErrorCode(revisionError)})` : ""}.`,
      500,
    );
  }
  const productionManifest = manifest.filter((asset) => assets.find((row) => row.id === asset.productionAssetId)?.origin === "PRODUCTION");
  const brandingManifest = manifest.filter((asset) => assets.find((row) => row.id === asset.productionAssetId)?.origin === "BRANDING");
  const soundEffectManifest = manifest.filter((asset) => assets.find((row) => row.id === asset.productionAssetId)?.origin === "SOUND_EFFECT");
  if (productionManifest.length > 0) {
    const { error: linkError } = await params.supabase.from("video_composition_assets").insert(productionManifest.map((asset) => ({
      composition_revision_id: revision.id, file_size_bytes: asset.fileSizeBytes, mime_type: asset.mimeType, organization_id: params.organizationId,
      production_asset_id: asset.productionAssetId, role: asset.mimeType.startsWith("audio/") ? "AUDIO" : asset.mimeType.startsWith("video/") ? "VIDEO" : "IMAGE",
      source_checksum: asset.checksum, source_storage_path: asset.storagePath,
    })));
    if (linkError) {
      throw new CompositionSnapshotError(
        `La revisión se creó, pero no se pudieron vincular sus assets${readExternalErrorCode(linkError) ? ` (${readExternalErrorCode(linkError)})` : ""}.`,
        500,
      );
    }
  }
  if (brandingManifest.length > 0) {
    const { error: linkError } = await params.supabase.from("video_composition_brand_assets").insert(brandingManifest.map((asset) => ({
      composition_revision_id: revision.id,
      file_size_bytes: asset.fileSizeBytes,
      mime_type: asset.mimeType,
      organization_assembly_asset_id: asset.productionAssetId,
      organization_id: params.organizationId,
      role: "VIDEO",
      source_checksum: asset.checksum,
      source_storage_bucket: asset.storageBucket || "production-assets",
      source_storage_path: asset.storagePath,
