/** SHA-256 domain separator; changing the encoding requires a new digest version.
 * This is our bounded V1 encoding, not a claim of RFC 8785/JCS compliance. */
export const HTML_EDITABLE_MANIFEST_DIGEST_PREFIX = "courseforge-html-editable-manifest-digest-v1\n";

function manifestPreimage(manifest: HtmlEditableManifest): string {
  // Only this one self-referential slot is omitted. Source/document hashes and
  // every authorization-scoping identity remain covered by the content digest.
  const { manifestSha256: _selfDigest, ...binding } = manifest.binding;
  return HTML_EDITABLE_MANIFEST_DIGEST_PREFIX + canonicalHtmlEditingJson({
    format: manifest.format, binding, elements: manifest.elements,
  });
}

/** Bounded JSON/schema validation occurs before canonicalization. Issuers may
 * use a valid placeholder hash in both bindings when initially computing it. */
export function createHtmlEditableManifestDigestPreimage(
  encodedManifest: string, expectedBinding: HtmlEditingBinding,
): string {
  return manifestPreimage(parseHtmlEditableManifest(encodedManifest, expectedBinding));
}

export function computeHtmlEditableManifestSha256(
  encodedManifest: string, expectedBinding: HtmlEditingBinding,
): string {
  return createHash("sha256").update(createHtmlEditableManifestDigestPreimage(encodedManifest, expectedBinding), "utf8").digest("hex");
}

/** Content integrity only. The expected digest must be fetched independently
 * from authoritative storage, not copied from the request's claimed binding. */
export function verifyHtmlEditableManifestContent(
  encodedManifest: string, authoritativeBinding: HtmlEditingBinding,
): HtmlEditableManifest {
  const manifest = parseHtmlEditableManifest(encodedManifest, authoritativeBinding);
  const observedSha256 = createHash("sha256").update(manifestPreimage(manifest), "utf8").digest("hex");
  if (observedSha256 !== authoritativeBinding.manifestSha256) {
    throw new HtmlEditingValidationError("MANIFEST_DIGEST_MISMATCH");
  }
  return manifest;
}

/** Verifies the manifest anew before command preflight, preventing callers from
 * treating a previously checked but subsequently mutated object as verified. */
export function validateContentVerifiedHtmlEditingCommand(params: {
  encodedManifest: string; encodedCommand: string;
  authoritativeBinding: HtmlEditingBinding; grantedAssetIds: readonly string[];
}): HtmlEditingCommand {
  const manifest = verifyHtmlEditableManifestContent(params.encodedManifest, params.authoritativeBinding);
  return validateHtmlEditingCommand({
    encodedCommand: params.encodedCommand, manifest,
    verifiedBinding: params.authoritativeBinding, grantedAssetIds: params.grantedAssetIds,
  });
}

import { lstat, readFile } from "node:fs/promises";
import { join } from "node:path";
import type { SupabaseClient } from "@supabase/supabase-js";
import JSZip from "jszip";
import { z } from "zod";
import { playbackVisualFramesHash } from "./composition-playback-audio-contract";
import { compositionConformanceContractSchema } from "../composition-preview-render-conformance";
import { CONFORMANCE_EVIDENCE_STORAGE } from "./composition-conformance-evidence-package";
import { AUDIO_EVIDENCE_LIMITS, audioEvidenceHashSchema, audioEvidenceMetadataSchema, audioEvidenceReceiptSchema,
  audioEvidenceSha256, audioEvidenceStoragePath, validateAudioEvidenceBytes } from "./composition-audio-evidence-contract";

async function boundedFile(path: string, maximumBytes: number) {
  const file = await lstat(path);
  if (!file.isFile() || file.size <= 0 || file.size > maximumBytes) throw new Error("AUDIO_EVIDENCE_FILE_INVALID");
  const bytes = await readFile(path);
  if (bytes.length !== file.size || bytes.length > maximumBytes) throw new Error("AUDIO_EVIDENCE_FILE_CHANGED");
  return bytes;
}
/** Worker-only operation: caller must establish organization authority before using service-role credentials. */
export async function persistAudioConformanceEvidence(params: {
  supabase: SupabaseClient<any, any, any>; organizationId: string; revisionId: string;
  visualChecksum: string; audioDirectory: string;
}) {
  z.string().uuid().parse(params.organizationId); z.string().uuid().parse(params.revisionId);
  audioEvidenceHashSchema.parse(params.visualChecksum);
  const visual = await params.supabase.rpc("read_hyperframes_visual_conformance_evidence", {
    p_organization_id: params.organizationId, p_revision_id: params.revisionId, p_bundle_sha256: params.visualChecksum,
  });
  if (visual.error || !visual.data) throw new Error("AUDIO_EVIDENCE_VISUAL_UNAVAILABLE");
  const context = z.object({ organizationId: z.string().uuid(), revisionId: z.string().uuid(), checksum: audioEvidenceHashSchema,
    projectHash: audioEvidenceHashSchema, documentHash: audioEvidenceHashSchema, contract: compositionConformanceContractSchema }).parse(visual.data);
  if (context.organizationId !== params.organizationId || context.revisionId !== params.revisionId
    || context.checksum !== params.visualChecksum) throw new Error("AUDIO_EVIDENCE_CONTEXT_MISMATCH");
  const metadata = audioEvidenceMetadataSchema.parse(JSON.parse((await boundedFile(join(params.audioDirectory, "audio-reference-metadata.json"), AUDIO_EVIDENCE_LIMITS.jsonBytes)).toString("utf8")));
  const receipt = audioEvidenceReceiptSchema.parse({
    ...JSON.parse((await boundedFile(join(params.audioDirectory, "audio-reference-receipt.json"), AUDIO_EVIDENCE_LIMITS.jsonBytes)).toString("utf8")),
    visualChecksum: params.visualChecksum,
  });
  const wavMaximumBytes = receipt.schemaVersion === 1 ? AUDIO_EVIDENCE_LIMITS.legacyWavBytes : AUDIO_EVIDENCE_LIMITS.wavBytes;
  const wav = await boundedFile(join(params.audioDirectory, "audio-reference.wav"), wavMaximumBytes);
  if (receipt.organizationId !== params.organizationId || receipt.revisionId !== params.revisionId
    || receipt.projectHash !== context.projectHash || receipt.documentHash !== context.documentHash) throw new Error("AUDIO_EVIDENCE_CONTEXT_MISMATCH");
  if (receipt.schemaVersion === 3) {
    if (playbackVisualFramesHash(visual.data.frames) !== receipt.visualFramesSha256) {
      throw new Error("AUDIO_EVIDENCE_PLAYBACK_VISUAL_MISMATCH");
    }
  }
  validateAudioEvidenceBytes({ wav, metadata, receipt, contract: context.contract });
  const zip = new JSZip(); const date = new Date("2000-01-01T00:00:00Z");
  for (const [name, bytes] of [["audio-reference.wav", wav], ["audio-reference-metadata.json", JSON.stringify(metadata)],
    ["audio-reference-receipt.json", JSON.stringify(receipt)]] as const) zip.file(name, bytes, { date, createFolders: false });
  const bytes = await zip.generateAsync({ type: "nodebuffer", compression: "DEFLATE", compressionOptions: { level: 6 } });
  if (bytes.length > (receipt.schemaVersion === 1 ? AUDIO_EVIDENCE_LIMITS.legacyPackageBytes : AUDIO_EVIDENCE_LIMITS.packageBytes)) {
    throw new Error("AUDIO_EVIDENCE_PACKAGE_LIMIT");
  }
  const checksum = audioEvidenceSha256(bytes);
  const storagePath = audioEvidenceStoragePath(params.organizationId, params.revisionId, params.visualChecksum, checksum);
  const storage = params.supabase.storage.from(CONFORMANCE_EVIDENCE_STORAGE.bucket);
  await storage.upload(storagePath, bytes, { contentType: "application/zip", upsert: false });
  // Lost acknowledgement or an existing content-addressed object is safe only after exact readback.
  const readback = await storage.download(storagePath);
  if (readback.error || !readback.data || readback.data.size !== bytes.length) throw new Error("AUDIO_EVIDENCE_READBACK_FAILED");
  const persisted = Buffer.from(await readback.data.arrayBuffer());
  if (persisted.length !== bytes.length || audioEvidenceSha256(persisted) !== checksum) throw new Error("AUDIO_EVIDENCE_STORAGE_MISMATCH");
  const recorded = await params.supabase.rpc("record_hyperframes_audio_conformance_evidence", {
    p_organization_id: params.organizationId, p_revision_id: params.revisionId, p_visual_checksum: params.visualChecksum,
    p_bundle_sha256: checksum, p_file_size_bytes: bytes.length, p_receipt: receipt,
  });
  if (recorded.error || recorded.data !== checksum) throw new Error("AUDIO_EVIDENCE_RECORD_FAILED");
  return { checksum, storagePath, sizeBytes: bytes.length, receipt, status: receipt.status };
}

import { mkdtemp, rm, rmdir, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { Writable } from "node:stream";
import { pipeline } from "node:stream/promises";
import { isDeepStrictEqual } from "node:util";
import type { SupabaseClient } from "@supabase/supabase-js";
import JSZip from "jszip";
import { z } from "zod";
import { CONFORMANCE_EVIDENCE_STORAGE } from "./composition-conformance-evidence-package";
import { AUDIO_EVIDENCE_LIMITS, audioEvidenceHashSchema, audioEvidenceReceiptSchema, audioEvidenceRecordSchema,
  audioEvidenceSha256, audioEvidenceStoragePath, validateAudioEvidenceBytes } from "./composition-audio-evidence-contract";

/** Internal worker read. Scope must come from an authorized job, not arbitrary user input. */
export async function readPersistedAudioConformanceEvidence(params: {
  supabase: SupabaseClient<any, any, any>; organizationId: string; revisionId: string;
  visualChecksum: string; checksum: string; outputParentDirectory: string;
}) {
  z.string().uuid().parse(params.organizationId); z.string().uuid().parse(params.revisionId);
  audioEvidenceHashSchema.parse(params.visualChecksum); audioEvidenceHashSchema.parse(params.checksum);
  const result = await params.supabase.rpc("read_hyperframes_audio_conformance_evidence", {
    p_organization_id: params.organizationId, p_revision_id: params.revisionId,
    p_visual_checksum: params.visualChecksum, p_bundle_sha256: params.checksum,
  });
  if (result.error || !result.data) throw new Error("AUDIO_EVIDENCE_RECORD_UNAVAILABLE");
  const record = audioEvidenceRecordSchema.parse(result.data);
  const storagePath = audioEvidenceStoragePath(params.organizationId, params.revisionId, params.visualChecksum, params.checksum);
  if (record.organizationId !== params.organizationId || record.revisionId !== params.revisionId
    || record.visualChecksum !== params.visualChecksum || record.checksum !== params.checksum || record.storagePath !== storagePath
    || record.receipt.organizationId !== record.organizationId || record.receipt.revisionId !== record.revisionId
    || record.receipt.projectHash !== record.projectHash || record.receipt.documentHash !== record.documentHash
    || record.receipt.visualChecksum !== record.visualChecksum) throw new Error("AUDIO_EVIDENCE_CONTEXT_MISMATCH");
  const downloaded = await params.supabase.storage.from(CONFORMANCE_EVIDENCE_STORAGE.bucket).download(storagePath);
  if (downloaded.error || !downloaded.data || downloaded.data.size !== record.sizeBytes) throw new Error("AUDIO_EVIDENCE_DOWNLOAD_FAILED");
  const bytes = Buffer.from(await downloaded.data.arrayBuffer());
  if (bytes.length !== record.sizeBytes || audioEvidenceSha256(bytes) !== record.checksum) throw new Error("AUDIO_EVIDENCE_STORAGE_MISMATCH");
  const zip = await JSZip.loadAsync(bytes);
  const limits = new Map([["audio-reference.wav", record.receipt.schemaVersion === 1 ? AUDIO_EVIDENCE_LIMITS.legacyWavBytes : AUDIO_EVIDENCE_LIMITS.wavBytes],
    ["audio-reference-metadata.json", AUDIO_EVIDENCE_LIMITS.jsonBytes], ["audio-reference-receipt.json", AUDIO_EVIDENCE_LIMITS.jsonBytes]]);
  const entries = Object.values(zip.files);
  if (entries.length !== limits.size || entries.some((entry) => entry.dir || !limits.has(entry.name)
    || entry.unsafeOriginalName !== entry.name)) throw new Error("AUDIO_EVIDENCE_ARCHIVE_INVALID");
  const files = new Map<string, Buffer>();
  for (const [name, maximum] of limits) {
    let size = 0; const chunks: Buffer[] = [];
    await pipeline(zip.file(name)!.nodeStream("nodebuffer"), new Writable({ write(chunk: Buffer, _encoding, callback) {
      size += chunk.length;
      if (size > maximum) callback(new Error("AUDIO_EVIDENCE_EXTRACTION_LIMIT"));
      else { chunks.push(chunk); callback(); }
    } }));
    files.set(name, Buffer.concat(chunks));
  }
  const receipt = audioEvidenceReceiptSchema.parse(JSON.parse(files.get("audio-reference-receipt.json")!.toString("utf8")));
  if (!isDeepStrictEqual(receipt, record.receipt)) throw new Error("AUDIO_EVIDENCE_RECEIPT_MISMATCH");
  const metadata = validateAudioEvidenceBytes({ wav: files.get("audio-reference.wav")!, receipt, contract: record.contract,
    metadata: JSON.parse(files.get("audio-reference-metadata.json")!.toString("utf8")) });
  const directory = await mkdtemp(join(params.outputParentDirectory, "conformance-audio-evidence-"));
  const cleanup = async () => {
    for (const name of limits.keys()) await rm(join(directory, name), { force: true });
    await rmdir(directory).catch((error: NodeJS.ErrnoException) => { if (error.code !== "ENOENT") throw error; });
  };
  try {
    for (const [name, content] of files) await writeFile(join(directory, name), content, { flag: "wx", mode: 0o600 });
    return { directory, receipt, metadata, contract: record.contract, checksum: record.checksum, audioReferencePath: join(directory, "audio-reference.wav"),
      audioReferenceMetadataPath: join(directory, "audio-reference-metadata.json"), cleanup };
  } catch (error) { await cleanup(); throw error; }
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { createHash } from "node:crypto";
import { compositionConformanceContractSchema } from "../composition-preview-render-conformance";
import { eventBatchMeasurementIdentitySchema, eventBatchMeasurementPacketSchema,
  type EventBatchMeasurementAdapters, type EventBatchMeasurementIdentity } from "./composition-conformance-event-batch-execution";
import { prepareAndPersistVisualConformanceReference } from "./composition-conformance-reference-pipeline";
import { measureCompositionEventBatchWithPersistedReference } from "./composition-conformance-event-batch-measurement";
import { persistCompositionEventBatchMeasurement, readCompositionEventBatchMeasurement } from "./composition-conformance-event-batch-persistence";
import type {ComparisonProcessPorts} from "./composition-comparison-process-ports";
import {z} from "zod";

const defaultDependencies = {prepareVisual: prepareAndPersistVisualConformanceReference,
  measure: measureCompositionEventBatchWithPersistedReference,
  readPacket: readCompositionEventBatchMeasurement, persistPacket: persistCompositionEventBatchMeasurement};

/** Compose actual worker adapters. The root and local video must already pass revision/integrity verification. */
export function createPersistedCompositionEventBatchAdapters(params: {
  supabase: SupabaseClient<any, any, any>; supabaseUrl: string; rootIdentity: EventBatchMeasurementIdentity;
  outputParentDirectory: string; videoPath: string; renderReceiptPath: string; signal?: AbortSignal;
  processPorts?: ComparisonProcessPorts;
  visualReferenceChecksums?: string[];
  resolveRenderReceipt?: (contractSha256: string, batchIndex: number) => {path: string; sha256: string};
}, dependencies: typeof defaultDependencies = defaultDependencies): EventBatchMeasurementAdapters {
  const root = eventBatchMeasurementIdentitySchema.parse(params.rootIdentity);
  if (root.batch.batchIndex !== 0 || root.parentContractSha256 !== root.batchContractSha256) {
    throw new Error("CONFORMANCE_EVENT_ADAPTER_ROOT_REQUIRED");
  }
  const {supabase, supabaseUrl, outputParentDirectory, videoPath, renderReceiptPath, signal} = params;
  const visualReferences = params.visualReferenceChecksums === undefined ? undefined
    : z.array(z.string().regex(/^[a-f0-9]{64}$/)).length(root.batch.batchCount).parse(params.visualReferenceChecksums);
  if (visualReferences && !params.resolveRenderReceipt)
    throw new Error("CONFORMANCE_EVENT_ADAPTER_ADMITTED_RECEIPTS_REQUIRED_INVALID");
  const operations = {...dependencies};
  const captureChecksums = new Map<string, string>();
  const assertActive = () => {if (signal?.aborted) throw new Error("CONFORMANCE_EVENT_EXECUTION_ABORTED");};
  const validateIdentity = (input: unknown) => {
    assertActive();
    const identity = eventBatchMeasurementIdentitySchema.parse(input);
    const sameScope = (['organizationId', 'revisionId', 'projectHash', 'videoSha256', 'documentHash', 'parentContractSha256'] as const)
      .every((key) => identity[key] === root[key]);
    if (!sameScope || JSON.stringify({...identity.batch, batchIndex: 0}) !== JSON.stringify(root.batch)) {
      throw new Error("CONFORMANCE_EVENT_ADAPTER_SCOPE_MISMATCH");
    }
    if (Boolean(visualReferences) !== Boolean(identity.visualReferenceSha256)
      || visualReferences && identity.visualReferenceSha256 !== visualReferences[identity.batch.batchIndex])
      throw new Error("CONFORMANCE_EVENT_ADAPTER_REFERENCE_SELECTION_MISMATCH");
    return identity;
  };
  const identityKey = (identity: EventBatchMeasurementIdentity) => JSON.stringify(identity);
  return {
    async readBatch(input) {
      const identity = validateIdentity(input);
      const stored = await operations.readPacket({supabase, identity}); assertActive(); return stored;
    },
    async measureBatch(input) {
      const identity = validateIdentity(input.identity);
      const contract = compositionConformanceContractSchema.parse(input.contract);
      if (contract.documentHash !== identity.documentHash || contract.schemaVersion !== 4
        || JSON.stringify(contract.checkpointBatch) !== JSON.stringify(identity.batch)
        || createHash("sha256").update(JSON.stringify(contract)).digest("hex") !== identity.batchContractSha256) {
        throw new Error("CONFORMANCE_EVENT_ADAPTER_CONTRACT_MISMATCH");
      }
      const visual = identity.visualReferenceSha256 ? {organizationId: root.organizationId, revisionId: root.revisionId,
        projectHash: root.projectHash, documentHash: root.documentHash, checksum: identity.visualReferenceSha256}
        : await operations.prepareVisual({supabase, supabaseUrl, organizationId: root.organizationId,
          revisionId: root.revisionId, outputParentDirectory, signal, eventBatchIndex: identity.batch.batchIndex});
      assertActive();
      if (visual.organizationId !== root.organizationId || visual.revisionId !== root.revisionId
        || visual.projectHash !== root.projectHash || visual.documentHash !== root.documentHash) {
        throw new Error("CONFORMANCE_EVENT_ADAPTER_REFERENCE_MISMATCH");
      }
      const admittedReceipt = params.resolveRenderReceipt?.(identity.batchContractSha256, identity.batch.batchIndex);
      const packet = eventBatchMeasurementPacketSchema.parse(await operations.measure({identity: structuredClone(identity), contract: structuredClone(contract),
        comparison: {supabase, checksum: visual.checksum, outputParentDirectory, videoPath,
          renderReceiptPath: admittedReceipt?.path ?? renderReceiptPath,
          ...(admittedReceipt ? {expectedContractSha256: identity.batchContractSha256, expectedRenderReceiptSha256: admittedReceipt.sha256} : {}),
          signal, processPorts: params.processPorts}}));
      assertActive();
      if (identityKey(packet.identity) !== identityKey(identity)) throw new Error("CONFORMANCE_EVENT_ADAPTER_PACKET_MISMATCH");
      captureChecksums.set(identityKey(identity), visual.checksum);
      return packet;
    },
    async persistBatch(input) {
      const packet = eventBatchMeasurementPacketSchema.parse(input);
      const identity = validateIdentity(packet.identity), key = identityKey(identity);
      const visualChecksum = captureChecksums.get(key);
      if (!visualChecksum) throw new Error("CONFORMANCE_EVENT_ADAPTER_MEASUREMENT_REQUIRED");
      await operations.persistPacket({supabase, packet, visualChecksum});
      captureChecksums.delete(key); assertActive();
    },
  };
}

import { createHash } from "node:crypto";
import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";
import { eventBatchMeasurementIdentitySchema, eventBatchMeasurementPacketSchema,
  hashEventBatchMeasurementPacket, persistedEventBatchMeasurementSchema } from "./composition-conformance-event-batch-execution";
import { eventBatchAuthorizationManifestSchema } from "../composition-conformance-batch-contract";
import { compositionConformanceContractSchema } from "../composition-preview-render-conformance";

export const EVENT_BATCH_PACKET_MAXIMUM_BYTES = 4 * 1024 * 1024;
const digestSchema = z.string().regex(/^[a-f0-9]{64}$/);
type WorkerDatabase = SupabaseClient<any, any, any>;
const canonicalHash = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");

async function authorizeIdentity(supabase: WorkerDatabase, identity: z.infer<typeof eventBatchMeasurementIdentitySchema>) {
  const revision = await supabase.from("video_composition_revisions").select("id, organization_id, project_hash, manifest")
    .eq("id", identity.revisionId).eq("organization_id", identity.organizationId).maybeSingle();
  const row = revision.data;
  if (revision.error || !row || row.id !== identity.revisionId || row.organization_id !== identity.organizationId
    || row.project_hash !== identity.projectHash || row.manifest?.conformance_reference_version !== 1) {
    throw new Error("CONFORMANCE_EVENT_PACKET_REVISION_UNAVAILABLE");
  }
  const parent = compositionConformanceContractSchema.parse(row.manifest.conformance_contract);
  const authorization = eventBatchAuthorizationManifestSchema.parse(row.manifest.conformance_event_batch_authorization);
  if (parent.schemaVersion !== 4 || !parent.checkpointBatch || parent.documentHash !== identity.documentHash
    || canonicalHash(parent) !== identity.parentContractSha256 || authorization.documentHash !== identity.documentHash
    || authorization.parentContractSha256 !== identity.parentContractSha256
    || JSON.stringify(parent.checkpointBatch) !== JSON.stringify(authorization.rootBatch)
    || JSON.stringify({...identity.batch, batchIndex: 0}) !== JSON.stringify(authorization.rootBatch)
    || authorization.batchContractSha256[identity.batch.batchIndex] !== identity.batchContractSha256) {
    throw new Error("CONFORMANCE_EVENT_PACKET_AUTHORIZATION_MISMATCH");
  }
}

/** Internal worker only. DB stores bounded measurement packets, never a trusted PASS verdict. */
export async function persistCompositionEventBatchMeasurement(params: {
  supabase: WorkerDatabase; packet: unknown; visualChecksum: string;
}) {
  const supabase = params.supabase;
  const packet = eventBatchMeasurementPacketSchema.parse(params.packet);
  const visualChecksum = digestSchema.parse(params.visualChecksum);
  if (packet.identity.visualReferenceSha256 && packet.identity.visualReferenceSha256 !== visualChecksum)
    throw new Error("CONFORMANCE_EVENT_PACKET_REFERENCE_MISMATCH");
  if (Buffer.byteLength(JSON.stringify(packet)) > EVENT_BATCH_PACKET_MAXIMUM_BYTES) throw new Error("CONFORMANCE_EVENT_PACKET_SIZE_LIMIT");
  await authorizeIdentity(supabase, packet.identity);
  const packetSha256 = hashEventBatchMeasurementPacket(packet);
  const recorded = await supabase.rpc(packet.identity.visualReferenceSha256
    ? "record_hyperframes_selected_event_batch_measurement" : "record_hyperframes_event_batch_measurement", {
    p_identity: packet.identity, p_packet: packet, p_packet_sha256: packetSha256, p_visual_sha256: visualChecksum,
  });
  if (recorded.error || recorded.data !== packetSha256) throw new Error("CONFORMANCE_EVENT_PACKET_RECORD_FAILED");
  return {packetSha256};
}

/** Null means no matching packet, not a transport or authorization failure. */
export async function readCompositionEventBatchMeasurement(params: {supabase: WorkerDatabase; identity: unknown}) {
  const supabase = params.supabase;
  const identity = eventBatchMeasurementIdentitySchema.parse(params.identity);
  await authorizeIdentity(supabase, identity);
  const recorded = await supabase.rpc(identity.visualReferenceSha256
    ? "read_hyperframes_selected_event_batch_measurement" : "read_hyperframes_event_batch_measurement", {p_identity: identity});
  if (recorded.error) throw new Error("CONFORMANCE_EVENT_PACKET_READ_FAILED");
  if (recorded.data === null) return null;
  if (recorded.data === undefined || Buffer.byteLength(JSON.stringify(recorded.data)) > EVENT_BATCH_PACKET_MAXIMUM_BYTES + 256) {
    throw new Error("CONFORMANCE_EVENT_PACKET_SIZE_LIMIT");
  }
  const stored = persistedEventBatchMeasurementSchema.parse(recorded.data);
  if (canonicalHash(stored.packet.identity) !== canonicalHash(identity)
    || hashEventBatchMeasurementPacket(stored.packet) !== stored.packetSha256) {
    throw new Error("CONFORMANCE_EVENT_PACKET_READBACK_MISMATCH");
  }
  return stored;
}

import { createHash } from "node:crypto";
import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";
import { buildVisualConformanceEvidencePackage, CONFORMANCE_EVIDENCE_STORAGE } from "./composition-conformance-evidence-package";
import { compositionConformanceContractSchema } from "../composition-preview-render-conformance";
import { COMPOSITION_EVENT_PLAN_MAX_BATCHES } from "../composition-conformance-batch-contract";

/** Internal worker operation: organization authority must be established by the caller, not user input. */
export async function persistVisualConformanceEvidence(params: {
  supabase: SupabaseClient<any, any, any>; organizationId: string; revisionId: string; captureDirectory: string;
  eventBatchIndex?: number; eventContract?: unknown;
}) {
  z.string().uuid().parse(params.organizationId); z.string().uuid().parse(params.revisionId);
  if (params.eventBatchIndex !== undefined) z.number().int().nonnegative().max(COMPOSITION_EVENT_PLAN_MAX_BATCHES - 1).parse(params.eventBatchIndex);
  if ((params.eventBatchIndex !== undefined) !== (params.eventContract !== undefined)) throw new Error("CONFORMANCE_EVENT_PERSIST_SELECTION_REQUIRED");
  const { data, error } = await params.supabase.from("video_composition_revisions")
    .select("id, organization_id, project_hash, manifest").eq("id", params.revisionId)
    .eq("organization_id", params.organizationId).maybeSingle();
  if (error || !data || data.id !== params.revisionId || data.organization_id !== params.organizationId
    || data.manifest?.conformance_reference_version !== 1) throw new Error("CONFORMANCE_EVIDENCE_REVISION_UNAVAILABLE");
  const contract = compositionConformanceContractSchema.parse(params.eventContract ?? data.manifest.conformance_contract);
  if (params.eventBatchIndex !== undefined && (contract.schemaVersion !== 4 || contract.checkpointBatch?.batchIndex !== params.eventBatchIndex)) {
    throw new Error("CONFORMANCE_EVENT_PERSIST_INDEX_MISMATCH");
  }
  const bundle = await buildVisualConformanceEvidencePackage({...params, projectHash: data.project_hash, contract,
    ...(params.eventBatchIndex !== undefined ? {authorizedEventRevision: {parentContract: data.manifest.conformance_contract,
      batchAuthorization: data.manifest.conformance_event_batch_authorization}} : {})});
  const storage = params.supabase.storage.from(CONFORMANCE_EVIDENCE_STORAGE.bucket);
  const uploaded = await storage.upload(bundle.storagePath, bundle.bytes, { contentType: "application/zip", upsert: false });
  // A content-addressed object may already exist after a lost acknowledgement. Never overwrite it.
  const readback = await storage.download(bundle.storagePath);
  if (readback.error || !readback.data || readback.data.size !== bundle.bytes.length
    || readback.data.size > CONFORMANCE_EVIDENCE_STORAGE.maximumBytes) {
    throw new Error(uploaded.error ? "CONFORMANCE_EVIDENCE_UPLOAD_FAILED" : "CONFORMANCE_EVIDENCE_READBACK_FAILED");
  }
  const persistedBytes = Buffer.from(await readback.data.arrayBuffer());
  if (persistedBytes.length !== bundle.bytes.length || createHash("sha256").update(persistedBytes).digest("hex") !== bundle.checksum) {
    throw new Error("CONFORMANCE_EVIDENCE_STORAGE_MISMATCH");
  }
  const recorded = await params.supabase.rpc(params.eventBatchIndex !== undefined
    ? "record_hyperframes_event_visual_conformance_evidence" : "record_hyperframes_visual_conformance_evidence", {
    p_organization_id: params.organizationId, p_revision_id: params.revisionId,
    p_project_hash: bundle.receipt.projectHash, p_document_hash: bundle.receipt.documentHash,
    p_bundle_sha256: bundle.checksum, p_file_size_bytes: bundle.bytes.length, p_frames: bundle.receipt.frames,
    ...(params.eventBatchIndex !== undefined ? {p_batch_index: params.eventBatchIndex, p_contract: contract,
      p_lineage: bundle.receipt.eventBatchLineage} : {}),
  });
  if (recorded.error || recorded.data !== bundle.checksum) throw new Error("CONFORMANCE_EVIDENCE_RECORD_FAILED");
  return { status: "VISUAL_CAPTURED_AUDIO_PENDING" as const, organizationId: params.organizationId, revisionId: params.revisionId,
    documentHash: bundle.receipt.documentHash, projectHash: bundle.receipt.projectHash,
    bucket: CONFORMANCE_EVIDENCE_STORAGE.bucket, storagePath: bundle.storagePath, checksum: bundle.checksum, sizeBytes: bundle.bytes.length };
}

import { createHash } from "node:crypto";
import { createWriteStream } from "node:fs";
import { mkdtemp, readFile, rm, rmdir } from "node:fs/promises";
import { join } from "node:path";
import { Transform } from "node:stream";
import { pipeline } from "node:stream/promises";
import { isDeepStrictEqual } from "node:util";
import type { SupabaseClient } from "@supabase/supabase-js";
import JSZip from "jszip";
import { z } from "zod";
import { compositionConformanceContractSchema } from "../composition-preview-render-conformance";
import { CONFORMANCE_EVIDENCE_STORAGE, validateVisualConformanceCapture, visualCaptureReceiptSchema } from "./composition-conformance-evidence-package";
import { eventBatchAuthorizationManifestSchema, COMPOSITION_EVENT_PLAN_MAX_BATCHES } from "../composition-conformance-batch-contract";
import { assertEventBatchCaptureLineage, eventBatchCaptureLineageSchema } from "../composition-conformance-event-batch-lineage";
import { suppressedTextFrameName } from "./composition-text-paint-mask-derivation";
import { suppressedDeckTextFrameName } from "./composition-deck-text-paint-derivation";
import { COMPOSITION_TEXT_PARITY_POLICY } from "../composition-text-parity-policy";

const digestSchema = z.string().regex(/^[a-f0-9]{64}$/);
const evidenceRecordSchema = z.object({
  organizationId: z.string().uuid(), revisionId: z.string().uuid(), checksum: digestSchema,
  projectHash: digestSchema, documentHash: digestSchema, storagePath: z.string(),
  sizeBytes: z.number().int().positive().max(CONFORMANCE_EVIDENCE_STORAGE.maximumBytes),
  frames: visualCaptureReceiptSchema.shape.frames, status: z.literal("VISUAL_CAPTURED_AUDIO_PENDING"),
  contract: compositionConformanceContractSchema,
  eventAuthorization: z.object({parentContract: compositionConformanceContractSchema,
    batchAuthorization: eventBatchAuthorizationManifestSchema, lineage: eventBatchCaptureLineageSchema}).strict().optional(),
}).strict();

/** Only for trusted workers: the caller must establish organization authority before using service-role credentials. */
export async function readPersistedVisualConformanceEvidence(params: {
  supabase: SupabaseClient<any, any, any>; organizationId: string; revisionId: string;
  checksum: string; outputParentDirectory: string;
  eventBatchIndex?: number;
}) {
  z.string().uuid().parse(params.organizationId); z.string().uuid().parse(params.revisionId);
  digestSchema.parse(params.checksum);
  if (params.eventBatchIndex !== undefined) z.number().int().nonnegative().max(COMPOSITION_EVENT_PLAN_MAX_BATCHES - 1).parse(params.eventBatchIndex);
  const recorded = await params.supabase.rpc(params.eventBatchIndex !== undefined
    ? "read_hyperframes_event_visual_conformance_evidence" : "read_hyperframes_visual_conformance_evidence", {
    p_organization_id: params.organizationId, p_revision_id: params.revisionId, p_bundle_sha256: params.checksum,
    ...(params.eventBatchIndex !== undefined ? {p_batch_index: params.eventBatchIndex} : {}),
  });
  if (recorded.error || !recorded.data) throw new Error("CONFORMANCE_EVIDENCE_RECORD_UNAVAILABLE");
  const record = evidenceRecordSchema.parse(recorded.data);
  if (params.eventBatchIndex !== undefined) {
    if (!record.eventAuthorization || record.contract.schemaVersion !== 4
      || record.contract.checkpointBatch?.batchIndex !== params.eventBatchIndex) throw new Error("CONFORMANCE_EVENT_EVIDENCE_AUTHORIZATION_REQUIRED");
    assertEventBatchCaptureLineage(record.eventAuthorization.lineage, record.contract, undefined, record.eventAuthorization);
  } else if (record.eventAuthorization) throw new Error("CONFORMANCE_EVENT_EVIDENCE_UNEXPECTED_AUTHORIZATION");
  const storagePath = `${params.organizationId}/${params.revisionId}/${params.checksum}.zip`;
  if (record.organizationId !== params.organizationId || record.revisionId !== params.revisionId
    || record.checksum !== params.checksum || record.storagePath !== storagePath
    || record.documentHash !== record.contract.documentHash) throw new Error("CONFORMANCE_EVIDENCE_RECORD_MISMATCH");
  const downloaded = await params.supabase.storage.from(CONFORMANCE_EVIDENCE_STORAGE.bucket).download(storagePath);
  if (downloaded.error || !downloaded.data || downloaded.data.size !== record.sizeBytes) {
    throw new Error("CONFORMANCE_EVIDENCE_DOWNLOAD_FAILED");
  }
  const bytes = Buffer.from(await downloaded.data.arrayBuffer());
  if (bytes.length !== record.sizeBytes || createHash("sha256").update(bytes).digest("hex") !== record.checksum) {
    throw new Error("CONFORMANCE_EVIDENCE_STORAGE_MISMATCH");
  }
  // Hash verification precedes decompression. Never extract archive-controlled paths.
  const zip = await JSZip.loadAsync(bytes);
  const files = new Map<string, number>([
    ["conformance-contract.json", 1024 * 1024], ["preview-metadata.json", 1024 * 1024], ["capture-receipt.json", 1024 * 1024],
    ...record.contract.checkpoints.map(({ frameIndex }) => [`frame-${frameIndex}.png`, 20 * 1024 * 1024] as [string, number]),
  ]);
  const entries = Object.values(zip.files);
  for (const checkpoint of record.contract.checkpoints) {
    const name = suppressedTextFrameName(checkpoint.frameIndex);
    if (zip.file(name)) files.set(name, COMPOSITION_TEXT_PARITY_POLICY.maximumPaintCapturePngBytes);
    const deckName = suppressedDeckTextFrameName(checkpoint.frameIndex);
    if (zip.file(deckName)) files.set(deckName, COMPOSITION_TEXT_PARITY_POLICY.maximumPaintCapturePngBytes);
  }
  if (entries.length !== files.size || entries.some((entry) => entry.dir || !files.has(entry.name)
    || entry.unsafeOriginalName !== entry.name)) throw new Error("CONFORMANCE_EVIDENCE_ARCHIVE_INVALID");
  const directory = await mkdtemp(join(params.outputParentDirectory, "conformance-evidence-"));
  const ownedPaths: string[] = [];
  const cleanup = async () => {
    for (const path of ownedPaths) await rm(path, { force: true });
    await rmdir(directory).catch((error: NodeJS.ErrnoException) => { if (error.code !== "ENOENT") throw error; });
  };
  try {
    let totalBytes = 0;
    for (const [name, maximumBytes] of files) {
      const destination = join(directory, name); ownedPaths.push(destination);
      let entryBytes = 0;
      const bound = new Transform({ transform(chunk: Buffer, _encoding, callback) {
        entryBytes += chunk.length; totalBytes += chunk.length;
        if (entryBytes > maximumBytes || totalBytes > 131 * 1024 * 1024) {
          callback(new Error("CONFORMANCE_EVIDENCE_EXTRACTION_LIMIT"));
        } else callback(null, chunk);
      } });
      await pipeline(zip.file(name)!.nodeStream("nodebuffer"), bound, createWriteStream(destination, { flags: "wx", mode: 0o600 }));
    }
    const contract = compositionConformanceContractSchema.parse(JSON.parse(await readFile(join(directory, "conformance-contract.json"), "utf8")));
    if (!isDeepStrictEqual(contract, record.contract)) throw new Error("CONFORMANCE_EVIDENCE_CONTRACT_MISMATCH");
    const capture = await validateVisualConformanceCapture({ captureDirectory: directory,
      organizationId: record.organizationId, revisionId: record.revisionId, projectHash: record.projectHash, contract,
      ...(record.eventAuthorization ? {authorizedEventRevision: record.eventAuthorization} : {}) });
    if (capture.images.length + 3 !== files.size || capture.images.some((image) => !files.has(image.name)))
      throw new Error("CONFORMANCE_EVIDENCE_ARCHIVE_INVALID");
    if (record.eventAuthorization && !isDeepStrictEqual(capture.receipt.eventBatchLineage, record.eventAuthorization.lineage)) {
      throw new Error("CONFORMANCE_EVENT_EVIDENCE_LINEAGE_MISMATCH");
    }
    if (!isDeepStrictEqual(capture.receipt.frames, record.frames)) throw new Error("CONFORMANCE_EVIDENCE_RECEIPT_MISMATCH");
    return { directory, contract, contractPath: join(directory, "conformance-contract.json"),
      previewDirectory: directory, previewMetadataPath: join(directory, "preview-metadata.json"),
      receipt: capture.receipt, checksum: record.checksum, status: record.status, cleanup };
  } catch (error) { await cleanup(); throw error; }
}

import { mkdtemp, rm, rmdir, writeFile } from "node:fs/promises";
import {createHash} from "node:crypto";
import { tmpdir } from "node:os";
import { join, isAbsolute } from "node:path";
import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";
import { prepareAndPersistVisualConformanceReference } from "./composition-conformance-reference-pipeline";
import { prepareAndPersistAudioConformanceReference } from "./composition-audio-evidence-pipeline";
import { compareVideoWithPersistedConformanceReferences, compareVideoWithPersistedSilentReference } from "./composition-persisted-audio-comparison";
import {assertSilentConformanceMeasurement} from "./composition-silent-conformance-gate";
import { conformanceJobClaimSchema, durableConformanceReportSchema, type ConformanceJobClaim } from "./composition-conformance-job-worker";
import { resolveExportedColorTagPolicyId, type ExportedColorTagPolicyId } from "./composition-exported-color-tags";
import { executePersistedCompositionEventBatches } from "./composition-conformance-persisted-event-execution";
import { eventBatchExecutionSummarySchema } from "./composition-conformance-event-batch-execution";
import { evaluateEventVisualCoverageGate } from "./composition-conformance-event-visual-gate";
import { evaluateConformanceJobStatus } from "./composition-conformance-job-status";
import { evaluateEventMeasurementGate } from "./composition-event-measurement-gate";
import { wrapConformanceStageFailure, recordConformanceCleanupFailure, ConformanceStageFailure, type ConformanceExecutionStage } from "./composition-conformance-stage-failure";
import { assertConformanceReportMatchesContract } from "./composition-conformance-contract-report-gate";
import {assertConformanceJobActive} from "./composition-conformance-job-lease";
import {createControlledRenderDeadline, CONTROLLED_RENDER_DEADLINE_POLICY} from "./composition-controlled-render-deadline";
import {bindConformanceReportToAttempt} from "./composition-conformance-attempt-binding";
import type {ComparisonProcessPorts} from "./composition-comparison-process-ports";
import {requiresConformanceExecutionRecovery} from "./composition-conformance-stage-failure";
import {recoverConformanceRenderEvidence, type ConformanceRenderEvidenceReservation} from "./composition-conformance-render-evidence";
import {bindConformanceReferenceReservation} from "./composition-conformance-reference-reservation";
import {controlledReferenceSelectionSchema} from "./composition-controlled-reference-selection";
import {readConformanceCheckpointReservation, type ConformanceCheckpointReservation} from "./composition-conformance-checkpoint-reservation";

const integritySchema = z.object({ assetId: z.string().uuid(), checksum: z.string().regex(/^[a-f0-9]{64}$/),
  documentHash: z.string().regex(/^[a-f0-9]{64}$/), sizeBytes: z.number().int().positive().max(2 * 1024 ** 3), status: z.literal("MATCH") }).strict();
type IntegrityResult = z.infer<typeof integritySchema>;
type IntegrityScope = { supabase: SupabaseClient<any, any, any>; supabaseUrl: string; organizationId: string; requestId: string; signal?: AbortSignal };
export type ConformanceIntegrityAdapters = {
  snapshot: (params: IntegrityScope & { destinationPath: string }) => Promise<IntegrityResult>;
  recheck: (params: IntegrityScope) => Promise<IntegrityResult>;
};
const defaultEvidence = { visual: prepareAndPersistVisualConformanceReference, audio: prepareAndPersistAudioConformanceReference,
  compare: compareVideoWithPersistedConformanceReferences, events: executePersistedCompositionEventBatches };
type ConformanceEvidenceAdapters = typeof defaultEvidence & {compareSilent?: typeof compareVideoWithPersistedSilentReference};

type ConformanceJobExecutionInput = {
  claim: ConformanceJobClaim; supabase: SupabaseClient<any, any, any>; supabaseUrl: string; ffmpegPath: string; allowLongAudio?: boolean; capturePlaybackAudio?: boolean;
  colorTagPolicyId?: ExportedColorTagPolicyId;
  signal?: AbortSignal;
  processPorts?: ComparisonProcessPorts;
  controlledRenderEvidence?: ConformanceRenderEvidenceReservation;
  referenceSelection?: z.input<typeof controlledReferenceSelectionSchema>;
  checkpointReservation?: ConformanceCheckpointReservation;
  /** Host opt-in only after the prepared V2 database gate is installed. No automatic negotiation. */
  enableSilentDurableReports?: boolean;
  reservationEvidence?: z.input<typeof durableConformanceReportSchema>["reservationEvidence"];
  resolveRenderReservation?: (claim: ConformanceJobClaim, signal: AbortSignal) => Promise<{
    controlledRenderEvidence: ConformanceRenderEvidenceReservation;
    referenceSelection: z.input<typeof controlledReferenceSelectionSchema>;
    processPorts: ComparisonProcessPorts;
    reservationEvidence: NonNullable<z.input<typeof durableConformanceReportSchema>["reservationEvidence"]>;
  }>;
};

export const CONFORMANCE_JOB_EXECUTION_POLICY = Object.freeze({
  id: "WHOLE_CONFORMANCE_EXECUTION_BUDGET_V1",
  timeoutMilliseconds: CONTROLLED_RENDER_DEADLINE_POLICY.maximumMilliseconds,
});

/** Includes preparation, all partitions, remote recheck and owned cleanup; no per-stage reset.
 * Waits for adapter ownership before cleanup: a logical timeout is not OS termination. */
export async function executeConformanceJob(params: ConformanceJobExecutionInput,
  integrity: ConformanceIntegrityAdapters, evidence: ConformanceEvidenceAdapters = defaultEvidence,
  budgetOptions: {timeoutMilliseconds?: number; clock?: () => number} = {}) {
  assertConformanceJobActive(params.signal);
  if ((params.controlledRenderEvidence || params.checkpointReservation) && !params.processPorts)
    throw new Error("CONFORMANCE_JOB_CONTROLLED_PROCESS_PORTS_REQUIRED_INVALID");
  if (params.referenceSelection && !params.controlledRenderEvidence)
    throw new Error("CONFORMANCE_JOB_REFERENCE_RESERVATION_AUTHORITY_REQUIRED_INVALID");
  if (params.checkpointReservation && (params.controlledRenderEvidence || params.referenceSelection))
    throw new Error("CONFORMANCE_JOB_CHECKPOINT_RESERVATION_AMBIGUOUS_INVALID");
  if (params.resolveRenderReservation && (params.controlledRenderEvidence || params.referenceSelection
    || params.checkpointReservation || params.processPorts || params.reservationEvidence))
    throw new Error("CONFORMANCE_JOB_DURABLE_RESERVATION_AMBIGUOUS_INVALID");
  const budget = createControlledRenderDeadline(budgetOptions.timeoutMilliseconds
    ?? CONFORMANCE_JOB_EXECUTION_POLICY.timeoutMilliseconds, params.signal, budgetOptions.clock);
  const assertActive = () => {
    try {budget.remainingMilliseconds();}
    catch (error) {
      const message = error instanceof Error ? error.message : "";
      if (message === "CONTROLLED_RENDER_DEADLINE_EXCEEDED") throw new Error("CONFORMANCE_JOB_DEADLINE_TIMEOUT");
      if (message === "CONTROLLED_RENDER_ABORTED") throw new Error("CONFORMANCE_JOB_EXECUTION_CANCELLED");
      throw new Error("CONFORMANCE_JOB_DEADLINE_INVALID");
    }
  };
  try {
    assertActive();
    let reserved: Awaited<ReturnType<typeof readConformanceCheckpointReservation>> | undefined;
    let durable: Awaited<ReturnType<NonNullable<ConformanceJobExecutionInput["resolveRenderReservation"]>>> | undefined;
    if (params.resolveRenderReservation) {
      try {durable = await params.resolveRenderReservation(conformanceJobClaimSchema.parse(params.claim), budget.signal);}
      catch (error) {throw wrapConformanceStageFailure("RENDER_EVIDENCE_ADMISSION", error);}
      assertActive();
      if (!durable?.controlledRenderEvidence || !durable.referenceSelection || !durable.reservationEvidence
        || !durable.processPorts || typeof durable.processPorts.execute !== "function"
        || typeof durable.processPorts.consumePcm !== "function"
        || typeof durable.processPorts.pixelDecoderPath !== "string" || !isAbsolute(durable.processPorts.pixelDecoderPath)
        || typeof durable.processPorts.probePath !== "string" || !isAbsolute(durable.processPorts.probePath))
        throw new Error("CONFORMANCE_JOB_DURABLE_RESERVATION_CONFIGURATION_INVALID");
    }
    if (params.checkpointReservation) {
      try {reserved = await readConformanceCheckpointReservation(params.checkpointReservation,
        conformanceJobClaimSchema.parse(params.claim), budget.signal);}
      catch (error) {throw wrapConformanceStageFailure("RENDER_EVIDENCE_ADMISSION", error);}
      assertActive();
    }
    const result = await executeActiveConformanceJob({...params, ...reserved, ...durable, signal: budget.signal}, integrity, evidence, assertActive);
    try {assertActive();} catch (error) {throw wrapConformanceStageFailure("RESOURCE_CLEANUP", error);}
    return result;
  } finally {budget.dispose();}
}

/** Worker-only: MP4 streamed by the integrity service, exact persisted references and a second remote check. */
async function executeActiveConformanceJob(params: ConformanceJobExecutionInput,
  integrity: ConformanceIntegrityAdapters, evidence: ConformanceEvidenceAdapters, assertActive: () => void) {
  assertActive();
  const claim = conformanceJobClaimSchema.parse(params.claim);
  const controlledReservation = params.controlledRenderEvidence ? structuredClone(params.controlledRenderEvidence) : undefined;
  const referenceSelection = params.referenceSelection ? controlledReferenceSelectionSchema.parse(params.referenceSelection) : undefined;
  resolveExportedColorTagPolicyId(params.colorTagPolicyId);
  const directory = await mkdtemp(join(tmpdir(), "composition-conformance-job-"));
  const videoPath = join(directory, "final.mp4");
  const renderReceiptPath = join(directory, "receipt.json");
  const ownedReceiptPaths = [renderReceiptPath];
  const scope = { supabase: params.supabase, supabaseUrl: params.supabaseUrl,
    organizationId: claim.organization_id, requestId: claim.request_id, signal: params.signal };
  const preparation = { ...scope, revisionId: claim.revision_id, outputParentDirectory: directory };
  let stage: ConformanceExecutionStage = "REMOTE_SNAPSHOT";
  let primaryFailure: ConformanceStageFailure | undefined;
  try {
    assertActive();
    const before = integritySchema.parse(await integrity.snapshot({ ...scope, destinationPath: videoPath }));
    assertActive();
    stage = "RENDER_EVIDENCE_ADMISSION";
    const controlledEvidence = controlledReservation ? await recoverConformanceRenderEvidence({
      supabase: params.supabase, reservation: controlledReservation,
      jobScope: {...scope, revisionId: claim.revision_id}, integrity: before, videoPath, signal: params.signal,
    }) : undefined;
    assertActive();
    if (params.reservationEvidence && (!controlledEvidence
      || params.reservationEvidence.executionId !== controlledEvidence.binding.executionId
      || params.reservationEvidence.supervisorReceiptSha256 !== controlledEvidence.supervisorReceiptSha256))
      throw new Error("CONFORMANCE_JOB_DURABLE_RESERVATION_BINDING_INVALID");
    const referenceReservation = controlledReservation && controlledEvidence && referenceSelection
      ? bindConformanceReferenceReservation(controlledReservation, controlledEvidence, referenceSelection) : undefined;
    const selectedRoot = referenceReservation?.selection.references[0];
    const silent = Boolean(selectedRoot && !selectedRoot.audioChecksum);
    if (silent && params.enableSilentDurableReports !== true)
      throw new Error("CONFORMANCE_JOB_SILENT_RESERVED_REPORT_UNSUPPORTED");
    if (silent && params.capturePlaybackAudio) throw new Error("CONFORMANCE_JOB_SILENT_PLAYBACK_INVALID");
    const receiptPaths = new Map<number, {contractSha256: string; path: string; sha256: string}>();
    if (controlledEvidence) {
      for (const batch of controlledEvidence.batches) {
        const path = batch.batchIndex === 0 ? renderReceiptPath : join(directory, `receipt-batch-${batch.batchIndex}.json`);
        if (batch.batchIndex !== 0) ownedReceiptPaths.push(path);
        await writeFile(path, JSON.stringify(batch.receipt), {flag: "wx", mode: 0o600});
        receiptPaths.set(batch.batchIndex, {contractSha256: batch.contractSha256, path, sha256: batch.receiptSha256});
      }
    }
    const resolveRenderReceipt = controlledEvidence ? (contractSha256: string, batchIndex: number) => {
      const selected = receiptPaths.get(batchIndex);
      if (!selected || selected.contractSha256 !== contractSha256)
        throw new Error("CONFORMANCE_JOB_RENDER_EVIDENCE_BATCH_MISMATCH");
      return {path: selected.path, sha256: selected.sha256};
    } : undefined;
    stage = "PREVIEW_REFERENCE";
    const visual = selectedRoot && controlledEvidence ? {documentHash: before.documentHash,
      projectHash: controlledEvidence.projectHash, organizationId: scope.organizationId, revisionId: claim.revision_id,
      checksum: selectedRoot.visualChecksum} : await evidence.visual(preparation);
    assertActive();
    if (visual.documentHash !== before.documentHash || visual.organizationId !== scope.organizationId
      || visual.revisionId !== claim.revision_id) throw new Error("CONFORMANCE_JOB_REVISION_MISMATCH");
    if (controlledEvidence && visual.projectHash !== controlledEvidence.projectHash)
      throw new Error("CONFORMANCE_JOB_RENDER_EVIDENCE_PROJECT_MISMATCH");
    stage = "AUDIO_REFERENCE";
    const audio = silent ? undefined : selectedRoot ? {checksum: selectedRoot.audioChecksum!, receipt: undefined}
      : await evidence.audio({ ...preparation, visualChecksum: visual.checksum,
        ffmpegPath: params.ffmpegPath, allowLongAudio: params.allowLongAudio, capturePlaybackAudio: params.capturePlaybackAudio });
    assertActive();
    if (!controlledEvidence) await writeFile(renderReceiptPath,
      JSON.stringify({ documentHash: before.documentHash, videoSha256: before.checksum }), { flag: "wx", mode: 0o600 });
    stage = "RENDER_COMPARISON";
    assertActive();
    const comparisonInput = { ...preparation, checksum: visual.checksum,
      videoPath, renderReceiptPath, audioPolicyId: "course-v1", processPorts: params.processPorts,
      ...(referenceReservation && controlledReservation?.artifacts.kind === "EVENT_BATCH_SET" ? {eventBatchIndex: 0} : {}),
      ...(controlledEvidence ? {expectedContractSha256: controlledEvidence.batches[0]!.contractSha256,
        expectedRenderReceiptSha256: controlledEvidence.batches[0]!.receiptSha256} : {}),
      ...(params.colorTagPolicyId ? {colorTagPolicyId: params.colorTagPolicyId} : {}) } as const;
    const comparison = silent
      ? {...await (evidence.compareSilent ?? compareVideoWithPersistedSilentReference)(comparisonInput), audioReference: undefined}
      : await evidence.compare({...comparisonInput, audioChecksum: audio!.checksum});
    assertActive();
    if (params.colorTagPolicyId && comparison.report.colorTags?.policy !== params.colorTagPolicyId) {
      throw new Error("CONFORMANCE_JOB_COLOR_TAG_EVIDENCE_MISSING_INVALID");
    }
    if (params.capturePlaybackAudio === true && (!selectedRoot && audio?.receipt?.schemaVersion !== 3
      || comparison.audioReference?.receipt?.schemaVersion !== 3
      || !("audioPlayback" in comparison.report) || !comparison.report.audioPlayback)) {
      throw new Error("CONFORMANCE_JOB_PLAYBACK_EVIDENCE_MISSING_INVALID");
    }
    if (comparison.reference.documentHash !== before.documentHash || comparison.reference.projectHash !== visual.projectHash
      || comparison.reference.organizationId !== scope.organizationId || comparison.reference.revisionId !== claim.revision_id
      || comparison.reference.checksum !== visual.checksum || comparison.audioReference?.checksum !== audio?.checksum) {
      throw new Error("CONFORMANCE_JOB_REFERENCE_MISMATCH");
    }
    const referenceContract = assertConformanceReportMatchesContract(comparison.reference.contract, comparison.report.visual,
      {videoSha256: before.checksum});
    if (silent) assertSilentConformanceMeasurement(referenceContract, comparison.report);
    if (controlledEvidence && createHash("sha256").update(JSON.stringify(referenceContract), "utf8").digest("hex")
      !== controlledEvidence.batches[0]!.contractSha256)
      throw new Error("CONFORMANCE_JOB_RENDER_EVIDENCE_CONTRACT_MISMATCH");
    if (referenceContract.documentHash !== before.documentHash)
      throw new Error("CONFORMANCE_JOB_CONTRACT_DOCUMENT_MISMATCH_INVALID");
    stage = "EVENT_COMPARISON";
    const eventResult = await evidence.events({...preparation, projectHash: visual.projectHash,
      documentHash: before.documentHash, videoSha256: before.checksum, videoPath, renderReceiptPath,
      processPorts: params.processPorts, resolveRenderReceipt,
      visualReferenceChecksums: referenceReservation?.selection.references.map(reference => reference.visualChecksum)});
    assertActive();
    const events = eventResult === null ? undefined : eventBatchExecutionSummarySchema.parse(eventResult);
    if (events && events.projectHash !== visual.projectHash) throw new Error("CONFORMANCE_JOB_EVENT_PROJECT_MISMATCH");
    if (comparison.report.visual?.checkpointBatchCoverage && !events) throw new Error("CONFORMANCE_JOB_EVENT_EXECUTION_REQUIRED");
    const eventVisualCoverageGate = events ? evaluateEventVisualCoverageGate({root: comparison.report.visual, execution: events}) : undefined;
    const eventMeasurementGate = eventVisualCoverageGate ? evaluateEventMeasurementGate({comparison: comparison.report, visualCoverageGate: eventVisualCoverageGate}) : undefined;
    const status = evaluateConformanceJobStatus({comparisonStatus: comparison.report.status,
      eventStatus: events?.status, eventVisualCoverageStatus: eventVisualCoverageGate?.status, eventMeasurementStatus: eventMeasurementGate?.status});
    if (controlledEvidence && controlledReservation) {
      stage = "RENDER_EVIDENCE_ADMISSION";
      const refreshed = await recoverConformanceRenderEvidence({supabase: params.supabase,
        reservation: controlledReservation, jobScope: {...scope, revisionId: claim.revision_id},
        integrity: before, videoPath, signal: params.signal});
      if (refreshed.supervisorReceiptSha256 !== controlledEvidence.supervisorReceiptSha256)
        throw new Error("CONFORMANCE_JOB_RENDER_EVIDENCE_CHANGED_INVALID");
      assertActive();
    }
    stage = "REMOTE_RECHECK";
    const after = integritySchema.parse(await integrity.recheck(scope));
    assertActive();
    if ((["assetId", "checksum", "documentHash", "sizeBytes"] as const).some((key) => before[key] !== after[key])) {
      throw new Error("CONFORMANCE_JOB_REMOTE_CHANGED_INVALID");
    }
    const { status: _integrityStatus, ...boundIntegrity } = before;
    stage = "REPORT_VALIDATION";
    return durableConformanceReportSchema.parse({ reportVersion: silent ? 2 : 1, scope: "REMOTE_INTEGRITY_AND_PERSISTED_CONFORMANCE",
      status, organizationId: scope.organizationId, requestId: scope.requestId, revisionId: claim.revision_id,
      attemptBinding: bindConformanceReportToAttempt(claim),
      ...(controlledEvidence ? {renderEvidence: {scope: controlledEvidence.scope,
        binding: controlledEvidence.binding, supervisorReceiptSha256: controlledEvidence.supervisorReceiptSha256}} : {}),
      ...(referenceReservation ? {referenceSelection: referenceReservation.selection} : {}),
      ...(params.reservationEvidence ? {reservationEvidence: params.reservationEvidence} : {}),
      ...(silent ? {audioExpectation: {policy: "FROZEN_NO_AUDIO_TRACK_V1", contractSha256: controlledEvidence!.binding.contractSha256}} : {}),
      integrity: boundIntegrity, references: { visualChecksum: visual.checksum, ...(audio ? {audioChecksum: audio.checksum} : {}) },
