    layout: { height: 720, opacity: 0.8, rotation: 5, width: 1280, x: 120, y: 80, zIndex: 2 },
    mediaFit: "COVER",
    source: { productionAssetId: ORIGINAL_ID, type: "PRODUCTION_ASSET" },
    sourceDurationSeconds: 8,
    sourceOffsetSeconds: 1,
    startSeconds: 2,
    timingSource: "USER_EDITED",
    trackId: "visual",
  }],
  deckStyles: null,
