test("reconciles an existing draft with the active Production avatar only", () => {
  const staleAssetId = "00000000-0000-4000-8000-000000000051";
  const avatarAssetId = "00000000-0000-4000-8000-000000000052";
  const document = createInitialCompositionDocument({
    animatedDeck: {
      css: "",
      fonts: [],
      height: 1080,
      slides: [{ animationCount: 0, classes: "slide", html: "<h1>Uno</h1>", index: 0, label: "Uno" }],
      width: 1920,
    },
    assets: [{
      checksum: "1".repeat(64),
      durationSeconds: 8,
      fileSizeBytes: 4,
      mimeType: "video/mp4",
      productionAssetId: staleAssetId,
      publicUrl: null,
      storageBucket: "production-assets",
      storagePath: "production-assets/old-broll.mp4",
      timelineRole: "BROLL",
    }],
    plan: { accentColor: "#38BDF8", durationSeconds: 8, subtitle: "Prueba", title: "Draft" },
  });
  document.clips[0]!.layout.x = 123;
  document.clips[0]!.timingSource = "USER_EDITED";
  document.canvas.fps = 30;

  const operations = buildProductionAssetReconciliationOperations(document, [{
    checksum: "2".repeat(64),
    durationSeconds: 30,
    fileSizeBytes: 4,
    hasAudio: true,
    mimeType: "video/mp4",
    productionAssetId: avatarAssetId,
    publicUrl: null,
    storageBucket: "production-assets",
    storagePath: "production-assets/avatar.mp4",
    timelineRole: "AVATAR",
    timelineVariant: "FULL",
  }]);
  assert.throws(
    () => applyCompositionEditorPatches(document, operations),
    /exclusiva del sistema/,
  );
  const reconciled = applyCompositionEditorPatches(document, operations, "SYSTEM");

  assert.deepEqual(operations.map((operation) => operation.type), ["document.reconcile"]);
  assert.equal(reconciled.canvas.fps, 25);
  assert.equal(reconciled.clips.some((clip) => clip.source.type === "PRODUCTION_ASSET" && clip.source.productionAssetId === staleAssetId), false);
  assert.equal(reconciled.clips.some((clip) => clip.source.type === "PRODUCTION_ASSET" && clip.source.productionAssetId === avatarAssetId && clip.trackId === "avatar"), true);
  const avatar = reconciled.clips.find((clip) => clip.source.type === "PRODUCTION_ASSET" && clip.source.productionAssetId === avatarAssetId);
  assert.equal(avatar?.source.type === "PRODUCTION_ASSET" ? avatar.source.hasAudio : undefined, true);
  assert.equal(reconciled.clips.find((clip) => clip.source.type === "DECK_SLIDE")?.layout.x, 123);
  assert.equal(reconciled.clips.find((clip) => clip.source.type === "DECK_SLIDE")?.timingSource, "USER_EDITED");
});

test("recovers the composition that wins a concurrent initialization", async () => {
  const winner = {
    active_revision_id: null,
    artifact_id: "00000000-0000-4000-8000-000000000602",
    created_at: "2026-09-04T12:00:00.000Z",
    id: "00000000-0000-4000-8000-000000000603",
    material_component_id: "00000000-0000-4000-8000-000000000601",
    name: "Ganadora",
    status: "DRAFT",
    updated_at: "2026-09-04T12:00:00.000Z",
  };
  let compositionLookupCount = 0;
  const supabase = {
    from(table: string) {
      let inserting = false;
      const query = {
        eq() { return query; },
        insert() { inserting = true; return query; },
        limit() { return query; },
        maybeSingle() {
          compositionLookupCount += 1;
          return Promise.resolve({ data: compositionLookupCount === 1 ? null : winner, error: null });
        },
        neq() { return query; },
        order() { return query; },
        select() { return query; },
        single() {
          if (table === "material_components") {
            return Promise.resolve({
              data: {
                id: winner.material_component_id,
                material_lesson_id: "00000000-0000-4000-8000-000000000604",
                material_lessons: {
                  lesson_id: "lesson-1",
                  materials: {
                    artifact_id: winner.artifact_id,
                    artifacts: { organization_id: "00000000-0000-4000-8000-000000000605" },
                  },
                },
                type: "VIDEO_THEORETICAL",
              },
              error: null,
            });
          }
          return Promise.resolve(inserting
            ? { data: null, error: { code: "23505", message: "duplicate key" } }
            : { data: null, error: null });
        },
      };
      return query;
    },
  };

  const result = await getOrCreateHyperframesCompositionDraft({
    componentId: winner.material_component_id,
    createdBy: "00000000-0000-4000-8000-000000000606",
    name: "Composición concurrente",
    organizationId: "00000000-0000-4000-8000-000000000605",
    supabase: supabase as any,
  });

  assert.equal(result.created, false);
  assert.equal(result.composition.id, winner.id);
  assert.equal(compositionLookupCount, 2);
});

import type { SupabaseClient } from "@supabase/supabase-js";
import {
  HYPERFRAMES_SOURCE_BUCKETS,
  HYPERFRAMES_SOURCE_SIGNED_URL_TTL_SECONDS,
  PUBLIC_PRODUCTION_MEDIA_BUCKETS,
} from "../media-storage.config";
import type { HyperframesAssetManifestItem } from "./hyperframes.types";

const ASSET_VARIABLE_PREFIX = "cf_asset_";

export class HyperframesAssetDeliveryError extends Error {}

/**
 * Produces a stable provider variable name without persisting a temporary URL.
 * The UUID is already immutable within a snapshot and the prefix reserves a
 * namespace that cannot collide with author-defined composition variables.
 */
export function buildHyperframesAssetVariableName(productionAssetId: string) {
  if (!/^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i.test(productionAssetId)) {
    throw new HyperframesAssetDeliveryError("El identificador del asset remoto no es válido.");
  }
  return `${ASSET_VARIABLE_PREFIX}${productionAssetId.replaceAll("-", "")}`;
}

export function buildHyperframesAssetVariableNames(assets: HyperframesAssetManifestItem[]) {
  return new Map(assets.map((asset) => [
    asset.productionAssetId,
    buildHyperframesAssetVariableName(asset.productionAssetId),
  ]));
}

/** Resolves a short-lived delivery URL without persisting credentials in a revision. */
export async function resolveHyperframesAssetDeliveryUrl(params: {
  asset: HyperframesAssetManifestItem;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const bucket = params.asset.storageBucket || "production-assets";
  if (!HYPERFRAMES_SOURCE_BUCKETS.has(bucket)) {
    throw new HyperframesAssetDeliveryError(`El bucket “${bucket}” no permite entrega remota a HyperFrames.`);
  }
  const objectPath = bucketRelativePath(bucket, params.asset.storagePath);
  let deliveryUrl: string;
  if (PUBLIC_PRODUCTION_MEDIA_BUCKETS.has(bucket)) {
    const { data } = params.supabase.storage.from(bucket).getPublicUrl(objectPath);
    deliveryUrl = data.publicUrl;
  } else {
    const { data, error } = await params.supabase.storage
      .from(bucket)
      .createSignedUrl(objectPath, HYPERFRAMES_SOURCE_SIGNED_URL_TTL_SECONDS);
    if (error || !data?.signedUrl) {
      throw new HyperframesAssetDeliveryError(
        `No se pudo autorizar temporalmente el asset remoto “${params.asset.productionAssetId}”.`,
      );
    }
    deliveryUrl = data.signedUrl;
  }
  let url: URL;
  try {
    url = new URL(deliveryUrl);
  } catch {
    throw new HyperframesAssetDeliveryError("Supabase no generó una URL válida para el asset remoto.");
  }
  if (url.protocol !== "https:") {
    throw new HyperframesAssetDeliveryError("HyperFrames requiere URLs HTTPS para descargar medios remotos.");
  }
  url.searchParams.set("v", params.asset.checksum.toLowerCase());
  return url.toString();
}

export async function resolveHyperframesAssetVariables(params: {
  assets: HyperframesAssetManifestItem[];
  supabase: SupabaseClient<any, "public", any>;
}) {
  const entries = await Promise.all(params.assets.map(async (asset) => [
    buildHyperframesAssetVariableName(asset.productionAssetId),
    await resolveHyperframesAssetDeliveryUrl({ asset, supabase: params.supabase }),
  ] as const));
  return Object.fromEntries(entries);
}

export function buildHyperframesAssetVariableSchema(assets: HyperframesAssetManifestItem[]) {
  return assets.map((asset) => ({
    default: "",
    id: buildHyperframesAssetVariableName(asset.productionAssetId),
    label: `Asset ${asset.productionAssetId}`,
    type: "string",
  }));
}

function bucketRelativePath(bucket: string, storagePath: string) {
  const path = storagePath.startsWith(`${bucket}/`)
    ? storagePath.slice(bucket.length + 1)
    : storagePath;
  if (!path || path.startsWith("/") || path.includes("..") || path.includes("\\")) {
    throw new HyperframesAssetDeliveryError("La ruta del asset remoto no es segura.");
  }
  return path;
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { resolveProductionComponentContext } from "../jobs/production-jobs.service";

export class HyperframesCompositionError extends Error {
  constructor(message: string, readonly status = 400) {
    super(message);
  }
}

/** Creates the shell for an internally-authored HyperFrames composition. */
export async function createHyperframesCompositionDraft(params: {
  componentId: string;
  createdBy: string;
  name: string;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const context = await resolveProductionComponentContext({
    componentId: params.componentId,
    supabase: params.supabase,
  });
  if (context.organizationId !== params.organizationId) {
    throw new HyperframesCompositionError("El componente no pertenece a la empresa activa.", 403);
  }

  const { data, error } = await params.supabase
    .from("video_compositions")
    .insert({
      artifact_id: context.artifactId,
      created_by: params.createdBy,
      material_component_id: context.componentId,
      name: params.name,
      organization_id: params.organizationId,
      status: "DRAFT",
    })
    .select("id, name, status, artifact_id, material_component_id, created_at, updated_at")
    .single();
  if (error) throw error;
  return data;
}

/** One active composition is created or recovered when a video is opened in Ensamble. */
export async function getOrCreateHyperframesCompositionDraft(params: {
  componentId: string;
  createdBy: string;
  name: string;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const existing = await findActiveHyperframesComposition(params);
  if (existing) return { composition: existing, created: false };

  try {
    return { composition: await createHyperframesCompositionDraft(params), created: true };
  } catch (error) {
    // The partial unique index is authoritative when two tabs (or a Strict
    // Mode remount) initialize the same lesson concurrently. Recover the row
    // that won instead of surfacing an intermittent preparation failure.
    if (isUniqueViolation(error)) {
      const concurrent = await findActiveHyperframesComposition(params);
      if (concurrent) return { composition: concurrent, created: false };
    }
    throw error;
  }
}

async function findActiveHyperframesComposition(params: {
  componentId: string;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const { data, error } = await params.supabase
    .from("video_compositions")
    .select("id, name, status, active_revision_id, artifact_id, material_component_id, created_at, updated_at")
    .eq("organization_id", params.organizationId)
    .eq("material_component_id", params.componentId)
    .neq("status", "ARCHIVED")
    .order("updated_at", { ascending: false })
    .limit(1)
    .maybeSingle();
  if (error) throw error;
  return data;
}

function isUniqueViolation(error: unknown) {
  return Boolean(error && typeof error === "object" && "code" in error
    && (error as { code?: unknown }).code === "23505");
}

export async function listHyperframesCompositions(params: {
  componentId?: string;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  let query = params.supabase
    .from("video_compositions")
    .select("id, name, status, active_revision_id, artifact_id, material_component_id, created_at, updated_at")
    .eq("organization_id", params.organizationId)
    .order("updated_at", { ascending: false })
    .limit(100);
  if (params.componentId) query = query.eq("material_component_id", params.componentId);
  const { data, error } = await query;
  if (error) throw error;
  return data || [];
}

