const DRAFT_PROJECT_PREFIX = "video-composition-drafts";
const GENERATED_DECK_FONT_UNAVAILABLE_MESSAGE = "Las diapositivas usan una fuente personalizada pendiente de vinculación al editor. No se sustituirá la tipografía ni se creará un borrador con campos incompletos.";

export class HyperframesDraftError extends Error {
  constructor(message: string, readonly status = 400) {
    super(message);
  }
}

export type StudioProjectDescriptor = { draftId: string; projectId: string; version: number };

type DraftRow = {
  current_version: number;
  id: string;
  project_storage_bucket: string;
  project_storage_prefix: string;
};

/** Builds one atomic, server-only migration that preserves authored edits. */
export function buildProductionAssetReconciliationOperations(
  document: Parameters<typeof reconcileCompositionDocument>[0]["document"],
  assets: Parameters<typeof reconcileCompositionDocument>[0]["productionAssets"],
  deckDependencyAssetIds: Set<string> = new Set(),
  animatedDeck: Parameters<typeof reconcileCompositionDocument>[0]["animatedDeck"] = null,
  narrativeScenes?: CompositionNarrativeScene[],
  replaceNarrativeTiming = false,
) {
  const reconciled = reconcileCompositionDocument({
    narrativeScenes,
    replaceNarrativeTiming,
    animatedDeck,
    deckDependencyAssetIds,
    document,
    productionAssets: assets,
  });
  return reconciled.changed
    ? [{ document: reconciled.document, type: "document.reconcile" as const }]
    : [];
}

/**
 * Resolves the persistent project identity for the full visual editor.
 * The editor can use a temporary workspace, but Courseforge remains the source
 * of truth for this draft and its versioned files.
 */
export async function getOrCreateHyperframesDraft(params: {
  compositionId: string;
  organizationId: string;
  userId: string;
  supabase: SupabaseClient<any, "public", any>;
}): Promise<StudioProjectDescriptor> {
  const { data: composition, error: compositionError } = await params.supabase
    .from("video_compositions")
    .select("id")
    .eq("id", params.compositionId)
    .eq("organization_id", params.organizationId)
    .maybeSingle();
  if (compositionError) throw compositionError;
  if (!composition) throw new HyperframesDraftError("Composición de video no encontrada.", 404);

  const existing = await findActiveDraft(params);
  if (existing) return studioProjectDescriptor(existing.id, existing.current_version);

  const { data: created, error: createError } = await params.supabase
    .from("video_composition_drafts")
    .insert({
      composition_id: params.compositionId,
      last_changed_by: params.userId,
      organization_id: params.organizationId,
      project_storage_prefix: `${DRAFT_PROJECT_PREFIX}/${params.organizationId}/${params.compositionId}`,
      // The native document is the source of truth. An HTML file is compiled
      // only for a protected preview response and is never uploaded here.
      source_manifest: { documentFormat: "courseforge-composition-v1", version: 1 },
      state: "ACTIVE",
    })
    .select("id, current_version")
    .single();
  if (createError) {
    // A second editor may have initialized the same draft between our read and
    // insert. The database's unique constraint remains authoritative; recover
    // the winner instead of creating a duplicate workspace.
    if (createError.code === "23505") {
      const concurrentDraft = await findActiveDraft(params);
      if (concurrentDraft) return studioProjectDescriptor(concurrentDraft.id, concurrentDraft.current_version);
    }
    throw createError;
  }
  return studioProjectDescriptor(created.id, created.current_version);
}

/**
 * Initializes the native, versioned document exactly once. The preview compiles
 * it in memory, preserving the HTML deck without uploading a legacy index file.
 */
export async function initializeHyperframesDraft(params: {
  preassemblyVersion?: string;
  compositionId: string;
  organizationId: string;
  userId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const descriptor = await getOrCreateHyperframesDraft(params);
  const { data: draft, error: draftError } = await params.supabase
    .from("video_composition_drafts")
    .select("id, current_version, project_storage_bucket, project_storage_prefix")
    .eq("id", descriptor.draftId)
    .eq("organization_id", params.organizationId)
    .single();
  if (draftError) throw draftError;
  const typedDraft = draft as DraftRow;

  const { data: composition, error: compositionError } = await params.supabase
    .from("video_compositions")
    .select("name, material_component_id")
    .eq("id", params.compositionId)
    .eq("organization_id", params.organizationId)
    .single();
  if (compositionError) throw compositionError;
  if (!composition.material_component_id) {
    throw new HyperframesDraftError("La composición no está asociada a un componente de material.");
  }

  const [{ data: component, error: componentError }, candidates] = await Promise.all([
    params.supabase
      .from("material_components")
      .select("assets")
      .eq("id", composition.material_component_id)
      .single(),
    listHyperframesSourceAssets({
      componentId: composition.material_component_id,
      organizationId: params.organizationId,
      supabase: params.supabase,
    }),
  ]);
  if (componentError) throw componentError;
  // Images referenced inside the deck remain part of that HTML source. They
  // must not become duplicate, user-editable image clips in the timeline.
  const assets = candidates
    .filter(isAutomaticTimelineSourceAsset)
    .map((asset) => ({
      checksum: asset.checksum,
      durationSeconds: asset.durationSeconds,
      fileSizeBytes: asset.fileSizeBytes,
      hasAudio: asset.hasAudio,
      label: typeof asset.metadata.asset_display_name === "string"
        ? `${asset.metadata.asset_display_name}${asset.timelineRole === "VOICE" ? " · Voz" : ""}`
        : asset.sceneOrder
          ? `${asset.timelineRole === "AVATAR" ? "Avatar" : "Voz"} · Escena ${asset.sceneOrder}`
          : typeof asset.metadata.file_name === "string" ? asset.metadata.file_name : undefined,
      mimeType: asset.mimeType,
      productionAssetId: asset.productionAssetId,
      publicUrl: null,
      sceneClipId: asset.sceneClipId,
      sceneOrder: asset.sceneOrder,
      sourceHeight: positiveMetadataDimension(asset.metadata.source_height),
      sourceWidth: positiveMetadataDimension(asset.metadata.source_width),
      storageBucket: asset.storagePath.split("/")[0],
      storagePath: asset.storagePath,
      timelineRole: asset.timelineRole,
      timelineVariant: asset.timelineVariant,
    }));
  const deckDependencyAssetIds = new Set(candidates
    .filter((asset) => asset.sourceType === "DECK_DEPENDENCY")
    .map((asset) => asset.productionAssetId));
  const animatedDeck = await loadStandaloneHtmlDecks({
    componentId: composition.material_component_id, organizationId: params.organizationId,
    supabase: params.supabase, legacy: extractHyperframesAnimatedDeck(component.assets),
  });
  // A draft can predate a re-sync. Link assets on every initialization so an
  // older draft never hides assets that are already available in Production.
  if (candidates.length > 0) {
    const { error: assetLinkError } = await params.supabase
      .from("video_composition_draft_assets")
      .upsert(candidates.map((asset) => ({
        draft_id: typedDraft.id,
        organization_id: params.organizationId,
        production_asset_id: asset.productionAssetId,
        role: asset.timelineRole || inferAssetRole(asset.mimeType),
        source_reference: asset.sourceType,
      })), { onConflict: "draft_id,production_asset_id" });
    if (assetLinkError) throw assetLinkError;
  }
  const activeAssetIds = new Set(candidates.map((asset) => asset.productionAssetId));
  const { data: existingAssetLinks, error: existingAssetLinksError } = await params.supabase
    .from("video_composition_draft_assets")
    .select("production_asset_id")
    .eq("draft_id", typedDraft.id)
    .eq("organization_id", params.organizationId);
  if (existingAssetLinksError) throw existingAssetLinksError;
  const staleAssetIds = (existingAssetLinks || [])
    .map((link) => link.production_asset_id as string)
    .filter((assetId) => !activeAssetIds.has(assetId));
  if (staleAssetIds.length > 0) {
    const { error: staleAssetLinkError } = await params.supabase
      .from("video_composition_draft_assets")
      .delete()
      .eq("draft_id", typedDraft.id)
      .eq("organization_id", params.organizationId)
      .in("production_asset_id", staleAssetIds);
    if (staleAssetLinkError) throw staleAssetLinkError;
  }

  const { data: standaloneProject, error: standaloneError } = await params.supabase.from("standalone_assembly_projects")
    .select("id").eq("backing_component_id", composition.material_component_id).eq("organization_id", params.organizationId).maybeSingle();
  if (standaloneError) throw standaloneError;
  const persistedDocument = await loadOrCreateInitialDocument({
    generatedComponentId: component.assets?.slides?.editable_deck != null ? composition.material_component_id : undefined,
    narrativeAssets: component.assets,
    manualSourceInsertion: Boolean(standaloneProject),
    preassemblyVersion: params.preassemblyVersion,
    narrativeScenes: buildCompositionNarrativeScenes(component.assets, buildSceneVisualCatalog(animatedDeck)),
    animatedDeck,
    assets,
    compositionName: composition.name,
    deckDependencyAssetIds,
    draftId: typedDraft.id,
    organizationId: params.organizationId,
    supabase: params.supabase,
    userId: params.userId,
  });

  if (persistedDocument.created) {
    const { error: changeError } = await params.supabase
      .from("video_composition_draft_changes")
      .upsert({
        actor_id: params.userId,
        draft_id: typedDraft.id,
        metadata: { assetCount: assets.length, documentHash: hashCompositionDocument(persistedDocument.document), hasAnimatedDeck: Boolean(animatedDeck) },
        organization_id: params.organizationId,
        source: "SYSTEM",
        summary: "Documento inicial de la composición creado desde Producción.",
        version: persistedDocument.version,
      }, { onConflict: "draft_id,version" });
    if (changeError) throw changeError;
  }

  return { ...descriptor, initialized: persistedDocument.created, documentVersion: persistedDocument.version };
}

function positiveMetadataDimension(value: unknown) {
  return typeof value === "number" && Number.isInteger(value) && value > 0 && value <= 16_384
    ? value
    : undefined;
}

async function loadOrCreateInitialDocument(params: {
  generatedComponentId?: string;
  narrativeAssets?: Parameters<typeof buildCompositionNarrativeScenes>[0];
  manualSourceInsertion?: boolean;
  preassemblyVersion?: string;
  narrativeScenes?: CompositionNarrativeScene[];
  animatedDeck: ReturnType<typeof extractHyperframesAnimatedDeck>;
  assets: Parameters<typeof createInitialCompositionDocument>[0]["assets"];
  compositionName: string;
  deckDependencyAssetIds: Set<string>;
  draftId: string;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
  userId: string;
}) {
  try {
    const current = await getCurrentCompositionDocument(params);
    const preserveDeckSources = Boolean(params.generatedComponentId || current.document.htmlEditing?.items.length);
    if (preserveDeckSources && params.preassemblyVersion) {
      throw new HyperframesDraftError("El reensamble de diapositivas editables requiere conservar sus fuentes registradas. No se ha modificado el borrador.", 409);
    }
    if (params.preassemblyVersion) {
      if (params.preassemblyVersion !== current.documentHash) throw new CompositionDocumentConflictError(current);
      if (!canPreassembleScenes(params.narrativeScenes, params.assets)) {
        throw new HyperframesDraftError("Revisa las asociaciones de todas las escenas y espera a que sus audios o avatares estén listos antes de aplicar el preensamble.", 422);
      }
      if (current.document.tracks.some((track) => track.kind === "DECK" && track.locked)) {
        throw new HyperframesDraftError("Desbloquea la pista de slides antes de aplicar el preensamble.", 422);
      }
    }
    const operations = buildProductionAssetReconciliationOperations(
      params.manualSourceInsertion ? { ...current.document, sourceInsertionMode: "MANUAL" } : current.document,
      params.assets,
      params.deckDependencyAssetIds,
      // An existing draft is not an implicit migration target, even when its
      // Production material has since been regenerated with editorial fields.
      preserveDeckSources ? null : params.animatedDeck,
      preserveDeckSources ? undefined : params.narrativeScenes,
      Boolean(params.preassemblyVersion),
    );
    if (params.manualSourceInsertion && current.document.sourceInsertionMode !== "MANUAL" && operations.length === 0) {
      operations.push({ type: "document.reconcile", document: { ...current.document, sourceInsertionMode: "MANUAL" } });
    }
    if (operations.length === 0) {
      return { created: false, document: current.document, version: current.version };
    }

    try {
      const updated = await applyAndAppendCompositionDocumentPatches({
        auditSource: "SYSTEM",
        draftId: params.draftId,
        expectedDocumentHash: current.documentHash,
        organizationId: params.organizationId,
        patch: {
          operations,
          source: "AGENT",
          summary: `Sincronizó ${operations.length} cambio(s) de assets desde Producción.`,
        },
        supabase: params.supabase,
        userId: params.userId,
      });
      return { created: false, document: updated.document, version: updated.version };
    } catch (error) {
      if (error instanceof CompositionDocumentConflictError) {
        const latest = await getCurrentCompositionDocument(params);
        return { created: false, document: latest.document, version: latest.version };
      }
      throw error;
    }
  } catch (error) {
    if (!(error instanceof CompositionDocumentError) || error.status !== 404) throw error;
  }

  const verified = params.generatedComponentId && !params.manualSourceInsertion ? await readGeneratedCourseDeckEditorial({
    componentId: params.generatedComponentId, organizationId: params.organizationId, supabase: params.supabase,
  }).catch((error: unknown) => {
    if (error instanceof GeneratedDeckReadError && error.code === "FONT_BINDING_REQUIRED")
      throw new HyperframesDraftError(GENERATED_DECK_FONT_UNAVAILABLE_MESSAGE, 422);
    throw error;
  }) : null;
  if (params.generatedComponentId && !params.manualSourceInsertion && !verified) throw new GeneratedDeckReadError("UNAVAILABLE");
  if (verified && !verified.fontBindings) {
    throw new HyperframesDraftError(GENERATED_DECK_FONT_UNAVAILABLE_MESSAGE, 422);
  }
  if (verified && params.animatedDeck?.slides.some(slide => slide.htmlAssetId)) {
    throw new HyperframesDraftError("Esta composición mezcla HTML importado con diapositivas generadas. Requiere una importación editorial explícita; no se omitirán fuentes existentes.", 422);
  }
  const initialDeck = verified ? generatedDeckInitialSource(verified) : params.animatedDeck;
  const initialNarrative = verified && params.narrativeAssets ? buildCompositionNarrativeScenes(params.narrativeAssets,
    buildSceneVisualCatalog(verified.presentationSource())) : params.narrativeScenes;
  const plan = buildDeterministicPlan({ assetCount: params.assets.length, title: params.compositionName });
  let document;
  try {
    document = createInitialCompositionDocument({
      ...(params.manualSourceInsertion ? { sourceInsertionMode: "MANUAL" as const } : {}),
      narrativeScenes: verified ? generatedDeckInitialNarrativeScenes(initialNarrative, verified) : params.narrativeScenes,
      animatedDeck: initialDeck,
      assets: params.assets,
      plan,
    });
    if (verified) document = instantiateGeneratedDeckDocument(document, verified);
  } catch (error) {
    if (error instanceof CompositionDurationResolutionError) {
      throw new HyperframesDraftError(error.message, 422);
    }
    throw error;
  }
  return ensureInitialCompositionDocument({
    document,
    draftId: params.draftId,
    organizationId: params.organizationId,
    supabase: params.supabase,
    userId: params.userId,
  });
}

async function findActiveDraft(params: {
  compositionId: string;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const { data, error } = await params.supabase
    .from("video_composition_drafts")
    .select("id, current_version")
    .eq("composition_id", params.compositionId)
    .eq("organization_id", params.organizationId)
    .neq("state", "ARCHIVED")
    .maybeSingle();
  if (error) throw error;
  return data;
}

/** Safe identifier exposed to the editor; it never contains a storage path. */
export function studioProjectDescriptor(draftId: string, version: number): StudioProjectDescriptor {
  if (!isUuid(draftId) || !Number.isInteger(version) || version < 1) {
    throw new HyperframesDraftError("Identidad de proyecto de edición inválida.");
  }
  return { draftId, projectId: draftId, version };
}

/** Shared guard for every future editor file route. */
export function assertSafeDraftRelativePath(relativePath: string) {
  const normalized = relativePath.trim().replace(/\\/g, "/");
  if (!normalized || normalized.startsWith("/") || normalized.includes("..") || normalized.includes("\0")) {
    throw new HyperframesDraftError("La ruta del proyecto de edición no es segura.");
  }
  return normalized;
}

/** Strong content version for optimistic file writes and conflict detection. */
export function contentVersion(content: Uint8Array | string) {
  return createHash("sha256").update(content).digest("hex");
}

function isUuid(value: string) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value);
}

function inferAssetRole(mimeType: string) {
  if (mimeType.startsWith("video/")) return "VIDEO";
  if (mimeType.startsWith("audio/")) return "AUDIO";
  if (mimeType.startsWith("font/")) return "FONT";
  return "IMAGE";
}

import type { SupabaseClient } from "@supabase/supabase-js";
import {
  PRODUCTION_ASSET_TYPES,
  PRODUCTION_JOB_STATUSES,
  PRODUCTION_JOB_TYPES,
  PRODUCTION_PROVIDERS,
  PRODUCTION_QA_STATUSES,
} from "../types/production.types";

const FINAL_VIDEO_BUCKET = "production-videos";

type FinalVideoRow = {
  id: string;
  public_url: string | null;
  storage_bucket: string | null;
  storage_path: string | null;
};

export class HyperframesFinalVideoDeletionError extends Error {
  constructor(
    message: string,
    readonly status = 409,
    readonly code = "HYPERFRAMES_FINAL_VIDEO_DELETE_FAILED",
  ) {
    super(message);
  }
}

/**
 * Removes the current HyperFrames final-video file for one composition only.
 * Ledger rows are archived rather than destroyed so render history remains
 * auditable, while recovery/publication stop treating older files as current.
 */
export class HyperframesFinalVideoDeletionService {
  constructor(
    private readonly supabase: SupabaseClient<any, "public", any>,
  ) {}

  async deleteLatestForComposition(params: {
    compositionId: string;
    expectedAssetId: string;
    organizationId: string;
  }) {
    const { data: composition, error: compositionError } = await this.supabase
      .from("video_compositions")
      .select("artifact_id, material_component_id")
      .eq("id", params.compositionId)
      .eq("organization_id", params.organizationId)
      .maybeSingle();
    if (compositionError) throw compositionError;
    if (!composition?.material_component_id || !composition.artifact_id) {
      throw new HyperframesFinalVideoDeletionError(
        "La composición no está vinculada a una lección editable.",
        404,
        "HYPERFRAMES_COMPOSITION_COMPONENT_NOT_FOUND",
      );
    }

    const componentId = String(composition.material_component_id);
    const artifactId = String(composition.artifact_id);
    await this.assertNoActiveRender({
      componentId,
      organizationId: params.organizationId,
    });

    const { data: latest, error: latestError } = await this.supabase
      .from("production_assets")
      .select("id, public_url, storage_bucket, storage_path")
      .eq("organization_id", params.organizationId)
      .eq("material_component_id", componentId)
      .eq("asset_type", PRODUCTION_ASSET_TYPES.FINAL_VIDEO)
      .eq("provider", PRODUCTION_PROVIDERS.HYPERFRAMES)
      .neq("qa_status", PRODUCTION_QA_STATUSES.ARCHIVED)
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();
    if (latestError) throw latestError;
    if (!latest) {
      throw new HyperframesFinalVideoDeletionError(
        "Esta lección ya no tiene un video final de HyperFrames para eliminar.",
        404,
        "HYPERFRAMES_FINAL_VIDEO_NOT_FOUND",
      );
    }

    const video = latest as FinalVideoRow;
    if (video.id !== params.expectedAssetId) {
      throw new HyperframesFinalVideoDeletionError(
        "El video final cambió desde que abriste el editor. Actualiza antes de eliminarlo.",
        409,
        "HYPERFRAMES_FINAL_VIDEO_CHANGED",
      );
    }

    const { data: component, error: componentError } = await this.supabase
      .from("material_components")
      .select("assets")
      .eq("id", componentId)
      .maybeSingle();
    if (componentError) throw componentError;
    if (!component) {
      throw new HyperframesFinalVideoDeletionError(
        "No se encontró el componente de la lección.",
        404,
        "HYPERFRAMES_COMPONENT_NOT_FOUND",
      );
    }

    const nextAssets = removeHyperframesFinalVideoProjection(
      (component.assets || {}) as Record<string, unknown>,
      video,
    );
    const currentAssets = (component.assets || {}) as Record<string, unknown>;
    const assetsPatch = buildTopLevelAssetsPatch(currentAssets, nextAssets);
    const { error: componentUpdateError } = await this.supabase.rpc(
      "patch_material_component_assets",
      { p_component_id: componentId, p_assets_patch: assetsPatch },
    );
    if (componentUpdateError) throw componentUpdateError;

    const objectPath = resolveFinalVideoObjectPath({
      artifactId,
      componentId,
      organizationId: params.organizationId,
      storageBucket: video.storage_bucket,
      storagePath: video.storage_path,
    });
    if (objectPath) {
      const { error: storageError } = await this.supabase.storage
        .from(FINAL_VIDEO_BUCKET)
        .remove([objectPath]);
      if (storageError) {
        throw new HyperframesFinalVideoDeletionError(
          "Se retiró el video de publicación, pero no se pudo borrar su archivo de Storage.",
          502,
          "HYPERFRAMES_FINAL_VIDEO_STORAGE_DELETE_FAILED",
        );
      }
    }

    const { error: archiveError } = await this.supabase
      .from("production_assets")
      .update({
        qa_status: PRODUCTION_QA_STATUSES.ARCHIVED,
        updated_at: new Date().toISOString(),
      })
      .eq("organization_id", params.organizationId)
      .eq("material_component_id", componentId)
      .eq("asset_type", PRODUCTION_ASSET_TYPES.FINAL_VIDEO)
      .eq("provider", PRODUCTION_PROVIDERS.HYPERFRAMES)
      .neq("qa_status", PRODUCTION_QA_STATUSES.ARCHIVED);
    if (archiveError) throw archiveError;

    return {
      archivedAssetId: video.id,
      componentId,
      deletedFromStorage: Boolean(objectPath),
    };
  }

  private async assertNoActiveRender(params: {
    componentId: string;
    organizationId: string;
  }) {
    const { data, error } = await this.supabase
      .from("production_jobs")
      .select("id")
      .eq("organization_id", params.organizationId)
      .eq("material_component_id", params.componentId)
      .eq("job_type", PRODUCTION_JOB_TYPES.HYPERFRAMES_RENDER)
      .eq("provider", PRODUCTION_PROVIDERS.HYPERFRAMES)
      .in("status", [
        PRODUCTION_JOB_STATUSES.PENDING,
        PRODUCTION_JOB_STATUSES.RUNNING,
        PRODUCTION_JOB_STATUSES.WAITING_PROVIDER,
        PRODUCTION_JOB_STATUSES.RETRY_SCHEDULED,
      ])
      .limit(1)
      .maybeSingle();
    if (error) throw error;
    if (data) {
      throw new HyperframesFinalVideoDeletionError(
        "Espera a que termine el render activo antes de eliminar el video anterior.",
        409,
        "HYPERFRAMES_RENDER_ACTIVE",
      );
    }
  }
}

function buildTopLevelAssetsPatch(
  currentAssets: Record<string, unknown>,
  nextAssets: Record<string, unknown>,
) {
  const patch: Record<string, unknown> = {};
  const keys = new Set([...Object.keys(currentAssets), ...Object.keys(nextAssets)]);
  for (const key of keys) {
    if (!(key in nextAssets)) {
      patch[key] = null;
    } else if (JSON.stringify(currentAssets[key]) !== JSON.stringify(nextAssets[key])) {
      patch[key] = nextAssets[key] ?? null;
    }
  }
  return patch;
}

export function removeHyperframesFinalVideoProjection(
  currentAssets: Record<string, unknown>,
  video: Pick<FinalVideoRow, "public_url" | "storage_path">,
) {
  const isHyperframesProjection = currentAssets.final_video_source === "hyperframes_cloud"
    || currentAssets.final_video_asset_provider === PRODUCTION_PROVIDERS.HYPERFRAMES
    || currentAssets.final_video_url === video.public_url
    || currentAssets.final_video_storage_path === video.storage_path;
  if (!isHyperframesProjection) return currentAssets;

  const {
    final_video_asset_provider: _assetProvider,
    final_video_file_name: _fileName,
    final_video_source: _source,
    final_video_storage_path: _storagePath,
    final_video_url: _url,
    video_duration: _duration,
    ...preserved
  } = currentAssets;
  return {
    ...preserved,
    production_status: "PENDING",
    updated_at: new Date().toISOString(),
  };
}

export function resolveFinalVideoObjectPath(params: {
  artifactId: string;
  componentId: string;
  organizationId: string;
  storageBucket: string | null;
  storagePath: string | null;
}) {
  if (!params.storagePath) return null;
  if (params.storageBucket !== FINAL_VIDEO_BUCKET) {
    throw new HyperframesFinalVideoDeletionError(
      "El video final no pertenece al bucket administrado por HyperFrames.",
      409,
      "HYPERFRAMES_FINAL_VIDEO_BUCKET_INVALID",
    );
  }
  const path = params.storagePath.startsWith(`${FINAL_VIDEO_BUCKET}/`)
    ? params.storagePath.slice(FINAL_VIDEO_BUCKET.length + 1)
    : params.storagePath;
  const expectedPrefix = [
    "organizations",
    params.organizationId,
    "artifacts",
    params.artifactId,
    "components",
    params.componentId,
    "renders",
  ].join("/") + "/";
  if (
    !path.startsWith(expectedPrefix)
    || path.startsWith("/")
    || path.includes("..")
    || path.includes("\\")
  ) {
    throw new HyperframesFinalVideoDeletionError(
      "La ruta del video final no es segura para eliminarse.",
      409,
      "HYPERFRAMES_FINAL_VIDEO_PATH_INVALID",
    );
  }
  return path;
}

import type { SupabaseClient } from "@supabase/supabase-js";
import type { MaterialAssets } from "../../materials/types/materials.types";
import {
  PRODUCTION_ASSET_TYPES,
  PRODUCTION_QA_STATUSES,
  PRODUCTION_PROVIDERS,
} from "../types/production.types";

interface DurableFinalVideoRow {
  created_at: string;
  duration_seconds: number | null;
  id: string;
  material_component_id: string;
  production_job_id: string | null;
  public_url: string;
  storage_path: string | null;
}

interface RenderRevisionRow {
  composition_revision_id: string;
  production_job_id: string;
}

export interface HyperframesDurableFinalVideo {
  assetId: string;
  compositionRevisionId: string | null;
  createdAt: string;
  durationSeconds: number | null;
  productionJobId: string | null;
  publicUrl: string;
  storagePath: string | null;
}

/**
 * Reads imported HyperFrames videos from the append-only production ledger.
 * `material_components.assets` remains a UI projection and must not be the only
 * source used by recovery or publication flows.
 */
export class HyperframesFinalVideoService {
  constructor(
    private readonly supabase: SupabaseClient<any, "public", any>,
  ) {}

  async findLatestForComponent(params: {
    componentId: string;
    organizationId: string;
  }): Promise<HyperframesDurableFinalVideo | null> {
    const videos = await this.findLatestByComponentIds({
      componentIds: [params.componentId],
      organizationId: params.organizationId,
    });
    return videos.get(params.componentId) || null;
  }

  async findLatestByComponentIds(params: {
    componentIds: string[];
    organizationId: string;
  }): Promise<Map<string, HyperframesDurableFinalVideo>> {
    const componentIds = [...new Set(params.componentIds.filter(Boolean))];
    if (componentIds.length === 0) return new Map();

    const { data, error } = await this.supabase
      .from("production_assets")
      .select(
        "id, material_component_id, production_job_id, public_url, storage_path, duration_seconds, created_at",
      )
      .eq("organization_id", params.organizationId)
      .eq("asset_type", PRODUCTION_ASSET_TYPES.FINAL_VIDEO)
      .eq("provider", PRODUCTION_PROVIDERS.HYPERFRAMES)
      .neq("qa_status", PRODUCTION_QA_STATUSES.ARCHIVED)
      .in("material_component_id", componentIds)
      .not("public_url", "is", null)
      .order("created_at", { ascending: false });
    if (error) throw error;

    const latestRows = new Map<string, DurableFinalVideoRow>();
    for (const row of (data || []) as DurableFinalVideoRow[]) {
      if (!latestRows.has(row.material_component_id)) {
        latestRows.set(row.material_component_id, row);
      }
    }

    const productionJobIds = [...new Set(
      [...latestRows.values()]
        .map((row) => row.production_job_id)
        .filter((id): id is string => Boolean(id)),
    )];
    const revisionByJobId = new Map<string, string>();
    if (productionJobIds.length > 0) {
      const { data: requests, error: requestsError } = await this.supabase
        .from("hyperframes_render_requests")
        .select("production_job_id, composition_revision_id")
        .eq("organization_id", params.organizationId)
        .in("production_job_id", productionJobIds);
      if (requestsError) throw requestsError;
      for (const request of (requests || []) as RenderRevisionRow[]) {
        revisionByJobId.set(
          request.production_job_id,
          request.composition_revision_id,
        );
      }
    }

    return new Map(
      [...latestRows.entries()].map(([componentId, row]) => [
        componentId,
        {
          assetId: row.id,
          compositionRevisionId: row.production_job_id
            ? revisionByJobId.get(row.production_job_id) || null
            : null,
          createdAt: row.created_at,
          durationSeconds: row.duration_seconds,
          productionJobId: row.production_job_id,
          publicUrl: row.public_url,
          storagePath: row.storage_path,
        },
      ]),
    );
  }
}

/**
 * Rehydrates only HyperFrames-managed final-video fields. User-provided manual
 * links remain authoritative and are never replaced by a provider asset.
 */
export function mergeDurableFinalVideoIntoAssets(
  currentAssets: MaterialAssets | null | undefined,
  video: HyperframesDurableFinalVideo | null | undefined,
): MaterialAssets {
  const assets = { ...(currentAssets || {}) } as MaterialAssets;
  if (!video) return assets;

  const hasManualFinalVideo = Boolean(assets.final_video_url)
    && assets.final_video_source !== "hyperframes_cloud"
    && assets.final_video_asset_provider !== PRODUCTION_PROVIDERS.HYPERFRAMES;
  if (hasManualFinalVideo) return assets;

  return {
    ...assets,
    final_video_asset_provider: PRODUCTION_PROVIDERS.HYPERFRAMES,
    final_video_source: "hyperframes_cloud",
    final_video_storage_path: video.storagePath || undefined,
    final_video_url: video.publicUrl,
    production_status: "COMPLETED",
    video_duration: video.durationSeconds || undefined,
  };
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";
import { VIDEO_STUDIO_MODEL_IDS } from "./video-studio-model-options";

export const hyperframesGenerationSettingsSchema = z.object({
  agentAssistedGenerationEnabled: z.boolean().default(true),
  agentModel: z.enum(VIDEO_STUDIO_MODEL_IDS),
  automaticGenerationEnabled: z.boolean().default(true),
  fallbackModel: z.enum(VIDEO_STUDIO_MODEL_IDS).nullable().default(null),
  temperature: z.number().min(0).max(2).default(0.3),
}).strict().superRefine((settings, context) => {
  if (settings.fallbackModel === settings.agentModel) {
    context.addIssue({
      code: "custom",
      message: "El modelo de respaldo debe ser distinto del modelo principal.",
      path: ["fallbackModel"],
    });
  }
});

export type HyperframesGenerationSettings = z.infer<typeof hyperframesGenerationSettingsSchema>;

export const DEFAULT_HYPERFRAMES_GENERATION_SETTINGS: HyperframesGenerationSettings = {
  agentAssistedGenerationEnabled: true,
  agentModel: "gemini-3.5-flash",
  automaticGenerationEnabled: true,
  fallbackModel: null,
  temperature: 0.3,
};

export async function getHyperframesGenerationSettings(params: {
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const { data, error } = await params.supabase
    .from("video_composition_generation_settings")
    .select("agent_model, fallback_model, temperature, automatic_generation_enabled, agent_assisted_generation_enabled")
    .eq("organization_id", params.organizationId)
    .maybeSingle();
  if (error) throw error;
  if (!data) return DEFAULT_HYPERFRAMES_GENERATION_SETTINGS;
  return mapSettingsRow(data);
}

export async function saveHyperframesGenerationSettings(params: {
  organizationId: string;
  settings: HyperframesGenerationSettings;
  supabase: SupabaseClient<any, "public", any>;
  updatedBy: string;
}) {
  const now = new Date().toISOString();
  const { data, error } = await params.supabase
    .from("video_composition_generation_settings")
    .upsert({
      agent_assisted_generation_enabled: params.settings.agentAssistedGenerationEnabled,
      agent_model: params.settings.agentModel,
      automatic_generation_enabled: params.settings.automaticGenerationEnabled,
      fallback_model: params.settings.fallbackModel || null,
      organization_id: params.organizationId,
      temperature: params.settings.temperature,
      updated_at: now,
      updated_by: params.updatedBy,
    }, { onConflict: "organization_id" })
    .select("agent_model, fallback_model, temperature, automatic_generation_enabled, agent_assisted_generation_enabled")
    .single();
  if (error) throw error;
  return mapSettingsRow(data);
}

function mapSettingsRow(row: Record<string, unknown>): HyperframesGenerationSettings {
  const agentModel = typeof row.agent_model === "string" && VIDEO_STUDIO_MODEL_IDS.includes(row.agent_model as typeof VIDEO_STUDIO_MODEL_IDS[number])
    ? row.agent_model
    : DEFAULT_HYPERFRAMES_GENERATION_SETTINGS.agentModel;
  const fallbackModel = typeof row.fallback_model === "string"
    && row.fallback_model !== agentModel
    && VIDEO_STUDIO_MODEL_IDS.includes(row.fallback_model as typeof VIDEO_STUDIO_MODEL_IDS[number])
    ? row.fallback_model
    : null;
  return hyperframesGenerationSettingsSchema.parse({
    agentAssistedGenerationEnabled: row.agent_assisted_generation_enabled,
    agentModel,
    automaticGenerationEnabled: row.automatic_generation_enabled,
    fallbackModel,
    temperature: Number(row.temperature),
  });
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { sanitizeRenderDiagnostic, type HyperframesRenderDiagnostics, type RenderDiagnosticEvent } from "./hyperframes-render-diagnostics";

export class HyperframesRenderDiagnosticsService {
  constructor(private readonly supabase: SupabaseClient<any, "public", any>) {}

  async read(organizationId: string, requestId: string): Promise<HyperframesRenderDiagnostics | null> {
    const { data: request, error } = await this.supabase.from("hyperframes_render_requests")
      .select("id, production_job_id, provider_render_id, provider_status, import_status, provider_error, created_at, updated_at, archive_size_bytes, cancelled_at, diagnostic_events")
      .eq("id", requestId).eq("organization_id", organizationId).maybeSingle();
    if (error) throw error;
    if (!request) return null;
    const [{ data: job, error: jobError }, { data: imports, error: importError }] = await Promise.all([
      this.supabase.from("production_jobs")
        .select("id, status, progress, provider_error, completed_at, failed_at, updated_at")
        .eq("id", request.production_job_id).eq("organization_id", organizationId).maybeSingle(),
      this.supabase.rpc("get_hyperframes_import_diagnostics", { p_request_id: requestId, p_organization_id: organizationId }),
    ]);
    if (jobError) throw jobError;
    if (importError) throw importError;
    if (!job) throw new Error("No se encontró el trabajo de render.");
    const transfer = imports?.[0];
    const events: RenderDiagnosticEvent[] = [{ at: request.created_at, level: "info", stage: "created", message: "Solicitud registrada" }];
    for (const entry of Array.isArray(job.progress) ? job.progress : []) {
      if (!entry || typeof entry.at !== "string" || typeof entry.stage !== "string") continue;
      events.push({ at: entry.at, level: entry.stage.includes("fail") ? "error" : "info", stage: sanitizeRenderDiagnostic(entry.stage),
        message: sanitizeRenderDiagnostic(entry.stage) });
    }
    for (const entry of Array.isArray(request.diagnostic_events) ? request.diagnostic_events : []) {
      if (!entry || typeof entry.at !== "string") continue;
      events.push({ at: entry.at, level: entry.error ? "error" : "info", stage: sanitizeRenderDiagnostic(entry.stage),
        message: sanitizeRenderDiagnostic(entry.error?.message || entry.stage) });
    }
    const lastError = request.provider_error || job.provider_error;
    const errorMessage = sanitizeRenderDiagnostic(lastError?.message) || null;
    if (errorMessage) events.push({ at: request.updated_at, level: "error", stage: sanitizeRenderDiagnostic(lastError?.source), message: errorMessage });
    events.sort((a, b) => Date.parse(a.at) - Date.parse(b.at));
    return {
      requestId, jobId: job.id, providerRenderId: request.provider_render_id,
      providerStatus: request.provider_status, importStatus: request.import_status, jobStatus: job.status,
      createdAt: request.created_at, updatedAt: request.updated_at,
      finishedAt: request.cancelled_at || job.completed_at || job.failed_at || null,
      cancelledAt: request.cancelled_at, archiveSizeBytes: request.archive_size_bytes,
      uploadedBytes: transfer?.uploaded_bytes || 0, sourceSizeBytes: transfer?.source_size_bytes || null,
      attempts: transfer?.attempt_count || 0, failures: transfer?.failure_count || 0,
      nextAttemptAt: transfer?.next_attempt_at || null,
      lastActivityAt: transfer?.updated_at || job.updated_at || request.updated_at,
      events: events.slice(-100), error: errorMessage,
    };
  }

  async cancel(organizationId: string, requestId: string): Promise<string | null> {
    const { data, error } = await this.supabase.rpc("cancel_hyperframes_render", {
      p_organization_id: organizationId, p_request_id: requestId,
    });
    if (error) throw error;
    return data;
  }
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { compositionConformanceContractSchema } from "../composition-editor/composition-preview-render-conformance";

type RenderRequest = {
  id: string;
  organization_id: string;
  production_job_id: string;
  composition_revision_id: string;
  provider_render_id: string | null;
  provider_status: string;
  import_status: string;
};
type RenderJob = {
  id: string;
  organization_id: string;
  status: string;
  input_snapshot: Record<string, unknown> | null;
  output_snapshot: Record<string, unknown> | null;
};
type RenderRevision = {
  id: string;
  organization_id: string;
  project_hash: string;
  manifest: Record<string, unknown> | null;
};
type FinalVideoAsset = {
  id: string;
  organization_id: string;
  production_job_id: string;
  provider: string;
  asset_type: string;
  file_size_bytes: number | null;
  mime_type: string | null;
  metadata: Record<string, unknown> | null;
  storage_bucket: string | null;
  storage_path: string | null;
  checksum: string | null;
};

export type HyperframesRenderEvidence = {
  assetId: string | null;
  documentHash: string | null;
  failures: string[];
  finalVideoSha256: string | null;
  jobId: string;
  projectHash: string | null;
  providerRenderId: string | null;
  renderRequestId: string;
  revisionId: string;
  status: "LINEAGE_VERIFIED" | "INCOMPLETE";
};

/** Checks persisted lineage only. The TUS import does not yet attest video bytes. */
export function assessHyperframesRenderEvidence(input: {
  asset: FinalVideoAsset | null;
  job: RenderJob | null;
  organizationId: string;
  request: RenderRequest;
  revision: RenderRevision | null;
}): HyperframesRenderEvidence {
  const { asset, job, organizationId, request, revision } = input;
  const failures: string[] = [];
  const contract = compositionConformanceContractSchema.safeParse(revision?.manifest?.conformance_contract);
  if (request.organization_id !== organizationId) failures.push("request_tenant_mismatch");
  if (request.provider_status !== "COMPLETED" || request.import_status !== "COMPLETED") failures.push("render_not_completed");
  if (!request.provider_render_id) failures.push("provider_render_id_missing");
  if (!job || job.id !== request.production_job_id || job.organization_id !== organizationId || job.status !== "SUCCEEDED") {
    failures.push("job_mismatch");
  }
  if (!revision || revision.id !== request.composition_revision_id || revision.organization_id !== organizationId || !contract.success) {
    failures.push("revision_contract_mismatch");
  }
  if (revision && contract.success && revision.manifest?.draft_document_hash !== contract.data.documentHash) {
    failures.push("document_hash_mismatch");
  }
  if (revision && job && (job.input_snapshot?.revision_id !== revision.id || job.input_snapshot?.project_hash !== revision.project_hash)) {
    failures.push("job_revision_mismatch");
  }
  const expectedVideoPath = `production-videos/organizations/${organizationId}/artifacts/`;
  const expectedRenderSuffix = `/renders/${request.id}/final.mp4`;
  if (!asset || !job || asset.production_job_id !== job.id || asset.organization_id !== organizationId
    || asset.provider !== "hyperframes" || asset.asset_type !== "FINAL_VIDEO"
    || asset.metadata?.render_request_id !== request.id || asset.metadata?.provider_render_id !== request.provider_render_id
    || (job.output_snapshot?.final_video as Record<string, unknown> | undefined)?.asset_id !== asset.id
    || asset.storage_bucket !== "production-videos" || !asset.storage_path?.startsWith(expectedVideoPath)
    || !asset.storage_path.endsWith(expectedRenderSuffix)
    || asset.mime_type !== "video/mp4" || !asset.file_size_bytes || asset.file_size_bytes <= 0) {
    failures.push("final_asset_mismatch");
  }
  const hasVerifiedChecksum = Boolean(asset?.checksum && /^[a-f0-9]{64}$/.test(asset.checksum)
    && asset.metadata?.integrity_method === "storage-stream-sha256-v1");
  if (!hasVerifiedChecksum) {
    failures.push("final_video_checksum_missing");
  }
  return {
    assetId: asset?.id ?? null,
    documentHash: contract.success ? contract.data.documentHash : null,
    failures,
    finalVideoSha256: hasVerifiedChecksum ? asset!.checksum : null,
    jobId: request.production_job_id,
    projectHash: revision?.project_hash ?? null,
    providerRenderId: request.provider_render_id,
    renderRequestId: request.id,
    revisionId: request.composition_revision_id,
    status: failures.length === 0 ? "LINEAGE_VERIFIED" : "INCOMPLETE",
  };
}

export class HyperframesRenderEvidenceService {
  constructor(private readonly supabase: SupabaseClient<any, "public", any>) {}

  async read(organizationId: string, requestId: string): Promise<HyperframesRenderEvidence | null> {
    const { data: request, error: requestError } = await this.supabase.from("hyperframes_render_requests")
      .select("id, organization_id, production_job_id, composition_revision_id, provider_render_id, provider_status, import_status")
      .eq("id", requestId).eq("organization_id", organizationId).maybeSingle();
    if (requestError) throw requestError;
    if (!request) return null;
    const [jobResult, revisionResult, assetResult] = await Promise.all([
      this.supabase.from("production_jobs")
        .select("id, organization_id, status, input_snapshot, output_snapshot")
        .eq("id", request.production_job_id).eq("organization_id", organizationId).maybeSingle(),
      this.supabase.from("video_composition_revisions")
        .select("id, organization_id, project_hash, manifest")
        .eq("id", request.composition_revision_id).eq("organization_id", organizationId).maybeSingle(),
      this.supabase.from("production_assets")
        .select("id, organization_id, production_job_id, provider, asset_type, file_size_bytes, mime_type, metadata, storage_bucket, storage_path, checksum")
        .eq("production_job_id", request.production_job_id).eq("organization_id", organizationId)
        .eq("asset_type", "FINAL_VIDEO").maybeSingle(),
    ]);
    for (const result of [jobResult, revisionResult, assetResult]) if (result.error) throw result.error;
    return assessHyperframesRenderEvidence({
      asset: assetResult.data as FinalVideoAsset | null,
      job: jobResult.data as RenderJob | null,
      organizationId,
      request: request as RenderRequest,
      revision: revisionResult.data as RenderRevision | null,
    });
  }
}

import type { SupabaseClient } from "@supabase/supabase-js";
import {
  PRODUCTION_JOB_STATUSES,
  PRODUCTION_JOB_TYPES,
  PRODUCTION_PROVIDERS,
} from "../types/production.types";
import type { HyperframesCloudClient } from "./hyperframes-cloud.client";
import {
  decideHyperframesPollingAction,
  isUnsubmittedRenderStale,
} from "./hyperframes-polling.service";

type HyperframesRenderRequestRow = {
  import_status: string;
  cancelled_at: string | null;
  archive_size_bytes: number;
  composition_revision_id: string;
  id: string;
  poll_attempts: number;
  production_job_id: string;
  provider_render_id: string | null;
  provider_status: string;
  updated_at: string;
};

type HyperframesProductionJobRow = {
  artifact_id: string;
  created_by: string | null;
  id: string;
  material_component_id: string | null;
  organization_id: string | null;
  output_snapshot: Record<string, unknown> | null;
  progress: unknown[] | null;
};

export class HyperframesRenderPollingError extends Error {
  constructor(
    message: string,
    readonly status = 409,
  ) {
    super(message);
  }
}

export interface HyperframesPollResult {
  action: "WAIT" | "IMPORT_QUEUED" | "FAIL" | "CANCELLED" | "COMPLETED";
  providerStatus: string;
  requestId: string;
}

/**
 * Optional authenticated reconciliation nudge. Durable cron/webhook workers
 * remain authoritative; this endpoint never downloads or buffers the video.
 */
export class HyperframesRenderPollingService {
  constructor(
    private readonly supabase: SupabaseClient<any, "public", any>,
    private readonly client: HyperframesCloudClient,
  ) {}

  async poll(params: {
    organizationId: string;
    requestId: string;
  }): Promise<HyperframesPollResult> {
    const request = await this.getRequest(params);
    if (request.cancelled_at) return { action: "CANCELLED", providerStatus: request.provider_status, requestId: request.id };
    if (request.import_status === "COMPLETED") return { action: "COMPLETED", providerStatus: request.provider_status, requestId: request.id };
    if (request.provider_status === "FAILED" || request.import_status === "FAILED") return { action: "FAIL", providerStatus: request.provider_status, requestId: request.id };
    // Do not requeue imports or reset their backoff when the editor is reloaded.
    if (request.import_status && request.import_status !== "NONE") return { action: "IMPORT_QUEUED", providerStatus: request.provider_status, requestId: request.id };
    const job = await this.getJob({
      jobId: request.production_job_id,
      organizationId: params.organizationId,
    });

    if (!request.provider_render_id) {
      if (request.provider_status === "FAILED") {
        return {
          action: "FAIL",
          providerStatus: "FAILED",
          requestId: request.id,
        };
      }
      if (isUnsubmittedRenderStale(request.updated_at)) {
        const now = new Date().toISOString();
        await this.markFailed({
          errorMessage: "La carga no fue aceptada por HeyGen dentro de 10 minutos. Puedes reintentar el render.",
          jobId: job.id,
          pollAttempts: request.poll_attempts + 1,
          providerStatus: "FAILED",
          requestId: request.id,
          updatedAt: now,
        });
        return {
          action: "FAIL",
          providerStatus: "FAILED",
          requestId: request.id,
        };
      }
      return {
        action: "WAIT",
        providerStatus: request.provider_status,
        requestId: request.id,
      };
    }
    if (!job.material_component_id || !job.organization_id) {
      throw new HyperframesRenderPollingError(
        "El job de HyperFrames no tiene el contexto de componente requerido.",
      );
    }

    const render = await this.client.getRender(request.provider_render_id);
    const decision = decideHyperframesPollingAction(render);
    const now = new Date().toISOString();
    const providerStatus = toStoredProviderStatus(decision.providerStatus);

    if (decision.action === "WAIT") {
      await this.updateRequest({
        id: request.id,
        pollAttempts: request.poll_attempts + 1,
        providerError: null,
        providerStatus,
        updatedAt: now,
      });
      await this.updateJobWaiting({
        job,
        progressPercent: decision.progressPercent,
        providerRenderId: render.render_id,
        providerStatus: decision.providerStatus,
        updatedAt: now,
      });
      return {
        action: "WAIT",
        providerStatus: decision.providerStatus,
        requestId: request.id,
      };
    }

    if (decision.action === "FAIL") {
      await this.markFailed({
        errorMessage: decision.errorMessage || "El render de HyperFrames falló.",
        jobId: job.id,
        pollAttempts: request.poll_attempts + 1,
        providerStatus,
        requestId: request.id,
        updatedAt: now,
      });
      return {
        action: "FAIL",
        providerStatus: decision.providerStatus,
        requestId: request.id,
      };
    }

    const { error: queueError } = await this.supabase.rpc("queue_hyperframes_render_import", {
      p_provider_render_id: render.render_id,
      p_request_id: request.id,
    });
    if (queueError) throw queueError;
    return {
      action: "IMPORT_QUEUED",
      providerStatus: decision.providerStatus,
      requestId: request.id,
    };
  }

  private async getRequest(params: { organizationId: string; requestId: string }) {
    const { data, error } = await this.supabase
      .from("hyperframes_render_requests")
      .select("id, production_job_id, composition_revision_id, archive_size_bytes, provider_render_id, provider_status, import_status, cancelled_at, poll_attempts, updated_at")
      .eq("id", params.requestId)
      .eq("organization_id", params.organizationId)
      .maybeSingle();
    if (error) throw error;
    if (!data) {
      throw new HyperframesRenderPollingError("Render HyperFrames no encontrado para esta empresa.", 404);
    }
    return data as HyperframesRenderRequestRow;
  }

  private async getJob(params: { jobId: string; organizationId: string }) {
    const { data, error } = await this.supabase
      .from("production_jobs")
      .select("id, artifact_id, material_component_id, organization_id, created_by, output_snapshot, progress")
      .eq("id", params.jobId)
      .eq("organization_id", params.organizationId)
      .eq("job_type", PRODUCTION_JOB_TYPES.HYPERFRAMES_RENDER)
      .eq("provider", PRODUCTION_PROVIDERS.HYPERFRAMES)
      .maybeSingle();
    if (error) throw error;
    if (!data) {
      throw new HyperframesRenderPollingError("Job de HyperFrames no encontrado para esta empresa.", 404);
    }
    return data as HyperframesProductionJobRow;
  }

  private async updateRequest(params: {
    id: string;
    pollAttempts: number;
    providerError: Record<string, unknown> | null;
    providerStatus: string;
    updatedAt: string;
  }) {
    const { error } = await this.supabase
      .from("hyperframes_render_requests")
      .update({
        last_polled_at: params.updatedAt,
        poll_attempts: params.pollAttempts,
        provider_error: params.providerError,
        provider_status: params.providerStatus,
        updated_at: params.updatedAt,
      })
      .eq("id", params.id);
    if (error) throw error;
  }

  private async updateJobWaiting(params: {
    job: HyperframesProductionJobRow;
    progressPercent: number | null;
    providerRenderId: string;
    providerStatus: string;
    updatedAt: string;
  }) {
    const { error } = await this.supabase
      .from("production_jobs")
      .update({
        output_snapshot: {
          ...(params.job.output_snapshot || {}),
          provider_render_id: params.providerRenderId,
          provider_status: params.providerStatus,
        },
        progress: appendProgress(params.job.progress, params.progressPercent, params.providerStatus, params.updatedAt),
        provider_job_id: params.providerRenderId,
        status: PRODUCTION_JOB_STATUSES.WAITING_PROVIDER,
        updated_at: params.updatedAt,
      })
      .eq("id", params.job.id);
    if (error) throw error;
  }


  private async markFailed(params: {
    errorMessage: string;
    jobId: string;
    pollAttempts: number;
    providerStatus: string;
    requestId: string;
    updatedAt: string;
  }) {
    const providerError = { message: params.errorMessage, source: "hyperframes_polling" };
    await this.updateRequest({
      id: params.requestId,
      pollAttempts: params.pollAttempts,
      providerError,
      providerStatus: params.providerStatus,
      updatedAt: params.updatedAt,
    });
    const { error } = await this.supabase
      .from("production_jobs")
      .update({
        failed_at: params.updatedAt,
        provider_error: providerError,
        status: PRODUCTION_JOB_STATUSES.FAILED,
        updated_at: params.updatedAt,
      })
      .eq("id", params.jobId);
    if (error) throw error;
  }
}

function appendProgress(
  existing: unknown[] | null,
  percent: number | null,
  stage: string,
  at: string,
) {
  const entries = Array.isArray(existing) ? existing.slice(-49) : [];
  return [...entries, { at, percent, stage }];
}

function toStoredProviderStatus(status: string) {
  if (status === "queued") return "PENDING";
  if (status === "rendering") return "RUNNING";
  return status.toUpperCase();
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { sanitizeRenderDiagnostic } from "./hyperframes-render-diagnostics";
import {
  PRODUCTION_JOB_STATUSES,
  PRODUCTION_JOB_TYPES,
  PRODUCTION_PROVIDERS,
} from "../types/production.types";
import {
  HyperframesFinalVideoService,
  type HyperframesDurableFinalVideo,
} from "./hyperframes-final-video.service";

interface RecoverableProductionJob {
  id: string;
  status: string;
}

interface RecoverableRenderRequestRow {
  cancelled_at?: string | null;
  provider_error?: { message?: string } | null;
  composition_revision_id: string;
  id: string;
  import_status: string;
  provider_render_id: string | null;
  provider_status: string;
}

export interface RecoverableHyperframesRender {
  cancelledAt?: string | null;
  providerError?: string | null;
  compositionRevisionId: string;
  id: string;
  providerRenderId: string | null;
  providerStatus: string;
  importStatus: string;
}

export interface HyperframesCompositionRenderState {
  activeRender: RecoverableHyperframesRender | null;
  completedVideo: HyperframesDurableFinalVideo | null;
  latestRender: RecoverableHyperframesRender | null;
}

/**
 * Reads the latest attempt and the latest imported asset independently. A
 * failed attempt must never hide a previously imported, publishable video.
 * Every lookup is scoped to the active organization before service-role data
 * is returned to an authenticated route.
 */
export class HyperframesRenderRecoveryService {
  constructor(
    private readonly supabase: SupabaseClient<any, "public", any>,
  ) {}

  async findById(params: {
    organizationId: string;
    requestId: string;
  }): Promise<RecoverableHyperframesRender | null> {
    const { data, error } = await this.supabase
      .from("hyperframes_render_requests")
      .select(
        "id, composition_revision_id, import_status, provider_render_id, provider_status, cancelled_at, provider_error",
      )
      .eq("id", params.requestId)
      .eq("organization_id", params.organizationId)
      .maybeSingle();
    if (error) throw error;
    return toRecoverableRender(data as RecoverableRenderRequestRow | null);
  }

  async findLatestForComposition(params: {
    compositionId: string;
    organizationId: string;
  }): Promise<HyperframesCompositionRenderState | null> {
    const { data: composition, error: compositionError } = await this.supabase
      .from("video_compositions")
      .select("material_component_id")
      .eq("id", params.compositionId)
      .eq("organization_id", params.organizationId)
      .maybeSingle();
    if (compositionError) throw compositionError;

    const componentId = (composition as {
      material_component_id?: string | null;
    } | null)?.material_component_id;
    if (!componentId) return null;

    const { data: job, error: jobError } = await this.supabase
      .from("production_jobs")
      .select("id, status")
      .eq("organization_id", params.organizationId)
      .eq("material_component_id", componentId)
      .eq("job_type", PRODUCTION_JOB_TYPES.HYPERFRAMES_RENDER)
      .eq("provider", PRODUCTION_PROVIDERS.HYPERFRAMES)
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();
    if (jobError) throw jobError;

    const latestJob = job as RecoverableProductionJob | null;
    let latestRender: RecoverableHyperframesRender | null = null;
    if (latestJob?.id) {
      const { data: request, error: requestError } = await this.supabase
        .from("hyperframes_render_requests")
        .select(
          "id, composition_revision_id, import_status, provider_render_id, provider_status, cancelled_at, provider_error",
        )
        .eq("organization_id", params.organizationId)
        .eq("production_job_id", latestJob.id)
        .maybeSingle();
      if (requestError) throw requestError;
      latestRender = toRecoverableRender(
        request as RecoverableRenderRequestRow | null,
      );
    }

    const activeStatuses = new Set<string>([
      PRODUCTION_JOB_STATUSES.PENDING,
      PRODUCTION_JOB_STATUSES.WAITING_PROVIDER,
      PRODUCTION_JOB_STATUSES.RUNNING,
      PRODUCTION_JOB_STATUSES.RETRY_SCHEDULED,
    ]);
    const completedVideo = await new HyperframesFinalVideoService(this.supabase)
      .findLatestForComponent({
        componentId,
        organizationId: params.organizationId,
      });

    return {
      activeRender: latestJob && activeStatuses.has(latestJob.status)
        ? latestRender
        : null,
      completedVideo,
      latestRender,
    };
  }
}

function toRecoverableRender(
  row: RecoverableRenderRequestRow | null,
): RecoverableHyperframesRender | null {
  if (!row) return null;
  return {
    ...(row.cancelled_at !== undefined ? { cancelledAt: row.cancelled_at } : {}),
    ...(row.provider_error !== undefined ? { providerError: sanitizeRenderDiagnostic(row.provider_error?.message) || null } : {}),
    compositionRevisionId: row.composition_revision_id,
    id: row.id,
    providerRenderId: row.provider_render_id,
    providerStatus: row.provider_status,
    importStatus: row.import_status,
  };
}

import { createHash, randomUUID } from "node:crypto";
import type { SupabaseClient } from "@supabase/supabase-js";
import { getErrorMessage } from "../../../lib/errors";
import {
  buildProductionIdempotencyKey,
  createOrReuseProductionJob,
  resolveProductionComponentContext,
} from "../jobs/production-jobs.service";
import {
  PRODUCTION_JOB_STATUSES,
  PRODUCTION_JOB_TYPES,
  PRODUCTION_PROVIDERS,
} from "../types/production.types";
import { HyperframesCloudClient } from "./hyperframes-cloud.client";
import { resolveHyperframesAssetVariables } from "./hyperframes-asset-delivery.service";
import { HYPERFRAMES_MEDIA_BINDING_VERSION, materializeHyperframesRenderMedia } from "./hyperframes-render-media.service";
import { validateHyperframesPreflight } from "./hyperframes-preflight.service";
import {
  HYPERFRAMES_ASSET_DELIVERY_MODES,
  HYPERFRAMES_COMPOSITION_FORMAT,
  hyperframesAssetManifestSchema,
  hyperframesRevisionManifestSchema,
  type HyperframesAssetManifestItem,
  type HyperframesAssetDeliveryMode,
} from "./hyperframes.types";
import { HYPERFRAMES_DURABLE_RENDER_PROFILE } from "./hyperframes-media-constraints";
import type { HyperframesRenderSettings } from "./hyperframes-render-profiles";
import { resolveHyperframesSnapshotRenderProfile } from "./hyperframes-request-validation";

const PROJECT_ARCHIVE_BUCKET = "production-assets";

/**
 * Both composition_id and active_revision_id connect these tables. PostgREST
 * therefore requires the intended FK name; a bare `video_compositions!inner`
 * fails with PGRST201 before a production job can be created.
 */
export const HYPERFRAMES_RENDER_REVISION_SELECT =
  "id, composition_id, format, entry_point, project_storage_bucket, project_storage_path, project_archive_size_bytes, project_hash, variables_values, manifest, video_compositions!video_composition_revisions_composition_id_fkey(organization_id, artifact_id, material_component_id, name, status, active_revision_id)";

type StoredComposition = {
  active_revision_id: string | null;
  artifact_id: string;
  material_component_id: string | null;
  name: string;
  organization_id: string;
  status: string;
};

type StoredRevision = {
  composition_id: string;
  entry_point: string;
  format: string;
  id: string;
  manifest: unknown;
  project_archive_size_bytes: number;
  project_hash: string;
  project_storage_bucket: string;
  project_storage_path: string;
  variables_values: Record<string, unknown> | null;
  video_compositions: StoredComposition | StoredComposition[] | null;
};

type StoredRevisionAsset = {
  file_size_bytes: number;
  mime_type: string;
  production_asset_id: string;
  source_checksum: string;
  source_storage_bucket?: string;
  source_storage_path: string;
};

type ExistingRequest = {
  callback_id: string;
  id: string;
  provider_asset_id: string | null;
  provider_render_id: string | null;
  provider_status: string;
};

type ActiveRender = {
  jobId: string;
  request: ExistingRequest | null;
};

export class HyperframesRenderSubmissionError extends Error {
  constructor(
    message: string,
    readonly status = 409,
  ) {
    super(message);
  }
}

export interface HyperframesRenderSubmissionInput {
  aspectRatio: "16:9" | "9:16" | "1:1";
  attemptId?: string;
  createdBy: string;
  deferProcessing?: boolean;
  format?: "mp4" | "webm" | "mov";
  fps?: number;
  organizationId: string;
  quality?: "draft" | "standard" | "high";
  resolution?: "1080p" | "4k";
  revisionId: string;
  title?: string;
}

export interface HyperframesRenderSubmissionResult {
  jobId: string;
  preflight: ReturnType<typeof validateHyperframesPreflight>;
  providerAssetId: string | null;
  providerRenderId: string | null;
  providerStatus: string;
  renderRequestId: string;
  reused: boolean;
}

/**
 * Creates a durable request before uploading to HeyGen. Repeating a request
 * while it is active reuses its idempotency key, while a terminal failure gets
 * a fresh attempt key so it can be retried against the same snapshot.
 */
export class HyperframesRenderSubmissionService {
  constructor(
    private readonly supabase: SupabaseClient<any, "public", any>,
    private readonly client?: HyperframesCloudClient,
  ) {}

  async submit(input: HyperframesRenderSubmissionInput): Promise<HyperframesRenderSubmissionResult> {
    assertCompatibleRenderOptions(input);
    const revision = await this.getRevision(input);
    const context = await this.resolveComponentContext(revision, input.organizationId);
    const assets = await this.getRevisionAssets(revision.id);
    const revisionContract = parseAndVerifyManifest(revision.manifest, assets);
    const manifest = revisionContract.assets;
    const effectiveInput = applyRevisionRenderProfile(input, revisionContract.renderProfile);
    if (revisionContract.aspectRatio && effectiveInput.aspectRatio !== revisionContract.aspectRatio) {
      throw new HyperframesRenderSubmissionError("El formato solicitado no coincide con el snapshot. Regenera el snapshot.", 409);
    }
    const declaredPreflight = validateHyperframesPreflight({
      archiveSizeBytes: revision.project_archive_size_bytes,
      assets: manifest,
      deliveryMode: revisionContract.deliveryMode,
      durationSeconds: revisionContract.durationSeconds,
      renderProfile: revisionContract.renderProfile,
    });
    assertPassingPreflight(declaredPreflight);

    const activeRender = await this.findActiveRender({
      componentId: context.componentId,
      organizationId: input.organizationId,
    });
    if (activeRender) {
      if (!activeRender.request) {
        throw new HyperframesRenderSubmissionError(
          "Este video ya tiene un render iniciándose. Espera unos segundos y actualiza el estado.",
        );
      }
      return {
        jobId: activeRender.jobId,
        preflight: declaredPreflight,
        providerAssetId: activeRender.request.provider_asset_id,
        providerRenderId: activeRender.request.provider_render_id,
        providerStatus: activeRender.request.provider_status,
        renderRequestId: activeRender.request.id,
        reused: true,
      };
    }

    const baseJobInput = {
      aspect_ratio: effectiveInput.aspectRatio,
      format: effectiveInput.format || "mp4",
      fps: effectiveInput.fps || HYPERFRAMES_DURABLE_RENDER_PROFILE.fps,
      project_hash: revision.project_hash,
      quality: effectiveInput.quality || HYPERFRAMES_DURABLE_RENDER_PROFILE.quality,
      resolution: effectiveInput.resolution || "1080p",
      revision_id: revision.id,
      asset_delivery_mode: revisionContract.deliveryMode,
      media_binding_version: HYPERFRAMES_MEDIA_BINDING_VERSION,
      variables: revision.variables_values || {},
    };
    const baseIdempotencyKey = buildProductionIdempotencyKey({
      componentId: context.componentId,
      input: baseJobInput,
      jobType: PRODUCTION_JOB_TYPES.HYPERFRAMES_RENDER,
      provider: PRODUCTION_PROVIDERS.HYPERFRAMES,
    });
    const attemptId = input.attemptId || (
      await this.hasFailedAttempt({
        idempotencyKey: baseIdempotencyKey,
        organizationId: input.organizationId,
      })
        ? randomUUID()
        : undefined
    );
    const jobInput = attemptId
      ? { ...baseJobInput, attempt_id: attemptId }
      : baseJobInput;
    const idempotencyKey = attemptId
      ? buildProductionIdempotencyKey({
          componentId: context.componentId,
          input: jobInput,
          jobType: PRODUCTION_JOB_TYPES.HYPERFRAMES_RENDER,
          provider: PRODUCTION_PROVIDERS.HYPERFRAMES,
        })
      : baseIdempotencyKey;
    let job: Awaited<ReturnType<typeof createOrReuseProductionJob>>;
    try {
      job = await createOrReuseProductionJob(this.supabase, {
        context,
        createdBy: input.createdBy,
        idempotencyKey,
        inputSnapshot: jobInput,
        jobType: PRODUCTION_JOB_TYPES.HYPERFRAMES_RENDER,
        provider: PRODUCTION_PROVIDERS.HYPERFRAMES,
        providerModel: HYPERFRAMES_COMPOSITION_FORMAT,
      });
    } catch (error) {
      // The database trigger is the final guard for two users submitting in
      // the same instant. Return the winner instead of surfacing a generic 500.
      const concurrentRender = await this.findActiveRender({
        componentId: context.componentId,
        organizationId: input.organizationId,
      });
      if (concurrentRender?.request) {
        return {
          jobId: concurrentRender.jobId,
          preflight: declaredPreflight,
          providerAssetId: concurrentRender.request.provider_asset_id,
          providerRenderId: concurrentRender.request.provider_render_id,
          providerStatus: concurrentRender.request.provider_status,
          renderRequestId: concurrentRender.request.id,
          reused: true,
        };
      }
      if (concurrentRender) {
        throw new HyperframesRenderSubmissionError(
          "Este video ya tiene un render iniciándose. Espera unos segundos y actualiza el estado.",
        );
      }
      throw error;
    }
    let request: ExistingRequest;
    try {
      request = await this.ensureRenderRequest({
        archiveSizeBytes: revision.project_archive_size_bytes,
        compositionRevisionId: revision.id,
        idempotencyKey,
        jobId: job.id,
        organizationId: input.organizationId,
      });
    } catch (error) {
      await this.markSubmissionFailed(job.id, null, error);
      throw error;
    }

    if (request.provider_render_id) {
      return {
        jobId: job.id,
        preflight: declaredPreflight,
        providerAssetId: request.provider_asset_id,
        providerRenderId: request.provider_render_id,
        providerStatus: request.provider_status,
        renderRequestId: request.id,
        reused: true,
      };
    }

    if (input.deferProcessing) {
      const providerStatus = request.provider_asset_id ? "SUBMITTING" : "UPLOADING";
      const claimed = await this.claimBackgroundDispatch({
        expectedStatus: request.provider_status,
        jobId: job.id,
        providerStatus,
        requestId: request.id,
      });
      return {
        jobId: job.id,
        preflight: declaredPreflight,
        providerAssetId: request.provider_asset_id,
        providerRenderId: null,
        providerStatus,
        renderRequestId: request.id,
        reused: !claimed,
      };
    }

    return this.processSubmission({
      input: effectiveInput,
      jobId: job.id,
      idempotencyKey,
      manifest,
      deliveryMode: revisionContract.deliveryMode,
      request,
      revision,
      preflight: declaredPreflight,
    });
  }

  async resume(params: { organizationId: string; requestId: string }) {
    const { data: storedRequest, error: requestError } = await this.supabase
      .from("hyperframes_render_requests")
      .select("id, organization_id, production_job_id, composition_revision_id, idempotency_key, callback_id, provider_asset_id, provider_render_id, provider_status")
      .eq("id", params.requestId)
      .eq("organization_id", params.organizationId)
      .maybeSingle();
    if (requestError) throw requestError;
    if (!storedRequest) {
      throw new HyperframesRenderSubmissionError("Solicitud de render no encontrada.", 404);
    }

    const request = storedRequest as ExistingRequest & {
      composition_revision_id: string;
      idempotency_key: string;
      production_job_id: string;
    };
    if (request.provider_render_id || request.provider_status === "FAILED") return;

    const { data: storedJob, error: jobError } = await this.supabase
      .from("production_jobs")
      .select("id, created_by, input_snapshot")
      .eq("id", request.production_job_id)
      .eq("organization_id", params.organizationId)
      .maybeSingle();
    if (jobError) throw jobError;
    if (!storedJob) throw new HyperframesRenderSubmissionError("Job de render no encontrado.", 404);

    const options = parseStoredRenderOptions(storedJob.input_snapshot);
    const input: HyperframesRenderSubmissionInput = {
      ...options,
      createdBy: String(storedJob.created_by || ""),
      organizationId: params.organizationId,
      revisionId: request.composition_revision_id,
    };
    const revision = await this.getRevision(input, false);
    const assets = await this.getRevisionAssets(revision.id);
    const revisionContract = parseAndVerifyManifest(revision.manifest, assets);
    const manifest = revisionContract.assets;
    const effectiveInput = applyRevisionRenderProfile(input, revisionContract.renderProfile);
    if (revisionContract.aspectRatio && effectiveInput.aspectRatio !== revisionContract.aspectRatio) {
      throw new HyperframesRenderSubmissionError("El formato solicitado no coincide con el snapshot. Regenera el snapshot.", 409);
    }
    const preflight = validateHyperframesPreflight({
      archiveSizeBytes: revision.project_archive_size_bytes,
      assets: manifest,
      deliveryMode: revisionContract.deliveryMode,
      durationSeconds: revisionContract.durationSeconds,
      renderProfile: revisionContract.renderProfile,
    });
    assertPassingPreflight(preflight);

    await this.processSubmission({
      input: effectiveInput,
      idempotencyKey: request.idempotency_key,
      jobId: request.production_job_id,
      manifest,
      deliveryMode: revisionContract.deliveryMode,
      preflight,
      request,
      revision,
    });
  }

  async failDispatch(params: { error: unknown; organizationId: string; requestId: string }) {
    const { data, error } = await this.supabase
      .from("hyperframes_render_requests")
      .select("id, production_job_id")
      .eq("id", params.requestId)
      .eq("organization_id", params.organizationId)
      .maybeSingle();
    if (error) throw error;
    if (data) await this.markSubmissionFailed(data.production_job_id, data.id, params.error);
  }

  private async processSubmission(params: {
    deliveryMode: HyperframesAssetDeliveryMode;
    input: HyperframesRenderSubmissionInput;
    idempotencyKey: string;
    jobId: string;
    manifest: HyperframesAssetManifestItem[];
    preflight: ReturnType<typeof validateHyperframesPreflight>;
    request: ExistingRequest;
    revision: StoredRevision;
  }): Promise<HyperframesRenderSubmissionResult> {
    const { deliveryMode, input, idempotencyKey, jobId, manifest, preflight, request, revision } = params;
    const client = this.client;
    if (!client) {
      throw new HyperframesRenderSubmissionError("El worker de render no tiene un cliente de HeyGen configurado.", 500);
    }

    try {
      const remoteAssetVariables = deliveryMode === HYPERFRAMES_ASSET_DELIVERY_MODES.REMOTE_VARIABLES
        ? await resolveHyperframesAssetVariables({ assets: manifest, supabase: this.supabase })
        : {};
      let providerAssetId = request.provider_asset_id;
      await this.assertNotCancelled(request.id);
      if (!providerAssetId) {
        await this.markUploading(jobId, request.id);
        const snapshotBytes = await this.downloadAndVerifyArchive(revision, manifest, deliveryMode);
        const archiveBytes = deliveryMode === HYPERFRAMES_ASSET_DELIVERY_MODES.REMOTE_VARIABLES
          ? await materializeHyperframesRenderMedia({ archive: snapshotBytes, entryPoint: revision.entry_point, assetVariables: remoteAssetVariables })
          : snapshotBytes;
        await this.assertNotCancelled(request.id);
        const upload = await client.uploadProjectArchive({
          bytes: archiveBytes,
          fileName: `${revision.id}.zip`,
          idempotencyKey,
        });
        providerAssetId = upload.assetId;
        await this.markProjectUploaded({
          jobId,
          providerAssetId,
          requestId: request.id,
        });
      }
      await this.assertNotCancelled(request.id);
      const render = await client.createRender({
        aspectRatio: input.aspectRatio,
        assetId: providerAssetId,
        callbackId: request.callback_id,
        callbackUrl: await this.getWebhookCallbackUrl(input.organizationId),
        composition: revision.entry_point,
        format: input.format || "mp4",
        fps: input.fps || HYPERFRAMES_DURABLE_RENDER_PROFILE.fps,
        idempotencyKey,
        quality: input.quality || HYPERFRAMES_DURABLE_RENDER_PROFILE.quality,
        resolution: input.resolution || "1080p",
        title: input.title || getComposition(revision)!.name,
        variables: { ...(revision.variables_values || {}), ...remoteAssetVariables },
      });
      await this.markSubmitted({
        jobId,
        providerAssetId,
        providerRenderId: render.render_id,
        requestId: request.id,
      });
      return {
        jobId,
        preflight,
        providerAssetId,
        providerRenderId: render.render_id,
        providerStatus: "PENDING",
        renderRequestId: request.id,
        reused: false,
      };
    } catch (error) {
      await this.markSubmissionFailed(jobId, request.id, error);
      throw error;
    }
  }

  private async findActiveRender(params: {
    componentId: string;
    organizationId: string;
  }): Promise<ActiveRender | null> {
    const { data: job, error: jobError } = await this.supabase
      .from("production_jobs")
      .select("id")
      .eq("organization_id", params.organizationId)
      .eq("material_component_id", params.componentId)
      .eq("job_type", PRODUCTION_JOB_TYPES.HYPERFRAMES_RENDER)
      .eq("provider", PRODUCTION_PROVIDERS.HYPERFRAMES)
      .in("status", [
        PRODUCTION_JOB_STATUSES.PENDING,
        PRODUCTION_JOB_STATUSES.RUNNING,
        PRODUCTION_JOB_STATUSES.WAITING_PROVIDER,
        PRODUCTION_JOB_STATUSES.RETRY_SCHEDULED,
      ])
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();
    if (jobError) throw jobError;
    if (!job?.id) return null;

    const { data: request, error: requestError } = await this.supabase
      .from("hyperframes_render_requests")
      .select("id, callback_id, provider_asset_id, provider_render_id, provider_status")
      .eq("organization_id", params.organizationId)
      .eq("production_job_id", job.id)
      .maybeSingle();
    if (requestError) throw requestError;
    return { jobId: job.id as string, request: request as ExistingRequest | null };
  }

  private async assertNotCancelled(requestId: string) {
    const { data, error } = await this.supabase.from("hyperframes_render_requests")
      .select("cancelled_at").eq("id", requestId).single();
    if (error) throw error;
    if (data.cancelled_at) throw new HyperframesRenderSubmissionError("El proceso fue cancelado.");
  }

  private async hasFailedAttempt(params: {
    idempotencyKey: string;
    organizationId: string;
  }) {
    const { data, error } = await this.supabase
      .from("production_jobs")
      .select("id")
      .eq("organization_id", params.organizationId)
      .eq("idempotency_key", params.idempotencyKey)
      .eq("job_type", PRODUCTION_JOB_TYPES.HYPERFRAMES_RENDER)
      .eq("provider", PRODUCTION_PROVIDERS.HYPERFRAMES)
      .in("status", [PRODUCTION_JOB_STATUSES.FAILED, PRODUCTION_JOB_STATUSES.CANCELLED])
      .maybeSingle();
    if (error) throw error;
    return Boolean(data?.id);
  }

  private async getRevision(input: HyperframesRenderSubmissionInput, requireActive = true) {
    const { data, error } = await this.supabase
      .from("video_composition_revisions")
      .select(HYPERFRAMES_RENDER_REVISION_SELECT)
      .eq("id", input.revisionId)
      .eq("organization_id", input.organizationId)
      .maybeSingle();
    if (error) throw error;
    if (!data) {
      throw new HyperframesRenderSubmissionError("Revisión de HyperFrames no encontrada para esta empresa.", 404);
    }
    const revision = data as StoredRevision;
    if (revision.format !== HYPERFRAMES_COMPOSITION_FORMAT) {
      throw new HyperframesRenderSubmissionError("La revisión no usa el formato interno de HyperFrames.");
    }
    const composition = getComposition(revision);
    if (!composition || (requireActive && (
      composition.status !== "READY_FOR_RENDER"
      || composition.active_revision_id !== revision.id
    ))) {
      throw new HyperframesRenderSubmissionError(
        "Solo se puede renderizar la revisión activa aprobada para render.",
      );
    }
    if (revision.project_storage_bucket !== PROJECT_ARCHIVE_BUCKET) {
      throw new HyperframesRenderSubmissionError("El archivo de proyecto no está en el bucket interno permitido.");
    }
    return revision;
  }

  private async getRevisionAssets(revisionId: string) {
    const [{ data, error }, { data: branding, error: brandingError }, { data: soundEffects, error: soundEffectsError }] = await Promise.all([
      this.supabase
        .from("video_composition_assets")
        .select("production_asset_id, source_checksum, source_storage_path, file_size_bytes, mime_type")
        .eq("composition_revision_id", revisionId),
      this.supabase
        .from("video_composition_brand_assets")
        .select("organization_assembly_asset_id, source_checksum, source_storage_bucket, source_storage_path, file_size_bytes, mime_type")
        .eq("composition_revision_id", revisionId),
      this.supabase
        .from("video_composition_sound_effect_assets")
        .select("sound_effect_asset_id, source_checksum, source_storage_bucket, source_storage_path, file_size_bytes, mime_type")
        .eq("composition_revision_id", revisionId),
    ]);
    if (error) throw error;
    if (brandingError) throw brandingError;
    if (soundEffectsError) throw soundEffectsError;
    return [
      ...((data || []) as StoredRevisionAsset[]),
      ...(branding || []).map((row) => ({
        file_size_bytes: Number(row.file_size_bytes),
        mime_type: String(row.mime_type),
        production_asset_id: String(row.organization_assembly_asset_id),
        source_checksum: String(row.source_checksum),
        source_storage_bucket: String(row.source_storage_bucket),
        source_storage_path: String(row.source_storage_path),
      })),
      ...(soundEffects || []).map((row) => ({
        file_size_bytes: Number(row.file_size_bytes),
        mime_type: String(row.mime_type),
        production_asset_id: String(row.sound_effect_asset_id),
        source_checksum: String(row.source_checksum),
        source_storage_bucket: String(row.source_storage_bucket),
        source_storage_path: String(row.source_storage_path),
      })),
    ];
  }

  private async resolveComponentContext(revision: StoredRevision, organizationId: string) {
    const componentId = getComposition(revision)?.material_component_id;
    if (!componentId) {
      throw new HyperframesRenderSubmissionError("La composición no está asociada a un componente de material.");
    }
    const context = await resolveProductionComponentContext({
      componentId,
      supabase: this.supabase,
    });
    if (context.organizationId !== organizationId) {
      throw new HyperframesRenderSubmissionError("El componente no pertenece a la empresa de la composición.", 403);
    }
    return context;
  }

  private async ensureRenderRequest(params: {
    archiveSizeBytes: number;
    compositionRevisionId: string;
    idempotencyKey: string;
    jobId: string;
    organizationId: string;
  }): Promise<ExistingRequest> {
    const { data: existing, error: readError } = await this.supabase
      .from("hyperframes_render_requests")
      .select("id, callback_id, provider_asset_id, provider_render_id, provider_status")
      .eq("production_job_id", params.jobId)
      .maybeSingle();
    if (readError) throw readError;
    if (existing) return existing as ExistingRequest;

    const { data, error } = await this.supabase
      .from("hyperframes_render_requests")
      .insert({
        archive_size_bytes: params.archiveSizeBytes,
        composition_revision_id: params.compositionRevisionId,
        idempotency_key: params.idempotencyKey,
        organization_id: params.organizationId,
        production_job_id: params.jobId,
        provider_status: "CREATED",
      })
      .select("id, callback_id, provider_asset_id, provider_render_id, provider_status")
      .single();
    if (error) throw error;
    return data as ExistingRequest;
  }

  private async claimBackgroundDispatch(params: {
    expectedStatus: string;
    jobId: string;
    providerStatus: "SUBMITTING" | "UPLOADING";
    requestId: string;
  }) {
    const now = new Date().toISOString();
    const { data: claimed, error: requestError } = await this.supabase
      .from("hyperframes_render_requests")
      .update({
        provider_error: null,
        provider_status: params.providerStatus,
        updated_at: now,
      })
      .eq("id", params.requestId)
      .eq("provider_status", params.expectedStatus)
      .select("id")
      .maybeSingle();
    if (requestError) throw requestError;
    if (!claimed) return false;

    const { error: jobError } = await this.supabase
      .from("production_jobs")
      .update({
        failed_at: null,
        progress: [{ at: now, percent: 0, stage: "queued" }],
        provider_error: null,
        status: PRODUCTION_JOB_STATUSES.PENDING,
        updated_at: now,
      })
      .eq("id", params.jobId);
    if (jobError) throw jobError;
    return true;
  }

  private async getWebhookCallbackUrl(organizationId: string): Promise<string | undefined> {
    const { data, error } = await this.supabase
      .from("hyperframes_workspace_connections")
      .select("default_callback_url")
      .eq("organization_id", organizationId)
      .maybeSingle();
    if (error) throw error;
    const callbackUrl = typeof data?.default_callback_url === "string"
      ? data.default_callback_url.trim()
      : "";
    return callbackUrl || undefined;
  }

  private async markUploading(jobId: string, requestId: string) {
    const now = new Date().toISOString();
    const { error: jobError } = await this.supabase
      .from("production_jobs")
      .update({
        progress: [{ at: now, percent: 1, stage: "uploading" }],
        started_at: now,
        status: PRODUCTION_JOB_STATUSES.RUNNING,
        updated_at: now,
      })
      .eq("id", jobId);
    if (jobError) throw jobError;

    const { error: requestError } = await this.supabase
      .from("hyperframes_render_requests")
      .update({ provider_status: "UPLOADING", updated_at: now })
      .eq("id", requestId);
    if (requestError) throw requestError;
  }

  private async markProjectUploaded(params: {
    jobId: string;
    providerAssetId: string;
    requestId: string;
  }) {
    const now = new Date().toISOString();
    const { error: jobError } = await this.supabase
      .from("production_jobs")
      .update({
        output_snapshot: {
          provider_asset_id: params.providerAssetId,
          provider_status: "submitting",
        },
        progress: [{ at: now, percent: 3, stage: "submitting" }],
        status: PRODUCTION_JOB_STATUSES.RUNNING,
        updated_at: now,
      })
      .eq("id", params.jobId);
    if (jobError) throw jobError;

    const { error: requestError } = await this.supabase
      .from("hyperframes_render_requests")
      .update({
        provider_asset_id: params.providerAssetId,
        provider_status: "SUBMITTING",
        updated_at: now,
      })
      .eq("id", params.requestId);
    if (requestError) throw requestError;
  }

  private async downloadAndVerifyArchive(
    revision: StoredRevision,
    assets: HyperframesAssetManifestItem[],
    deliveryMode: HyperframesAssetDeliveryMode,
  ) {
    const { data, error } = await this.supabase.storage
      .from(revision.project_storage_bucket)
      .download(revision.project_storage_path);
    if (error) throw error;
    const archive = new Uint8Array(await data.arrayBuffer());
    const actualPreflight = validateHyperframesPreflight({
      archiveSizeBytes: archive.byteLength,
      assets,
      deliveryMode,
      durationSeconds: readManifestDuration(revision.manifest),
      renderProfile: readManifestRenderProfile(revision.manifest),
    });
    assertPassingPreflight(actualPreflight);
    if (archive.byteLength !== revision.project_archive_size_bytes) {
      throw new HyperframesRenderSubmissionError("El tamaño del archivo de proyecto no coincide con la revisión aprobada.");
    }
    const actualHash = createHash("sha256").update(archive).digest("hex");
    if (actualHash !== revision.project_hash.toLowerCase()) {
      throw new HyperframesRenderSubmissionError("El hash del archivo de proyecto no coincide con la revisión aprobada.");
    }
    return archive;
  }

  private async markSubmitted(params: {
    jobId: string;
    providerAssetId: string;
    providerRenderId: string;
    requestId: string;
  }) {
    const now = new Date().toISOString();
    const { error: jobError } = await this.supabase
      .from("production_jobs")
      .update({
        output_snapshot: {
          provider_asset_id: params.providerAssetId,
          provider_render_id: params.providerRenderId,
          provider_status: "queued",
        },
        progress: [{ at: now, percent: 5, stage: "queued" }],
        provider_job_id: params.providerRenderId,
        started_at: now,
        status: PRODUCTION_JOB_STATUSES.WAITING_PROVIDER,
        updated_at: now,
      })
      .eq("id", params.jobId);
    if (jobError) throw jobError;

    const { error: requestError } = await this.supabase
      .from("hyperframes_render_requests")
      .update({
        provider_asset_id: params.providerAssetId,
        provider_render_id: params.providerRenderId,
        provider_status: "PENDING",
        updated_at: now,
      })
      .eq("id", params.requestId);
    if (requestError) throw requestError;
  }

  private async markSubmissionFailed(
    jobId: string,
    requestId: string | null,
    error: unknown,
  ) {
    const now = new Date().toISOString();
    const message = getErrorMessage(error, "No se pudo enviar el render a HyperFrames.").slice(0, 500);
    const { error: updateError } = await this.supabase
      .from("production_jobs")
      .update({
        failed_at: now,
        provider_error: { message, source: "hyperframes_submission" },
        status: PRODUCTION_JOB_STATUSES.FAILED,
        updated_at: now,
      })
      .eq("id", jobId);
    if (updateError) throw updateError;

    if (!requestId) return;
    const { error: requestError } = await this.supabase
      .from("hyperframes_render_requests")
      .update({
        provider_error: { message, source: "hyperframes_submission" },
        provider_status: "FAILED",
        updated_at: now,
      })
      .eq("id", requestId);
    if (requestError) throw requestError;
  }
}

function assertCompatibleRenderOptions(input: HyperframesRenderSubmissionInput) {
  if (input.resolution === "4k" && (input.format === "webm" || input.format === "mov")) {
    throw new HyperframesRenderSubmissionError("4k solo está disponible para renders MP4.", 400);
  }
  if (input.fps !== undefined && (!Number.isInteger(input.fps) || input.fps < 1 || input.fps > 240)) {
    throw new HyperframesRenderSubmissionError("FPS debe ser un entero entre 1 y 240.", 400);
  }
}

function parseStoredRenderOptions(value: unknown): Pick<
  HyperframesRenderSubmissionInput,
  "aspectRatio" | "format" | "fps" | "quality" | "resolution"
> {
  const input = value && typeof value === "object" && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  const aspectRatio = input.aspect_ratio;
  const format = input.format;
  const quality = input.quality;
  const resolution = input.resolution;
  const fps = input.fps;
  if (!(["16:9", "9:16", "1:1"] as unknown[]).includes(aspectRatio)
    || !(["mp4", "webm", "mov"] as unknown[]).includes(format)
    || !(["draft", "standard", "high"] as unknown[]).includes(quality)
    || !(["1080p", "4k"] as unknown[]).includes(resolution)
    || !Number.isInteger(fps)) {
    throw new HyperframesRenderSubmissionError("El snapshot de opciones del render no es válido.", 500);
  }
  return {
    aspectRatio: aspectRatio as "16:9" | "9:16" | "1:1",
    format: format as "mp4" | "webm" | "mov",
    fps: fps as number,
    quality: quality as "draft" | "standard" | "high",
    resolution: resolution as "1080p" | "4k",
  };
}

function getComposition(revision: StoredRevision) {
  const relation = revision.video_compositions;
  return Array.isArray(relation) ? relation[0] || null : relation;
}

function parseAndVerifyManifest(rawManifest: unknown, rows: StoredRevisionAsset[]) {
  const parsedManifest = hyperframesRevisionManifestSchema.safeParse(rawManifest);
  if (!parsedManifest.success) {
    throw new HyperframesRenderSubmissionError("El manifiesto de assets de la revisión no es válido.");
  }
  if (!parsedManifest.data.render_profile) {
    throw new HyperframesRenderSubmissionError(
      "Este snapshot usa un perfil de render anterior. Regenera el snapshot antes de enviarlo a HeyGen.",
      409,
    );
  }
  const manifest = parsedManifest.data.asset_manifest;
  const expected = hyperframesAssetManifestSchema.parse(
    rows.map((row) => ({
      checksum: row.source_checksum,
      fileSizeBytes: row.file_size_bytes,
      mimeType: row.mime_type,
      productionAssetId: row.production_asset_id,
      ...(row.source_storage_bucket ? { storageBucket: row.source_storage_bucket } : {}),
      storagePath: row.source_storage_path,
    })),
  );
  if (!sameManifest(manifest, expected)) {
    throw new HyperframesRenderSubmissionError(
      "El manifiesto no coincide con la trazabilidad de assets de la revisión.",
    );
  }
  return {
    assets: manifest,
    aspectRatio: parsedManifest.data.canvas_aspect_ratio,
    deliveryMode: parsedManifest.data.asset_delivery_mode || HYPERFRAMES_ASSET_DELIVERY_MODES.EMBEDDED,
    durationSeconds: parsedManifest.data.canvas_duration_seconds,
    renderProfile: parsedManifest.data.render_profile,
  };
}

function readManifestDuration(value: unknown) {
  const parsed = hyperframesRevisionManifestSchema.safeParse(value);
  return parsed.success ? parsed.data.canvas_duration_seconds : undefined;
}

function readManifestRenderProfile(value: unknown) {
  const parsed = hyperframesRevisionManifestSchema.safeParse(value);
  return parsed.success ? parsed.data.render_profile : undefined;
}

export function applyRevisionRenderProfile(
  input: HyperframesRenderSubmissionInput,
  renderProfile: HyperframesRenderSettings | undefined,
) {
  const resolved = resolveHyperframesSnapshotRenderProfile(input, renderProfile);
  if (!resolved.success) {
    throw new HyperframesRenderSubmissionError(resolved.message, 409);
  }
  return { ...input, ...resolved.data };
}

function sameManifest(
  manifest: HyperframesAssetManifestItem[],
  expected: HyperframesAssetManifestItem[],
) {
  if (manifest.length !== expected.length) return false;
  const byAssetId = new Map(manifest.map((asset) => [asset.productionAssetId, asset]));
  return expected.every((asset) => {
    const actual = byAssetId.get(asset.productionAssetId);
    return actual?.checksum.toLowerCase() === asset.checksum.toLowerCase()
      && actual.fileSizeBytes === asset.fileSizeBytes
      && actual.mimeType.toLowerCase() === asset.mimeType.toLowerCase()
      && actual.storagePath === asset.storagePath;
  });
}

function assertPassingPreflight(result: ReturnType<typeof validateHyperframesPreflight>) {
  if (result.valid) return;
  throw new HyperframesRenderSubmissionError(result.errors.join(" "), 400);
}

import type { SupabaseClient } from "@supabase/supabase-js";
