function statusPaths(type: HeygenPlatformOperationType, output: unknown, providerId: string) {
  const providerIds = readStringArray(toRecord(output)?.provider_ids);
  const ids = providerIds.length > 0 ? providerIds : [providerId];
  const prefix: Partial<Record<HeygenPlatformOperationType, string>> = {
    AI_CLIPPING: "/v3/ai-clipping/", BRAND_KIT: "/v3/brand-kits/",
    FILLER_REMOVAL: "/v3/filler-word-removals/", LIPSYNC: "/v3/lipsyncs/",
    PROOFREAD: "/v3/video-translations/proofreads/", TEMPLATE_VIDEO: "/v3/videos/",
    VIDEO_AGENT: "/v3/video-agents/", VIDEO_BATCH: "/v3/videos/batches/",
    VIDEO_TRANSLATION: "/v3/video-translations/", VOICE_CLONE: "/v3/voices/",
  };
  return prefix[type] ? ids.map((id) => `${prefix[type]}${encodeURIComponent(id)}`) : [];
}

function extractProviderIds(value: unknown): string[] {
  const record = toRecord(value);
  if (!record) return [];
  for (const key of ["video_translation_ids", "proofread_ids", "video_ids"]) {
    const values = readStringArray(record[key]);
    if (values.length > 0) return values;
  }
  for (const key of ["ai_clipping_id", "batch_id", "brand_glossary_id", "brand_kit_id",
    "filler_word_removal_id", "lipsync_id", "proofread_id", "session_id", "video_id",
    "voice_clone_id", "voice_id", "id"]) {
    const valueAtKey = record[key];
    if (typeof valueAtKey === "string" && valueAtKey.trim()) return [valueAtKey.trim()];
  }
  return [];
}

function estimateActionCost(action: HeygenPlatformAction, operation: HeygenPlatformOperationType) {
  if (operation === "VIDEO_TRANSLATION") return estimateHeygenCost({ durationSeconds: action.durationSeconds,
    itemCount: action.action === "translate_video" ? action.outputLanguages.length : 1,
    mode: action.action === "translate_video" ? action.mode : "speed", operation });
  if (operation === "LIPSYNC") return estimateHeygenCost({ durationSeconds: action.durationSeconds,
    mode: action.action === "lipsync" ? action.mode : "speed", operation });
  if (operation === "FILLER_REMOVAL") return estimateHeygenCost({ durationSeconds: action.durationSeconds, operation });
  if (operation === "AI_CLIPPING") return estimateHeygenCost({ itemCount: action.action === "ai_clipping" ? action.durationTypes.length : 1, operation });
  if (operation === "VIDEO_AGENT") return estimateHeygenCost({ durationSeconds: action.durationSeconds, operation });
  return 0;
}

function normalizeSettings(row: Record<string, unknown>) {
  return {
    defaultBrandGlossaryId: readNullableString(row.default_brand_glossary_id),
    defaultBrandKitId: readNullableString(row.default_brand_kit_id),
    defaultLocale: readNullableString(row.default_locale) || "es-MX",
    liveavatarAvatarId: readNullableString(row.liveavatar_avatar_id),
    liveavatarContextId: readNullableString(row.liveavatar_context_id),
    liveavatarSandbox: row.liveavatar_sandbox !== false,
    monthlyBudgetUsd: readNullableNumber(row.monthly_budget_usd),
    perCourseBudgetUsd: readNullableNumber(row.per_course_budget_usd),
  };
}

function buildCapabilityManifest() {
  return [
    "voiceover", "avatar_video", "transparent_avatar", "video_translation", "proofread",
    "lipsync", "voice_design", "voice_clone", "brand_glossary", "brand_kit", "templates",
    "video_agent", "video_batches", "ai_clipping", "filler_removal", "audio_search",
    "hyperframes", "liveavatar",
  ];
}

function unwrapData(value: unknown) { return toRecord(value)?.data ?? value; }
function unwrapList(value: unknown) {
  const unwrapped = unwrapData(value);
  if (Array.isArray(unwrapped)) return unwrapped;
  const record = toRecord(unwrapped);
  if (!record) return [];
  for (const key of ["items", "templates", "brand_glossaries", "brand_kits", "styles", "languages", "data"]) {
    if (Array.isArray(record[key])) return record[key];
  }
  return [];
}
function readStringArray(value: unknown) {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string" && item.length > 0) : [];
}
function readNullableString(value: unknown) { return typeof value === "string" && value.trim() ? value.trim() : null; }
function readNullableNumber(value: unknown) {
  const number = typeof value === "number" ? value : typeof value === "string" ? Number(value) : NaN;
  return Number.isFinite(number) ? number : null;
}
function readStatus(value: unknown) {
  const record = toRecord(value);
  const explicit = readNullableString(record?.status) || readNullableString(record?.state);
  if (explicit) return explicit;
  if (readNullableString(record?.failure_message) || readNullableString(record?.error_message)) return "failed";
  if (["video_url", "audio_url", "output_url", "download_url"].some((key) => readNullableString(record?.[key]))) {
    return "completed";
  }
  return null;
}
function isCompleted(status: string | null) { return Boolean(status && ["complete", "completed", "success", "succeeded"].includes(status.toLowerCase())); }
function isFailed(status: string | null) { return Boolean(status && ["cancelled", "canceled", "error", "failed", "failure"].includes(status.toLowerCase())); }
function readFailure(value: unknown) {
  const record = toRecord(value);
  const error = toRecord(record?.error);
  return readNullableString(record?.failure_message) || readNullableString(record?.error_message)
    || readNullableString(error?.message) || "HeyGen reportó que la operación falló.";
}
function redactOperationInput(action: HeygenPlatformAction) {
  return JSON.parse(JSON.stringify(action, (_key, value) => typeof value === "string" && value.length > 20_000 ? "[omitted]" : value));
}
async function safeFeature<T>(loader: () => Promise<T>): Promise<T | { unavailable: true; message: string }> {
  try { return await loader(); }
  catch (error) { return { unavailable: true, message: error instanceof Error ? error.message : "Unavailable" }; }
}

import type {
  AvatarClip,
  VoiceClip,
} from "@/domains/materials/types/materials.types";

/**
 * Clears generated projections while retaining the authored scene. Incrementing
 * generation_revision makes the next provider request intentionally distinct.
 */
export function resetGeneratedSceneAssets(params: {
  avatarClips: AvatarClip[];
  clipIds: string[];
  voiceClips: VoiceClip[];
}) {
  const selectedIds = new Set(params.clipIds);
  const avatarClips = params.avatarClips.map((clip) => {
    if (!selectedIds.has(clip.id)) return clip;

    const {
      duration: _duration,
      error_message: _errorMessage,
      external_id: _externalId,
      file_name: _fileName,
      has_audio: _hasAudio,
      job_id: _jobId,
      provider: _provider,
      public_url: _publicUrl,
      script_hash: _scriptHash,
      storage_path: _storagePath,
      voice_error_message: _voiceErrorMessage,
      voice_status: _voiceStatus,
      ...editableScene
    } = clip;

    return {
      ...editableScene,
      generation_revision: (clip.generation_revision ?? 0) + 1,
      status: "DRAFT" as const,
      voice_status: "DRAFT" as const,
    };
  }).sort((left, right) => left.order - right.order);

  return {
    avatarClips,
    voiceClips: params.voiceClips.filter((clip) => !selectedIds.has(clip.clip_id)),
  };
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { encrypt } from "@/lib/server/crypto";
import { readJsonResponseWithLimit } from "@/lib/server/outbound-http";

const HEYGEN_API_BASE_URL = "https://api.heygen.com";
const WEBHOOK_FUNCTION_NAME = "heygen-hyperframes-webhook";
const MAX_HEYGEN_WEBHOOK_JSON_BYTES = 256 * 1024;

interface HeygenWebhookEndpointResponse {
  endpoint_id: string;
  secret: string;
  url: string;
}

/**
 * Registers an organization-scoped HeyGen endpoint and stores its one-time
 * signing secret encrypted. The reconciliation cron remains the recovery path
 * if HeyGen cannot deliver a webhook.
 */
export async function configureHeygenHyperframesWebhook(params: {
  apiKey: string;
  organizationId: string;
  previousApiKey?: string | null;
  supabase: SupabaseClient<any, "public", any>;
}): Promise<{ callbackUrl: string; endpointId: string }> {
  return configureHeygenWebhook(params);
}

export async function configureHeygenWebhook(params: {
  apiKey: string;
  organizationId: string;
  previousApiKey?: string | null;
  supabase: SupabaseClient<any, "public", any>;
}): Promise<{ callbackUrl: string; endpointId: string }> {
  const callbackUrl = buildWebhookUrl();
  const previousEndpointId = await readCurrentEndpointId(params.supabase, params.organizationId);
  const created = await createEndpoint(params.apiKey, callbackUrl);

  try {
    const { error } = await params.supabase.rpc("configure_heygen_webhook", {
      p_callback_url: callbackUrl,
      p_encrypted_secret: encrypt(created.secret),
      p_endpoint_id: created.endpoint_id,
      p_organization_id: params.organizationId,
    });
    if (error) throw error;
  } catch (error) {
    await deleteEndpoint(params.apiKey, created.endpoint_id).catch(() => undefined);
    throw error;
  }

  if (previousEndpointId && previousEndpointId !== created.endpoint_id) {
    await deleteEndpoint(params.previousApiKey || params.apiKey, previousEndpointId).catch((error) => {
      console.warn("[HeyGen webhook] Could not remove superseded endpoint:", {
        endpointId: previousEndpointId,
        message: error instanceof Error ? error.message : "unknown_error",
      });
    });
  }
  return { callbackUrl, endpointId: created.endpoint_id };
}

export async function disconnectHeygenHyperframesWebhook(params: {
  apiKey: string;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}): Promise<void> {
  return disconnectHeygenWebhook(params);
}

export async function disconnectHeygenWebhook(params: {
  apiKey: string;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}): Promise<void> {
  const endpointId = await readCurrentEndpointId(params.supabase, params.organizationId);
  if (endpointId) {
    await deleteEndpoint(params.apiKey, endpointId).catch((error) => {
      console.warn("[HeyGen webhook] Could not remove endpoint during disconnect:", {
        endpointId,
        message: error instanceof Error ? error.message : "unknown_error",
      });
    });
  }
  const { error } = await params.supabase.rpc("clear_heygen_webhook", {
    p_organization_id: params.organizationId,
  });
  if (error) throw error;
}

async function createEndpoint(apiKey: string, callbackUrl: string): Promise<HeygenWebhookEndpointResponse> {
  const response = await fetch(`${HEYGEN_API_BASE_URL}/v3/webhooks/endpoints`, {
    body: JSON.stringify({
      url: callbackUrl,
    }),
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      "X-Api-Key": apiKey.trim(),
    },
    method: "POST",
    signal: AbortSignal.timeout(15_000),
  });
  if (!response.ok) throw new Error(`HeyGen no pudo registrar el webhook (${response.status}).`);
  const payload = await readJsonResponseWithLimit<{
    data?: Partial<HeygenWebhookEndpointResponse>;
  }>(response, MAX_HEYGEN_WEBHOOK_JSON_BYTES);
  if (!payload.data?.endpoint_id || !payload.data.secret) {
    throw new Error("HeyGen no devolvió el secreto del webhook registrado.");
  }
  return {
    endpoint_id: payload.data.endpoint_id,
    secret: payload.data.secret,
    url: payload.data.url || callbackUrl,
  };
}

async function deleteEndpoint(apiKey: string, endpointId: string): Promise<void> {
  const response = await fetch(
    `${HEYGEN_API_BASE_URL}/v3/webhooks/endpoints/${encodeURIComponent(endpointId)}`,
    {
      headers: { "X-Api-Key": apiKey.trim() },
      method: "DELETE",
      signal: AbortSignal.timeout(10_000),
    },
  );
  if (!response.ok && response.status !== 404) {
    throw new Error(`HeyGen no pudo eliminar el webhook (${response.status}).`);
  }
}

async function readCurrentEndpointId(
  supabase: SupabaseClient<any, "public", any>,
  organizationId: string,
): Promise<string | null> {
  const { data, error } = await supabase
    .from("heygen_workspace_connections")
    .select("webhook_endpoint_id")
    .eq("organization_id", organizationId)
    .maybeSingle();
  if (error) throw error;
  if (typeof data?.webhook_endpoint_id === "string") return data.webhook_endpoint_id;
  const { data: fallback, error: fallbackError } = await supabase
    .from("hyperframes_workspace_connections")
    .select("webhook_endpoint_id")
    .eq("organization_id", organizationId)
    .maybeSingle();
  if (fallbackError) throw fallbackError;
  return typeof fallback?.webhook_endpoint_id === "string" ? fallback.webhook_endpoint_id : null;
}

function buildWebhookUrl(): string {
  const projectUrl = process.env.NEXT_PUBLIC_SUPABASE_URL?.trim();
  if (!projectUrl) throw new Error("NEXT_PUBLIC_SUPABASE_URL no está configurada.");
  const url = new URL(`/functions/v1/${WEBHOOK_FUNCTION_NAME}`, projectUrl);
  if (url.protocol !== "https:") throw new Error("El webhook de HeyGen requiere una URL HTTPS.");
  return url.toString();
}

