"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { usePathname } from "next/navigation";
import Link from "next/link";
import {
  ArrowRight,
  CheckCircle2,
  Film,
  Loader2,
  Plus,
  RefreshCw,
  Search,
  Sparkles,
  Upload,
} from "lucide-react";
import { StandaloneMediaLibrary } from "./StandaloneMediaLibrary";
import { PRODUCTION_THEME } from "@/domains/materials/components/production-asset-ui";
import {
  createStandaloneAssemblyProjectAction,
  getStandaloneAssemblyProjectAction,
  listStandaloneAssemblyProjectsAction,
  type StandaloneAssemblyComponentView,
  type StandaloneAssemblyProjectSummary,
} from "./standalone-assembly.actions";
import { getStandaloneAssemblyReadiness } from "./standalone-assembly-readiness";

function formatDate(value: string) {
  return new Intl.DateTimeFormat("es-MX", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(new Date(value));
}

function statusLabel(project: StandaloneAssemblyProjectSummary) {
  if (project.finalVideoUrl || project.status === "COMPLETED") return "Finalizado";
  if (project.status === "RENDERING") return "Renderizando";
  if (project.productionStatus === "COMPLETED") return "Assets listos";
  return "En preparacion";
}

function statusClass(project: StandaloneAssemblyProjectSummary) {
  if (project.finalVideoUrl || project.status === "COMPLETED") {
    return "bg-emerald-500/10 text-emerald-700 dark:text-emerald-300";
  }
  if (project.status === "RENDERING") {
    return "bg-blue-500/10 text-blue-700 dark:text-blue-300";
  }
  return "bg-gray-100 text-gray-600 dark:bg-white/10 dark:text-gray-300";
}

export function StandaloneAssemblyStudio() {
  const pathname = usePathname();
  const [query, setQuery] = useState("");
  const [projects, setProjects] = useState<StandaloneAssemblyProjectSummary[]>([]);
  const [selectedProject, setSelectedProject] =
    useState<StandaloneAssemblyProjectSummary | null>(null);
  const [componentView, setComponentView] =
    useState<StandaloneAssemblyComponentView | null>(null);
  const [loadingProjects, setLoadingProjects] = useState(true);
  const [loadingProject, setLoadingProject] = useState(false);
  const [creatingProject, setCreatingProject] = useState(false);
  const [newTitle, setNewTitle] = useState("");
  const [error, setError] = useState<string | null>(null);

  const selectedProjectId = selectedProject?.id || null;

  const loadProjects = useCallback(
    async (nextQuery = "", preferredProjectId?: string) => {
      setLoadingProjects(true);
      setError(null);
      const result = await listStandaloneAssemblyProjectsAction(nextQuery);
      if (!result.success) {
        setError(result.error || "No se pudieron cargar ensambles.");
        setProjects([]);
        setLoadingProjects(false);
        return;
      }

      const nextProjects = result.projects || [];
      setProjects(nextProjects);
      setSelectedProject((current) => {
        const selectedId = preferredProjectId || current?.id;
        if (selectedId) {
          const match = nextProjects.find((project) => project.id === selectedId);
          if (match) return match;
        }
        return nextProjects[0] || null;
      });
      setLoadingProjects(false);
    },
    [],
  );

  const loadSelectedProject = useCallback(async (projectId: string, silent = false) => {
    if (!silent) setLoadingProject(true);
    setError(null);
    const result = await getStandaloneAssemblyProjectAction(projectId);
    if (!result.success) {
      setError(result.error || "No se pudo cargar el proyecto.");
      setComponentView(null);
      setLoadingProject(false);
      return;
    }

    setComponentView(result.data || null);
    setLoadingProject(false);
  }, []);

  useEffect(() => {
    void loadProjects("");
  }, [loadProjects]);

  useEffect(() => {
    if (!selectedProjectId) {
      setComponentView(null);
      return;
    }

    void loadSelectedProject(selectedProjectId);
  }, [loadSelectedProject, selectedProjectId]);

  const selectedProjectLabel = useMemo(() => {
    if (!selectedProject) return "Sin video seleccionado";
    return selectedProject.title;
  }, [selectedProject]);
  const adminBasePath = useMemo(() => {
    const adminIndex = pathname.indexOf("/admin");
    return adminIndex >= 0 ? pathname.slice(0, adminIndex + "/admin".length) : "/admin";
  }, [pathname]);
  const readiness = useMemo(
    () => getStandaloneAssemblyReadiness(componentView?.component.assets, componentView?.media.length || 0),
    [componentView],
  );
  const editorHref = componentView
    ? `${adminBasePath}/assembly/${componentView.project.id}/edit`
    : null;

  const handleCreateProject = async () => {
    const title = newTitle.trim();
    if (!title) {
      setError("Agrega un titulo para crear el video de ensamble.");
      return;
    }

    setCreatingProject(true);
    setError(null);
    const result = await createStandaloneAssemblyProjectAction({ title });
    if (!result.success || !result.project) {
      setError(result.error || "No se pudo crear el proyecto.");
      setCreatingProject(false);
      return;
    }

    setNewTitle("");
    await loadProjects(query, result.project.id);
    setCreatingProject(false);
  };

  return (
    <div className="engine-assembly-studio space-y-5">
      <div className="engine-assembly-header">
        <div>
          <div className="mb-2 inline-flex items-center gap-2 rounded-lg border border-gray-200 bg-white px-3 py-1 text-xs font-semibold text-gray-600 dark:border-[var(--engine-muted)]/10 dark:bg-[var(--engine-surface-solid)] dark:text-[var(--engine-text-muted)]">
            <Sparkles className="h-3.5 w-3.5 text-[var(--engine-accent-strong)]" />
            Ensamble independiente
          </div>
          <h1 className="text-3xl text-gray-900 dark:text-white">
            Estudio de Ensamble
          </h1>
          <p className="mt-2 max-w-3xl text-sm text-gray-600 dark:text-[var(--engine-text-muted)]">
            Crea o selecciona un proyecto, prepara sus assets y después continúa al editor de video.
          </p>
        </div>

        <form
          className="engine-assembly-search"
          onSubmit={(event) => {
            event.preventDefault();
            void loadProjects(query);
          }}
        >
          <div className="relative min-w-0 flex-1">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
            <input
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="Buscar ensamble"
              className="w-full rounded-lg border border-gray-200 bg-white py-2 pl-9 pr-3 text-sm text-gray-900 outline-none transition focus:border-[var(--engine-accent)] focus:ring-2 focus:ring-[var(--engine-accent)]/20 dark:border-[var(--engine-muted)]/10 dark:bg-[var(--engine-surface-solid)] dark:text-white"
            />
          </div>
          <button
            type="submit"
            disabled={loadingProjects}
            className="engine-button engine-button--primary"
          >
            {loadingProjects ? <Loader2 className="h-4 w-4 animate-spin" /> : <Search className="h-4 w-4" />}
            Buscar
          </button>
        </form>
      </div>

      {error && (
        <div className="rounded-lg border border-red-200 bg-red-50 p-3 text-sm font-medium text-red-700 dark:border-red-500/20 dark:bg-red-500/10 dark:text-red-200">
          {error}
        </div>
      )}

      <div className="engine-assembly-layout">
        <aside className="engine-project-rail">
          <div className="border-b border-gray-100 p-4 dark:border-white/5">
            <div className="flex items-center justify-between gap-3">
              <div>
                <h2 className="text-sm font-bold text-gray-900 dark:text-white">Videos de ensamble</h2>
                <p className="text-xs text-gray-500 dark:text-[var(--engine-text-muted)]">{projects.length} proyecto(s)</p>
              </div>
              <button
                type="button"
                onClick={() => void loadProjects(query)}
                disabled={loadingProjects}
                className="inline-flex h-8 w-8 items-center justify-center rounded-lg border border-gray-200 text-gray-600 transition hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50 dark:border-[var(--engine-muted)]/20 dark:text-gray-200 dark:hover:bg-white/5"
                title="Actualizar"
              >
                <RefreshCw className={`h-4 w-4 ${loadingProjects ? "animate-spin" : ""}`} />
              </button>
            </div>

            <form
              className="mt-4 flex gap-2"
              onSubmit={(event) => {
                event.preventDefault();
                void handleCreateProject();
              }}
            >
              <input
                value={newTitle}
                onChange={(event) => setNewTitle(event.target.value)}
                placeholder="Titulo del video"
                className="min-w-0 flex-1 rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm text-gray-900 outline-none transition focus:border-[var(--engine-accent)] focus:ring-2 focus:ring-[var(--engine-accent)]/20 dark:border-[var(--engine-muted)]/10 dark:bg-[#0F131A] dark:text-white"
              />
              <button
                type="submit"
                disabled={creatingProject}
                className="inline-flex h-9 w-9 items-center justify-center rounded-lg bg-[var(--engine-accent-strong)] text-white transition hover:bg-[#008f79] disabled:cursor-not-allowed disabled:opacity-60"
                title="Crear video"
              >
                {creatingProject ? <Loader2 className="h-4 w-4 animate-spin" /> : <Plus className="h-4 w-4" />}
              </button>
            </form>
          </div>

          <div className="max-h-[620px] space-y-2 overflow-y-auto p-3">
            {loadingProjects ? (
              <div className="flex items-center justify-center py-12 text-sm text-gray-500">
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Cargando ensambles
              </div>
            ) : projects.length === 0 ? (
              <div className="rounded-lg border border-dashed border-gray-200 p-4 text-center text-sm text-gray-500 dark:border-[var(--engine-muted)]/20">
                Crea un video para iniciar el ensamble independiente.
              </div>
            ) : (
              projects.map((project) => {
                const isSelected = project.id === selectedProjectId;
                return (
                  <button
                    key={project.id}
                    type="button"
                    onClick={() => setSelectedProject(project)}
                    className={`w-full rounded-lg border p-3 text-left transition ${
                      isSelected
                        ? "border-[var(--engine-accent)] bg-[var(--engine-accent)]/5 ring-1 ring-[var(--engine-accent)]/25"
                        : "border-gray-200 hover:bg-gray-50 dark:border-[var(--engine-muted)]/10 dark:hover:bg-white/5"
                    }`}
                  >
                    <div className="mb-2 flex items-start justify-between gap-2">
                      <span className="line-clamp-2 text-sm font-bold text-gray-900 dark:text-white">
                        {project.title}
                      </span>
                      <span className={`shrink-0 rounded-full px-2 py-0.5 text-[10px] font-semibold ${statusClass(project)}`}>
                        {statusLabel(project)}
                      </span>
                    </div>
                    {project.description ? (
                      <p className="line-clamp-2 text-xs text-gray-500 dark:text-[var(--engine-text-muted)]">
                        {project.description}
                      </p>
                    ) : null}
                    <div className="mt-3 text-[11px] text-gray-400 dark:text-gray-500">
                      {formatDate(project.updatedAt)}
                    </div>
                  </button>
                );
              })
            )}
          </div>
        </aside>

        <main className="min-w-0 space-y-5">
          <div className="engine-assembly-context">
            <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
              <div className="min-w-0">
                <p className="text-xs font-semibold uppercase tracking-normal text-gray-500 dark:text-[var(--engine-text-muted)]">
                  Video activo
                </p>
                <h2 className="mt-1 truncate text-lg font-bold text-gray-900 dark:text-white">
                  {selectedProjectLabel}
                </h2>
              </div>
              {componentView?.component.assets?.final_video_url ? (
                <div className="inline-flex items-center gap-2 rounded-full bg-emerald-500/10 px-3 py-1 text-xs font-semibold text-emerald-700 dark:text-emerald-300">
                  <CheckCircle2 className="h-3.5 w-3.5" />
                  Video final disponible
                </div>
              ) : (
                <div className="inline-flex items-center gap-2 rounded-full bg-gray-100 px-3 py-1 text-xs font-semibold text-gray-600 dark:bg-white/10 dark:text-gray-300">
                  <Film className="h-3.5 w-3.5" />
                  Pendiente de ensamble
                </div>
              )}
            </div>
          </div>

          {loadingProject ? (
            <div className={`flex flex-col items-center justify-center py-20 ${PRODUCTION_THEME.panel}`}>
              <Loader2 className="mb-4 h-8 w-8 animate-spin text-[var(--engine-info)]" />
              <p className={`font-medium ${PRODUCTION_THEME.secondaryText}`}>Cargando ensamble...</p>
            </div>
          ) : componentView ? (
            <div className="space-y-6">
              <div className="engine-assembly-readiness">
                <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                  <div>
                    <p className="flex items-center gap-2 text-xs font-bold uppercase tracking-wide text-cyan-700 dark:text-cyan-300"><Upload size={14} /> Preparación de assets</p>
                    <h3 className="mt-1 text-base font-bold text-slate-900 dark:text-white">Carga los archivos del proyecto</h3>
                    <p className="mt-1 text-xs text-slate-600 dark:text-gray-400">Cuando termines, abre el editor en la siguiente página para trabajar con preview y timeline.</p>
                  </div>
                  <span className="shrink-0 rounded-full bg-white px-3 py-1 text-xs font-semibold text-slate-600 shadow-sm dark:bg-white/10 dark:text-gray-300">{readiness.assetCount} asset(s)</span>
                </div>
              </div>

              <StandaloneMediaLibrary
                key={componentView.component.id}
                componentId={componentView.component.id}
                assets={componentView.media}
                hasHtmlDeck={Boolean(componentView.component.assets?.slides?.animated_deck)}
                onChanged={async () => { await loadSelectedProject(componentView.project.id, true); }}
              />

              <div className="engine-assembly-next">
                <div>
                  <p className="text-sm font-bold text-slate-900 dark:text-white">Siguiente paso: edición</p>
                  <p className="mt-1 text-xs text-slate-500 dark:text-gray-400">{readiness.canOpenEditor ? "El proyecto ya tiene medios para editar." : "Agrega una imagen, video, audio o diapositivas HTML para continuar."}</p>
                </div>
                {readiness.canOpenEditor && editorHref ? (
                  <Link href={editorHref} className="engine-button engine-button--primary">Abrir editor <ArrowRight size={16} /></Link>
                ) : (
                  <button type="button" disabled className="inline-flex min-h-10 shrink-0 cursor-not-allowed items-center justify-center gap-2 rounded-lg bg-slate-200 px-5 py-2.5 text-sm font-bold text-slate-500 dark:bg-white/10 dark:text-gray-500">Abrir editor <ArrowRight size={16} /></button>
                )}
              </div>
            </div>
          ) : (
            <div className="rounded-lg border border-dashed border-gray-200 bg-white p-10 text-center dark:border-[var(--engine-muted)]/20 dark:bg-[var(--engine-surface-solid)]">
              <Film className="mx-auto mb-3 h-10 w-10 text-gray-300 dark:text-gray-600" />
              <p className="text-sm font-medium text-gray-500 dark:text-[var(--engine-text-muted)]">
                Crea o selecciona un video de ensamble para subir assets y renderizar.
              </p>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

import { getSupabaseServiceRoleKey, getSupabaseUrl } from "@/lib/server/env";
import {
  fetchWithDeadline,
  readResponseArrayBufferWithLimit,
  readResponseTextWithLimit,
} from "@/lib/server/outbound-http";
import { validateRemotionBundle, type ValidationReport } from "@/domains/production/validation/bundle-validator";

const TEMPLATE_BUNDLE_MAX_BYTES = 10 * 1024 * 1024;
const TEMPLATE_BUNDLE_DOWNLOAD_TIMEOUT_MS = 60_000;
const TEMPLATE_BUNDLE_ERROR_MAX_BYTES = 32 * 1024;

type SupabaseAdminClient = any;

export interface CreateTemplateVersionInput {
  admin: SupabaseAdminClient;
  activeOrgId: string;
  userId: string;
  templateId: string;
  storagePath: string;
  originalFileName: string;
  validationReport?: ValidationReport;
  bundleBuffer?: ArrayBuffer;
}

export function resolveBundleStorageLocation(storagePath: string) {
  const normalized = storagePath.replace(/\\/g, "/").replace(/^\/+/, "");

  if (normalized.startsWith("template-bundles/")) {
    return {
      bucket: "template-bundles",
      path: normalized.substring("template-bundles/".length),
    };
  }

  if (normalized.startsWith("production-assets/")) {
    return {
      bucket: "production-assets",
      path: normalized.substring("production-assets/".length),
    };
  }

  if (normalized.startsWith("http")) {
    const templateBundleMarker = "/template-bundles/";
    const templateBundleIndex = normalized.indexOf(templateBundleMarker);
    if (templateBundleIndex !== -1) {
      return {
        bucket: "template-bundles",
        path: normalized.substring(templateBundleIndex + templateBundleMarker.length),
      };
    }

    const productionAssetsMarker = "/production-assets/";
    const productionAssetsIndex = normalized.indexOf(productionAssetsMarker);
    if (productionAssetsIndex !== -1) {
      return {
        bucket: "production-assets",
        path: normalized.substring(productionAssetsIndex + productionAssetsMarker.length),
      };
    }
  }

  return { bucket: "template-bundles", path: normalized };
}

async function downloadBundleArrayBuffer(storagePath: string): Promise<ArrayBuffer> {
  const bundleLocation = resolveBundleStorageLocation(storagePath);
  const downloadUrl = `${getSupabaseUrl()}/storage/v1/object/${bundleLocation.bucket}/${bundleLocation.path}`;
  const response = await fetchWithDeadline(downloadUrl, {
    headers: {
      Authorization: `Bearer ${getSupabaseServiceRoleKey()}`,
    },
    cache: "no-store",
  }, TEMPLATE_BUNDLE_DOWNLOAD_TIMEOUT_MS);

  if (!response.ok) {
    const errText = await readResponseTextWithLimit(response, TEMPLATE_BUNDLE_ERROR_MAX_BYTES)
      .catch(() => "Unknown error");
    throw new Error(`HTTP ${response.status}: ${errText.slice(0, 500)}`);
  }

  return readResponseArrayBufferWithLimit(response, TEMPLATE_BUNDLE_MAX_BYTES);
}

export async function createTemplateVersionRecord(
  input: CreateTemplateVersionInput,
): Promise<{ version: any; report: ValidationReport; normalizedStoragePath: string }> {
  const { admin, activeOrgId, templateId } = input;
  const { data: template, error: fetchError } = await admin
    .from("remotion_templates")
    .select("organization_id, bundle_status")
    .eq("id", templateId)
    .single();

  if (fetchError || !template) throw new Error("Plantilla no encontrada");
  if (template.organization_id !== activeOrgId) {
    throw new Error("No tienes permiso para modificar esta plantilla");
  }

  const bundleLocation = resolveBundleStorageLocation(input.storagePath);
  const normalizedStoragePath = `${bundleLocation.bucket}/${bundleLocation.path}`;
  const arrayBuffer = input.bundleBuffer || (await downloadBundleArrayBuffer(normalizedStoragePath));
  const report = input.validationReport || (await validateRemotionBundle(arrayBuffer, input.originalFileName));

  const { data: latest } = await admin
    .from("remotion_template_versions")
    .select("version_number")
    .eq("template_id", templateId)
    .order("version_number", { ascending: false })
    .limit(1)
    .maybeSingle();

  const nextVersionNumber = latest ? latest.version_number + 1 : 1;
  const status = report.isValid ? "PENDING_REVIEW" : "VALIDATION_FAILED";
  const manifest = report.info.manifest;
  const compositionIds = manifest
    ? Array.from(new Set([manifest.compositionId, ...(manifest.compositionIds || [])]))
    : null;

  const { data: version, error: insertError } = await admin
    .from("remotion_template_versions")
    .insert({
      template_id: templateId,
      organization_id: activeOrgId,
      version_number: nextVersionNumber,
      status,
      template_type: "custom_bundle",
      storage_path: normalizedStoragePath,
      original_file_name: input.originalFileName,
      bundle_hash: report.info.hash,
      entry_point: manifest?.entryPoint || null,
      manifest: manifest || null,
      export_mode: manifest?.exportMode || "component",
      composition_id: manifest?.compositionId || null,
      composition_ids: compositionIds,
      props_schema: manifest?.propsSchema || null,
      default_props: manifest?.defaultProps || null,
      editable_layers: manifest?.editableLayers || [],
      default_duration_frames: manifest?.defaultDurationFrames || null,
      default_fps: manifest?.fps || null,
      default_width: manifest?.width || null,
      default_height: manifest?.height || null,
      build_status: "PENDING",
      validation_report: {
        isValid: report.isValid,
        errors: report.errors,
        warnings: report.warnings,
        info: {
          fileCount: report.info.fileCount,
          unzippedSize: report.info.unzippedSize,
          dependencies: report.info.dependencies || {},
        },
      },
      validated_at: new Date().toISOString(),
      created_by: input.userId,
    })
    .select(`
      *,
      created_by_profile:profiles!created_by(username, first_name, email),
      approved_by_profile:profiles!approved_by(username, first_name, email),
      rejected_by_profile:profiles!rejected_by(username, first_name, email)
    `)
    .single();

  if (insertError) throw insertError;

  await admin
    .from("remotion_templates")
    .update({
      bundle_status: report.isValid ? "PENDING_REVIEW" : "REJECTED",
      storage_path: normalizedStoragePath,
      updated_at: new Date().toISOString(),
    })
    .eq("id", templateId);

  return { version, report, normalizedStoragePath };
}

import crypto from "crypto";
import JSZip from "jszip";
import { z } from "zod";
import {
  editableLayerDefinitionSchema,
  TEMPLATE_LAYOUT_CONTRACT_VERSION,
  TEMPLATE_LAYOUT_COORDINATE_SPACE,
} from "../../../remotion/layout-overrides";

const MAX_ZIP_SIZE_BYTES = 10 * 1024 * 1024;
const MAX_UNZIPPED_SIZE_BYTES = 50 * 1024 * 1024;
const MAX_MANIFEST_BYTES = 64 * 1024;
const MAX_FILE_COUNT = 1000;
const MANIFEST_PATH = "courseforge-remotion-template.json";
const ALLOWED_ENTRY_EXTENSIONS = [".tsx", ".ts", ".jsx", ".js"];
const ALLOWED_SOURCE_EXTENSIONS = new Set([
  ".css",
  ".gif",
  ".jpeg",
  ".jpg",
  ".js",
  ".json",
  ".md",
  ".png",
  ".svg",
  ".ts",
  ".tsx",
  ".txt",
  ".webp",
]);
const BLOCKED_PACKAGE_SCRIPTS = new Set([
  "preinstall",
  "install",
  "postinstall",
  "prepack",
  "postpack",
  "prepare",
]);
const ALLOWED_DEPENDENCIES = new Set([
  "autoprefixer",
  "clsx",
  "framer-motion",
  "lucide-react",
  "postcss",
  "react",
  "react-dom",
  "remotion",
  "tailwind-merge",
  "tailwindcss",
  "typescript",
  "zod",
  "zustand",
]);

const positiveIntegerSchema = z.number().int().positive();
const jsonObjectSchema = z.record(z.string(), z.unknown());

const manifestSchema = z.object({
  name: z.string().trim().min(1).max(120).optional(),
  entryPoint: z.string().trim().min(1).max(240),
  compositionId: z.string().trim().min(1).max(120),
  compositionIds: z.array(z.string().trim().min(1).max(120)).max(100).optional(),
  exportMode: z.enum(["component", "root"]).default("component"),
  capabilities: z.object({
    animatedDeck: z.boolean().optional(),
    htmlDeck: z.boolean().optional(),
    htmlSlides: z.boolean().optional(),
  }).optional(),
  layoutContractVersion: z.number().int().min(1).max(TEMPLATE_LAYOUT_CONTRACT_VERSION).optional(),
  layoutCoordinateSpace: z.literal(TEMPLATE_LAYOUT_COORDINATE_SPACE).optional(),
  defaultDurationFrames: positiveIntegerSchema.optional(),
  fps: positiveIntegerSchema.optional(),
  width: positiveIntegerSchema.optional(),
  height: positiveIntegerSchema.optional(),
  propsSchema: jsonObjectSchema.optional(),
  defaultProps: jsonObjectSchema.optional(),
  editableLayers: z.array(editableLayerDefinitionSchema).max(40).optional(),
  remotionVersion: z.string().trim().min(1).max(40).optional(),
});

export interface RemotionTemplateManifest extends z.infer<typeof manifestSchema> {}

export interface ValidationReport {
  isValid: boolean;
  errors: string[];
  warnings: string[];
  info: {
    fileCount: number;
    unzippedSize: number;
    manifest: RemotionTemplateManifest | null;
    dependencies: Record<string, string>;
    hash: string;
  };
}

function hasUnsafePath(name: string) {
  const normalized = name.endsWith("/") ? name.slice(0, -1) : name;
  return (
    normalized.includes("..") ||
    normalized.includes("\\") ||
    normalized.startsWith("/") ||
    /^[a-zA-Z]:/.test(normalized) ||
    normalized.split("/").some((segment) => segment.length === 0 || segment === "." || segment.startsWith("."))
  );
}

function getFileExtension(name: string) {
  const normalized = name.toLowerCase();
  const dotIndex = normalized.lastIndexOf(".");
  return dotIndex === -1 ? "" : normalized.slice(dotIndex);
}

function isAllowedDependency(dep: string) {
  return ALLOWED_DEPENDENCIES.has(dep) || dep.startsWith("@remotion/") || dep.startsWith("@types/");
}

function isUnixSymlink(file: JSZip.JSZipObject) {
  const permissions = typeof file.unixPermissions === "number" ? file.unixPermissions : 0;
  return (permissions & 0o170000) === 0o120000;
}

function readPackageDependencies(packageJson: any) {
  return {
    ...(packageJson.dependencies || {}),
    ...(packageJson.devDependencies || {}),
    ...(packageJson.peerDependencies || {}),
  } as Record<string, string>;
}

function manifestSupportsArrayProp(manifest: RemotionTemplateManifest, propName: string): boolean {
  const propsSchema = manifest.propsSchema as Record<string, unknown> | undefined;
  const properties = propsSchema?.properties;

  if (!properties || typeof properties !== "object" || Array.isArray(properties)) {
    return false;
  }

  const propSchema = (properties as Record<string, unknown>)[propName];
  return Boolean(
    propSchema &&
    typeof propSchema === "object" &&
    !Array.isArray(propSchema) &&
    (propSchema as Record<string, unknown>).type === "array",
  );
}

function manifestSupportsLayoutOverrides(manifest: RemotionTemplateManifest): boolean {
  return manifestSupportsArrayProp(manifest, "layoutOverrides");
}

function manifestSupportsTimelineOverrides(manifest: RemotionTemplateManifest): boolean {
  return manifestSupportsArrayProp(manifest, "timelineOverrides");
}

/**
 * Validates a Remotion ZIP bundle statically in memory without execution.
 *
 * This validation is intentionally stricter than a generic ZIP check because a
 * passing bundle can later be reviewed and built in cloud. Static validation
 * is not treated as sufficient runtime isolation.
 */
export async function validateRemotionBundle(
  buffer: ArrayBuffer,
  _fileName: string,
): Promise<ValidationReport> {
  const errors: string[] = [];
  const warnings: string[] = [];
  let fileCount = 0;
  let unzippedSize = 0;
  let manifest: RemotionTemplateManifest | null = null;
  let dependencies: Record<string, string> = {};

  const hash = crypto.createHash("sha256").update(Buffer.from(buffer)).digest("hex");

  if (buffer.byteLength > MAX_ZIP_SIZE_BYTES) {
    errors.push(
      `El archivo ZIP supera el tamano maximo permitido de 10MB (${(buffer.byteLength / 1024 / 1024).toFixed(2)}MB).`,
    );
    return {
      isValid: false,
      errors,
      warnings,
      info: { fileCount, unzippedSize, manifest, dependencies, hash },
    };
  }

  try {
    const zip = new JSZip();
    const contents = await zip.loadAsync(buffer);
    const fileNames = Object.keys(contents.files);
    fileCount = fileNames.length;

    if (fileCount > MAX_FILE_COUNT) {
      errors.push(`El archivo ZIP contiene demasiados archivos (${fileCount}). El limite permitido es ${MAX_FILE_COUNT}.`);
    }

    for (const name of fileNames) {
      const file = contents.files[name];

      if (hasUnsafePath(name)) {
        errors.push(`Ruta de archivo no permitida: ${name}`);
        continue;
      }

      if (name.startsWith("node_modules/") || name.includes("/node_modules/")) {
        errors.push(`El bundle no debe incluir node_modules: ${name}`);
      }

      if (isUnixSymlink(file)) {
        errors.push(`El bundle no debe incluir symlinks: ${name}`);
      }

      if (!file.dir) {
        const extension = getFileExtension(name);
        if (!ALLOWED_SOURCE_EXTENSIONS.has(extension)) {
          errors.push(`Extension de archivo no permitida (${extension || "sin extension"}): ${name}`);
        }

        const bytes = await file.async("uint8array");
        unzippedSize += bytes.byteLength;
        if (unzippedSize > MAX_UNZIPPED_SIZE_BYTES) {
          errors.push(`El contenido descomprimido supera el limite de 50MB.`);
          break;
        }
      }

      if (name === "package.json") {
        try {
          const packageJson = JSON.parse(await file.async("text"));
          dependencies = readPackageDependencies(packageJson);
          const scripts = packageJson.scripts || {};
          const blockedScripts = Object.keys(scripts).filter((scriptName) => BLOCKED_PACKAGE_SCRIPTS.has(scriptName));
          if (blockedScripts.length > 0) {
            errors.push(`package.json declara scripts no permitidos: ${blockedScripts.join(", ")}.`);
          }
        } catch {
          errors.push("Se encontro package.json pero no es un JSON valido.");
        }
      }

      if (name === MANIFEST_PATH) {
        try {
          const manifestBytes = await file.async("uint8array");
          if (manifestBytes.byteLength > MAX_MANIFEST_BYTES) {
            errors.push(`El manifiesto ${MANIFEST_PATH} supera el limite de 64KB.`);
            continue;
          }

          const parsed = manifestSchema.safeParse(JSON.parse(Buffer.from(manifestBytes).toString("utf8")));
          if (!parsed.success) {
            errors.push(`El manifiesto ${MANIFEST_PATH} no cumple el contrato requerido.`);
          } else {
            manifest = parsed.data;
          }
        } catch {
          errors.push(`El archivo ${MANIFEST_PATH} no es un JSON valido.`);
        }
      }
    }

    if (!manifest) {
      errors.push(`No se encontro el manifiesto obligatorio '${MANIFEST_PATH}' en la raiz del ZIP.`);
    } else {
      const entryPointPath = manifest.entryPoint;
      const entryFile = contents.files[entryPointPath];
      if (hasUnsafePath(entryPointPath)) {
        errors.push(`El entryPoint contiene una ruta no permitida: ${entryPointPath}`);
      } else if (!entryFile) {
        errors.push(`El entryPoint especificado '${entryPointPath}' no existe en el ZIP.`);
      } else if (entryFile.dir) {
        errors.push(`El entryPoint especificado '${entryPointPath}' es un directorio, debe ser un archivo.`);
      }

      if (!ALLOWED_ENTRY_EXTENSIONS.some((extension) => entryPointPath.endsWith(extension))) {
        errors.push(`El entryPoint '${entryPointPath}' debe terminar en: ${ALLOWED_ENTRY_EXTENSIONS.join(", ")}.`);
      }

      if (!manifest.remotionVersion) {
        warnings.push("Se recomienda especificar remotionVersion en el manifiesto.");
      }

      if (!manifestSupportsLayoutOverrides(manifest)) {
        warnings.push(
          "El manifiesto no declara propsSchema.properties.layoutOverrides como array; el editor de layout no podra adaptar posicion, tamano o recorte en esta plantilla.",
        );
      } else if (
        manifest.layoutContractVersion !== TEMPLATE_LAYOUT_CONTRACT_VERSION ||
        !manifest.editableLayers?.length
      ) {
        warnings.push(
          "El bundle no declara un contrato de layout v2 completo. Se renderizara con su layout base y el editor ignorara layoutOverrides para evitar coordenadas incompatibles.",
        );
      } else {
        if (manifest.layoutCoordinateSpace !== TEMPLATE_LAYOUT_COORDINATE_SPACE) {
          warnings.push(
            "El contrato v2 usa coordenadas globales del canvas. Declara layoutCoordinateSpace como canvas para documentar ese origen de forma explicita.",
          );
        }
        if (!manifest.editableLayers.some((layer) => layer.capabilities.canReorder)) {
          warnings.push(
            "El bundle admite posicion y tamano, pero ninguna capa declara canReorder; el editor no mostrara controles de orden.",
          );
        }
      }

      if (manifestSupportsLayoutOverrides(manifest) && !manifestSupportsTimelineOverrides(manifest)) {
        warnings.push(
          "El manifiesto no declara propsSchema.properties.timelineOverrides como array; el editor de timeline no podra aplicar cambios de inicio, fin o recorte por asset en esta plantilla.",
        );
      }
    }

    const suspiciousDeps = Object.keys(dependencies).filter((dep) => !isAllowedDependency(dep));
    if (suspiciousDeps.length > 0) {
      errors.push(`Dependencias no permitidas detectadas: ${suspiciousDeps.join(", ")}.`);
    }
  } catch (err: any) {
    errors.push(`Error al leer o procesar el archivo ZIP: ${err.message || err}`);
  }

  return {
    isValid: errors.length === 0,
    errors,
    warnings,
    info: {
      fileCount,
      unzippedSize,
      manifest,
      dependencies,
      hash,
    },
  };
}

import { getServiceRoleClient } from "@/lib/server/artifact-action-auth";
import { prepareOpenDesignDeckForHtmlToPng } from "./open-design-slide-test.service";

export interface RenderableSlideAsset {
  file_name?: string;
  slide_index: number;
  storage_path: string;
  public_url: string;
  content_type?: string;
}

export interface OpenDesignHtmlRasterizeResult {
  images: RenderableSlideAsset[];
  cleanup: {
    slideCount: number;
    removedScripts: number;
    removedOpenDesignScripts: number;
    removedControllerNodes: number;
    removedDynamicVisibilityRules: number;
    hasSceneControllerResidue: boolean;
  };
}

type ServiceRoleClient = ReturnType<typeof getServiceRoleClient>;

const BUCKET = "production-assets";

export function isHtmlSlideSource(params: {
  fileName?: string;
  mimeType?: string;
  publicUrl?: string;
  storagePath?: string;
}) {
  const mimeType = params.mimeType?.toLowerCase() || "";
  const candidates = [
    params.fileName,
    params.publicUrl,
    params.storagePath,
  ]
    .filter((value): value is string => Boolean(value))
    .map((value) => value.toLowerCase().split("?")[0]);

  return (
    mimeType === "text/html" ||
    mimeType === "application/xhtml+xml" ||
    candidates.some((value) => value.endsWith(".html") || value.endsWith(".htm"))
  );
}

export function normalizeProductionAssetStoragePath(rawPath: string): string {
  const storagePath = rawPath.replace(/^production-assets\//, "");
  if (!/^slides\/[a-zA-Z0-9._-]+$/.test(storagePath)) {
    throw new Error("Ruta de HTML de slides invalida.");
  }
  if (!/\.html?$/i.test(storagePath)) {
    throw new Error("El archivo de slides debe ser HTML.");
  }
  return storagePath;
}

function dataUrl(html: string): string {
  return `data:text/html;charset=utf-8,${encodeURIComponent(html)}`;
}

function pad2(value: number): string {
  return String(value).padStart(2, "0");
}

async function wait(milliseconds: number) {
  await new Promise((resolve) => setTimeout(resolve, milliseconds));
}

export async function rasterizeOpenDesignHtmlToStorage(params: {
  admin: ServiceRoleClient;
  componentId: string;
  html: string;
  outputPrefix?: string;
}): Promise<OpenDesignHtmlRasterizeResult> {
  const { openBrowser } = await import("@remotion/renderer");
  const prepared = prepareOpenDesignDeckForHtmlToPng(params.html);

  if (prepared.cleanup.hasSceneControllerResidue) {
    throw new Error("OPEN_DESIGN_CLEANUP_FAILED: quedaron residuos del controlador de escenas.");
  }

  const browser = await openBrowser("chrome", {
    logLevel: "error",
    chromiumOptions: { headless: true },
    forceDeviceScaleFactor: 1,
  });
  const images: RenderableSlideAsset[] = [];
  const outputPrefix = params.outputPrefix || `slides/${params.componentId}-html-slide`;

  try {
    for (const slide of prepared.slides) {
      const page = await (browser as any).newPage({
        context: undefined,
        logLevel: "error",
        indent: false,
        pageIndex: slide.index,
        onBrowserLog: undefined,
        onLog: undefined,
      });

      try {
        await page.setViewport({
          width: slide.width,
          height: slide.height,
          deviceScaleFactor: 1,
        });
        await page.goto({
          url: dataUrl(slide.html),
          timeout: 30000,
          options: {},
        });
        await page.evaluate(() =>
          document.fonts?.ready ? document.fonts.ready : Promise.resolve(),
        );
        await wait(250);

        const response = await page._client().send("Page.captureScreenshot", {
          format: "png",
          fromSurface: true,
          captureBeyondViewport: false,
          clip: {
            x: 0,
            y: 0,
            width: slide.width,
            height: slide.height,
            scale: 1,
          },
        }) as any;
        const base64 = response.value?.data || response.data;
        const png = Buffer.from(base64, "base64");
        const storagePath = `${outputPrefix}-${pad2(slide.index)}.png`;

        const { error } = await params.admin.storage
          .from(BUCKET)
          .upload(storagePath, png, {
            contentType: "image/png",
            upsert: true,
          });

        if (error) {
          throw new Error(`No se pudo guardar la slide ${slide.index}: ${error.message}`);
        }

        const {
          data: { publicUrl },
        } = params.admin.storage.from(BUCKET).getPublicUrl(storagePath);

        images.push({
          file_name: storagePath.split("/").pop(),
          slide_index: slide.index,
          storage_path: `${BUCKET}/${storagePath}`,
          public_url: publicUrl,
          content_type: "image/png",
        });
      } finally {
        await page.close();
      }
    }
  } finally {
    await browser.close({ silent: true });
  }

  return {
    images,
    cleanup: prepared.cleanup,
  };
}

export async function rasterizeStoredOpenDesignHtmlSlides(params: {
  admin: ServiceRoleClient;
  componentId: string;
  htmlStoragePath: string;
  deleteSourceHtml?: boolean;
}): Promise<OpenDesignHtmlRasterizeResult> {
  const storagePath = normalizeProductionAssetStoragePath(params.htmlStoragePath);
  const { data, error } = await params.admin.storage
    .from(BUCKET)
    .download(storagePath);

  if (error || !data) {
    throw new Error(`No se pudo descargar el HTML de slides: ${error?.message || "archivo no encontrado"}`);
  }

  const html = await data.text();
  const result = await rasterizeOpenDesignHtmlToStorage({
    admin: params.admin,
    componentId: params.componentId,
    html,
  });

  if (params.deleteSourceHtml ?? true) {
    const { error: removeError } = await params.admin.storage
      .from(BUCKET)
      .remove([storagePath]);

    if (removeError) {
      console.warn("[open-design-html-rasterizer] No se pudo eliminar el HTML fuente:", removeError.message);
    }
  }

  return result;
}

