'use client';

import { useState, useEffect } from 'react';
import { Save, AlertTriangle, CheckCircle2, MessageSquareCode, RotateCcw } from 'lucide-react';
import { SystemPrompt, UpdateSystemPromptDTO } from '../types';
import { getSystemPromptsAction, updateSystemPromptAction, resetPromptToDefaultAction } from '../../../app/admin/settings/actions';
import { STATUS_MESSAGE_DISMISS_DELAY_MS } from '@/shared/constants/timing';

function ResetConfirmModal({
    promptCode,
    onConfirm,
    onCancel,
    loading,
}: {
    promptCode: string;
    onConfirm: () => void;
    onCancel: () => void;
    loading: boolean;
}) {
    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center">
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onCancel} />
            <div className="relative bg-white dark:bg-[var(--engine-surface-solid)] border border-gray-200 dark:border-[var(--engine-muted)]/20 rounded-2xl shadow-2xl p-6 max-w-sm w-full mx-4">
                <div className="flex items-center gap-3 mb-4">
                    <div className="w-10 h-10 rounded-xl bg-amber-500/10 flex items-center justify-center">
                        <RotateCcw className="w-5 h-5 text-amber-500" />
                    </div>
                    <div>
                        <h3 className="font-semibold text-gray-900 dark:text-white text-sm">Restaurar prompt default</h3>
                        <p className="text-xs text-gray-500 dark:text-gray-400">{promptCode}</p>
                    </div>
                </div>
                <p className="text-sm text-gray-600 dark:text-gray-300 mb-6">
                    Se eliminará la versión personalizada de este prompt y se restaurará el default global. Esta acción no puede deshacerse.
                </p>
                <div className="flex gap-3 justify-end">
                    <button
                        onClick={onCancel}
                        disabled={loading}
                        className="px-4 py-2 rounded-lg text-sm font-medium text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5 transition-colors"
                    >
                        Cancelar
                    </button>
                    <button
                        onClick={onConfirm}
                        disabled={loading}
                        className="px-4 py-2 rounded-lg text-sm font-semibold bg-amber-500 hover:bg-amber-400 text-white transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                    >
                        <RotateCcw className="w-3.5 h-3.5" />
                        {loading ? 'Restaurando...' : 'Restaurar default'}
                    </button>
                </div>
            </div>
        </div>
    );
}

export function SystemPromptsManager() {
    const [prompts, setPrompts] = useState<SystemPrompt[]>([]);
    const [selectedPromptId, setSelectedPromptId] = useState<string | null>(null);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [showResetModal, setShowResetModal] = useState(false);
    const [resetting, setResetting] = useState(false);

    // Edit state
    const [content, setContent] = useState('');
    const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

    useEffect(() => {
        loadPrompts();
    }, []);

    useEffect(() => {
        if (selectedPromptId) {
            const prompt = prompts.find(p => p.id === selectedPromptId);
            if (prompt) {
                setContent(prompt.content);
                setMessage(null);
            }
        }
    }, [selectedPromptId, prompts]);

    const loadPrompts = async () => {
        setLoading(true);
        const res = await getSystemPromptsAction();
        if (res.success && res.prompts) {
            setPrompts(res.prompts);
            if (res.prompts.length > 0 && !selectedPromptId) {
                setSelectedPromptId(res.prompts[0].id);
            }
        }
        setLoading(false);
    };

    const handleSave = async () => {
        if (!selectedPromptId) return;

        setSaving(true);
        setMessage(null);
        const promptBeforeSave = prompts.find(p => p.id === selectedPromptId);

        const updateDTO: UpdateSystemPromptDTO = {
            id: selectedPromptId,
            content: content
        };

        const res = await updateSystemPromptAction(updateDTO);

        if (res.success && res.prompt) {
            setPrompts(prev => prev.map(p => {
                const isSavedPrompt = p.id === selectedPromptId
                    || (promptBeforeSave && p.code === promptBeforeSave.code && p.version === promptBeforeSave.version);

                return isSavedPrompt ? { ...res.prompt!, is_org_override: true } : p;
            }));
            setSelectedPromptId(res.prompt.id);
            setMessage({ type: 'success', text: 'Prompt actualizado correctamente.' });
            setTimeout(() => setMessage(null), STATUS_MESSAGE_DISMISS_DELAY_MS);
        } else {
            setMessage({ type: 'error', text: res.error || 'Error al guardar.' });
        }
        setSaving(false);
    };

    const handleResetConfirm = async () => {
        if (!selectedPrompt) return;
        setResetting(true);
        const res = await resetPromptToDefaultAction(selectedPrompt.code);
        if (res.success) {
            setShowResetModal(false);
            await loadPrompts();
            setMessage({ type: 'success', text: 'Prompt restaurado al default global.' });
            setTimeout(() => setMessage(null), STATUS_MESSAGE_DISMISS_DELAY_MS);
        } else {
            setMessage({ type: 'error', text: res.error || 'Error al restaurar.' });
        }
        setResetting(false);
    };

    const selectedPrompt = prompts.find(p => p.id === selectedPromptId);

    if (loading) {
        return <div className="p-8 text-center text-gray-500">Cargando prompts...</div>;
    }

    if (prompts.length === 0) {
        return (
             <div className="p-8 text-center border mr-6 rounded-xl border-dashed border-gray-300 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/30">
                <AlertTriangle className="mx-auto h-8 w-8 text-yellow-500 mb-2" />
                <p className="text-gray-500 dark:text-gray-400">No hay prompts de sistema configurados en la base de datos.</p>
            </div>
        );
    }

    return (
        <>
            {showResetModal && selectedPrompt && (
                <ResetConfirmModal
                    promptCode={selectedPrompt.code}
                    onConfirm={handleResetConfirm}
                    onCancel={() => setShowResetModal(false)}
                    loading={resetting}
                />
            )}

            <div className="bg-white dark:bg-[var(--engine-surface-solid)] border border-gray-200 dark:border-[var(--engine-muted)]/10 rounded-2xl overflow-hidden flex flex-col md:flex-row min-h-[500px] shadow-sm">
                {/* Sidebar List */}
                <div className="w-full md:w-64 border-r border-gray-200 dark:border-[var(--engine-muted)]/10 bg-gray-50 dark:bg-[var(--engine-canvas)]/50 flex flex-col">
                    <div className="p-4 border-b border-gray-200 dark:border-[var(--engine-muted)]/10">
                        <h3 className="text-sm font-bold text-gray-500 dark:text-[var(--engine-text-muted)] uppercase tracking-wider">Prompts Disponibles</h3>
                    </div>
                    <div className="overflow-y-auto flex-1 p-2 space-y-1">
                        {prompts.map(prompt => (
                            <button
                                key={prompt.id}
                                onClick={() => setSelectedPromptId(prompt.id)}
                                className={`w-full text-left px-3 py-2.5 rounded-lg text-sm font-medium transition-all ${
                                    selectedPromptId === prompt.id
                                        ? 'bg-[var(--engine-accent)]/10 text-[var(--engine-accent)] shadow-sm'
                                        : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5 hover:text-gray-900 dark:hover:text-gray-200'
                                }`}
                            >
                                <div className="flex items-center gap-2">
                                    <span className="truncate flex-1">{prompt.code}</span>
                                    {prompt.is_org_override && (
                                        <span className="w-2 h-2 rounded-full bg-amber-400 flex-shrink-0" title="Versión personalizada" />
                                    )}
                                </div>
                                <div className="text-xs opacity-60 truncate font-normal mt-0.5">{prompt.description || 'Sin descripción'}</div>
                            </button>
                        ))}
                    </div>
                </div>

                {/* Editor Area */}
                <div className="flex-1 flex flex-col bg-white dark:bg-[var(--engine-surface-solid)]">
                    {selectedPrompt ? (
                        <>
                            <div className="p-4 border-b border-gray-200 dark:border-[var(--engine-muted)]/10 flex justify-between items-center bg-white dark:bg-[var(--engine-canvas)]/30">
                               <div>
                                    <h3 className="text-gray-900 dark:text-white font-semibold flex items-center gap-2">
                                        <MessageSquareCode size={18} className="text-[var(--engine-accent)]" />
                                        {selectedPrompt.code} v{selectedPrompt.version}
                                        {selectedPrompt.is_org_override && (
                                            <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-amber-500/10 text-amber-500 border border-amber-500/20">
                                                Personalizado
                                            </span>
                                        )}
                                    </h3>
                                    <p className="text-xs text-gray-500 dark:text-[var(--engine-text-muted)] mt-0.5">{selectedPrompt.description}</p>
                               </div>
                               <div className="flex items-center gap-3">
                                    {/* Status Message */}
                                    {message && (
                                        <div className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium animate-in fade-in slide-in-from-right-2 ${
                                            message.type === 'success' ? 'bg-green-500/10 text-green-600 dark:text-green-400' : 'bg-red-500/10 text-red-600 dark:text-red-400'
                                        }`}>
                                            {message.type === 'success' ? <CheckCircle2 size={12} /> : <AlertTriangle size={12} />}
                                            {message.text}
                                        </div>
                                    )}

                                    {selectedPrompt.is_org_override && (
                                        <button
                                            onClick={() => setShowResetModal(true)}
                                            className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium text-amber-600 dark:text-amber-400 border border-amber-500/30 hover:bg-amber-500/10 transition-colors"
                                        >
                                            <RotateCcw size={14} />
                                            <span>Restaurar default</span>
                                        </button>
                                    )}

                                    <button
                                        onClick={handleSave}
                                        disabled={saving}
                                        className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
                                            saving
                                                ? 'bg-gray-200 dark:bg-gray-700 text-gray-400 cursor-not-allowed'
                                                : 'bg-[var(--engine-accent)] text-white dark:text-black hover:bg-[var(--engine-accent)]/90 shadow-lg shadow-[var(--engine-accent)]/10'
                                        }`}
                                    >
                                        {saving ? (
                                            <><span>Guardando...</span></>
                                        ) : (
                                            <><Save size={16} /><span>Guardar</span></>
                                        )}
                                    </button>
                               </div>
                            </div>

                            <div className="flex-1 p-0 relative">
                                 <textarea
                                    value={content}
                                    onChange={(e) => setContent(e.target.value)}
                                    className="w-full h-full bg-white dark:bg-[var(--engine-canvas)] text-gray-900 dark:text-gray-300 font-mono text-sm p-6 resize-none focus:outline-none focus:ring-1 focus:ring-[var(--engine-accent)]/30 leading-relaxed"
                                    spellCheck={false}
                                    placeholder="Escribe aquí el contenido del prompt..."
                                />
                            </div>
                            <div className="px-4 py-2 bg-gray-50 dark:bg-[var(--engine-canvas)] border-t border-gray-200 dark:border-[var(--engine-muted)]/10 text-xs text-gray-500 dark:text-[var(--engine-text-muted)] flex justify-between">
                                <span>
                                    {selectedPrompt.is_org_override
                                        ? 'Versión personalizada para esta organización'
                                        : 'Versión global (default)'}
                                </span>
                                <span>Última actualización: {new Date(selectedPrompt.updated_at).toLocaleDateString()}</span>
                            </div>
                        </>
                    ) : (
                         <div className="flex-1 flex flex-col items-center justify-center text-gray-400 dark:text-gray-500">
                            <MessageSquareCode size={48} className="mb-4 opacity-20" />
                            <p>Selecciona un prompt para editar</p>
                        </div>
                    )}
                </div>
            </div>
        </>
    );
}

import { useCallback, useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { Loader2 } from "lucide-react";
import { UpstreamChangeAlert } from "@/shared/components/UpstreamChangeAlert";
import {
  dismissUpstreamDirtyAction,
  markDownstreamDirtyAction,
} from "@/lib/server/pipeline-dirty-actions";
import { REVIEWER_ROLE_SET, SYLLABUS_STATES } from "@/lib/pipeline-constants";
import { syllabusService } from "@/domains/syllabus/services/syllabus.service";
import {
  Esp02Route,
  Esp02StepState,
  SyllabusModule,
  SyllabusRow,
  TemarioEsp02,
} from "../types/syllabus.types";
import { SyllabusGenerationHeader } from "./SyllabusGenerationHeader";
import { SyllabusObjectivesAccordion } from "./SyllabusObjectivesAccordion";
import { SyllabusReviewPanel } from "./SyllabusReviewPanel";
import { SyllabusSetupPanel } from "./SyllabusSetupPanel";
import { SyllabusStatusPanel } from "./SyllabusStatusPanel";
import { SyllabusViewer } from "./SyllabusViewer";
import { SyllabusImportPanel } from "./SyllabusImportPanel";
import {
  canIterateSyllabus,
  normalizeSyllabusIterationCount,
  SYLLABUS_MAX_ITERATIONS,
} from "../lib/syllabus-iteration";
import type { SyllabusSourceDocument } from "../syllabus-source-documents";

interface SyllabusProfile {
  platform_role?: string | null;
}

interface SyllabusGenerationContainerProps {
  artifactId: string;
  initialObjetivos: string[];
  initialIdeaCentral: string;
  onNext?: () => void;
  profile?: SyllabusProfile | null;
  className?: string;
}

function buildTemarioForReview(
  temario: TemarioEsp02 | SyllabusRow,
  route: Esp02Route | null,
  objetivos: string[],
): TemarioEsp02 {
  const validation = syllabusService.validateTemario(temario, objetivos);

  return {
    ...temario,
    route: temario.route || route || "B_NO_SOURCE",
    validation: {
      automatic_pass: Boolean(validation.passed),
      checks: validation.checks,
    },
    qa: temario.qa || { status: "PENDING" },
  };
}

export function SyllabusGenerationContainer({
  artifactId,
  initialObjetivos,
  initialIdeaCentral,
  onNext,
  profile,
  className = "",
}: SyllabusGenerationContainerProps) {
  const router = useRouter();
  const [route, setRoute] = useState<Esp02Route | null>("B_NO_SOURCE");
  const [status, setStatus] = useState<Esp02StepState>("STEP_DRAFT");
  const [temario, setTemario] = useState<TemarioEsp02 | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [reviewNotes, setReviewNotes] = useState("");
  const [loading, setLoading] = useState(false);
  const [isObjectivesOpen, setIsObjectivesOpen] = useState(false);
  const [iterationCount, setIterationCount] = useState(0);
  const [hasExistingSyllabus, setHasExistingSyllabus] = useState(false);
  const [sourceDocuments, setSourceDocuments] = useState<SyllabusSourceDocument[]>([]);
  const [documentsUploading, setDocumentsUploading] = useState(false);
  const [importAvailable, setImportAvailable] = useState(false);
  const [useProvidedSyllabus, setUseProvidedSyllabus] = useState(false);
  const [configuredPrompt, setConfiguredPrompt] = useState("");
  const [prompt, setPrompt] = useState("");
  const [promptError, setPromptError] = useState<string | null>(null);
  const [promptLoading, setPromptLoading] = useState(true);
  const [promptReloadKey, setPromptReloadKey] = useState(0);
  const [promptSource, setPromptSource] = useState<
    "organization" | "global" | "default" | null
  >(null);
  const [promptVersion, setPromptVersion] = useState<string | null>(null);

  const getPromptOverride = () => {
    const trimmedPrompt = prompt.trim();
    return trimmedPrompt && trimmedPrompt !== configuredPrompt.trim()
      ? trimmedPrompt
      : undefined;
  };

  const applyTemario = (generatedTemario: TemarioEsp02 | SyllabusRow) => {
    const nextTemario = buildTemarioForReview(
      generatedTemario,
      route,
      initialObjetivos,
    );

    setTemario(nextTemario);
    setHasExistingSyllabus(true);
    setRoute(nextTemario.route);
    setStatus(generatedTemario.state || "STEP_READY_FOR_QA");
    if (generatedTemario.iteration_count !== undefined) {
      setIterationCount(
        normalizeSyllabusIterationCount(generatedTemario.iteration_count),
      );
    }
    setError(null);
  };

  const handleIterate = async () => {
    if (temario?.input_mode === "PROVIDED_SYLLABUS") { setUseProvidedSyllabus(true); return; }
    if (!route || status === "STEP_GENERATING") {
      return;
    }

    if (!canIterateSyllabus(iterationCount)) {
      setError(
        `El temario alcanzo el limite de ${SYLLABUS_MAX_ITERATIONS} iteraciones.`,
      );
      return;
    }

    const previousStatus = status;
    setStatus("STEP_GENERATING");
    setError(null);

    try {
      await syllabusService.startGeneration({
        artifactId,
        route,
        objetivos: initialObjetivos,
        ideaCentral: initialIdeaCentral,
        iterationInstructions: reviewNotes.trim() || undefined,
        promptOverride: getPromptOverride(),
        sourceDocuments: route === "A_WITH_SOURCE" ? sourceDocuments : undefined,
      });
      await markDownstreamDirtyAction(artifactId, 2, "Temario");
    } catch (iterationError) {
      setError(
        iterationError instanceof Error
          ? iterationError.message
          : "No se pudo iterar el temario.",
      );
      setStatus(previousStatus);
    }
  };

  const handleGenerate = async () => {
    if (temario?.input_mode === "PROVIDED_SYLLABUS") { setUseProvidedSyllabus(true); return; }
    if (!route) {
      return;
    }
    if (route === "A_WITH_SOURCE" && sourceDocuments.length === 0) {
      setError("Agrega al menos un documento para generar el temario basado en fuentes.");
      return;
    }

    setStatus("STEP_GENERATING");
    setError(null);

    try {
      const result = await syllabusService.startGeneration({
        artifactId,
        route,
        objetivos: initialObjetivos,
        ideaCentral: initialIdeaCentral,
        promptOverride: getPromptOverride(),
        sourceDocuments: route === "A_WITH_SOURCE" ? sourceDocuments : undefined,
      });

      if ("modules" in result && Array.isArray(result.modules)) {
        applyTemario(result);
      }
    } catch (generationError) {
      setError(
        generationError instanceof Error
          ? generationError.message
          : "No se pudo generar el temario.",
      );
      setStatus("STEP_ESCALATED");
    }
  };

  const handleDismissAlert = async () => {
    try {
      await dismissUpstreamDirtyAction("syllabus", artifactId);
      setTemario((currentTemario) =>
        currentTemario
          ? { ...currentTemario, upstream_dirty: false }
          : currentTemario,
      );
    } catch (dismissError) {
      setError(
        dismissError instanceof Error
          ? dismissError.message
          : "No se pudo descartar el aviso.",
      );
    }
  };

  const handleSaveModules = async (modules: SyllabusModule[]) => {
    if (!temario) {
      return;
    }

    // Keep the saved view intact on failure; the viewer retains the editable draft.
    setError(null);
    await syllabusService.updateModules(artifactId, modules);
    setTemario(buildTemarioForReview({ ...temario, modules }, route, initialObjetivos));

    try {
      await markDownstreamDirtyAction(artifactId, 2, "Temario");
    } catch {
      setError(
        "El temario se guardó, pero no se pudo avisar a las fases siguientes del cambio. Revisa su contenido antes de continuar.",
      );
    }
  };

  const handleApprove = async () => {
    try {
      await syllabusService.updateStatus(
        artifactId,
        "STEP_APPROVED",
        reviewNotes,
      );
      setStatus("STEP_APPROVED");
      router.refresh();
    } catch (approveError) {
      setError(
        approveError instanceof Error
          ? approveError.message
          : "No se pudo aprobar el temario.",
      );
    }
  };

  const handleReject = async () => {
    try {
      await syllabusService.updateStatus(
        artifactId,
        "STEP_REJECTED",
        reviewNotes,
      );
      setStatus("STEP_REJECTED");
      router.refresh();
    } catch (rejectError) {
      setError(
        rejectError instanceof Error
          ? rejectError.message
          : "No se pudo rechazar el temario.",
      );
    }
  };

  const handleReset = async () => {
    if (
      !confirm(
        "¿Estás seguro de que quieres eliminar este temario y volver a generarlo?",
      )
    ) {
      return;
    }

    try {
      await syllabusService.deleteSyllabusContent(artifactId);
      setTemario(null);
      setHasExistingSyllabus(false);
      setStatus("STEP_DRAFT");
      setReviewNotes("");
      setRoute(null);
      setSourceDocuments([]);
      setUseProvidedSyllabus(false);
      setError(null);
      setIterationCount(0);
    } catch (resetError) {
      setError(
        resetError instanceof Error
          ? resetError.message
          : "No se pudo reiniciar el temario.",
      );
    }
  };

  useEffect(() => {
    const checkExisting = async () => {
      setLoading(true);

      try {
        const data = await syllabusService.getSyllabus(artifactId);
        if (data) {
          setHasExistingSyllabus(true);
          setIterationCount(
            normalizeSyllabusIterationCount(data.iteration_count),
          );
          setRoute(data.route || "B_NO_SOURCE");
          setUseProvidedSyllabus(data.input_mode === "PROVIDED_SYLLABUS");
          setSourceDocuments(data.source_summary?.source_documents || []);
          if (data.state === SYLLABUS_STATES.ESCALATED) {
            setError(
              data.source_summary?.error ||
                "La iteración del temario terminó con un error.",
            );
          }
        }
        if (data?.modules?.length) {
          applyTemario(data);
        } else if (data?.state === SYLLABUS_STATES.GENERATING) {
          setStatus(SYLLABUS_STATES.GENERATING);
        } else if (data?.state) {
          setStatus(data.state);
        }
      } catch {
        // Ignorar error si el syllabus aún no existe.
      } finally {
        setLoading(false);
      }
    };

    void checkExisting();
  }, [artifactId]);

  useEffect(() => {
    const controller = new AbortController();
    void fetch(`/api/syllabus/imports?artifactId=${encodeURIComponent(artifactId)}`, { signal: controller.signal })
      .then(response => response.ok ? response.json() : null)
      .then(payload => { if (!controller.signal.aborted) setImportAvailable(Boolean(payload?.enabled)); })
      .catch(() => { /* Existing generation remains available if import setup is unavailable. */ });
    return () => controller.abort();
  }, [artifactId]);

  const reloadImportedSyllabus = useCallback(async () => {
    const current = await syllabusService.getSyllabus(artifactId);
    if (current?.modules.length) {
      setTemario(buildTemarioForReview(current, current.route, initialObjetivos));
      setStatus(current.state);
      setHasExistingSyllabus(true);
      setRoute(current.route);
      router.refresh();
    }
  }, [artifactId, initialObjetivos, router]);

  useEffect(() => {
    let cancelled = false;

    const loadPrompt = async () => {
      setPromptLoading(true);
      setPromptError(null);
      try {
        const resolvedPrompt = await syllabusService.getGenerationPrompt(artifactId);
        if (cancelled) return;
        setConfiguredPrompt(resolvedPrompt.content);
        setPrompt(resolvedPrompt.content);
        setPromptSource(resolvedPrompt.source);
        setPromptVersion(resolvedPrompt.version);
      } catch (promptLoadError) {
        if (cancelled) return;
        setPromptError(
          promptLoadError instanceof Error
            ? promptLoadError.message
            : "No se pudo cargar el prompt configurado.",
        );
      } finally {
        if (!cancelled) setPromptLoading(false);
      }
    };

    void loadPrompt();
    return () => {
      cancelled = true;
    };
  }, [artifactId, promptReloadKey]);

  useEffect(() => {
    if (status !== "STEP_GENERATING") {
      return undefined;
    }

    let disposed = false;
    let inFlight = false;
    const poll = async () => {
      if (disposed || inFlight) return;
      inFlight = true;
      try {
        const data = await syllabusService.getSyllabus(artifactId);
        if (disposed) return;
        if (data) {
          setHasExistingSyllabus(true);
          setIterationCount(
            normalizeSyllabusIterationCount(data.iteration_count),
          );
          if (data.state === SYLLABUS_STATES.ESCALATED) {
            setError(
              data.source_summary?.error ||
                "La iteración del temario terminó con un error.",
            );
          }
        }
        if (data?.modules?.length) {
          applyTemario(data);
        } else if (data?.state && data.state !== SYLLABUS_STATES.GENERATING) {
          setStatus(data.state);
        }
      } catch (pollingError) {
        if (!disposed && pollingError instanceof Error) {
          setError(pollingError.message);
        }
      } finally {
        inFlight = false;
      }
    };
    void poll();
    const interval = setInterval(() => void poll(), 3000);

    return () => {
      disposed = true;
      clearInterval(interval);
    };
  }, [artifactId, status]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
      </div>
    );
  }

  return (
    <div className={`space-y-6 max-w-5xl mx-auto pb-20 ${className}`}>
      {temario?.upstream_dirty && (
        <UpstreamChangeAlert
          source={temario.upstream_dirty_source || "la idea central"}
          onIterate={handleGenerate}
          onDismiss={handleDismissAlert}
          isIterating={status === "STEP_GENERATING"}
        />
      )}

      <SyllabusGenerationHeader
        ideaCentral={initialIdeaCentral}
        iterationCount={iterationCount}
        iterationLimit={SYLLABUS_MAX_ITERATIONS}
        canIterate={canIterateSyllabus(iterationCount)}
        isIterating={status === "STEP_GENERATING"}
        onIterate={
