}

export async function assertArtifactOrgAccess(
  artifactId: string,
  activeOrgId: string | null,
  tenantContext?: Pick<TenantContext, "organizationId"> | null,
) {
  if (tenantContext?.organizationId && activeOrgId && tenantContext.organizationId !== activeOrgId) return null;
  const requestedOrganizationId = tenantContext?.organizationId ?? activeOrgId;
  const tenant = requestedOrganizationId
    ? await resolveTenantContextByOrganizationId(requestedOrganizationId)
    : await resolveActiveTenantContext();
  if (!tenant) return null;

  const admin = getServiceRoleClient();
  const { data, error } = await admin
    .from("artifacts")
    .select("id, organization_id")
    .eq("id", artifactId)
    .eq("organization_id", tenant.organizationId)
    .maybeSingle();
  if (error) {
    console.error("[ArtifactAccess] No se pudo verificar el acceso al artefacto.");
    return null;
  }
  return data?.organization_id === tenant.organizationId ? data : null;
}

export async function getAuthorizedArtifactAdmin(artifactId: string) {
  const tenantContext = await resolveActiveTenantContext();
  if (!tenantContext) return null;
  const artifact = await assertArtifactOrgAccess(
    artifactId,
    tenantContext.organizationId,
    tenantContext,
  );

  if (!artifact) {
    return null;
  }

  return {
    admin: getServiceRoleClient(),
    artifact,
  };
}

export async function getAuthorizedArtifactAdminForTenant(
  artifactId: string,
  tenantContext: Pick<TenantContext, "organizationId">,
) {
  const artifact = await assertArtifactOrgAccess(
    artifactId,
    tenantContext.organizationId,
    tenantContext,
  );

  if (!artifact) {
    return null;
  }

  return {
    admin: getServiceRoleClient(),
    artifact,
  };
}

export async function getAuthorizedCurationRowAdmin(rowId: string) {
  const tenant = await resolveActiveTenantContext();
  if (!tenant) return null;
  const admin = getServiceRoleClient();
  const { data: row, error } = await admin
    .from("curation_rows")
    .select("id, curation_id, curation!inner(artifact_id, artifacts!inner(organization_id))")
    .eq("id", rowId)
    .eq("curation.artifacts.organization_id", tenant.organizationId)
    .maybeSingle();
  if (error) {
    console.error("[CurationRowAccess] No se pudo consultar la fila autorizada.");
    return null;
  }
  const curation = Array.isArray(row?.curation) ? row.curation[0] : row?.curation;
  if (!row?.curation_id || !curation?.artifact_id) return null;
  const authorized = await getAuthorizedArtifactAdminForTenant(curation.artifact_id, tenant);
  if (!authorized) return null;
  return {
    admin,
    row: { id: row.id, curation_id: row.curation_id },
    artifactId: curation.artifact_id,
  };
}

interface MaterialComponentAdminRow {
  assets?: Record<string, any> | null;
  content?: unknown;
  id: string;
  material_lesson_id?: string | null;
  material_lessons?:
    | {
        materials?:
          | {
              artifact_id?: string | null;
            }
          | Array<{
              artifact_id?: string | null;
            }>
          | null;
      }
    | Array<{
        materials?:
          | {
              artifact_id?: string | null;
            }
          | Array<{
              artifact_id?: string | null;
            }>
          | null;
      }>
    | null;
  type?: string | null;
}

export class MaterialComponentLookupUnavailableError extends Error {
  readonly code = "MATERIAL_COMPONENT_LOOKUP_UNAVAILABLE";
  readonly retryable = true;

  constructor() {
    super("No se pudo consultar temporalmente el componente. Intenta de nuevo.");
    this.name = "MaterialComponentLookupUnavailableError";
  }
}

function getArtifactIdFromComponent(component: MaterialComponentAdminRow) {
  const lessonRelation = Array.isArray(component.material_lessons)
    ? component.material_lessons[0]
    : component.material_lessons;
  const materialsRelation = Array.isArray(lessonRelation?.materials)
    ? lessonRelation.materials[0]
    : lessonRelation?.materials;

  return materialsRelation?.artifact_id || null;
}

export async function getAuthorizedMaterialComponentAdmin(componentId: string) {
  const tenant = await resolveActiveTenantContext();
  if (!tenant) return null;
  return loadAuthorizedMaterialComponent(componentId, tenant.organizationId, true);
}

export async function getAuthorizedMaterialComponentAdminForTenant(
  componentId: string,
  organizationId: string,
) {
  const tenant = await resolveTenantContextByOrganizationId(organizationId);
  if (!tenant) return null;
  return loadAuthorizedMaterialComponent(componentId, tenant.organizationId, false);
}

async function loadAuthorizedMaterialComponent(
  componentId: string,
  organizationId: string,
  throwOnLookupError: boolean,
) {
  const admin = getServiceRoleClient();
  const { data: component, error } = await admin
    .from("material_components")
    .select(
      `
        id,
        type,
        content,
        assets,
        material_lesson_id,
        material_lessons!inner (
          materials!inner (
            artifact_id,
            artifacts!inner ( organization_id )
          )
        )
      `,
    )
    .eq("id", componentId)
    .eq("material_lessons.materials.artifacts.organization_id", organizationId)
    .maybeSingle();

  if (error || !component) {
    if (error) {
      console.error("[MaterialComponentAccess] No se pudo consultar el componente autorizado.");
      if (throwOnLookupError) throw new MaterialComponentLookupUnavailableError();
    }
    return null;
  }

  const normalizedComponent = component as MaterialComponentAdminRow;
  const artifactId = getArtifactIdFromComponent(normalizedComponent);
  if (!artifactId) return null;

  const authorized = await getAuthorizedArtifactAdminForTenant(artifactId, { organizationId });
  if (!authorized) return null;
  return { admin, artifactId, component: normalizedComponent };
}

"use server";

import { getBackgroundFunctionsBaseUrl } from "@/lib/server/artifact-action-auth";
import {
  signBackgroundPayload,
  type SignedBackgroundPayload,
} from "@/lib/server/background-payload-signature";
import { buildLocalBackgroundHandlerUrl } from "@/lib/server/background-request-environment";
import { isProductionEnvironment } from "@/lib/server/env";
import { PIPELINE_GENERATION_LIMITS } from "../pipeline-generation-policy";

type BackgroundFunctionPayload = Record<string, unknown>;

type LocalFunctionEvent = {
  body: string;
  headers: Record<string, string>;
  httpMethod: string;
  multiValueHeaders?: Record<string, string[]>;
  multiValueQueryStringParameters?: Record<string, string[]>;
  path?: string;
  queryStringParameters?: Record<string, string>;
  rawQuery?: string;
  rawUrl?: string;
};

type LocalFunctionResponse = {
  body?: string;
  headers?: Record<string, string | number | boolean>;
  statusCode?: number;
};

type LocalFunctionModule = Record<string, unknown>;

interface BackgroundFunctionOptions {
  fallbackError: string;
  localHandlerLoader?: () => Promise<LocalFunctionModule>;
  onFailure?: (error: unknown) => Promise<void>;
}


function ensureSignedPayload(
  payload: BackgroundFunctionPayload,
): SignedBackgroundPayload {
  if (
    typeof payload.payload === "string" &&
    typeof payload.signature === "string"
  ) {
    return payload as SignedBackgroundPayload;
  }

  return signBackgroundPayload(payload);
}

function parseJsonOrText<TData>(rawBody: string): TData | { error?: string; message?: string } {
  if (!rawBody) {
    return {} as TData;
  }

  try {
    return JSON.parse(rawBody) as TData;
  } catch {
    return { message: rawBody };
  }
}

function getResponseErrorMessage(
  data: unknown,
  fallbackError: string,
  statusCode: number,
) {
  if (typeof data === "object" && data !== null) {
    if ("error" in data && typeof data.error === "string" && data.error) {
      return data.error;
    }

    if ("message" in data && typeof data.message === "string" && data.message) {
      return data.message;
    }
  }

  return `${fallbackError} (${statusCode})`;
}

async function parseRemoteResponse<TData>(
  response: Response,
  fallbackError: string,
) {
  const rawBody = await response.text();
  const data = parseJsonOrText<TData>(rawBody);

  if (!response.ok) {
    throw new Error(
      getResponseErrorMessage(data, fallbackError, response.status),
    );
  }

  return data as TData;
}

async function parseLocalResponse<TData>(
  response: LocalFunctionResponse | Response | unknown,
  fallbackError: string,
) {
  if (response instanceof Response) {
    return parseRemoteResponse<TData>(response, fallbackError);
  }

  if (typeof response !== "object" || response === null) {
    throw new Error(fallbackError);
  }

  const normalizedResponse = response as LocalFunctionResponse;
  const statusCode = normalizedResponse.statusCode ?? 200;
  const rawBody = normalizedResponse.body ?? "";
  const data = parseJsonOrText<TData>(rawBody);

  if (statusCode >= 400) {
    throw new Error(getResponseErrorMessage(data, fallbackError, statusCode));
  }

  return data as TData;
}

async function tryLocalHandler<TData>(
  functionName: string,
  payload: BackgroundFunctionPayload,
  options: BackgroundFunctionOptions,
) {
  if (isProductionEnvironment() || !options.localHandlerLoader) {
    return null;
  }

  console.log(`[BackgroundFunctionClient] Running local handler: ${functionName}`);
  const module = await options.localHandlerLoader();
  const localHandler = (module.handler || module.default) as
    | ((
        event: LocalFunctionEvent,
        context: Record<string, unknown>,
      ) => Promise<LocalFunctionResponse | Response | unknown> | LocalFunctionResponse | Response | unknown)
    | undefined;

  if (!localHandler) {
    console.warn(
      `[BackgroundFunctionClient] Local handler not found for ${functionName}; falling back to HTTP.`,
    );
    return null;
  }

  const signedPayload = ensureSignedPayload(payload);
  const localResponse = await localHandler(
    {
      body: JSON.stringify(signedPayload),
      headers: { "Content-Type": "application/json" },
      httpMethod: "POST",
      multiValueHeaders: {},
      multiValueQueryStringParameters: {},
      path: `/.netlify/functions/${functionName}`,
      queryStringParameters: {},
      rawQuery: "",
      rawUrl: buildLocalBackgroundHandlerUrl(functionName),
    },
    {},
  );

  const parsedResponse = await parseLocalResponse<TData>(
    localResponse,
    options.fallbackError,
  );
  console.log(`[BackgroundFunctionClient] Local handler completed: ${functionName}`);
  return parsedResponse;
}

async function fetchRemoteFunction(
  functionName: string,
  payload: BackgroundFunctionPayload,
) {
  const url = `${getBackgroundFunctionsBaseUrl()}/.netlify/functions/${functionName}`;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), functionName.endsWith("-background")
    ? PIPELINE_GENERATION_LIMITS.dispatchTimeoutMs : PIPELINE_GENERATION_LIMITS.requestTimeoutMs);

  try {
    console.log(`[BackgroundFunctionClient] Calling HTTP function: ${url}`);
    return await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(ensureSignedPayload(payload)),
      signal: controller.signal,
    });
  } finally {
    if (timeout) {
      clearTimeout(timeout);
    }
  }
}

export async function callBackgroundFunctionJson<
  TData extends Record<string, unknown> = Record<string, unknown>,
>(
  functionName: string,
  payload: BackgroundFunctionPayload,
  options: BackgroundFunctionOptions,
) {
  const localResult = await tryLocalHandler<TData>(functionName, payload, options);
  if (localResult) {
    return localResult;
  }

  const response = await fetchRemoteFunction(functionName, payload);

  return parseRemoteResponse<TData>(response, options.fallbackError);
}

/** Dispatches a background task without coupling the caller's response time to local execution. */
export async function dispatchBackgroundFunctionJson(
  functionName: string,
  payload: BackgroundFunctionPayload,
  options: BackgroundFunctionOptions,
) {
  if (!isProductionEnvironment() && options.localHandlerLoader) {
    void tryLocalHandler(functionName, payload, options).catch(async (error) => {
      console.error(`[BackgroundFunctionClient] Local handler failed: ${functionName}`, error);
      try {
        await options.onFailure?.(error);
      } catch (persistError) {
        console.error(`[BackgroundFunctionClient] Could not persist failure: ${functionName}`, persistError);
      }
    });
    return;
  }

  await callBackgroundFunctionJson(functionName, payload, options);
}

export class ExternalImportCapacityError extends Error {
  readonly code = "EXTERNAL_IMPORT_CAPACITY";
  readonly retryAfterSeconds = 5;

  constructor(readonly reason: "queue_full" | "wait_timeout") {
    super("La capacidad temporal de importación está ocupada.");
    this.name = "ExternalImportCapacityError";
  }
}

interface QueueEntry {
  cancel: (error: unknown) => void;
  start: () => void;
}

export class BoundedConcurrencyLimiter {
  private active = 0;
  private readonly queue: QueueEntry[] = [];

  constructor(
    private readonly maxConcurrent: number,
    private readonly maxQueued: number,
    private readonly waitTimeoutMilliseconds: number,
  ) {
    if (!Number.isInteger(maxConcurrent) || maxConcurrent <= 0) {
      throw new Error("maxConcurrent debe ser un entero positivo.");
    }
    if (!Number.isInteger(maxQueued) || maxQueued < 0) {
      throw new Error("maxQueued debe ser un entero no negativo.");
    }
    if (!Number.isFinite(waitTimeoutMilliseconds) || waitTimeoutMilliseconds <= 0) {
      throw new Error("waitTimeoutMilliseconds debe ser positivo.");
    }
  }

  snapshot() {
    return { active: this.active, queued: this.queue.length };
  }

  run<T>(task: () => Promise<T>, signal?: AbortSignal): Promise<T> {
    if (signal?.aborted) return Promise.reject(signal.reason);
    if (this.active >= this.maxConcurrent && this.queue.length >= this.maxQueued) {
      return Promise.reject(new ExternalImportCapacityError("queue_full"));
    }

    return new Promise<T>((resolve, reject) => {
      let timer: ReturnType<typeof setTimeout> | undefined;
      let queuedEntry: QueueEntry | undefined;

      const cleanupWaitingState = () => {
        if (timer) clearTimeout(timer);
        if (signal) signal.removeEventListener("abort", onAbort);
      };
      const removeFromQueue = () => {
        if (!queuedEntry) return;
        const index = this.queue.indexOf(queuedEntry);
        if (index >= 0) this.queue.splice(index, 1);
      };
      const cancel = (error: unknown) => {
        removeFromQueue();
        cleanupWaitingState();
        reject(error);
      };
      const onAbort = () => cancel(signal?.reason);
      const start = () => {
        cleanupWaitingState();
        this.active += 1;
        Promise.resolve()
          .then(task)
          .then(resolve, reject)
          .finally(() => {
            this.active -= 1;
            this.drain();
          });
      };

      if (this.active < this.maxConcurrent) {
        start();
        return;
      }

      queuedEntry = { cancel, start };
      this.queue.push(queuedEntry);
      if (signal) signal.addEventListener("abort", onAbort, { once: true });
      timer = setTimeout(
        () => queuedEntry?.cancel(new ExternalImportCapacityError("wait_timeout")),
        this.waitTimeoutMilliseconds,
      );
    });
  }

  private drain() {
    while (this.active < this.maxConcurrent && this.queue.length > 0) {
      this.queue.shift()?.start();
    }
  }
}

export type ExternalImportProvider = "artlist" | "google_drive" | "onedrive";

const providerLimiters = new Map<ExternalImportProvider, BoundedConcurrencyLimiter>();

export function withExternalImportCapacity<T>(
  provider: ExternalImportProvider,
  task: () => Promise<T>,
  signal?: AbortSignal,
) {
  let limiter = providerLimiters.get(provider);
  if (!limiter) {
    limiter = new BoundedConcurrencyLimiter(3, 12, 10_000);
    providerLimiters.set(provider, limiter);
  }
  return limiter.run(task, signal);
}

export function isExternalImportCapacityError(
  error: unknown,
): error is ExternalImportCapacityError {
  return error instanceof ExternalImportCapacityError;
}

import type { MaterialAssets, VoiceClip } from "@/domains/materials/types/materials.types";
import { repairCommonUtf8Mojibake } from "../domains/production/text/mojibake.service";
import type {
  AssemblyAvatarClip,
  AssemblyBrollClip,
  AssemblySlide,
  AssemblyVoiceClip,
} from "./types";
import { durationSecondsToFrames } from "./media-duration";

const DEFAULT_CLIP_SECONDS = 5;
const DEFAULT_SLIDE_SECONDS = 5;
const DEFAULT_BG_MUSIC_VOLUME = 0.15;

export type AssemblyAssetWarningCode =
  | "SLIDES_REFERENCE_NOT_RENDERIZABLE"
  | "INCOMPLETE_VOICE_CLIPS"
  | "NO_RENDERABLE_VISUAL_ASSETS";

export interface AssemblyAssetWarning {
  code: AssemblyAssetWarningCode;
  message: string;
}

export interface NormalizedAssemblyAssets {
  voiceAudioUrl?: string;
  voiceClips: AssemblyVoiceClip[];
  bgMusicUrl?: string;
  bgMusicVolume: number;
  avatarVideoUrl?: string;
  avatarClips: AssemblyAvatarClip[];
  slides: AssemblySlide[];
  deckCss: string;
  deckFonts: { family: string; href: string }[];
  brollClips: AssemblyBrollClip[];
  totalDurationSeconds: number;
  warnings: AssemblyAssetWarning[];
}

export interface AssemblyAssetReadiness {
  hasAnyAssetReference: boolean;
  hasRenderableAssets: boolean;
  hasRenderableVisualAssets: boolean;
  canRender: boolean;
  blockingIssues: AssemblyBlockingIssue[];
  manifest: AssemblyAssetManifest;
  warnings: AssemblyAssetWarning[];
}

export type AssemblyBlockingIssueCode =
  | "SLIDES_REFERENCE_NOT_RENDERIZABLE"
  | "NO_RENDERABLE_ASSETS";

export interface AssemblyBlockingIssue {
  code: AssemblyBlockingIssueCode;
  message: string;
}

export interface AssemblyAssetManifest {
  slideCount: number;
  brollClipCount: number;
  avatarClipCount: number;
  hasAvatarVideo: boolean;
  hasVoiceAudio: boolean;
  hasBackgroundMusic: boolean;
  totalDurationSeconds: number;
}

function isPositiveNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value) && value > 0;
}

function hasSlideReference(assets: MaterialAssets): boolean {
  return Boolean(
      assets.slides_url ||
      assets.slides?.html_public_url ||
      assets.slides?.html_content_path ||
      assets.slides?.animated_deck?.status === "READY_FOR_PREVIEW" ||
      assets.slides?.animated_deck?.status === "READY_FOR_RENDER" ||
      assets.slides?.open_design_project_id,
  );
}

function buildWarnings(params: {
  assets: MaterialAssets;
  slides: AssemblySlide[];
  brollClips: AssemblyBrollClip[];
  avatarClips: AssemblyAvatarClip[];
  voiceClips: AssemblyVoiceClip[];
}) {
  const warnings: AssemblyAssetWarning[] = [];
  const hasNonRenderableSlides =
    hasSlideReference(params.assets) && params.slides.length === 0;

  if (hasNonRenderableSlides) {
    warnings.push({
      code: "SLIDES_REFERENCE_NOT_RENDERIZABLE",
      message:
        "Hay slides cargadas como referencia, pero todavia no existen imagenes renderizables para ensamblado.",
    });
  }

  if ((params.assets.voice_clips?.length || 0) > 0 && params.voiceClips.length === 0) {
    warnings.push({
      code: "INCOMPLETE_VOICE_CLIPS",
      message:
        "Las voces por escena no forman una colección completa y sincronizada; se usará el audio del avatar como respaldo.",
    });
  }

  if (
    params.slides.length === 0 &&
    params.brollClips.length === 0 &&
    params.avatarClips.length === 0
  ) {
    warnings.push({
      code: "NO_RENDERABLE_VISUAL_ASSETS",
      message:
        "No hay recursos visuales renderizables; el preview usara audio/avatar o un fondo neutro.",
    });
  }

  return warnings;
}

function isCompletedAvatarClip(
  clip: NonNullable<MaterialAssets["avatar_clips"]>[number],
) {
  return Boolean(clip?.public_url) && !clip.deleted && (!clip.status || clip.status === "COMPLETED");
}

function normalizeAnimatedSlideClasses(classes: string | undefined) {
  const classList = (classes || "slide").split(/\s+/).filter(Boolean);
  if (!classList.includes("active")) {
    classList.push("active");
  }
  return classList.join(" ");
}

export function normalizeAssemblyAssets(
  assets: MaterialAssets | null | undefined,
  fps: number,
): NormalizedAssemblyAssets {
  const a = assets ?? {};

  const animatedDeck = a.slides?.animated_deck;
  const hasAnimatedDeck =
    animatedDeck?.status === "READY_FOR_PREVIEW" ||
    animatedDeck?.status === "READY_FOR_RENDER";
  const animatedSlides = hasAnimatedDeck
    ? (animatedDeck.slides ?? [])
        .sort((left, right) => left.index - right.index)
        .map((slide, index) => ({
          animationCount: slide.animationCount,
          classes: normalizeAnimatedSlideClasses(slide.classes),
          html: repairCommonUtf8Mojibake(slide.html),
          index,
          kind: "html" as const,
          label: slide.label,
        }))
    : [];
  const imageSlides = (a.slides?.images ?? [])
    .filter((img) => Boolean(img?.public_url))
    .sort((left, right) => left.slide_index - right.slide_index)
    .map((img, index) => ({
      animationCount: 0,
      index,
      kind: "image" as const,
      url: img.public_url,
    }));
  const slides = animatedSlides.length > 0 ? animatedSlides : imageSlides;

  const brollClips = (a.b_roll_clips ?? [])
    .filter((clip) => Boolean(clip?.public_url))
    .map((clip, index) => ({
      url: clip.public_url,
      durationInFrames: durationSecondsToFrames(
        isPositiveNumber(clip.duration) ? clip.duration : DEFAULT_CLIP_SECONDS,
        fps,
      ),
      order: isPositiveNumber(clip.order) ? clip.order : index + 1,
      originalIndex: index,
    }))
    .sort(
      (left, right) =>
        left.order - right.order || left.originalIndex - right.originalIndex,
    )
    .map(({ originalIndex: _originalIndex, ...clip }) => clip);

  const activeSceneSources = (a.avatar_clips ?? [])
    .filter((clip) => !clip.deleted)
    .sort((left, right) => left.order - right.order);
  const completedVoiceByClipId = new Map(
    (a.voice_clips ?? [])
      .filter((clip): clip is VoiceClip & { public_url: string } =>
        clip.status === "COMPLETED" && Boolean(clip.public_url),
      )
      .map((clip) => [clip.clip_id, clip] as const),
  );
  const sceneTimingByClipId = new Map<string, { durationInFrames: number; startInFrames: number }>();
  let sceneCursor = 0;
  for (const scene of activeSceneSources) {
    const voiceClip = completedVoiceByClipId.get(scene.id);
    const durationInFrames = durationSecondsToFrames(
      isPositiveNumber(voiceClip?.duration)
        ? voiceClip.duration
        : isPositiveNumber(scene.duration)
          ? scene.duration
          : DEFAULT_CLIP_SECONDS,
      fps,
    );
    sceneTimingByClipId.set(scene.id, { durationInFrames, startInFrames: sceneCursor });
    sceneCursor += durationInFrames;
  }

  const completedAvatarClipSources = activeSceneSources.filter(isCompletedAvatarClip);
  const avatarClips = completedAvatarClipSources
    .map((clip, index) => ({
      clipId: clip.id,
      url: clip.public_url as string,
      durationInFrames: sceneTimingByClipId.get(clip.id)?.durationInFrames
        || durationSecondsToFrames(
          isPositiveNumber(clip.duration) ? clip.duration : DEFAULT_CLIP_SECONDS,
          fps,
        ),
      order: isPositiveNumber(clip.order) ? clip.order : index + 1,
      startInFrames: sceneTimingByClipId.get(clip.id)?.startInFrames,
      originalIndex: index,
    }))
    .sort(
      (left, right) =>
        left.order - right.order || left.originalIndex - right.originalIndex,
    )
    .map(({ originalIndex: _originalIndex, ...clip }) => clip);

  const voiceClips = activeSceneSources
    .flatMap((avatarClip, index) => {
      const voiceClip = completedVoiceByClipId.get(avatarClip.id);
      if (!voiceClip || (avatarClip.script_hash && voiceClip.script_hash !== avatarClip.script_hash)) {
        return [];
      }
      return {
        clipId: avatarClip.id,
        url: voiceClip.public_url,
        durationInFrames: sceneTimingByClipId.get(avatarClip.id)?.durationInFrames
          || durationSecondsToFrames(
            isPositiveNumber(voiceClip.duration) ? voiceClip.duration : DEFAULT_CLIP_SECONDS,
            fps,
          ),
        order: isPositiveNumber(avatarClip.order) ? avatarClip.order : index + 1,
        startInFrames: sceneTimingByClipId.get(avatarClip.id)?.startInFrames,
      };
    })
    .sort((left, right) => left.order - right.order);

  const explicitBrollTotalSeconds = (a.b_roll_clips ?? [])
    .filter(
      (clip): clip is NonNullable<MaterialAssets["b_roll_clips"]>[number] & { duration: number } =>
        Boolean(clip?.public_url) && isPositiveNumber(clip.duration),
    )
    .reduce((sum, clip) => sum + clip.duration, 0);
  const fallbackBrollTotalSeconds = brollClips.reduce(
    (sum, clip) => sum + clip.durationInFrames / fps,
    0,
  );
  const avatarClipTotalSeconds = avatarClips.length > 0
    ? Math.max(...avatarClips.map((clip) => (clip.startInFrames || 0) + clip.durationInFrames)) / fps
    : 0;
  const voiceClipTotalSeconds = voiceClips.length > 0
    ? Math.max(...voiceClips.map((clip) => (clip.startInFrames || 0) + clip.durationInFrames)) / fps
    : 0;

  const voiceDurationSeconds = a.avatar_generation_mode !== "scene_clips"
    && isPositiveNumber(a.voice_audio?.duration)
    ? a.voice_audio.duration
    : 0;
  const avatarDurationSeconds = isPositiveNumber(a.avatar_video?.duration)
    ? a.avatar_video.duration
    : 0;
  let totalDurationSeconds = 0;

  if (voiceDurationSeconds > 0) {
    totalDurationSeconds = voiceDurationSeconds;
  } else if (voiceClipTotalSeconds > 0) {
    totalDurationSeconds = voiceClipTotalSeconds;
  } else if (
    a.avatar_generation_mode === "scene_clips" &&
    avatarClipTotalSeconds > 0
  ) {
    totalDurationSeconds = avatarClipTotalSeconds;
  } else if (a.avatar_generation_mode === "single_video" && avatarDurationSeconds > 0) {
    totalDurationSeconds = avatarDurationSeconds;
  } else if (!a.avatar_generation_mode && avatarClipTotalSeconds > 0) {
    totalDurationSeconds = avatarClipTotalSeconds;
  } else if (avatarDurationSeconds > 0) {
    totalDurationSeconds = avatarDurationSeconds;
  } else if (explicitBrollTotalSeconds > 0) {
    totalDurationSeconds = explicitBrollTotalSeconds;
  } else if (fallbackBrollTotalSeconds > 0) {
    totalDurationSeconds = fallbackBrollTotalSeconds;
  } else if (slides.length > 0) {
    totalDurationSeconds = slides.length * DEFAULT_SLIDE_SECONDS;
  }

  const warnings = buildWarnings({ assets: a, slides, brollClips, avatarClips, voiceClips });

  return {
    voiceAudioUrl: a.avatar_generation_mode === "scene_clips"
      ? undefined
      : a.voice_audio?.public_url || undefined,
    voiceClips,
    bgMusicUrl: a.background_music?.public_url || undefined,
    bgMusicVolume: a.background_music?.volume_multiplier ?? DEFAULT_BG_MUSIC_VOLUME,
    avatarVideoUrl: a.avatar_generation_mode === "scene_clips"
      ? undefined
      : a.avatar_video?.public_url || undefined,
    avatarClips,
    slides,
    deckCss: animatedSlides.length > 0 ? animatedDeck?.css || "" : "",
    deckFonts: animatedSlides.length > 0
      ? (animatedDeck?.fonts ?? []).map((font) => ({
          family: font.family,
          href: font.href,
        }))
      : [],
    brollClips,
    totalDurationSeconds,
    warnings,
  };
}

export function getAssemblyAssetReadiness(
  assets: MaterialAssets | null | undefined,
  fps: number,
): AssemblyAssetReadiness {
  const a = assets ?? {};
  const normalized = normalizeAssemblyAssets(a, fps);
  const hasRenderableVisualAssets =
    normalized.slides.length > 0 ||
    normalized.brollClips.length > 0 ||
    normalized.avatarClips.length > 0;
  const hasRenderableAssets = Boolean(
      normalized.voiceAudioUrl ||
      normalized.voiceClips.length > 0 ||
      normalized.avatarVideoUrl ||
      normalized.avatarClips.length > 0 ||
      normalized.bgMusicUrl ||
      hasRenderableVisualAssets,
  );
  const hasAnyAssetReference = Boolean(
    hasRenderableAssets ||
      hasSlideReference(a) ||
      a.video_url ||
      a.screencast_url ||
      a.final_video_url ||
      a.b_roll_prompts,
  );
  const blockingIssues: AssemblyBlockingIssue[] = [];
  if (normalized.warnings.some((warning) => warning.code === "SLIDES_REFERENCE_NOT_RENDERIZABLE")) {
    blockingIssues.push({
      code: "SLIDES_REFERENCE_NOT_RENDERIZABLE",
      message:
        "Las diapositivas existen solo como referencia HTML/proyecto. Exportalas a imagenes o prepara el deck animado antes de renderizar.",
    });
  }
  if (!hasRenderableAssets) {
    blockingIssues.push({
      code: "NO_RENDERABLE_ASSETS",
      message:
        "No hay assets renderizables. Sube voz, avatar, diapositivas renderizables o B-roll antes de ensamblar.",
    });
  }

  return {
    hasAnyAssetReference,
    hasRenderableAssets,
    hasRenderableVisualAssets,
    canRender: blockingIssues.length === 0,
    blockingIssues,
    manifest: {
      slideCount: normalized.slides.length,
      brollClipCount: normalized.brollClips.length,
      avatarClipCount: normalized.avatarClips.length,
      hasAvatarVideo: Boolean(normalized.avatarVideoUrl),
      hasVoiceAudio: Boolean(normalized.voiceAudioUrl || normalized.voiceClips.length > 0),
      hasBackgroundMusic: Boolean(normalized.bgMusicUrl),
      totalDurationSeconds: normalized.totalDurationSeconds,
    },
    warnings: normalized.warnings,
  };
}

import type { CSSProperties } from "react";
import {
  AbsoluteFill,
  Freeze,
  Sequence,
  interpolate,
  useCurrentFrame,
} from "remotion";
import { Video } from "@remotion/media";
import type { AssemblyAvatarClip } from "../types";
import type { LayoutOverrideStyle } from "../layout-override-styles";
import type { VisualTimelineSegment } from "../visual-timeline";
import { REMOTE_MEDIA_RENDER_PROPS } from "../media-rendering.config";
import {
  getAvatarClipCrossfadeFrames,
  getAvatarSegmentCrossfadeFrames,
} from "../avatar-clip-transitions";
import { resolveSafeRemoteVideoRange } from "../remote-video-source-range";

interface AvatarClipLayerProps {
  clips: AssemblyAvatarClip[];
  muted: boolean;
  objectFit?: CSSProperties["objectFit"];
  style?: CSSProperties;
  segments?: VisualTimelineSegment[];
  getClipStyle?: (clip: AssemblyAvatarClip) => LayoutOverrideStyle;
}

function AvatarClipVideo({
  clip,
  durationInFrames,
  fadeInFrames = 0,
  fadeOutFrames = 0,
  muted,
  objectFit,
  segment,
  style,
}: {
  clip: AssemblyAvatarClip;
  durationInFrames: number;
  fadeInFrames?: number;
  fadeOutFrames?: number;
  muted: boolean;
  objectFit: CSSProperties["objectFit"];
  segment?: VisualTimelineSegment;
  style?: CSSProperties;
}) {
  const frame = useCurrentFrame();
  const sourceRange = resolveSafeRemoteVideoRange({
    sourceStartFrame: segment?.sourceStartFrame,
    sourceEndFrame: segment?.sourceEndFrame,
    fallbackDurationInFrames: clip.durationInFrames,
    sequenceDurationInFrames: durationInFrames,
  });
  const fadeInOpacity =
    fadeInFrames > 0
      ? interpolate(frame, [0, fadeInFrames], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        })
      : 1;
  const fadeOutOpacity =
    fadeOutFrames > 0
      ? interpolate(
          frame,
          [Math.max(0, durationInFrames - fadeOutFrames), durationInFrames - 1],
          [1, 0],
          {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          },
        )
      : 1;
  const opacity = Math.min(fadeInOpacity, fadeOutOpacity);

  const video = (
    <Video
      {...REMOTE_MEDIA_RENDER_PROPS}
      src={clip.url}
      muted={muted}
      volume={muted ? 0 : opacity}
      trimBefore={sourceRange.sourceStartFrame}
      trimAfter={sourceRange.sourceEndFrame}
      onError={(err) => {
        console.warn("[Remotion preview] Clip de avatar no reproducible:", clip.url, err);
        return "fallback";
      }}
      style={{ width: "100%", height: "100%", objectFit, opacity, ...style }}
    />
  );

  if (sourceRange.tailFreezeInFrames <= 0) {
    return video;
  }

  return (
    <>
      <Sequence from={0} durationInFrames={sourceRange.sourceDurationInFrames}>
        {video}
      </Sequence>
      <Sequence
        from={sourceRange.sourceDurationInFrames}
        durationInFrames={sourceRange.tailFreezeInFrames}
      >
        <Freeze frame={sourceRange.sourceDurationInFrames - 1}>{video}</Freeze>
      </Sequence>
    </>
  );
}

/** Reproduce clips de avatar en secuencia, respetando la duracion real de cada clip. */
export function AvatarClipLayer({
  clips,
  muted,
  objectFit = "cover",
  style,
  segments,
  getClipStyle,
}: AvatarClipLayerProps) {
  if (clips.length === 0) {
    return null;
  }

  const ordered = [...clips].sort((a, b) => a.order - b.order);
  const clipByOrder = new Map(ordered.map((clip) => [clip.order, clip] as const));

  if (segments && segments.length > 0) {
    const orderedSegments = [...segments].sort(
      (left, right) => left.startFrame - right.startFrame || left.id.localeCompare(right.id),
    );

    return (
      <>
        {orderedSegments.flatMap((segment, index) => {
          const orderMatch = segment.id.match(/^avatar-(\d+)$/);
          const clip = orderMatch ? clipByOrder.get(Number(orderMatch[1])) : undefined;
          if (!clip) return [];
          const { fadeInFrames, fadeOutFrames } = getAvatarSegmentCrossfadeFrames({
            current: segment,
            previous: orderedSegments[index - 1],
            next: orderedSegments[index + 1],
          });

          return (
            <Sequence
              key={segment.id}
              from={segment.startFrame}
              durationInFrames={segment.durationInFrames}
            >
              <AbsoluteFill
                style={{
                  backgroundColor: "transparent",
                  ...style,
                  ...getClipStyle?.(clip),
                }}
              >
                <AvatarClipVideo
                  clip={clip}
                  durationInFrames={segment.durationInFrames}
                  fadeInFrames={fadeInFrames}
                  fadeOutFrames={fadeOutFrames}
                  muted={muted}
                  objectFit={objectFit}
                  segment={segment}
                />
              </AbsoluteFill>
            </Sequence>
          );
        })}
      </>
    );
  }

  let cursor = 0;

  return (
    <>
      {ordered.map((clip, index) => {
        const previousClip = ordered[index - 1];
        const nextClip = ordered[index + 1];
        const startFrame = cursor;
        const fadeInFrames = previousClip
          ? getAvatarClipCrossfadeFrames(previousClip, clip)
          : 0;
        const fadeOutFrames = nextClip
          ? getAvatarClipCrossfadeFrames(clip, nextClip)
          : 0;
        cursor += Math.max(1, clip.durationInFrames - fadeOutFrames);

        return (
          <Sequence
            key={`${clip.order}-${index}`}
            from={startFrame}
            durationInFrames={clip.durationInFrames}
          >
            <AbsoluteFill
              style={{
                backgroundColor: "transparent",
                ...style,
                ...getClipStyle?.(clip),
              }}
            >
              <AvatarClipVideo
                clip={clip}
                durationInFrames={clip.durationInFrames}
                fadeInFrames={fadeInFrames}
                fadeOutFrames={fadeOutFrames}
                muted={muted}
                objectFit={objectFit}
              />
            </AbsoluteFill>
          </Sequence>
        );
      })}
    </>
  );
}

