  `,resolveDir:process.cwd(),loader:'tsx'},tsconfig:'apps/web/tsconfig.json',bundle:true,write:false,outfile:'.tmp/manual-caption-evidence/fixture.js',platform:'browser',jsx:'automatic',define:{'process.env':'{}'}});
